local GameApi = GameApi
local TimeNow

NpcPrologue = {}

--定义错误字符串，可以改成换条件变的，看需要

NpcPrologue.Error_Prologue = "對不起，我沒有什麼好說的……"

--定义NPC字符串

NpcPrologue.Desinged_Prologue =
{
    --基本的写法

	--[NPC的ID] = {CommonPl = "开场白文字"},
	--复杂的写法：暂时只能取全局条件，不能取自身条件
	--将来希望加上生成器条件，将来从NPC身上取数，任务，声望，成就条件，从角色数据上取数
	--[[
	[622] =
	{
		--如果有此行且为1，说明该NPC受全局条件影响，将来再加别的，比如全世界通用条件等。


		NPCType = 1,
		--全局条件，可分gametime（游戏时间0~23），hour（真实小时），weekday（周几），暂只有这三个

		--条件需尽可能不重复，否则从前优先

		SpecialPl =
		{
			[1] =
			{
				Condition = "gametime",
	    		Variable = {0,1,2,3,4,5,6,22,23},
				String = "^00ff00#N^ffffff，请留步……！\r\r我在这等了整整一天，\r一直到^00ffff晚上（笑傲游戏时间）^ffffff……\r\r^00ff00#Y^ffffff我看您额有朝天骨，眼中有灵光，终于让我等到你啦！！！"
			},
			[2] =
			{
				Condition = "hour",
	    		Variable = {19,20,21,22,23},
				String = "^00ff00#W的#N^ffffff，\r最近听您在江湖上名头响得很哪！\r\r现在已经下班了您还没走？！\r\r既然如此，\r我就告诉您一些NPC开场白通配符吧：\r\r用井号（Shift+3）加上对应代码\r　“#”+N：角色名称\r　+P：门派\r　+Y：少侠女侠\r\r其它的我也记不清了：）"
			},
			[3] =
			{
				Condition = "weekday",
	    		Variable = {0,6},
				String = "我还以为是谁呢，\r原来是^00ff00#P的#N#Y^ffffff。\r\r正如你所见，\r今天就是传说中的^ffcb4a周末^ffffff！\r\r既然今天您还在，\r我就告诉您所有的开场白通配符吧：\r\r用井号（Shift+3）加上对应代码\r　+N：角色名称\r　+P：门派\r　+F：家族名\r　+G：帮派名\r　+W：当前头顶称号\r　+X、Y、Z：男女代称，依次为\r（壮士姑娘，少侠女侠，哥哥姐姐）"
			}
		},
		CommonPl = "久违了，\r^00ff00#N#X^ffffff！\r\r今天是工作日，所以正常上班，\r现在笑傲游戏时间是^ff0000白天^ffffff。\r\r作为一个没有填写开场白的NPC，\r我感觉压力很大！"
	},
	]]--
	--[622] = {CommonPl = "^ff0000×××××××××××××\r×××××××××××××\r×××××××××××××\r×××××××××××××\r这个NPC没有开场白\r×××××××××××××\r×××××××××××××\r×××××××××××××\r×××××××××××××"},
	[622] = {CommonPl = "今兒個天氣真是不錯！"},
	--正式用时可以去掉注释
	[1683] =
	{
		NPCType = 1,
		SpecialPl =
		{
			[1] =
			{
				Condition = "gametime",
	    		Variable = {0,1,2,3,4,5,6,19,20,21,22,23},
				String = "\r^00ff00　　　　　　公　　告^ffffff\r\r　　洛陽城的夜晚是和諧的！\r　　凡夜間打架者一律法辦！！！\r"
			},
		},
		CommonPl = "\r^d02222　　　　　　公　　告^ffffff\r\r　　今有梁山好漢李逵在此，\r　　挑戰費：^00ffff10文錢^ffffff打一次，\r　　擊敗者即送暗金狂戰斧一對！\r\r　　　　　　　　　　^ffcb4a金刀競技委員會\r"
	},
	[4706] = {CommonPl = "－－－－－\r｜我\r｜有\r｜話\r｜說\r－－－－－"},
	[4709] = {CommonPl = "－－－－－\r｜我\r｜有\r｜一\r｜句\r｜話\r｜說\r－－－－－"},
	[4712] = {CommonPl = "－－－－－\r｜我\r｜有\r｜一\r｜句\r｜話\r｜想\r｜要\r｜說\r－－－－－"},
	[4715] = {CommonPl = "－－－－－\r｜我\r｜，\r｜有\r｜一\r｜句\r｜話\r｜想\r｜要\r｜說\r｜！\r－－－－－"},
--————————————————————————————————

--导出开场白开始
	[1153] = {CommonPl = "你很面生啊，敢問尊駕大名？哦，原來是#N！此地名為蘭封，是江湖過客來往之所，江湖險惡，俠士你一定要小心！"},
	[1154] = {CommonPl = "喲，我之前沒見過你啊！是要前去遊歷江湖嗎？有什麼不懂的儘管問我好啦！"},
	[1155] = {CommonPl = "新來的？規矩懂嗎？不懂規矩就得受欺負，這就是江湖的規矩。問我？你可得誠懇點。"},
	[1162] = {CommonPl = "近日來鎮上蹊蹺之事甚多，看來連小小的蘭封鎮也要捲入江湖恩怨中了，唉……"},
	[1163] = {CommonPl = "跟爺爺去了那麼多大城市，見過那麼多江湖中人，卻沒見到幾個好玩的人。不過有個叫儀琳的姐姐，倒是很有意思。"},
	[1164] = {CommonPl = "人生難得一知己，千古知音最難覓。看來我這七弦琴，也只能泠泠獨奏了。"},
	[1165] = {CommonPl = "你不知道吧，練琴也是個苦差事，別看我現在琴藝高超，這不知是多少辛苦和眼淚換來的。"},
	[1174] = {CommonPl = "你聽過曉彤姑娘彈琴嗎？那可真是仙樂啊……"},
	[1175] = {CommonPl = "雖說洛陽比蘭封鎮繁華許多，但走南闖北了這麼多年，還是覺得在家鄉踏實。"},
	[1176] = {CommonPl = "我家那口子常年在洛陽和蘭封之間奔波，這年頭，生意不好做了。"},
	[1177] = {CommonPl = "年輕人，總是看不透浮名，追逐名利奔波多年後，人都變了。等到像我這般年紀的時候，就會明白，所謂的那些名利，不過是過眼雲煙罷了。"},
	[1200] = {CommonPl = "小胖總是搶我的糖葫蘆吃，下次不跟他玩了。"},
	[1201] = {CommonPl = "我最喜歡過年了，過年就會有好多好多好吃的。"},
	[1202] = {CommonPl = "江湖中的恩恩怨怨，那可是說不清道不明的。人心難測，一切還是小心為好。"},
	[1203] = {CommonPl = "哼哼，我可是跟各大門派的掌門都有交情，走到哪兒，只要報一聲我燕小七的名號，江湖上的兄弟肯定會賣你個面子。"},
	[1205] = {CommonPl = "過幾日武林大會就要開了，現下青年才俊還不夠多，到時場面不夠熱鬧，丟的是我金刀王家的臉面。這可如何是好……"},
	[1206] = {CommonPl = "#Y，你可懂些醫術？我家來了個落魄的傷患，雖然邋遢不堪，畢竟是我金刀王家的客人，一定要賓至如歸。勞煩你給看看？"},
	[1209] = {CommonPl = "咱們花紅苑的姑娘，可是全洛陽城最漂亮的！"},
	[1210] = {CommonPl = "咱們花紅苑的姑娘，可是全洛陽城最漂亮的！"},
	[1211] = {CommonPl = "本門武功亦剛亦柔，攻防兼具，靜若處子，動如脫兔，是謂：峨眉天下秀，武功獨一枝."},
	[1212] = {CommonPl = "少林收弟子向來講究一個“緣”字，不知施主可有佛緣？"},
	[1213] = {CommonPl = "咱們南疆五仙教歷來只收女人，你可要瞧清楚了。"},
	[1214] = {CommonPl = "武當派的祖師爺是張三豐大俠，武功主要以內家拳法為主。"},
	[1215] = {CommonPl = "華山派是江湖上響噹噹的名門正派，不過門風嚴謹，弟子大多都很低調。"},
	[1216] = {CommonPl = "#Y，你是否要去恆山拜師？"},
	[1217] = {CommonPl = "衡山派弟子多喜音律，掌門人更是將二胡拉的出神入化……"},
	[1218] = {CommonPl = "逍遙一派源自雪山，很少涉足中原，#Y要是想入逍遙派，眼下正是千載難逢的好機會."},
	[1219] = {CommonPl = "東方教主的名頭，想必#Y一定有所耳聞了。"},
	[1220] = {CommonPl = "最初唐門只收內家弟子，近幾年不少有為青年慕名前往唐門拜師，這位#Y，你可有興趣入唐門？"},
	[1221] = {CommonPl = "叫我作甚？沒看見正忙著呢嗎……"},
	[1222] = {CommonPl = "好奇怪，鎮外楊將軍廟裡的神像倘若是楊再興，便不是楊公再；如果是楊公再，便不是楊再興。怎麼又是楊再興，又是楊公再？"},
	[1223] = {CommonPl = "你們可知平大夫生平最怕的是甚麼？就是他老婆。有甚麼好笑，我就是他老婆。"},
	[1224] = {CommonPl = "幫主也派我來巡邏喲……"},
	[1225] = {CommonPl = "幫主派我來巡邏喲……"},
	[1226] = {CommonPl = "我長大要做岳爺爺一樣的大英雄！"},
	[1227] = {CommonPl = "書中自有顏如玉……不過書外也有。"},
	[1228] = {CommonPl = "投我以木桃，報之以瓊瑤，匪報也，永以為好也。"},
	[1385] = {CommonPl = "無論多少磨難，只要人心向上就都會安然度過。"},
	[1386] = {CommonPl = "二板橋\r癸亥年七月立"},
	[1419] = {CommonPl = "人之初，性本善……"},
	[1420] = {CommonPl = "一會我就去找小琳子玩去！"},
	[1584] = {CommonPl = "世上樂事千千萬，我獨愛“吃”這一項。"},
	[1590] = {CommonPl = "再不能將歹人緝拿歸案，這月俸祿就拿不到了……"},
	[1635] = {CommonPl = "一行！"},
	[1789] = {CommonPl = "江湖上混的人，說出來的話就像是釘在牆上，一個釘子一個眼，永無更改。"},
	[1792] = {CommonPl = "女人的眼淚簡直比暗器還可怕，無論多厲害的暗器，你至少還能躲。女人的眼淚卻連躲也躲不了。無論多厲害的暗器最多不過在你身上打出幾個洞來。女人的眼淚卻能將你的心滴碎。"},
	[1795] = {CommonPl = "一個玩不起的浪子就不是浪子。一個放不下的智者，絕對不是一個真正的智者。"},
	[1798] = {CommonPl = "有些事，看得太清楚卻容易太痛楚，太清醒往往不一定是件好事。"},
	[1801] = {CommonPl = "人常想要做他想做的事，但卻常常只能做他可以做的事。"},
	[1807] = {CommonPl = "閣下有何冤情？盡可稟報我家大人。"},
	[1810] = {CommonPl = "威——武——"},
	[1813] = {CommonPl = "威——武——"},
	[1816] = {CommonPl = "威——武——"},
	[1819] = {CommonPl = "愛和恨最大的不同，是愛能使人憧憬未來，能使人對未來充滿希望。恨卻只有使人想到過去那些痛若的往事。"},
	[1822] = {CommonPl = "一片，兩片……\r他喜歡我……他不喜歡我……"},
	[1831] = {CommonPl = "何必多情？何必癡情？\r花若多情，也早凋零。\r人若多情，憔悴、憔悴……\r人在天涯，何妨憔悴？\r酒入金樽，何妨沉醉？\r醉眼看別人成雙成對，\r也勝過無人處暗彈相思淚……\r花木縱無情，遲早也凋零。\r無情人，終有一日須憔悴。\r人若無情，活著還有何滋味？\r縱然在無人處暗彈相思淚，\r也總比無淚可流好幾倍。"},
	[1834] = {CommonPl = "阿彌陀佛，善哉善哉。"},
	[1837] = {CommonPl = "光明也正如黑暗一樣，總是忽然而來，誰也不知道它什麼時候會來，但是你一定要有信心，一定要相信它遲早總會來的。"},
	[1840] = {CommonPl = "人之所以會有痛苦，就是因為人類是有感情的動物。"},
	[1846] = {CommonPl = "人類最大的敵人，就是自己；最可怕的敵人，卻是朋友。"},
	[1849] = {CommonPl = "青山相待，白雲相愛。夢不到紫羅袍共黃金帶。一茅齋，野花開，管甚誰家興廢誰成敗。陋巷單瓢亦樂哉。貧，氣不改！達，志不改！"},
	[1852] = {CommonPl = "只可惜我們相見太晚了”，古往今來，不知有多少人說過這句話，也不知有多少人聽過，可是，除非你真的聽過、真的說過，否則你絕對無法想像這句話裡有多少辛酸，多少痛苦。"},
	[1855] = {CommonPl = "情人雖是新的好，但朋友總是老的好。"},
	[1858] = {CommonPl = "你若經歷過很多事，忽然發現所有的事都已成了過去，你若得到過很多東西，忽然發現那也不過是一場空，到了夜深人靜只剩下你一個人，那時你才會懂得什麼叫寂寞。"},
	[1861] = {CommonPl = "夏之日，冬之夜。百歲之後，歸於其居。\r冬之夜，夏之日。百歲之後，歸於其室。\r"},
	[2835] = {CommonPl = "養育你那麼多年，大叔真捨不得你走啊……\r自己在外面多保重身體，多學本事，以後記得回來看看大家。\r別回頭了，要不我就要留下你不讓你走了！"},
	[2838] = {CommonPl = "雖說你是長大成人了，但畢竟閱歷還淺，出門在外多留點心眼兒，別被人騙了走入歧途。\r我們都已經老啦……這個江湖將會是你們這些年輕人的天下。"},
	[2841] = {CommonPl = "帶著我家囡囡去買糖葫蘆嘍！"},
	[2844] = {CommonPl = "真不捨得讓你走啊孩子……你現在的功夫差得還遠，也就只能對付幾個雞豚狗彘、地痞流氓什麼的。\r到外面好好找個師父學藝吧！不求做大俠，咱好歹得能防身啊……"},
	[2847] = {CommonPl = "狐死尚且首丘，我這老漢不願客死他鄉，趁還有力氣重歸故里開店謀生很奇怪嗎？"},
	[2850] = {CommonPl = "宛兒自知生的醜，客官您還是別看我的好……"},
	[2853] = {CommonPl = "我們此行竟然遇到歹人，少鏢頭沒來真是對了，要不有個三長兩短還真是不好交代。"},
	[2856] = {CommonPl = "我福威鏢局保鏢，向來以安全可靠著稱，從東南直到京城，福威鏢局都是您的最佳選擇！"},
	[2859] = {CommonPl = "好容易能出城打獵，夫人偏偏不肯放少鏢頭出來，我們自己來了也真甚是無趣……"},
	[2862] = {CommonPl = "江湖險惡，別忘了給你講過的道理，凡事多動腦子想想，不要偏聽偏信。\r趕緊去吧，再耽擱天色就晚了。"},
	[2878] = {CommonPl = "蘭亭不僅有崇山峻嶺，茂林修竹；又有清流激湍，映帶左右，引以為流觴曲水，列坐其次。\r如此美景，再加上友人的絲竹管弦之盛，一觴一詠，足以暢敘幽情了。"},
	[2881] = {CommonPl = "（石碑上清楚的寫著：）\r五嶽獨尊"},
	[2884] = {CommonPl = "大丈夫在世，當盡識天下武功。\r吾聞近日裡江湖中正當風起雲湧，武林中人無不盡相約同前往華山論劍。這位#Y何不前往？"},
	[2887] = {CommonPl = "武學千變萬化，江湖眾生正為了武林密笈爭得頭破血流、黑白不分，甚至不顧自己的身份和地位。\r相比之下，我等閒士游天下之樂，#X#N，你可知乎？"},
	[2890] = {CommonPl = "武功有何用？名望又有何用？？\r但凡個人所有，無論學識、地位，同此音樂一樣，於吾皆為身外之物。\r人在江湖，得一知己足已。"},
	[2893] = {CommonPl = "蘭亭氣味氛芳，風景宜人，不知何此才能再與爹爹入此畫境。\r#N#Z，可惜我學習琵琶時間太短，不然真想彈奏一曲呢。"},
	[2896] = {CommonPl = "（草的氣息使人倍覺足下有力）"},
	[2899] = {CommonPl = "宛兒，快為外面的客官上茶。"},
	[2902] = {CommonPl = "客官，您有什麼吩咐就儘管說。"},
	[2905] = {CommonPl = "這一路上看來越來越不安全了。\r所以如果有啥金銀細軟、貴重寶貝什麼的，還是找我們鏢局代為押送才是為上策啊，哈哈。"},
	[2908] = {CommonPl = "雖說平日裡押鏢遇劫匪並非異事，\r但近日這幾次也太奇怪了……"},
	[2911] = {CommonPl = "好久沒碰到過這麼大的雨了……\r請各位速速上車，我即刻送各位前往城中的福威鏢局總局！"},
	[2914] = {CommonPl = "看什麼看，沒見過鏢師啊！"},
	[2917] = {CommonPl = "（馬車停在雨中正待出發）"},
	[2920] = {CommonPl = "聽說此處路上強人甚多，為保財物不失我們還是小心一點為好。"},
	[2921] = {CommonPl = "不知再幹多久我才能做到鏢師，又要多久才能做到史鏢頭那樣。"},
	[2927] = {CommonPl = "外面好吵啊，不知發生了什麼事。"},
	[2928] = {CommonPl = "請恩人稍侯，\r我馬上就為您奉茶出去。"},
	[2929] = {CommonPl = "這一路上多有坎坷，\r快到福州我反而更擔心了。"},
	[2930] = {CommonPl = "若少鏢頭在此，\r這一路賊寇何足掛心！"},
	[2934] = {CommonPl = "#N，久違了！\r此地名為蘭亭，雖為世間之地，卻有世外之景，世人皆以到此一遊為幸。"},
	[2941] = {CommonPl = "（書聖之墓）"},
	[2944] = {CommonPl = "（凳子）"},
	[2947] = {CommonPl = "（刻著蝌蚪文寫的文章，完全看不懂）"},
	[2950] = {CommonPl = "（裝著半缸粗製黃酒）"},
	[2953] = {CommonPl = "（普通的灶台，散發著淡淡的油煙味）"},
	[3259] = {CommonPl = "我福威鏢局三代走鏢，行走十數省，托黑白兩道朋友照顧，從未失鏢！"},
	[3262] = {CommonPl = "爹爹也不讓我跟鏢，平日城裡連個毛賊都遇不到，更別說江洋大盜了，只能天天出去打些野物，真是無聊地緊！"},
	[3265] = {CommonPl = "我夫婦愛護平兒太過，雖然教他武功，卻也不想太早讓他在江湖上闖蕩受苦。"},
	[3268] = {CommonPl = "請問這位#Y有何貴幹？要找何人？"},
	[3271] = {CommonPl = "帳房重地，非請勿入。"},
	[3274] = {CommonPl = "世人只知武功高強可成為宗師，卻不知廚藝高超了也是宗師。"},
	[3277] = {CommonPl = "昨晚手氣真臭，居然輸給老崔十多兩銀子！"},
	[3280] = {CommonPl = "哈哈，今兒爺高興，晚上再去找小翠談談心！"},
	[3283] = {CommonPl = "你可別以為趟子手這行當好幹，銀錢不多，受累不少，有時候小命都難保！"},
	[3501] = {CommonPl = "客官，您是打尖還是住店？"},
	[3513] = {CommonPl = "嘿嘿，客官，要不要嘗嘗餛飩？\r餡大皮薄，味美湯鮮，就是神仙聞到了味，也得饞的跳腳！\r今天吃上一碗，保准你明天還想再來。"},
	[3519] = {CommonPl = "三年之後又三年，那狠心短命挨千刀的死鬼，到底還要我再等幾個三年？！\r當時只道是會試之後，夏末便歸。\r如今也不知過了多少寒暑，女兒都長這麼大了，卻音信全無。\r早知文人無義，秀才薄情，還不如嫁那賣貨郎，倒是個圓滿人家。\r"},
	[3558] = {CommonPl = "全是前面福州城裡的稀奇物，客官要不要買幾件送人？"},
	[3561] = {CommonPl = "風月中哪在乎年紀少，我王婆歷練過手段高。\r識趣人才知道千般妙，你卻瞧咱嬌是不嬌？"},
	[3573] = {CommonPl = "空手把鋤頭，步行騎水牛。\r人從橋上過，橋流水不流。"},
	[3621] = {CommonPl = "不要太奇怪！我並不是經常來這裡，最近穿越的費用也漲高了不少的說！"},
	[4576] = {CommonPl = "好生，疼啊！！！！！！"},
	[4585] = {CommonPl = "這幾日忙著辦金盆洗手大會，可忙死我了。"},
	[4588] = {CommonPl = "武當山秀水美，人人皆可隨口吟唱。\r空山新雨後，天氣晚來秋。\r明月松間照，清泉石上流。\r樵子歸向晚，王孫自可留。"},
	[4591] = {CommonPl = "智者無惑，勇者無懼；\r仁者無敵，行者無疆。\r雖千萬人，吾往矣。"},
	[4594] = {CommonPl = "武當山下治安一向不錯，南來北往的到了這兒都變得低眉順目，悄悄行走，不敢驚動了道長真人。\r今兒這是怎麼了？難道有什麼大變故要出現了！"},
	[4600] = {CommonPl = "自從爹媽去世後，只有我和小飛相依為命了。這孩子倔強得緊，總是逞強，弄得自己滿身是傷。\r如今讓他去道觀學點武藝防身，只願以後不要被人欺負。"},
	[4603] = {CommonPl = "那些臭道士竟然騙我，看來這世上我能相信的只有姐姐了……"},
	[4606] = {CommonPl = "人生在世，該當暢情適意.\r有點小傷就不能喝酒，還做什麼人？\r不如及早死了爽快！"},
	[4609] = {CommonPl = "這趟跟師兄弟一起去參加“金盆洗手大會”，\r一定能見識到很多武林前輩！\r只是不知道師傅他們走到哪裡了？"},
	[4612] = {CommonPl = "不知道洛陽城裡面有沒有特產的水粉？\r那裡可是繁華之地，牡丹之都，肯定有不少好吃的好玩的，\r我真想早點去看看，嘿嘿……"},
	[4615] = {CommonPl = "是藥三分毒，是毒三分藥。藥可害人，毒也可救人。\r但毒比起藥卻更有美妙之處。\r我們榮於毒又毀於毒，明知是毒，又欲罷不能。真不愧是醉人的毒藥啊！"},
	[4621] = {CommonPl = "我昆侖派乃是江湖上的名門正派，沒想到今日虎落平陽被犬欺！唉……都怪我學藝不精，身敗名裂也就罷了，只恐貽羞師門啊……"},
	[4687] = {CommonPl = "日行一善，積善成德。\r以德服人，那就無往不利了。"},
	[4718] = {CommonPl = "看個景兒，聽個曲兒，品個茶兒，打個盹兒。\r活到這種分兒上就可以知足啦！\r客人，看景累了坐我這歇歇吧，我給您拉個小曲兒，上壺香茶，您可愜意？\r不爽對我說，滿意了記得告訴朋友。"},
	[4721] = {CommonPl = "花自飄零水自流……\r這不正是說的我們花家嗎？\r天氣涼了加暖衣裳，就不會傷春悲秋了。"},
	[4736] = {CommonPl = "誰能告訴我如何才能得道成仙？\r其實得道並不重要，關鍵是成仙。\r相傳漢代的淮南王飛升之後，雞犬吃了遺下的丹藥都升天了，\r老子是人，為何不能白日飛升！"},
	[4853] = {CommonPl = "林夫人於我有救命之恩。只要是為了夫人，我縱赴湯蹈火，在所不辭！"},
	[4909] = {CommonPl = "我很擔心我家相公。\r百密一疏，無論他管理書院多麼盡心盡責，都難保不出點差錯啊。\r而且這幾天人多眼雜的，怎麼能冤枉他是內賊呢？\r他不會因此想不開吧……"},
	[4912] = {CommonPl = "有點累了，我在這個地方歇歇腳。"},
	[4915] = {CommonPl = "周圍全是狼，人家好害怕！\r雖然哥哥在我面前總是開心地笑著，可我知道他也有害怕的時候。\r為了哥哥，我也要堅強起來。"},
	[4918] = {CommonPl = "沒想到嵩山上也有這麼多惡狼，今天看來要把小命交待在這了……\r我死了倒沒什麼，可憐思燕從此得孤單一人，我還向爹媽保證要照顧好她的……"},
	[4969] = {CommonPl = "遠山含黛，近水浮青，寺鐘杳杳，紅葉拂心。"},
	[4972] = {CommonPl = "撫長劍，一揚眉，清水白石何離離。\r世間苦無知音，縱活千載，夫複何益？"},
	[5005] = {CommonPl = "如果能再讓我選擇一次，我不知道還會不會這樣……\r可是，可是已經沒有機會了。"},
	[5221] = {CommonPl = "阿明……你說讓我等你回家的，可你怎麼就說話不算數了呢？\r可如今你躺在這裡，留我一個弱女子在世上，教我如何活下去……\r都怪我，若不是我看上那脂月齋的胭脂，你也不會一早就去採草藥，被那六喬寨的惡徒殺害了……嗚嗚嗚……\r"},
	[5224] = {CommonPl = "（草席裡裹著一具男子的屍體。）"},
	[5227] = {CommonPl = "客官，你是初次來仙愁峽的吧？\r那可一定要小心仙愁峽裡的毒物了，不過比起那些毒物，六喬寨的強盜可比這些毒物還要毒上好多倍呢！"},
	[5230] = {CommonPl = "可惡的六喬寨，為了本破書，害死這麼多無辜村民！\r我要讓他們嘗嘗斷腸草的厲害！"},
	[5233] = {CommonPl = "我們總管說過:\r敢惹我們落雪莊的人，一定沒有什麼好下場！"},
	[5236] = {CommonPl = "聽我舅舅說，洛陽城裡的家丁一月能發二兩銀子！\r不過莊主對我們這麼好……\r就算是不給錢白乾，我也不想離開落雪莊！"},
	[5411] = {CommonPl = "聖教主千秋萬載，一統江湖！"},
	[5414] = {CommonPl = "餘杭徑山，據傳乃是茶聖陸羽著《茶經》之處。\r我也只是個來懷古的路人而已。"},
	[5417] = {CommonPl = "這次兩個幫派火拼，聽說飛魚幫折損不小，唉……蘇大小姐的日子不好過啊。"},
	[5420] = {CommonPl = "青青子衿，悠悠我心。\r但為君故，沉吟至今。\r此去經年，良辰美景。\r煙雨難顧，將心牧雲。"},
	[5423] = {CommonPl = "沒有過不去的坎兒。\r第一要務是復興幫派，為父報仇。\r兒女情長什麼的，還是忘了的好。"},
	[5426] = {CommonPl = "此次計畫若不成功，我便拿刀砍死我自己！\r銅都能化成金，要人化泥又有何難？"},
	[5429] = {CommonPl = "在下風二中，只是一名華山的普通弟子。\r風老前輩，那自然是師伯前輩。\r他老人家仙逝已久，小輩能一睹他的精妙劍法，乃是三生有幸。"},
	[5456] = {CommonPl = "茅山派才是道門正宗。這幫天師派的龜孫子，敢在太歲爺頭上動土，我定叫他們吃不了兜著走！"},
	[5459] = {CommonPl = "要混出頭一定要跟對靠山，這是萬古不變的硬道理。"},
	[5462] = {CommonPl = "茅山術博大精深，你們這些只會動刀動槍的武夫是理解不了的。"},
	[5465] = {CommonPl = "人靠衣裝，馬靠鞍。出門在外，難免碰到颳風下雨濕了衣服，還是多備兩件妥當。"},
	[5479] = {CommonPl = "這風雷幫和那飛魚幫的恩怨，真不知道幾時能休！不過這次風雷幫這次好像做的是有點過份了。"},
	[5482] = {CommonPl = "有我蘇奎一日，便要叫風雷幫的畜生們血債血償！"},
	[5623] = {CommonPl = "別看我現在是個黃牛，原來可是混江湖的。\r路子野，朋友多，不管是真戲票還是假銀票，儘管開口，沒有我搞不到的。"},
	[5626] = {CommonPl = "我聽說，如果找一個樹洞，說出自己的秘密，用泥土封起來，這世上就會多一棵會行走的樹。"},
	[5629] = {CommonPl = "浮生若夢，終歸要醒。\r最好的故事，是沒有然後的。\r最好的時光，只能存在於記憶中。"},
	[5650] = {CommonPl = "卦面的意思我只能讀懂一半，所以叫做半仙。"},
	[5653] = {CommonPl = "恩德相結者，謂之知己；\r腹心相照者，謂之知心，聲氣相求者，謂之知音。\r知己知心易求，唯獨知音難覓。"},
	[5667] = {CommonPl = "莊主和夫人，當年可是一對神仙眷侶啊……\r唉，可惜現在已經物是人非了……"},
	[5670] = {CommonPl = "\r鑄劍不僅需要技術，也需要那麼點“靈氣”。\r真正的好劍，是有靈魂的。\r如果沒那點“靈氣”，縱是再好的技術，鑄出的劍，總是缺少了靈魂。\r"},
	[5673] = {CommonPl = "人生裡有些事，一步跨出去即成天涯，縱然無歌，但能無悔。\r莊主就是這樣的人吧，還記得莊主練武成狂時說過的話：\r“終生未許狂到老，一時能狂便算狂。”"},
	[5676] = {CommonPl = "(石碑上寫著幾個字：“愛妻鄒氏夕顏之墓”。）"},
	[6053] = {CommonPl = "自己的苦倒還算不得什麼，\r恩師竟然被這些奸賊害得家破人亡，溘然長逝！\r衡山派到底怎麼得罪嵩山了?!"},
	[6056] = {CommonPl = "此次我等奉師父之命下山緝盜，\r沒想到竟碰上如此少年才俊，\r江湖上後繼有人，師父也一定歡喜的很。"},
	[6177] = {CommonPl = "陌上花開遲，想郎盼歸早。\r憑眼裡情火相交，縱好殺也不到老，何必到老。"},
	[6177] = {CommonPl = "原來我以為這世上最容易的一件事，就是忘記。後來我總算明白了，原來這世上最難的事，才是忘記。\r我猜，是因為痛不可抑，所以永不記起。"},
	[6180] = {CommonPl = "唉，家有良田萬頃，不抵片刻安寧。\r要我說，縱是在這裡吃包子，也勝過與那三房夫人喝好酒。"},
	[6183] = {CommonPl = "哼，看那珠兒成天介淒淒切切把癡心亂抛灑，怎比得咱殷殷實實賺銀錢早成家。"},
	[6186] = {CommonPl = "那天，他又對我笑了。\r他笑得真是好看，眼睛水一樣亮，牙齒雪一樣白。"},
	[6189] = {CommonPl = "多情總被無情誤。他們不信我便罷了，他也不信我。\r他竟不信我！"},
	[6204] = {CommonPl = "年少輕狂時學藝不精，終至作下冤孽悔恨一生。\r即便現在脫胎換骨，每日夢中依然會被舊事驚醒。"},
	[6207] = {CommonPl = "哎，這輛車子陪著我送貨十幾年了，一直沒啥毛病，跟它都有感情了，就這麼被那些畜生糟蹋了！\r鐵背山豬太可恨了！誰能除掉那個“少爺”啊……"},
	[6210] = {CommonPl = "書到用時方恨少，事非經過不知難。\r少年兒郎就應該吃點苦頭，栽幾個跟頭，方知人生不易，世事沒那麼想當然。然後對欲望和坎坷都能看得淡些。"},
	[6228] = {CommonPl = "那淫賊田伯光，竟癡想染指我妻！\r可是小瞧了我丁勉“托塔手”的名號？！"},
	[6231] = {CommonPl = "白骨露於野，千里無雞鳴。\r天災人禍，餓殍遍野，此率獸而食人也。"},
	[6927] = {CommonPl = "客官，小店現在可打烊啦，我勸您也先到外面躲躲再來，要是被那黃風寨的強人遇到，這輩子小的可就沒法伺候您啦！"},
	[6930] = {CommonPl = "多謝少俠相救……"},
	[6933] = {CommonPl = "今日我恆山派遭逢大難，得蒙少俠援手相救，大恩大德，不知如何報答才是。"},
	[6936] = {CommonPl = "頭好暈……不知那婦人的藍花布裡藏著什麼迷藥。"},
	[6952] = {CommonPl = "“正直相扶無依傍，撐持天地與人看”。\r如今宦官當道，權力紛爭，哪裡做得到絕對的正直無傍。\r還真不如像閣下當個江湖人逍遙自在。"},
	[6955] = {CommonPl = "當年黃巢開仙霞山道七百里，名為開路，實則借機埋藏了起義寶藏。\r只是我苦尋多年，卻還是不得門徑。"},
	[6958] = {CommonPl = "這月黑風高，山路陡峭，賊人殺將出來，時機選得真是恰到好處。\r我們中了埋伏，不知師父師姐她們現下怎樣，一定得把消息儘快告知她們。"},
	[6961] = {CommonPl = "陌上誰家年少，足風流。\r妾擬將身嫁與，一生休。\r縱被無情棄，不能羞！"},
	[6964] = {CommonPl = "昔有太白詩仙高歌蜀道難，今有顧某被困仙霞道。\r單是被困也便罷了，偏偏還惹下這一身相思債。"},
	[6973] = {CommonPl = "唉，我就是有一身拔山趕海的力氣，也撥不動那一絲一毫的女人心。"},
	[6976] = {CommonPl = "孩兒他爹幹活就快回來了，我得趕緊做好飯菜才成。\r好些日子不見了，我要拿出最好的手藝，叫他吃了再也不想離開。"},
	[6979] = {CommonPl = "上山砍柴心裡亂，\r下山回家沒人管。\r難得出個俏寡婦，\r卻把死夫當活男。\r苦了街邊老光棍，\r二兩白乾慰心酸。"},
	[6982] = {CommonPl = "想當初我與元鶴同是熱血男兒，意氣風發，創下這份事業。\r可歲月偷換，竟使我們面目全非，成了當年自己不齒的人。"},
	[7134] = {CommonPl = "嵩山派那些出爾反爾、假仁假義、卑鄙無恥的偽君子！姐妹們這次下山，真是大開眼界。"},
	[7160] = {CommonPl = "你永遠無法知道你將遇到什麼樣的人，遇到什麼樣的事，你也永遠不知道自己的命運會在何時轉折。\r有時候，一個不經意的眼神，一次擦肩而過的邂逅，便能改寫一個人的一生。"},
	[7163] = {CommonPl = "俗話說“養兒防老，積穀防饑。”，誰知到頭來，竟是收養的女兒對自己最好，真是造孽啊，造孽……"},
	[7166] = {CommonPl = "強中更遇強中手，惡人須服惡人磨。\r早知更有強中手，卻悔當初枉用心。\r要是我早聽得這兩句話，如今也不會落得如此境地。"},
	[8327] = {CommonPl = "古人雲：“夕陽無限好，只是近黃昏。”\r在我看來卻是：“人老情未老，執子看暮雲。”"},
	[8330] = {CommonPl = "松嫣命途多舛，卻一直心念養父母。此番性情，就是八尺男兒，也要汗顏不已。"},
	[8359] = {CommonPl = "“書中自有顏如玉，書中自有黃金屋”\r我萬卷樓開辦百年有餘，所出書籍無不是請名家撰寫，品質上乘。\r閣下請看，這書卷印章，便是我萬卷樓之標記，各地書商均有銷售。"},
	[8362] = {CommonPl = "您可小心點，這水燙著呐！"},
	[8394] = {CommonPl = "告示牌@S@"},
	[8397] = {CommonPl = "這泰山可是大大的有名，連孔聖人都曾說過“登泰山而小天下”，客人一定好好觀賞一番，也好給小店些許生意來做。"},
	[8400] = {CommonPl = "蕭牆之內，有禍亂乎？"},
	[8403] = {CommonPl = "造化鐘神秀，陰陽割昏曉。\r蕩胸生層雲，訣眥入歸鳥。\r會當凌絕頂，一覽眾山小。"},
	[8406] = {CommonPl = "泰山為五嶽之首，有天下第一山的美譽。我們泰山派也應該做五嶽劍派之首，博得天下第一劍派的美名。"},
	[8412] = {CommonPl = "咱們做生意之人，凡事都圖個吉利。若是像我這樣的經營書坊，不但書坊的名字中不能帶“火，風，雨”之類的字，就連自己的名字，也要改個吉利點的哩！\r您瞧我這名字是不是大富大貴之名？"},
	[8455] = {CommonPl = "聽說那個夜貓子計無施，有一門“化整為零大法”，你說，你說他若是被人給吃了，是不是剖開那人的肚子，他又可以一一取出，拼在身上，化整為零？"},
	[8458] = {CommonPl = "這朱仙鎮是那平一指矮冬瓜的地盤，他想在這裡給令狐沖治傷，卻也是不靈的。\r令狐沖的內傷，便是因我六兄弟以內力給他治療而起，這矮冬瓜居然又來學樣，令狐沖豈不是傷上加傷，傷之又傷，傷之不已！"},
	[8461] = {CommonPl = "這哪是“楊再興”，這裡分明寫的“楊公再”。原來這個楊將軍姓楊，名字叫做公再。唔，楊公再，楊公再，好名字啊，好名字。"},
	[8464] = {CommonPl = "我說這裡供的是楊七郎，果然不錯，我桃葉仙大有先見之明。\r不論是楊再興，還是楊公再，都是排行第七，因此都是楊七郎。"},
	[8467] = {CommonPl = "令狐沖那小子，走到哪都有女人愛。連五仙教那妖女，都對他另眼相看，在船上大家都中了毒，只給他服瞭解藥。\r不對，難道說那碗毒酒就是解藥？還是他贊那妖女年輕貌美？\r唔唔，其實還是因為他有膽量喝那毒酒，吞了那五條毒蟲吧？\r但他吞了毒蟲，雖然在船上不嘔，焉知不是因為吞了毒蟲，中毒更深？"},
	[8470] = {CommonPl = "我們鑄劍一族，已隱居這鑄劍谷數百年，遠離廟堂、不問世事，便是為了躲避那朝廷的煩擾，沒想到頭來還是躲不了……"},
	[8473] = {CommonPl = "你不知道吧，鑄劍是一件極耗心力的事，很講究天時地利人和，但最重要的是材料和火候，這諸多環節只要有一個出了差錯，便會前功盡棄，鑄不出好劍來。"},
	[8476] = {CommonPl = "往事經年，只記得大明湖畔，醉花台前。半點相思短，一任燕蹁躚。誰解心事？青絲依然。執劍在手，戎裝勒馬，別問前程後路，留待來生姻緣。"},
	[8479] = {CommonPl = "這鑄劍谷盛產精鐵礦石，那可都是鑄劍的好材料啊！"},
	[8482] = {CommonPl = "恆山派乃是武林中名門正派，從也未得罪過何人，不知是何方勢力竟要下此狠手？"},
	[8485] = {CommonPl = "老子的兵刃有些鈍了，一會兒讓鑄劍谷的朋友給我打磨打磨，哈哈！"},
	[8488] = {CommonPl = "在下點蒼派陶白白，這位#Y，點蒼派的大名，你不會不知道吧……我們點蒼派在劍術上也頗有造詣，江湖上如今都推崇五嶽劍派的劍法，要我看，哼哼，也不過如此！"},
	[8491] = {CommonPl = "與朝廷作對本不是我武林中人所為之事，不過這夥閹黨忒也欺人太甚！再說我等早年間都受過鑄劍谷的恩惠，急人所難，乃是豪傑本分，今番誓與鑄劍谷共存亡！"},
	[8494] = {CommonPl = "沒想到……五嶽劍派，同氣連枝什麼的，都是騙人的幌子！我一定要早點回去向師父報告！"},
	[8497] = {CommonPl = "老夫隱居此地已有十多年，不知#X來此有何貴幹？"},
	[8500] = {CommonPl = "我前後足足花了一十二年的時光，採集九種珍貴至極的藥物，九蒸九曬，製成起死回生的“續命八丸”。哈哈哈哈，我閨女終於有救了！"},
	[8503] = {CommonPl = "姓老的那傢伙也到了此地，若有了他的寶貝藥丸，聖姑朋友不管什麼病都應該不在話下了。噓——剛才我說的你什麼也沒有聽見。"},
	[8506] = {CommonPl = "這五霸崗本是春秋時代五霸會盟之地，如今我等江湖人士在此集會，真是胸中平添幾分豪氣。"},
	[8509] = {CommonPl = "中原風光不錯，如果不是要等藍教主來，我肯定到處去逛逛。\r那邊葵丘真是名不虛傳，好多向日葵，硬是漂亮了！"},
	[8512] = {CommonPl = "看樣子你不像是會耍鬼心眼的漢人啊。以後有空可以到南疆去我們教裡玩玩。\r真想趕緊回家，中原的天氣我不喜歡。"},
	[8515] = {CommonPl = "最恨那些假惺惺的名門正派了。\r什麼華山派令狐沖，不是因為聖姑一句話誰管他死活。"},
	[8518] = {CommonPl = "一具僵硬男屍，似是被一根繡花針穿刺死穴而亡，全身上下並無其它傷口。\r衣飾已破，卻均是上好蘇繡，可見身份不凡。"},
	[8521] = {CommonPl = "昨日忽做一夢，猶是舊時家中。\r松竹茶棋，言笑晏晏，夫君造了一口新寶劍。"},
	[8524] = {CommonPl = "他騙了我。\r騙了我，毀了山莊，又何必救我。\r我寧願那日死了，不用面對這一切，不用讓自己親手去殺了他。"},
	[8527] = {CommonPl = "廟門前來了許多外路和尚說要與本庵高人論佛法，恐怕說佛法三千是假，求龍泉寶劍是真。\r匹夫無罪，懷璧其罪，那五柄寶劍真是引來無數禍端。"},
	[8530] = {CommonPl = "我自幼便服侍夫人，如今山莊遭此劫難，雖說要報仇雪恨，然人死不能復生，往日歡樂又豈能追回。"},
	[8533] = {CommonPl = "唉，房子毀了能再蓋，傢俱丟了可重打。\r可我藏在炕席底下那套《妙妙小尼姑》，那可是插圖孤本僅此一套啊！"},
	[8536] = {CommonPl = "看什麼看，我這幾位師弟可不是好脾氣的。\r一拳下去，保你一佛出世，二佛升天。"},
	[8539] = {CommonPl = "自從離開了那死鬼，日子甚是輕鬆自在。\r回頭想想，那前半輩子竟是白活了。"},
	[8542] = {CommonPl = "近來地面上頗不平靜。\r自日月神教血洗名劍山莊，跟著便來了各色江湖人，官府也不敢出面過問，閣下還是謹慎行路為妙。"},
	[8545] = {CommonPl = "年輕人，進來坐坐吧。\r一個孤老頭子，便總想找人說說話。\r家裡憋悶，出來就是看看貓打架也是好的。"},
	[8548] = {CommonPl = "聽說孫癩子自從娶了媳婦便金盆洗手，不挖墳墓改挖香菇了，如今倒也賺下一份身家。\r您說我是不是也該改個行呢，還是該先娶個媳婦？"},
	[8551] = {CommonPl = "客官快請進，好酒好菜好彈唱。\r偌大的龍泉，您縱找的出咱這裡的好酒好菜，也找不出我這樣的老闆娘。"},
	[8554] = {CommonPl = "問世間情為何物，直叫生死相許。"},
	[8557] = {CommonPl = "總有一天我要成為一個真正的大俠。\r戴著牛皮帽，嚼著牛肉乾，騎著老黃牛。\r走遍大江南北，幫助那些遇到困難的姐姐們。"},
	[8560] = {CommonPl = "賣藥糖嘞！\r吃快藥糖心裡順，含著藥糖你不困。\r吃塊藥糖精神爽，勝過去吃禦膳坊。\r吃塊藥糖你快樂，比吃包子還解餓。"},
	[8563] = {CommonPl = "閣下可不要小看了我這份買賣。\r當年鄭和下西洋，那船上帶的就是我祖爺爺燒的青花瓷。"},
	[8566] = {CommonPl = "不得隨意亂貼亂畫，違者必究，罰錢十貫。\r——龍淵鎮地保"},
	[8569] = {CommonPl = "吃這水上飯，最怕的就是上年紀。\r一逢陰天下雨，從骨頭縫往外冒著涼氣，難熬啊。"},
	[9029] = {CommonPl = "各門各派為了讓聖姑看到心意都來此地獻寶，我巨鯨幫這樣出名的幫派，又怎麼能少。\r如此大事幫主竟然肯派我來，果然是器重我的。"},
	[9032] = {CommonPl = "官府的鹽政要是無縫可鑽，我們海砂幫也沒有市場，販私鹽雖然有利可圖，但真不是人幹的活兒。\r你可千萬別跟比人提起我們幫裡兄弟其實都是鹽梟的事情啊！"},
	[9035] = {CommonPl = "上次劇變之後已經過了很久，我飛魚幫也已經漸漸恢復了元氣，此番已經能抽出人手來五霸崗了。\r現在的幫主雖然和我一樣是女子，但可真是巾幗不讓鬚眉。"},
	[9038] = {CommonPl = "我黃河幫歷史不可謂不悠久，幫中的先人當年和郭靖郭大俠是交過手的。"},
	[9041] = {CommonPl = "將進酒，杯莫停！\r鐘鼓饌玉不足貴，但願長醉不復醒。\r古來聖賢皆寂寞，惟有飲者留其名。"},
	[9223] = {CommonPl = "此次我天河幫決定熱情款待令狐少俠，以表我們對聖姑的不二忠心。\r幫中上下已經前前後後忙了一個月了，算日子令狐少俠應該很快就能到此間了！"},
	[9229] = {CommonPl = "蒼天棄吾，吾寧成魔。"},
	[9419] = {CommonPl = "哪天有空我要去鎮上看看我姐姐，好久沒見她了。"},
	[10414] = {CommonPl = "我雲頂派創派上百年，如若不能在我手中發揚光大，我還有何臉面去面對列位祖師爺？\r還好我兒曾男天生就是練武奇才，雖然他現在還不肯習武，但我相信總有一天他會明白做父親的一片苦心。"},
	[10417] = {CommonPl = "我曾問過大師兄對杜家小姐的感情，我說我不懂，不懂他為什麼要為了一個女子放棄掌門之位，他只說了一句話：“直道相思了無益，未妨惆悵是清狂。”"},
	[10420] = {CommonPl = "蒹葭蒼蒼，白露為霜。\r所謂伊人，在水一方。\r巧笑倩兮，美目盼兮。\r一日不見，如三秋兮。"},
	[10423] = {CommonPl = "爹爹說的那些青年才俊，年紀輕輕就武功蓋世，都是一頂一的高手。\r我知道他們都是很好很好的，可是我偏不喜歡。"},
	[10426] = {CommonPl = "吼——吼————\r吼——吼————\r（老虎低低地咆哮著，靠近的人感到壓力很大。）"},
	[10458] = {CommonPl = "在江湖中混跡的久了，江湖中的很多事都因你而改變，也許命好沒死掉，還會留下某某大俠的美名。\r別以為只有你能改變江湖，其實江湖也在改變著你，你看我身上的這些傷疤，就是江湖留給我永遠的刺青。"},
	[10461] = {CommonPl = "好吃好喝好時節，美人美酒美風光。\r到我這兒來，只有你想不到的，沒有我辦不到的。"},
	[10464] = {CommonPl = "朱簾寂寂下金鉤，香鴨沉沉冷畫樓。\r移枕怕驚鴛並宿，挑燈偏惜蕊雙頭。\r誰都道風月場中風波多，我只求江州司馬對影酌。"},
	[10467] = {CommonPl = "我聽春花姨說“民以食為天”，敢情我們廚子還是頂頂重要的人物呐！哈哈哈哈……\r不過我一高興，就忘了跟春花姨提漲工錢的事……"},
	[10513] = {CommonPl = "最近村子裡好熱鬧哦，可還是沒人陪小萌玩……"},
	[10516] = {CommonPl = "久仰久仰！最近適逢武林盛事，招待不周，還望#Y海涵."},
	[10519] = {CommonPl = "不問蒼生，只問鬼神！"},
	[10522] = {CommonPl = "小村的和諧安定是吾等的神聖使命！"},
	[10556] = {CommonPl = "嘻嘻，你猜錯了，我是假新娘！"},
	[10559] = {CommonPl = "你真笨，我不是慕容七啦！"},
	[10562] = {CommonPl = "你終於找到我了……"},
	[10568] = {CommonPl = "老闆娘，您可別衝動。\r衝動是魔鬼啊！"},
	[10698] = {CommonPl = "今夕何夕兮，搴舟中流。\r今日何日兮，得與王子同舟。\r山有木兮木有枝，心悅君兮君不知。\r"},
	[10701] = {CommonPl = "白雲初晴，幽鳥相逐。\r眠琴綠陰，上有飛瀑。\r落花無言，人淡如菊。\r人淡如菊……我又怎好擾了這份清淨。"},
	[10704] = {CommonPl = "飯後百步走，\r能活九十九;\r飯前百步走，\r多喝三兩酒。"},
	[10707] = {CommonPl = "你歌沒有我歌多，\r我有十萬八千籮;\r只因那年漲大水，\r山歌塞斷九條河。"},
	[10710] = {CommonPl = "小歌終於答應嫁入靖江王府了，這樣最好。\r熾烈愛火總會熄滅，利益糾纏卻永恆牢固。\r那朱子夕也是個謙謙君子，他會給小歌幸福吧……"},
	[10713] = {CommonPl = "世間哪得雙全法，\r不負如來不負卿……\r張大哥，一切往日情，全付此江水。"},
	[10716] = {CommonPl = "我要為我心愛的女人畫一幅最美的畫，送給她未來的夫君。\r讓她比誰都幸福，連同我的那一份，一直幸福下去……"},
	[10719] = {CommonPl = "夜雨瀟湘驚昨夢，\r星河欲往東南傾;\r江湖酒伴如相問，\r終老煙波不記程。"},
	[10722] = {CommonPl = "據說老爺少年時常與一位友人在這亭子撫琴觀花，於是臨終前託付夫人把他葬於花下。\r不立碑文，只與清風明月為伴。\r"},
	[10725] = {CommonPl = "看公主如今的樣子，讓我想到了當年的夫人。\r世人都道岑大人一曲“高山流水”絕代風華，她卻獨愛那“瀟湘夜雨”無邊孤寂。\r唉，是孽是緣，轉頭皆空。\r"},
	[10728] = {CommonPl = "扶桑人來者不善，嵩山派暗裡玄機，靖江王搖擺不定，這桂林府何去何從，真也叫人焦心。"},
	[10731] = {CommonPl = "故人死去那年，我親手栽下這棵樹，如今竟已亭亭如蓋。\r二十年，他永遠留在那一刻，而我卻垂垂老矣。怕是泉下再見，他已識不得我。"},
	[10734] = {CommonPl = "我們一族世世代代生活在這哀牢山上，一切都是大山的恩賜。\r我們族人也像大山一樣，熱情地對待朋友。\r但是惹了我們，就不要想好過了，我們會像山洪一樣不留情面的。"},
	[10737] = {CommonPl = "有心摘花莫怕刺，打開青苔喝山泉。\r阿哥啊阿哥，你怎麼就不明白呢……"},
	[10740] = {CommonPl = "教我讀書的先生是漢人，他給我講過霍去病“匈奴未滅何以家為”的典故，我想我們兩族修好是頭等要事，兒女私情只能暫時放在一邊。"},
	[10743] = {CommonPl = "難得出一次門，結果還半路受傷……人在江湖，果然大意不得。"},
	[10746] = {CommonPl = "太陽歇歇麼，歇得呢；月亮歇歇麼，歇得呢；女人歇歇麼，歇不得。\r女人要是歇著麼，男人就要生病啦。"},
	[10749] = {CommonPl = "我雖是漢人，但也當自己是大山的兒子，和土生土長的兄弟姊妹一樣，都是喝瀾滄江的水長大的，最愛的是香茅草的味道。"},
	[10752] = {CommonPl = "同飲一江水，都愛這片土地，為哪樣還要互相殘殺？\r先人的恩怨我們已經悔悟，為哪樣不能一筆勾銷！"},
	[10755] = {CommonPl = "彩鳳姑媽年紀大了，以後估計是靠讓阿細來撐起我們一族，可是我看她不經歷點兒挫折，始終都就是這種昏昏叨叨的。"},
	[10787] = {CommonPl = "大刀砍去倭寇頭，\r血濺三尺報國仇;\r太平縱馬還鄉去，\r三姐給我斟滿酒。"},
	[10788] = {CommonPl = "依我看呐，小姐都是被老爺慣壞了。一個丫頭而已，竟敢不聽父母之言，跟仇家的兒子私定終身？\r要是蘭心敢這麼做，看我不打斷她的腿！"},
	[10791] = {CommonPl = "我們馬幫就是沿著這個茶馬道，用山裡面產的東西換山外面的稀奇玩意兒，北邊的商人，對普洱茶喜歡得緊。"},
	[10932] = {CommonPl = "遠道而來辛苦了，要不要歇歇腳，坐下來喝一杯？"},
	[10933] = {CommonPl = "天南海北的好皮貨！"},
	[10934] = {CommonPl = "吃穿用度全都漲價了，連草料都比往年貴了些，偏偏酬俸還少了！這哪裡是人過的日子！我看過兩天我也要上山當強盜去！"},
	[10936] = {CommonPl = "收各色藥材啦！有貨的儘管開價！要買藥也來找我，記住我的招牌--從不賣假藥的賈藥！"},
	[10937] = {CommonPl = "此地盜匪猖獗，身為沒有一個下屬的地保，我覺得壓力很大."},
	[10956] = {CommonPl = "常跟草藥打交道，難免眼花中了套。\r若是上山採藥去，幾種毒藥要記牢。\r壯士可聽好了：\r披金戴銀一天仙，半升半降黃白錢。\r川南狼，鬧粉娘，遂草炒豆熬酥糖。@S@"},
	[10959] = {CommonPl = "茲日起，高價收購血玉蜘蛛毒液，如有此物，請交予竹海藥農處，必有重謝。@S@"},
	[11133] = {CommonPl = "說起這迴雁樓的美酒，莫說在衡陽城內是個魁首，便是在整個湖廣那都是赫赫有名的。\r“衡陽有迴雁，美酒更傳香”，你非要飲了這迴雁樓的美酒，才不枉來衡陽一場。"},
	[11142] = {CommonPl = "客官且先坐坐，小的這就來招呼您。"},
	[11145] = {CommonPl = "客官快請坐。\r看您不像本地人，來了這衡山城，可一定得嘗嘗我們迴雁樓的美酒。\r"},
	[11148] = {CommonPl = "客官且先坐坐，容小的先招呼完這位爺，馬上就來招呼您。"},
	[11151] = {CommonPl = "朱文燈下逢劉倩，師厚燕山遇故人。\r隔斷死生終不泯，人間最切是深情。\r話說大唐中和年間，博陵有個才子，姓崔名護，生得風流俊雅，才貌無雙。偶遇春榜動，選場開，收拾琴劍書箱，前往長安應舉。歸當暮春，崔生暫離旅舍，往城南郊外遊賞。但覺口燥咽乾，唇焦鼻熱。一來走得急，那時候也有些熱了。這崔生只為口渴，又無溪澗取水。\r崔生去叩門，覓一口水，立了半日，不見一人出來。正無計結，忽聽得門內笑聲。崔生鷹覷鶻望，去門縫裡一瞧，原來那笑的，卻是一個女孩兒，約有十六歲……"},
	[11160] = {CommonPl = "嘿！今天迴雁樓裡可真熱鬧，不虛此行！不虛此行啊！"},
	[11208] = {CommonPl = "農婦、山泉、有點田，這正是我理想中的生活狀態啊。"},
	[11211] = {CommonPl = "救命啊，惡霸要搶如花似玉的美人兒啦。"},
	[11214] = {CommonPl = "我長大之後也要像擂臺上這些大俠一樣威風，這樣娘就不會受人欺侮了。"},
	[11217] = {CommonPl = "我熟讀醫典，救治過無數病人，卻無法醫治自己的相思病。"},
	[11238] = {CommonPl = "關關雎鳩，在河之洲。\r窈窕淑女，君子好逑。\r#N，我已在此等你許久了。"},
	[11241] = {CommonPl = "客官，您有東西要當嗎？\r本店什麼都當，包括良心。"},
	[11244] = {CommonPl = "百年修得同船渡，千年修得共枕眠。\r看來老朽和客官，竟有幾世的淵源啦。"},
	[11247] = {CommonPl = "最近城裡都傳開啦，城西的白公子，每天都在橋頭等人。\r我聽說呀，他的聲音像夜鶯一樣好聽，容貌像天上的月亮一般好看。\r這可不是神仙下凡嗎？"},
	[11305] = {CommonPl = "江湖上混的人，說出來的話就像是釘在牆上，一個釘子一個眼，永無更改。"},
	[11308] = {CommonPl = "浪子三唱，只唱英雄。\r浪子無根，英雄無淚。\r浪子三唱，不唱悲歌。\r紅塵間，悲傷事，已太多。\r浪子為君歌一曲，勸君切莫把淚流。\r人間若有不平事，縱酒揮刀斬人頭。"},
	[11765] = {CommonPl = "少爺若是要走，就一定得帶上我！\r我會疊被鋪床，我會縫鞋補襪；\r我會紅袖添香，我會煮飯生娃。"},
	[11768] = {CommonPl = "“書中自有顏如玉，書中自有黃金屋”\r我萬卷樓開辦百年有餘，所出書籍無不是請名家撰寫，品質上乘。\r閣下請看，這書卷印章，便是我萬卷樓之標記，各地書商均有銷售。"},
	[11789] = {CommonPl = "女人真奇怪，不該知道的事，她們全知道，該知道的事，她們反而不知道。"},
	[11964] = {CommonPl = "么妹一去不歸，本以為是好姻緣，現在卻音信全無。\r似這等鞭長莫及之事，我夫婦只能默默求菩薩保佑，惟願大家皆能平安康樂，便是人間仙境了。"},
	[12052] = {CommonPl = "呦呦鹿鳴，食野之蘋。我有嘉賓，鼓瑟吹笙。"},
	[12055] = {CommonPl = "客官且先坐坐，小的這就來招呼您。"},
	[12058] = {CommonPl = "客官快請坐。\r看您不像本地人，來了這臨江鎮，可一定得嘗嘗我們醉仙樓的香茶美酒。\r"},
	[12061] = {CommonPl = "客官且先坐坐，容小的先招呼完這位爺，馬上就來招呼您。"},
	[12064] = {CommonPl = "若說起這世間的美貌女子，我還沒見過比白燕姐姐更好看的人。\r可要說這世間最清純的女子呀，我看非儀琳姐姐莫屬！"},
	[12067] = {CommonPl = "銀河耿耿兮寒氣侵，月色橫斜兮玉漏沉。\r憂心炳炳兮，發我哀吟；吟複吟兮，寄我知音。"},
	[12070] = {CommonPl = "今日是郡王府大喜之日，何人在此喧嘩？\r快快走開！"},
	[12073] = {CommonPl = "我既已娶了郡主，往後郡主就是我名正言順的妻。\r至於此前的往事，我已盡數忘記，還望小姐也能忘記。"},
	[12076] = {CommonPl = "一個人若是對一個男人有了感情，就算全世界的霧也掩飾不住。\r即使她已看過太多的悲歡離合，也不例外。"},
	[12079] = {CommonPl = "雖說我是一方郡守，但回到家也是個父親、叔父。可恨我那兒子與侄女，竟沒一個教人省心！"},
	[12082] = {CommonPl = "自古姻緣天定，不由人力謀求。\r有緣千里也相投，對面無緣不偶。\r仙境桃花出水，宮中紅葉傳溝。\r三生簿上注風流，伺用冰人開口。"},
	[12085] = {CommonPl = "“子午卯酉弟兄多，寅申巳亥三兩個，辰戌醜未獨一個”\r#Y，你生辰多少？"},
	[12088] = {CommonPl = "屍體是不會回答你的。"},
	[12091] = {CommonPl = "（新娘蓋著蓋頭，對你的話充耳不聞）"},
	[12127] = {CommonPl = "我的意中人，是個蓋世英雄，總有一天，他會重新回到臨江鎮，用那柄飛刀，來換一塊豆腐。"},
	[12130] = {CommonPl = "到我這來喝酒的客人，有的喜歡追憶往事，有的喜歡憧憬未來，但是也有些人從不回憶過去。這種人並不是沒有事值得回憶，只不過通常都不太願意去想它而已。\r但他們不知有時老時光並不一定就是好時光，未來的事也不是任何人所能預測的。只有“現在”最真實，所以一定要好好把握。"},
	[12133] = {CommonPl = "我一直跟著白燕姑娘，看她在客人面前或悲或喜，或嗔或怒，卻從沒見過她哭。\r也許，這世上只有那柄飛刀才見過她的淚水。"},
	[12136] = {CommonPl = "客官您要去哪？\r只要錢給夠，就是刀山火海我也在所不辭！"},
	[12302] = {CommonPl = "朱文燈下逢劉倩，師厚燕山遇故人。\r隔斷死生終不泯，人間最切是深情。\r話說大唐中和年間，博陵有個才子，姓崔名護，生得風流俊雅，才貌無雙。偶遇春榜動，選場開，收拾琴劍書箱，前往長安應舉。歸當暮春，崔生暫離旅舍，往城南郊外遊賞。但覺口燥咽乾，唇焦鼻熱。一來走得急，那時候也有些熱了。這崔生只為口渴，又無溪澗取水。\r崔生去叩門，覓一口水，立了半日，不見一人出來。正無計結，忽聽得門內笑聲。崔生鷹覷鶻望，去門縫裡一瞧，原來那笑的，卻是一個女孩兒，約有十六歲……"},
	[12305] = {CommonPl = "這催稿可是個技術活，你得看人下菜。\r三兩句話裡，你就得知道面前這人，到底是吃軟不吃硬，還是吃硬不吃軟。"},
	[12308] = {CommonPl = "你知道這世上有什麼事比遇見一個潑婦更為可怕？\r那就是遇見兩個潑婦。"},
	[12311] = {CommonPl = "此番咱可是奉了萬卷樓樓主之命，前來迎接公子的。"},
	[12314] = {CommonPl = "救命啊！救命！"},
	[12517] = {CommonPl = "我也想像你一樣，在自己最美麗的時刻，遇到白公子那樣的人。"},
	[13084] = {CommonPl = "哈哈哈，師父終於肯讓我拜師了！\r嗚嗚嗚，皇天不負有心人，我靜坐九九八十一天終於感動師父了。"},
	[13090] = {CommonPl = "昨天被官兵搶去了包裹，正愁沒盤纏，正巧瑤琴這飯碗送到我面前，真是天無絕人之路啊，哈哈哈！"},
	[13093] = {CommonPl = "你有沒有見過一個五十左右的莊稼漢，那是我爹爹，我們走散了……嗚嗚嗚……"},
	[13096] = {CommonPl = "大官人，若是來福州，不見見花魁娘子，可算是白來一趟。\r你問我那花魁娘子容貌幾何？待老身細細跟您說：\r那花魁娘子可是蛾眉帶秀，鳳眼含情，腰如弱柳迎風，面似嬌花拂水。\r體態輕盈，漢家飛燕同稱；性格風流，吳國西施並美。蕊宮仙子謫人間，月殿嫦娥臨下界。"},
	[13099] = {CommonPl = "道一聲千不該萬不該，不該在大婚之日如此不小心，說了那樣一些話！"},
	[13102] = {CommonPl = "身在煙火之地，連從良也難上加難。\r你可知這從良一事並不簡單，有個真從良，有個假從良；有個苦從良，有個樂從良；有個趁好的從良，有個沒奈何的從良；有個了從良，有個不了的從良。"},
	[13105] = {CommonPl = "群玉院裡的姑娘，各個貌美如花，不論你喜歡清純的，妖豔的；還是溫柔，嬌蠻的，都能在群玉院裡找到。"},
	[13108] = {CommonPl = "老身是個女隨何，雌陸賈，能說得羅漢思情，嫦娥想嫁。"},
	[13111] = {CommonPl = "我願與瑞姑攜手到老，許一生的安定與幸福予她。"},
	[13141] = {CommonPl = "閣下名門，又這般大才，因甚困守在此？若能致力於舉業，必有官作的。\r不如買一本在下新編的八股選本，定然能有所助益。"},
	[13144] = {CommonPl = "如今鏢行這碗飯是越來越難吃了，不知朋友在哪裡發財，可否介紹在下過去？"},
	[13147] = {CommonPl = "學武的人，一輩子動刀動槍，不免多結冤家。臨到老來，寢食難安。\r像衡山城的劉三爺，廣邀賓客，金盆洗手，便是說仇家不必擔心他去報復，卻也盼他們別再來找麻煩。"},
	[13150] = {CommonPl = "客官，您這樣盯著奴家看，是有話要說，還是有情要表？"},
	[13153] = {CommonPl = "客官可是要結帳？和您老有交情的南海霍家，京師李家，江南蘇家已經給您預存了千兩銀子。\r您便是在小店再住上一年半載，怕是也花不完。"},
	[13156] = {CommonPl = "客官，您是打尖還是住店？"},
	[13159] = {CommonPl = "大將生來膽氣豪，腰橫秋水雁翎刀。\r風吹鼙鼓山河動，電閃旌旗日月高。\r天上麒麟原有種，火中螻蟻豈能逃。\r太平待詔歸來日，朕與將軍解戰袍。"},
	[13162] = {CommonPl = "客官一看便是吃過見過的主兒，也嘗嘗咱們悅來客棧的點心可合您脾胃。別的我不敢誇口，絕對是別無分號，正經的“私房菜”。"},
	[13165] = {CommonPl = "掌櫃的讓我小心那姓田的大爺，莫要被他騙去。奴家倒覺得田爺人甚好，不說待人的和氣，花錢的豪爽，便只說那樣的相貌，被他騙去也是福氣。"},
	[13168] = {CommonPl = "我與嬌娜也如這戲裡唱的，她便是傾國傾城貌，我是那多愁多病身。\r既是情比金堅，哪怕海枯石爛。"},
	[13171] = {CommonPl = "我與王郎自私奔離鄉便投宿在這悅來客棧。\r每日裡花銷甚大，他又是個不事稼軒的書生。\r日子久了，坐吃山空，還不知是個什麼結局。"},
	[13174] = {CommonPl = "這位朋友，你是來找我喝酒的，還是來找我喝花酒的，在下都願奉陪。"},
	[13177] = {CommonPl = "今日我卓某人設宴，來者即客。\r這位朋友，你我雖非故交，但既有此緣，便算得是新知了。\r何不坐下，共飲一杯？"},
	[13180] = {CommonPl = "不是我信不過閣下，實在是職責所在。\r閣下要想進去，請先出示官府的牙牌，容小的驗明正身方可入內。"},
	[13183] = {CommonPl = "這些闊少爺真是難伺候。\r分明有人給他下了戰帖，說十日之內要取他人頭。\r他還偏要大肆宴客，生怕別人不能拿他當靶子。"},
	[13186] = {CommonPl = "朝廷命官在此，何處宵小，竟敢擅入。"},
	[13189] = {CommonPl = "大丈夫當朝游碧海而暮宿蒼梧。\r余行路千里，每夜宿悅來客棧，常有幽夢還鄉之感。\r自問緣故，多因老闆娘頗似我管家娘子罷。"},
	[13192] = {CommonPl = "閣下請留步，不知可願將自家過往告知一二？\r如我料的不錯，這江湖上很快便會有人來詢問閣下的消息了。"},
	[13195] = {CommonPl = "速速出去，否則休要怪這刀劍無眼。"},
	[13198] = {CommonPl = "哪裡來的懵懂少年，竟擅闖雅室。"},
	[13201] = {CommonPl = "則為你如花美眷，似水流年，是答兒閑尋遍，在幽閨自憐。"},
	[13204] = {CommonPl = "原來姹紫嫣紅開遍，似這般都付與斷井頹垣。良辰美景奈何天。賞心樂事誰家院。"},
	[13207] = {CommonPl = "除卻還未沐浴我主的光輝，貴國的偉大堪稱舉世無雙。"},
	[13210] = {CommonPl = "此次案件牽扯甚廣，少不得要勞煩閣下這般江湖豪俠相助。"},
	[13213] = {CommonPl = "客官，小賭怡情，何不來試試今天的手氣如何。"},
	[13216] = {CommonPl = "在下一向少在江湖走動，今見閣下，實臥龍鳳雛之屬。不知可有幸結交，共對清歌妙舞。"},
	[13219] = {CommonPl = "這位英雄，別怪我沒提醒您，和我們家公子相交，您還是小心謹慎些的好。"},
	[13222] = {CommonPl = "柳暗青煙密，花殘紅雨飛。\r這人人和柳渾相類，花飛吹得人心碎。\r柳眉不轉蛾眉系，為甚西園陡恁景狼籍。\r正是東君不管人憔悴。"},
	[13225] = {CommonPl = "Ican'tspeakchinese."},
	[13228] = {CommonPl = "猶記初遇劉賢弟，便是在此地。\r共譜笑傲江湖之曲，亦是在此地。\r而眼下我在此撫琴，吹簫人何在？"},
	[13231] = {CommonPl = "客官既然能上這三層，自然是難得的貴人了。\r咱們都是眼拙口笨的婢子，或有個不周全的地方，還望您海涵，莫與奴家一般見識。"},
	[13714] = {CommonPl = "官場險惡，卻也是個體會人生的好地方。\r我最近悟出來的是：很少說話的人，說出來的話通常都比較有分量。"},
	[13757] = {CommonPl = "衙門辦案，閒雜人等一律避讓。"},
	[13760] = {CommonPl = "遷就別人是一種美德，遷就自己就是一種過錯。"},
	[13763] = {CommonPl = "人在做，天在看！\r有多大能耐辦多大事。\r既然當了管事，該做的樣子自然一樣也不能落下。"},
	[14087] = {CommonPl = "子曰，朝聞道，夕死可矣。\r今聽田兄大話風月，真如醍醐灌頂。\r只覺天下女子，皆是不著寸縷，一看即透。"},
	[14093] = {CommonPl = "飛雪渡春，寒梅清舞，好一個梅關古道！此時若能梅下煮酒，便更妙了。"},
	[14099] = {CommonPl = "我自看破紅塵，大師卻道我塵緣未了，遲遲不肯為我剃度。"},
	[14102] = {CommonPl = "呔，攢了五年的錢，一心要買那城東的草房。\r誰知錢可算攢夠了，這洛陽的房價又漲了。\r早知如此，還不如把銀子都拿去花紅苑取樂。"},
	[14105] = {CommonPl = "少爺說若是這件事辦的漂亮，便升小的作後廚總管。\r那時候，哼哼，我倒要看吳媽悔是不悔。"},
	[14108] = {CommonPl = "我真不知是該贊你有膽量，還是笑你太莽撞。\r十年了，你是我的第一個客人。"},
	[14111] = {CommonPl = "少年人是來參禪還是尋人？\r若是參禪，便誠心向佛；若是尋人，還請你回去罷。"},
	[14114] = {CommonPl = "朋友莫要再看了，咱這西瓜不賣。\r你若口渴，前面便是藥王廟，不妨去那裡討口水喝。"},
	[14120] = {CommonPl = "遇到他的事，我都要忘了。\r本就是風過無痕一場邂逅，也不過是等我變成了老太婆，說給孫女聽的奇遇罷了。"},
	[14533] = {CommonPl = "是生是死一場夢，或勝或敗轉頭空！不要太介懷昨日，再戰江湖才是最緊要的！"},
	[14665] = {CommonPl = "過幾日金盆洗手之後，劉某可再也不過問江湖中事了。"},
	[14672] = {CommonPl = "客官可千萬別被那不長眼的酒客掃了雅興，不如晚上去我們衡山城鼎鼎有名的群玉院找找樂子吧！"},
	[14675] = {CommonPl = "#Y，快帶著儀琳離開這裡！田伯光武功高強，我就快撐不住了！"},
	[14678] = {CommonPl = "曲長老帶師父離開，情急之下我也跟了來，好像就在前面。"},
	[14681] = {CommonPl = "令狐大哥……我要留在這裡，令狐大哥是為了救我才受的傷，萬一他有個好歹……嗚……"},
	[14684] = {CommonPl = "師父也來參加劉師叔的金盆洗手大會，咱們快快去找她老人家吧，這樣令狐大哥就有救了！"},
	[14687] = {CommonPl = "師父不在，沒人救得了令狐大哥了！我要趕緊回去看看！"},
	[14690] = {CommonPl = "曲洋該殺！該殺！……不要殺我……不要殺我啊……我什麼也不知道……"},
	[14693] = {CommonPl = "嗚哇——我這是在哪裡？爹爹……對了！嵩山派的壞人差點殺了我，爹爹也被曲叔叔帶走了，不知現在他們在哪，真叫人擔心。"},
	[14696] = {CommonPl = "我……我才不去給大師兄送飯，我……我還要跟小林子練劍去呢，你讓六猴兒帶你去吧。"},
	[14699] = {CommonPl = "聽六猴兒說大師兄受了傷……嗚嗚嗚……都怪我……我要想個法子救救大師兄……"},
	[14702] = {CommonPl = "小猴乖小猴乖，我一定會把你的病治好的……"},
	[14705] = {CommonPl = "這下好了，大師兄在崖上可無聊死啦！你去陪大師兄喝酒，大師兄一定高興的緊。"},
	[14708] = {CommonPl = "大師兄！大師兄哪去了？不好，難道是有宵小闖入了華山派？#N，快快隨我下山看看！"},
	[14711] = {CommonPl = "竟然是氣宗來我華山挑釁！看師父不把他們打的落花流水才怪！"},
	[14714] = {CommonPl = "紫霞秘笈……看來小師妹還是念著大師兄的，這就好，這就好了……"},
	[14717] = {CommonPl = "難道我華山派竟要滅派於此？不會的！#N，沖兒身受重傷，快去看看他怎麼樣了！"},
	[14720] = {CommonPl = "去去去別擋道，我這正在找這身穿白袍的老頭子呢！"},
	[14723] = {CommonPl = "身材高瘦，腰掛彎刀……就算翻遍嵩山，也得找出這人不可！"},
	[14726] = {CommonPl = "小朋友，聽我一句勸，今天這熱鬧，你還是別來湊的好。"},
	[14729] = {CommonPl = "我點蒼雙劍要找的人，從來都是死的！那人今天也不例外！"},
	[14732] = {CommonPl = "今日一定要替教主清理門戶！"},
	[14735] = {CommonPl = "聽說那白袍老人已經逃往仙愁峽了，你也是來圍攻他的吧！"},
	[14738] = {CommonPl = "等一會找到那人，大夥一起上，保准他插翅難逃！"},
	[14741] = {CommonPl = "厲害……太……厲害了……#Y，那人就在前方……今天我看不到他死了，就靠你們了！"},
	[14744] = {CommonPl = "好膽色！老夫交了你這個朋友！"},
	[14747] = {CommonPl = "世人都傳言莫大先生和我家老爺有過節，我看卻並非如此。再說從今往後……莫大先生獨掌門戶，再有什麼閒言碎語，恐怕也都平息了吧……"},
	[14750] = {CommonPl = "今番若不能建寸功，恐怕回去又不好交代了……唉，走一步算一步吧，沒想我堂堂雕俠，今日也得親身來這鳥不生蛋的地方辦事。"},
	[14753] = {CommonPl = "唉，這一路上可把我累壞了，還好撿回一條命，想必命中有這囹圄之困，大難不死必有厚福，大難不死必有厚福！"},
	[14756] = {CommonPl = "高山傾，流水涸。\r新愁易積，故人難聚。\r廣陵一曲成絕響，知音無覓此生休。"},
	[14788] = {CommonPl = "游龍山莊莊主賈原陵家財萬貫，富可敵國，然而為人古道熱腸，看不得行惡之人，作惡之事，但深感人力有限。為揚俠義之名，抑行惡之路。今日，山莊告示：凡英雄俠士剷除四方惡人首領，帶來證據，都可領取相應資財。各位英雄俠士應量力而為，為避免傷及無辜，每日只可領取一次。"},
	[14791] = {CommonPl = "游龍山莊莊主賈原陵家財萬貫，富可敵國，然而為人古道熱腸，看不得行惡之人，作惡之事，但深感人力有限。為揚俠義之名，抑行惡之路。今日，山莊告示：凡英雄俠士剷除四方惡人首領，帶來證據，都可領取相應資財。各位英雄俠士應量力而為，為避免傷及無辜，每日只可領取一次。"},
