	[14809] = {CommonPl = "游龍山莊莊主賈原陵家財萬貫，富可敵國，然而為人古道熱腸，看不得行惡之人，作惡之事，但深感人力有限。為揚俠義之名，抑行惡之路。今日，山莊告示：凡英雄俠士剷除四方惡人首領，帶來證據，都可領取相應資財。各位英雄俠士應量力而為，為避免傷及無辜，每日只可領取一次。"},
	[14812] = {CommonPl = "此去嵩山，不知是福是禍……"},
	[14815] = {CommonPl = "大丈夫能伸能屈，勝負之數，並非決於一時，我看還是先避一避，君子報仇，十年不晚。"},
	[14818] = {CommonPl = "師父一生光明磊落，今日竟然……竟然被人污蔑抱恨而死……\r也好……這樣他就能和曲長老做永遠的知音了。"},
	[14821] = {CommonPl = "多謝#Y冒死相助，老夫感激不盡。"},
	[14824] = {CommonPl = "一入梅關便遭了伏擊，這一路怕是走不太平了。"},
	[14827] = {CommonPl = "咱們便在此處歇歇腳，等少鏢頭前來會合吧。"},
	[14830] = {CommonPl = "都為我一時忍不住氣，殺了一人，以致這許多人為我而死。不知爹娘和鏢局現在如何了。"},
	[14833] = {CommonPl = "幼時吳鏢頭常帶我來梅關打獵，後來此地惡匪為患，才漸漸不來了。\r誰知今日再入梅關，竟是天人永隔！\r吳鏢頭為救我而死，同去不同歸，同去不同歸……"},
	[14836] = {CommonPl = "#N……一路小心！"},
	[14839] = {CommonPl = "咱們分開後，我在這寨中好一番探尋。多虧了捉到這俘虜，才找到這監牢與你會合。"},
	[14842] = {CommonPl = "#N，我心焦得很，若不是為護住我，崔鏢頭他們也不至於……"},
	[14845] = {CommonPl = "老子要再跟你們賭上三百回合！來啊！"},
	[14848] = {CommonPl = "膽敢在我們賭坊賴帳，真是吃了熊心豹子膽了。"},
	[14851] = {CommonPl = "人生在世，會當暢情適意，若是酒不能喝了，女人不能想了，別人欺負到頭上還不能還手？不如及早死了，來的痛快！"},
	[14857] = {CommonPl = "姑姑一向待人極有分寸，可是如今對令狐小友……咳咳，看來我真是老啦……"},
	[14860] = {CommonPl = "什麼江湖紛爭，門派爭鬥，我都不想理會。我只願在這綠竹巷裡，找一位琴瑟和鳴的知音，共奏一曲足矣。"},
	[14863] = {CommonPl = "客官，要什麼裡面請。"},
	[14866] = {CommonPl = "天機不可洩露。"},
	[14869] = {CommonPl = "疼疼疼……哎喲……癢……癢癢癢……救我啊……救我……"},
	[14872] = {CommonPl = "他奶奶的……差點把命丟了，下次見到苗女千萬要繞道走！！"},
	[14875] = {CommonPl = "我看呐，中原的男人沒一個好的。不知教主那個叫令狐沖的朋友，是不是也跟尋常男子一樣。"},
	[16025] = {CommonPl = "快……快去救人……"},
	[16337] = {CommonPl = "屍體是不會回答你的。"},
	[16340] = {CommonPl = "屍體是不會回答你的。"},
	[16343] = {CommonPl = "屍體是不會回答你的。"},
	[16346] = {CommonPl = "若沒了把酒言歡的朋友，就算是迴雁樓的好酒，也沒甚麼滋味。\r可惜那令狐沖……\r可笑可笑，我田伯光萬里獨行，幾時變得這般矯情。\r來來來，咱們樓上喝個痛快！"},
	[16349] = {CommonPl = "屍體是不會回答你的。"},
	[16352] = {CommonPl = "這尼姑姐姐長得可真美。"},
	[16355] = {CommonPl = "她什麼事情都看不開，是做不了尼姑的。"},
	[16358] = {CommonPl = "華山派的小子和田伯光小賊的眼光倒是都不差。"},
	[16361] = {CommonPl = "嵩山派雖然人多勢眾，左盟主武功蓋世，咱們華山派卻也寧死不屈。"},
	[16364] = {CommonPl = "師父師娘有命，弟子赴湯蹈火，在所不辭。"},
	[16367] = {CommonPl = "嵩山派總算要動手了。"},
	[16370] = {CommonPl = "事到如今，只有走一步算一步了。"},
	[16373] = {CommonPl = "師父師娘有命，弟子赴湯蹈火，在所不辭。"},
	[16376] = {CommonPl = "師父師娘有命，弟子赴湯蹈火，在所不辭。"},
	[16379] = {CommonPl = "情勢兇險，先保住性命要緊。"},
	[16382] = {CommonPl = "不要緊！"},
	[16385] = {CommonPl = "如今只有拼死一戰，可不能墜了華山派的威名。"},
	[16388] = {CommonPl = "背靠著背，不要讓敵人有可趁之機。"},
	[16391] = {CommonPl = "小林子，你不要緊吧！"},
	[16394] = {CommonPl = "我華山派數百年令名，豈可在我手中葬送！"},
	[16397] = {CommonPl = "岳老兒受了傷，累也累死了他！"},
	[16400] = {CommonPl = "岳先生，我們跟你無冤無仇，今晚冒昧得罪，只不過想借那《辟邪劍譜》一觀。"},
	[16403] = {CommonPl = "大夥兒右手拾起兵刃，左手拉住同伴腰帶，一起走啊！"},
	[16406] = {CommonPl = "大夥兒右手拾起兵刃，左手拉住同伴腰帶，跟著我去！"},
	[16409] = {CommonPl = "屍體是不會回答你的。"},
	[16412] = {CommonPl = "膽敢在我們賭坊賴帳，真是吃了熊心豹子膽了。"},
	[16415] = {CommonPl = "要不是這個渾人惹事，我下把說不定就大胡特胡了。"},
	[16418] = {CommonPl = "令人恐懼的毒蠍。"},
	[16421] = {CommonPl = "令人恐懼的毒蛛。"},
	[16424] = {CommonPl = "令人恐懼的毒蛇。"},
	[16427] = {CommonPl = "我點蒼雙劍要找的人，從來都沒有活下來的！那人今天也不例外！"},
	[16430] = {CommonPl = "別擋路，可不要讓向老兒逃了！"},
	[16433] = {CommonPl = "別擋路，可不要讓向老兒逃了！"},
