	[16535] = {CommonPl = "今天一定要殺了向問天，為我正道除害！"},
	[16538] = {CommonPl = "今天一定要殺了向問天，為我正道除害！"},
	[16541] = {CommonPl = "今天一定要殺了向問天，為我正道除害！"},
	[16544] = {CommonPl = "今天一定要殺了向問天，為我正道除害！"},
	[16547] = {CommonPl = "今天一定要殺了向問天，為我正道除害！"},
	[16550] = {CommonPl = "今天一定要殺了向問天，為我正道除害！"},
	[16553] = {CommonPl = "若能殺了向問天，我就能揚名天下了！"},
	[16556] = {CommonPl = "若能殺了向問天，我就能揚名天下了！"},
	[16559] = {CommonPl = "若能殺了向問天，我就能揚名天下了！"},
	[16562] = {CommonPl = "今天一定要殺了向問天，為我正道除害！"},
	[16565] = {CommonPl = "今天一定要殺了向問天，為我正道除害！"},
	[16568] = {CommonPl = "今天一定要殺了向問天，為我正道除害！"},
	[16571] = {CommonPl = "殺了叛徒向問天！"},
	[16574] = {CommonPl = "殺了叛徒向問天！"},
	[16577] = {CommonPl = "殺了叛徒向問天！"},
	[16580] = {CommonPl = "我自和向老前輩喝酒，礙你什麼事了？"},
	[16634] = {CommonPl = "#N，莫要管我，保護好少鏢頭要緊！"},
	[16637] = {CommonPl = "這一路的梅花倒好。只是這樣安靜，總覺得有些不妥，但願是我多心。"},
	[16640] = {CommonPl = "吳鏢頭身受重傷，倒在血泊之中，已然氣絕。"},
	[16646] = {CommonPl = "這次多虧#Y，咱們才能化險為夷。改日#N再來福州，可一定要與咱眾兄弟把酒言歡！"},
	[16649] = {CommonPl = "車轔轔，馬蕭蕭，行人弓箭各在腰。"},
	[16652] = {CommonPl = "車轔轔，馬蕭蕭，行人弓箭各在腰。"},
	[16655] = {CommonPl = "車轔轔，馬蕭蕭，行人弓箭各在腰。"},
	[16658] = {CommonPl = "車轔轔，馬蕭蕭，行人弓箭各在腰。"},
	[16662] = {CommonPl = "#N，前面便是梅關古道了。"},
	[16667] = {CommonPl = "曲洋、劉正風二位前輩的合葬之墓。"},
	[16686] = {CommonPl = "劉老爺子金盤洗手，我等一定要前來拜賀。"},
	[16689] = {CommonPl = "劉老爺子金盤洗手，我等一定要前來拜賀。"},
	[16692] = {CommonPl = "劉老爺子金盤洗手，我等一定要前來拜賀。"},
	[16695] = {CommonPl = "劉老爺子金盤洗手，我等一定要前來拜賀。"},
	[16698] = {CommonPl = "劉老爺子金盤洗手，我等一定要前來拜賀。"},
	[16701] = {CommonPl = "劉老爺子金盤洗手，我等一定要前來拜賀。"},
	[16704] = {CommonPl = "劉老爺子金盤洗手，我等一定要前來拜賀。"},
	[16707] = {CommonPl = "劉老爺子金盤洗手，我等一定要前來拜賀。"},
	[16887] = {CommonPl = "綠竹巷裡的婆婆，是個溫柔善良的好人。"},
	[16898] = {CommonPl = "無量天尊！此地妖氣彌天，似乎隱有億萬妖魔鬼怪，爾等速速前去查探。"},
	[16901] = {CommonPl = "客人是來找我家主人的嗎？可惜主人遠遊已久，不知歸期。"},
	[16904] = {CommonPl = "蘇堤亭柱上似是刻著一行字，風化日久，模糊難辨。"},
	[16907] = {CommonPl = "昔日地藏王菩薩發大願，“眾生渡盡，方證菩提。地獄不空，誓不成佛”。\r貧僧雖無力發此宏願，只望能渡一個，便是一個。"},
	[16910] = {CommonPl = "佛不渡我，我自成魔。\r朋友你又何必帶我去尋什麼佛光，豈不是犯了佛家所謂的“我執”。"},
	[16913] = {CommonPl = "佛光普照，明亮，溫暖，如慈母懷抱。"},
	[16916] = {CommonPl = "曠野無人，只停著一輛馬車。一望便知是匹識途老馬。"},
	[16919] = {CommonPl = "要問我作個好管家的秘訣，那就只有嘴嚴，嘴嚴，還是嘴嚴。妄議主家秘事的管家，往往要變成死管家。"},
	[16922] = {CommonPl = "你問我老頭子哪去了？笑話，他只是老頭子，又不是我老婆子！\r江湖人雖給我們一個“黃河老祖”的匪號，但我可受不住日日夜夜的和他共處。"},
	[16925] = {CommonPl = "#N，多加小心，暗裡似乎已有人盯上我們。"},
	[16928] = {CommonPl = "忽逢幽人，如見道心。\r何時我才能像聖姑那般，碰到自己命定之人呢。"},
	[16931] = {CommonPl = "這仙霞嶺惡匪為患，\r連官家的糧草都照劫不誤！\r委實駭人。"},
	[16937] = {CommonPl = "若我此入江湖，能得三兩知己，吾生足矣，絕不相棄。"},
	[17129] = {CommonPl = "我是一個包袱，袱袱袱袱袱袱袱袱袱袱袱袱。"},
	[18510] = {CommonPl = "好似南萁北斗，若想出人頭地就得講人脈，講氣運，若有朝一日能略有修為，你周遭的朋友就能因你而得益，你若是有心人且聽完我這幾句話。"},
	[18513] = {CommonPl = "有本事能吸引別人的人，絕對不會是一個普通人，你記住我的話。"},
	[18516] = {CommonPl = "有名望自然會得到別人的敬仰，我們常會抬頭去看一個人，你可想過終會有一天，變得和他一樣。"},
	[18519] = {CommonPl = "師徒之間的禮儀，豈是一兩句可以說得清，如果你真是有心來學，我便助你，如若無心，請閣下自便。"},
	[18563] = {CommonPl = "鏢師背受數刀，刀刀見骨，死於馬上。"},
	[18579] = {CommonPl = "我的松風劍法，可是餘觀主親傳的！你要來領教領教嗎？"},
	[18799] = {CommonPl = "我本是在和爺爺前去衡山城拜訪劉公公的路上。\r可一見這潭水清澈沁涼，便忍不住貪玩，和爺爺走散了。"},
	[18802] = {CommonPl = "嵩山派的陸師兄邀我同去華山為那劍宗兄弟撐腰，怎麼船早來了，他們人卻未到。\r莫不是劍宗的師叔也和那氣宗的徒兒一樣，也被咱衡山城的群玉苑迷住了魂魄。"},
	[18805] = {CommonPl = "東方教主游幸夜雨西湖，狂妄豎子還不速速退下！"},
	[18808] = {CommonPl = "江湖爭鬥本是庸人自擾，卻想不到你這樣的人竟也無法參透。"},
	[18811] = {CommonPl = "江湖爭鬥本是庸人自擾，卻想不到你這樣的人竟也無法參透。"},
	[18814] = {CommonPl = "江湖爭鬥本是庸人自擾，卻想不到你這樣的人竟也無法參透。"},
	[18817] = {CommonPl = "江湖爭鬥本是庸人自擾，卻想不到你這樣的人竟也無法參透。"},
	[18820] = {CommonPl = "想不到這福州城賣酒的生意竟這樣好做。\r我此次再入福州，便要細細考察一番。若真有一日歸隱江湖，也算是個不錯的營生。\r不知閣下可願入夥？"},
	[18823] = {CommonPl = "若可每日在此吸取天地精華，煉氣化神，武功必能大有進益。\r只可惜師命在身，又將遠行。"},
	[18850] = {CommonPl = "藥王廟一戰後，在下心灰意冷。\r行至武當，卻見此地蒼松翠柏，走獸鳴禽。\r造化靈秀，竟這般可親可愛。遙想昨日，真真一葉障目，一夢十年。"},
	[18856] = {CommonPl = "我只出去一趟，回來竟是天人永隔！甚至連在黑木崖立塊墓碑都不能，只得埋骨這荒山野嶺。\r二位兄弟九泉之下安息吧，我定要向東方兄弟為你們討回公道！"},
	[18859] = {CommonPl = "想泰山派當年多少豪邁，如今也都風流雲散，竟是連徒弟都招不到了。"},
	[18862] = {CommonPl = "昔日青城上人創吾青城派，傳至今日數百年矣。\r奉守無致虛之訣，修天地風雲之功。"},
	[18865] = {CommonPl = "劉賢弟不肯讓我出手相助，只一味令我在此等他消息。\r可方才琴弦無故而斷，難道……"},
	[18877] = {CommonPl = "肌理細膩，骨肉停勻。寶相莊嚴，眼目慈悲。\r最難得是這個“純”字，在下在此處揣摩數日，仍無法參透。"},
	[18880] = {CommonPl = "怎麼，莫非閣下也是同道中人，要來這黃土陵死人塚裡借銀子？"},
	[18883] = {CommonPl = "五年前，我與爹娘在此登高望遠。\r一年前，我與靈珊在此採菇做菜。\r今日，我卻在此偷練本是我林家的《辟邪劍法》。\r天地不仁，竟以愚人為樂。頃刻翻覆，真叫人手足無措。"},
	[19080] = {CommonPl = "……"},
	[19081] = {CommonPl = "……"},
	[19082] = {CommonPl = "想我莊上曾是天下第十一大門派，哎……"},
	[19095] = {CommonPl = "……"},
	[19126] = {CommonPl = "這年頭掙錢養家糊口不容易啊。"},
	[19155] = {CommonPl = "劍氣森森，龍吟隱隱。\r這劍陵下必是鎮著一把絕世寶劍。"},
	[21888] = {CommonPl = "天上的事我知道一半，地上的事我全知道。"},
	[21895] = {CommonPl = "在下青城派新進弟子何人軒，閣下遠道而來有何貴幹？"},
	[21907] = {CommonPl = "人想忘記一件事情，為什麼會那麼難……"},
	[21910] = {CommonPl = "六扇門聽說過吧，六扇門女捕頭……沒聽說過吧，俺就是！"},
	[21913] = {CommonPl = "我相信不出三年，我們青城派就是武林第一大派！"},
	[21916] = {CommonPl = "在青城山上，你可得安生點，別給我們捅出什麼簍子來。"},
	[21919] = {CommonPl = "如果不反抗，\r就只有死路一條！\r兄弟們，\r為了自由，\r讓我們集結起所有人，\r無論前方是平坦還是坎坷，\r大家隨我殺出一條血路。"},
	[21922] = {CommonPl = "#N#X，多虧你出的力，\r兄弟們都成功逃出來了！\r下雨了，\r估計敵人會很快追過來，\r大家還是分頭逃吧。"},
	[21925] = {CommonPl = "看到了吧，\r這麼多礦石，\r得全部運到過去才能鑄成劍。\r快裝備車走吧，\r白把頭還在前面等著呢。"},
	[21928] = {CommonPl = "前面是監工的營房，\r等會兒沖過去必然少不了一場打鬥。"},
	[21931] = {CommonPl = "下雨了啊，\r想必雨過必將天晴，\r兄弟們一定會一帆風順的。"},
	[21934] = {CommonPl = "大夥兒這幾段時間辛苦了，\r想鑄成劍，確實得累累啊。\r不過即使鑄成了劍，\r劍順不順手，鋒不鋒利似乎更重要。"},
	[21937] = {CommonPl = "#N，你剛營救的礦工，\r也會和你一起衝鋒的，\r敵人打不過我們。"},
	[21940] = {CommonPl = "聚聚散散，\r剛幾天的夥伴就得在這分手了。\r不過我並不擔心，\r從大家的團結上，\r相信沒有什麼困難是大家斬不斷的。"},
	[21943] = {CommonPl = "剛才聽說這些不要臉的宦官，\r他們打算讓我們做完活，\r就把我們全在這山凹裡殺掉。\r看來不反抗是沒有出路了。"},
	[21946] = {CommonPl = "#N#Y，\r等會請大家奮勇殺敵啊。\r不要擔心其它，\r大家都有集結號的保護，\r不會輕易受重傷的。"},
	[21949] = {CommonPl = "雖然我們都是普通人，\r但只要團結起來，\r沒有什麼無法克服的困難。\r縱然前面有大山擋著，\r我們還可以愚公移山嘛。"},
	[21952] = {CommonPl = "誰想逃跑的話，\r後果就和這些被抓的監工一樣！"},
	[21955] = {CommonPl = "呼……呼……呼……"},
	[21958] = {CommonPl = "一個大木架，奴隸被鎖在裡面。"},
	[21961] = {CommonPl = "#N#X，\r謝謝你剛才救了我。\r並非我等想反，實乃宦官當權無道。"},
	[21964] = {CommonPl = "別看我這個小店鋪不怎麼樣，\r但來我這的可都是名人異士。\r不信，\r你看一看就知道了。"},
	[21967] = {CommonPl = "（青衫客一話不說……）"},
	[21970] = {CommonPl = "問個錘子，\r知道多了對自己不好。"},
	[21973] = {CommonPl = "還是我們那氣侯好，\r休息時打打麻將好巴適。"},
	[21976] = {CommonPl = "那個瓜娃子，\r敢踩我們的地皮，\r還不知道老子們的厲害。"},
	[21979] = {CommonPl = "#N你來了，\r隨便推一輛車走吧，\r向把頭那邊正等著裝貨呢。"},
	[21982] = {CommonPl = "我從小無父無母，是師父把我撫養長大，師兄妹對我也都很好，特別是師兄……\r那些失去親人的村民，他們一定比我當年更加傷心。"},
	[21985] = {CommonPl = "難道是五仙教？龍游鎮村民與他們無冤無仇，為何會做出這等殘忍的事？\r師父說邪教中人，喜怒無常，拿殺人當家常便飯，看來果然是真的了！"},
	[21988] = {CommonPl = "#N，前兩天師姐說師兄在樂山出現了，\r可是我再問她其他消息，她就死也不肯告訴我了。\r這可如何是好？！"},
	[22000] = {CommonPl = "很多村民們都受了傷，需要儘快去醫治，沒別的事的話我要繼續煎藥了。"},
	[22003] = {CommonPl = "瑤草真是個傻姑娘……\r我早跟他說過，項凌雲不在她身邊，我會代替他，對她加倍的好，可是……可是……\r她連做替身的機會……也不曾留給我……"},
	[22006] = {CommonPl = "瑤草和凌雲師兄，真是天生一對，要不是出了那件事，先如今他倆也該成親了吧。"},
	[22009] = {CommonPl = "瑤草師妹真是心地善良，又有耐心，換過是我，給那麼多傷患換藥，早就煩了。"},
	[22012] = {CommonPl = "師父讓我們下山尋找凌雲師兄……不料卻碰到了這樣的事。"},
	[22015] = {CommonPl = "那艘大船擱淺，就牽扯出這麼多事來。\r若是我偷吃阿果零食的事被發現了，豈不是會有更多更嚴重的事被牽扯進來？"},
	[22018] = {CommonPl = "等我處理完大船殘骸，拿回香囊，再把解藥給那男子，就可以離開這裡啦。"},
	[22021] = {CommonPl = "聽說附近的龍遊鎮被毀了，到底他們是得罪了什麼人呢?"},
	[22024] = {CommonPl = "嗚嗚嗚嗚……我要姐姐……我要姐姐……"},
	[22027] = {CommonPl = "#N#Z，路上的山雞可厲害啦，你可要保護好我喲。"},
	[22030] = {CommonPl = "瑤草姐姐說一會就帶我找我娘去，讓我在這裡等她辦完一件重要的事再回來。"},
	[22033] = {CommonPl = "真是福無雙至禍不單行，不光村子被燒了，竟然連孩子們也……"},
	[22036] = {CommonPl = "我的二毛啊！苦命的孩子……娘再也看不到你了啊，嗚嗚嗚……"},
	[22039] = {CommonPl = "多虧了峨嵋派的仙女搭救，不然我這條小命可就玩完啦。"},
	[22042] = {CommonPl = "這裡是哪裡啊……我想我娘……嗚嗚嗚……"},
	[22045] = {CommonPl = "這裡是哪裡啊……我想我娘……嗚嗚嗚……"},
	[22048] = {CommonPl = "這裡是哪裡啊……我想我娘……嗚嗚嗚……"},
	[22128] = {CommonPl = "青城四秀的名頭，在武林之中威名遠播，只可惜自從羅師弟被令狐沖那廝戕害之後，我們四秀只剩下三人……大為不美，大為不美啊！"},
	[22130] = {CommonPl = "青城派乃是蜀中名門，我可是本派大弟子，要想入派先要過我這一關。怎麼過關？嘿嘿，那就看你識不識相了。"},
	[22131] = {CommonPl = "人無橫財不富，馬無夜草不肥。要想發財，還是得幹點旁門左道之事啊！"},
	[22132] = {CommonPl = "如今江湖上都知我們青城派挑了福威鏢局，雖不明言，恐怕此事於我派聲譽已然大大有損。"},
	[22134] = {CommonPl = "哼，馬師兄就是膽小怕事，那林家人學藝不精，也怨不得我們手狠。"},
	[22137] = {CommonPl = "我師父的摧心掌乃是武林之中一門絕學，我也只見師父使過幾次，就是在福州城挑福威鏢局總局的時候，嘿嘿……，掌風凌厲卻又悄無聲息，當真厲害！"},
	[22138] = {CommonPl = "昔日青城上人創吾青城派，傳至今日數百年矣。\r奉守無致虛之訣，修天地風雲之功。"},
	[22200] = {CommonPl = "我相信不出三年，我們青城派就是武林第一大派！"},
	[22201] = {CommonPl = "在青城山上，你可得安生點，別給我們捅出什麼簍子來。"},
	[22202] = {CommonPl = "我相信不出三年，我們青城派就是武林第一大派！"},
	[22203] = {CommonPl = "在青城山上，你可得安生點，別給我們捅出什麼簍子來。"},
	[22228] = {CommonPl = "這福州城可是好地方，鐘天地之秀，聚日月之華，人傑地靈，天寶人和，各色英雄人物層出不窮。"},
	[22231] = {CommonPl = "每年北燕南飛之時，此地就落滿了過冬的候鳥。就像此地的離人，始終只是過客。"},
	[22234] = {CommonPl = "多謝你救了我一命。"},
	[22235] = {CommonPl = "（何人軒躺在地上一動不動，身體早已冰涼……）"},
	[22379] = {CommonPl = "一口大鍋飄出陣陣美味……\r看來這是宦官監工們的食物。"},
	[22382] = {CommonPl = "鍋中飄出的味道更香了……\r這下有好戲看嘍。"},
	[22385] = {CommonPl = "如果不反抗，\r就只有死路一條！\r兄弟們，\r為了自由，\r讓我們集結起所有人，\r無論前方平坦還是坎坷，\r大家隨我殺出一條血路！"},
	[22388] = {CommonPl = "前面快撐不住了，快去支援！"},
	[22391] = {CommonPl = "看樣子我不得不出手了……"},
	[22394] = {CommonPl = "快放火把營房全燒掉！"},
	[22397] = {CommonPl = "為了自由！"},
	[22400] = {CommonPl = "為了自由！"},
	[22403] = {CommonPl = "為了自由！"},
	[22406] = {CommonPl = "為了自由！"},
	[22409] = {CommonPl = "敢在咱家門口打架，\r就算你自己闖到鬼門關了！"},
	[22412] = {CommonPl = "這幫傢伙不想活了，\r快來人幫忙啊！"},
	[22415] = {CommonPl = "一座柵欄擋住了去路。"},
	[22443] = {CommonPl = "馬太尉上面派下活來了，\r得在十天內打造一千把兵器。\r如果不能按時完成，\r你們就別想再見自己的家人了！"},
	[22446] = {CommonPl = "看什麼看，\r咱家四處巡邏，盯的就是你！"},
	[22449] = {CommonPl = "快別休息了，\r眼瞅著太陽都快下山，\r今天怎麼也得把所有礦石全運過去，\r不然大家都得吃不了兜著走。\r什麼，\r你不知道去哪領車，\r旁邊的老劉那就是。"},
	[22968] = {CommonPl = "奉上命嚴查進出大理城人員，請出示路引。"},
	[22971] = {CommonPl = "世人只道蠱蟲毒人心腸，卻不知人心更比蠱蟲毒上百倍。"},
	[22974] = {CommonPl = "晦氣，晦氣，才入劍閣這馬車便壞了。\r旁邊那個牽驢的小老兒，誇下海口說自己點哪傳哪。\r其實卻連修車都不會！"},
	[22977] = {CommonPl = "政治合格，軍事過硬。\r作風優良，紀律嚴明。\r保障有力，服務到位。\r守衛西安，從我做起。\r過橋過路，請交雜費。"},
	[22980] = {CommonPl = "來來來，走過路過千萬不要錯過！\r您有錢的捧個錢場，沒錢的捧個人場。\r胸口碎大石，吞刀吐火球，真正賣藝不賣身的好把式嘞！"},
	[22983] = {CommonPl = "千年石俑雖保經風霜，佈滿溝壑，卻蘊藏著難以言喻的生命力。\r靠近石俑，竟似能聽見來自千年的呼喚。"},
	[22986] = {CommonPl = "你，想看看我的臉嗎……"},
	[23013] = {CommonPl = "看樣子不把周圍的柵欄都燒掉，\r還真難以再逃出去。"},
	[23016] = {CommonPl = "多少長安名利客，機關算盡不如君。\r朋友此入西安，定有一番不俗作為。\r江湖再見。"},
	[23061] = {CommonPl = "敢上青城山鬧事，貧道今天叫你們有來無回！"},
	[23067] = {CommonPl = "青城派乃是蜀中名門，我可是本派大弟子，要想入派先要過我這一關。怎麼過關？嘿嘿，那就看你識不識相了。"},
	[23344] = {CommonPl = "我常常想，也許我們與南邊的朝廷，不應該是對立和戰爭，只要能讓兩邊的老百姓都過上好日子，誰佔據更多的土地，又有什麼意義呢？"},
	[23347] = {CommonPl = "俺答汗大人是我們族群最有威望的人，大家都信任他。"},
	[23350] = {CommonPl = "美麗的草原我的家\r風吹綠草遍地花\r彩蝶紛飛白鳥唱\r一彎碧水映彩霞"},
	[23353] = {CommonPl = "我們部族是黃金家族的後裔，黃金家族就是我們蒙古最偉大的成吉思汗大汗的皇族。說了這麼半天，就是說我是皇族……嗯，你懂了吧……"},
	[23356] = {CommonPl = "大汗之魂永照我心……"},
	[23359] = {CommonPl = "小女子已見慣了這草原上的殺伐征戰，若是舍我一命，能讓大家止戰息戈，我真是歡喜得緊。可這畢竟是癡念，天下之大，又有誰能逃過那權力的欲望呢？"},
	[23362] = {CommonPl = "阿日善姐姐就像是我們部族的聖女一樣，純潔和高貴。"},
	[23365] = {CommonPl = "我是俺答汗的兒子，天不怕地不怕的，誰也別想勸我回去！"},
	[23368] = {CommonPl = "嗡嘛呢叭咪吽！諸佛密乘咒，諸法集精英，眾生現祥瑞，灌頂六字明！"},
	[23371] = {CommonPl = "歡迎你，遠方而來的客人！"},
	[23374] = {CommonPl = "阿媽說，我的名字是雄獅的意思，期望我如雄獅一樣。"},
	[23377] = {CommonPl = "蒙古草原上的狼，據說是最兇猛的，可以殺死猛虎和黑熊。"},
	[23380] = {CommonPl = "我的孩子啊，我在找我的孩子！"},
	[23383] = {CommonPl = "一切眾生，真如法性，不生不滅，不垢不淨，不增不減，真如體、相、用的法、報、化三身本自具足，不必向外馳求。"},
	[23386] = {CommonPl = "活佛坐化，萬民同哀！這瓦剌卻居然想趁此機會控制大金光寺，實在是可恨。"},
	[23389] = {CommonPl = "草原男兒就像天上的飛鷹，地上的蒼狼一樣，豪爽、勇猛。"},
	[23392] = {CommonPl = "我心愛的阿哥他叫帖木兒，他就像是溫暖的陽光，照耀在我的心裡。"},
	[23395] = {CommonPl = "空則惑，幼則真，城則深，深則滿，滿則空。"},
	[23414] = {CommonPl = "凡是來往於黑木崖之人，必須持有神教所發通關文碟。閒雜人等，一律不許通過。"},
	[23417] = {CommonPl = "近幾年來教中事物都由那楊蓮亭掌管，他不管別的，專管陷害教中長老。\r如今的日月神教，真是金玉其外，敗絮其中了。"},
	[23420] = {CommonPl = "我本是在神教正殿供職的長老，舊日承蒙任教主多方關照。\r東方不敗登基之日，任教主失蹤了，迫於壓力我決定潛伏下來，暗暗尋找教主蹤跡。"},
	[23423] = {CommonPl = "聖姑的眼光果然不錯，若是沒有你，真不知那荒火教會做出什麼事。"},
	[23426] = {CommonPl = "我常想，若我不是聖姑，他也不是華山派弟子，我就能從此不管教中事務，他也放下正邪之爭，一輩子在綠竹巷相伴到老，便也是好的。"},
	[23429] = {CommonPl = "現在教主閉關潛心修煉武藝，承蒙教主錯愛，教內事務，暫時由楊某代管。"},
	[23432] = {CommonPl = "今朝有酒今朝醉……\r明日愁來明日憂。"},
	[23462] = {CommonPl = "游龍山莊莊主賈原陵家財萬貫，富可敵國，然而為人古道熱腸，看不得行惡之人，作惡之事，但深感人力有限。為揚俠義之名，抑行惡之路。今日，山莊告示：凡英雄俠士剷除四方惡人首領，帶來證據，都可領取相應資財。各位英雄俠士應量力而為，為避免傷及無辜，每日只可領取一次。"},
	[23465] = {CommonPl = "游龍山莊莊主賈原陵家財萬貫，富可敵國，然而為人古道熱腸，看不得行惡之人，作惡之事，但深感人力有限。為揚俠義之名，抑行惡之路。今日，山莊告示：凡英雄俠士剷除四方惡人首領，帶來證據，都可領取相應資財。各位英雄俠士應量力而為，為避免傷及無辜，每日只可領取一次。"},
	[23468] = {CommonPl = "游龍山莊莊主賈原陵家財萬貫，富可敵國，然而為人古道熱腸，看不得行惡之人，作惡之事，但深感人力有限。為揚俠義之名，抑行惡之路。今日，山莊告示：凡英雄俠士剷除四方惡人首領，帶來證據，都可領取相應資財。各位英雄俠士應量力而為，為避免傷及無辜，每日只可領取一次。"},
