	[23477] = {CommonPl = "游龍山莊莊主賈原陵家財萬貫，富可敵國，然而為人古道熱腸，看不得行惡之人，作惡之事，但深感人力有限。為揚俠義之名，抑行惡之路。今日，山莊告示：凡英雄俠士剷除四方惡人首領，帶來證據，都可領取相應資財。各位英雄俠士應量力而為，為避免傷及無辜，每日只可領取一次。"},
	[23480] = {CommonPl = "游龍山莊莊主賈原陵家財萬貫，富可敵國，然而為人古道熱腸，看不得行惡之人，作惡之事，但深感人力有限。為揚俠義之名，抑行惡之路。今日，山莊告示：凡英雄俠士剷除四方惡人首領，帶來證據，都可領取相應資財。各位英雄俠士應量力而為，為避免傷及無辜，每日只可領取一次。"},
	[23483] = {CommonPl = "游龍山莊莊主賈原陵家財萬貫，富可敵國，然而為人古道熱腸，看不得行惡之人，作惡之事，但深感人力有限。為揚俠義之名，抑行惡之路。今日，山莊告示：凡英雄俠士剷除四方惡人首領，帶來證據，都可領取相應資財。各位英雄俠士應量力而為，為避免傷及無辜，每日只可領取一次。"},
	[23486] = {CommonPl = "游龍山莊莊主賈原陵家財萬貫，富可敵國，然而為人古道熱腸，看不得行惡之人，作惡之事，但深感人力有限。為揚俠義之名，抑行惡之路。今日，山莊告示：凡英雄俠士剷除四方惡人首領，帶來證據，都可領取相應資財。各位英雄俠士應量力而為，為避免傷及無辜，每日只可領取一次。"},
	[23489] = {CommonPl = "游龍山莊莊主賈原陵家財萬貫，富可敵國，然而為人古道熱腸，看不得行惡之人，作惡之事，但深感人力有限。為揚俠義之名，抑行惡之路。今日，山莊告示：凡英雄俠士剷除四方惡人首領，帶來證據，都可領取相應資財。各位英雄俠士應量力而為，為避免傷及無辜，每日只可領取一次。"},
	[24608] = {CommonPl = "這位朋友看起來好眼熟，很像是在下一位故人。\r只是記憶裡那位故人並並沒有朋友這樣好身手。"},
	[24611] = {CommonPl = "湯鮮肉爛滋味美，老孫從不跟你吹。\r南來北往嘗一碗，絕對不讓你後悔。"},
	[24614] = {CommonPl = "驛站竟這麼安靜，莫不是出了什麼事？"},
	[24617] = {CommonPl = "這次如能找回少鏢頭，重振福威鏢局。我便是死了，也能在總鏢頭和夫人面前有個交代了。"},
	[24620] = {CommonPl = "無論如何，我老趙也要把這福威鏢局撐下去！"},
	[24623] = {CommonPl = "一把鋒利的飛刀將信箋深紮在客棧的木柱之上。"},
	[24626] = {CommonPl = "唉，那位華山派的姑娘必是對我有情，才會出手相助。\r可惜她功夫尚淺，幾個回合便被賊人的頭目給制服了。\r只恨為何沒將我倆關在一處，錯失了這段風月佳話。"},
	[24629] = {CommonPl = "俺本是在客棧裡喝茶歇腳，忽然就被這群人綁了來。\r綁來也就罷了，看他們也沒甚惡意，只是把俺和這聒噪的小白臉關在一處，實在讓人火大。"},
	[24632] = {CommonPl = "三個壯漢！三個壯漢啊！\r就這麼團團把小女子圍住，荒山野嶺的，真是喊破喉嚨也沒人理啊。\r多虧你來的及時，不然，不然小女子真是……"},
	[24635] = {CommonPl = "我隱隱約約聽那些人說是要為一位華山派的棄徒討公道，才把我們這些老百姓綁來。\r這究竟是什麼緣故？他們自去江湖紛擾，與我們這些平頭百姓有何相干。"},
	[24638] = {CommonPl = "師兄看到我的信號，現在應該已經趕到山下了吧。"},
	[24641] = {CommonPl = "上次講到少林寺的方正大師，大師贈我一言：\r“因愛而生憂，因愛而生怖。或使離愛者，無憂亦無怖。”\r可是，若能相離，便不是愛了。"},
	[24644] = {CommonPl = "看到師妹發的信號，我便急急下山來。\r卻被海砂幫的人攔住去路，這些人來者不善，到底所為何事。"},
	[24647] = {CommonPl = "這位桑綺姑娘天然質樸，頗有真味，較之那位楚然姑娘的明豔潑辣，別有一番情趣。\r可謂“落花無言，人淡如菊”。"},
	[24650] = {CommonPl = "老闆娘，趕緊燙壺熱酒來！\r這一天，過得忒不太平。\r可要好好喝上幾杯，去去晦氣。"},
	[24653] = {CommonPl = "客官，還沒看出來嗎，那位公子哥是看上我們桑綺姑娘了。\r只是我也看桑綺這丫頭甚好，本想說媒給我那在西安城當兵的表弟的。\r那些讀書人，嘴上說的好聽，終究不是什麼好依靠。"},
	[24656] = {CommonPl = "這位書生待人倒是親切得很，不似那私塾裡的夫子，總說些“唯女子與小人難養也”的鬼話。"},
	[24659] = {CommonPl = "此地不宜久留，我還是和師兄早日回師門向師父稟明一切，請師父定奪才是。"},
	[24662] = {CommonPl = "咱們這次來華山，就是要為令狐兄弟討個公道！"},
	[24665] = {CommonPl = "“忽逢幽人，如見道心”。\r只是……幽人自往來，此心何所寄？"},
	[24668] = {CommonPl = "師妹自被人俘虜後再回來，便一直神情恍惚，莫不是被那些妖邪之輩下了什麼毒蠱？"},
	[24671] = {CommonPl = "忍春心，妒遍天涯草。\r不遇他，倒還好！"},
	[24674] = {CommonPl = "不止那女人的心思摸不透，男人的心思也都是海底針。\r這令狐兄弟到底是怎麼想的！"},
	[24773] = {CommonPl = "天下之大，江湖之廣，即便是仙人也不可能盡知盡覺。所以我只知道一半的江湖事。"},
	[24918] = {CommonPl = "現在看來，此事確實有些令人費解，你看前面那條路上，山匪橫行，不少路人都慘遭打劫。按說來往此地的都是些書生，身邊並無甚貴重財物，這些山匪為何在此設障？不如#Y跟我走一趟，去探探這些山匪的來路。"},
	[24921] = {CommonPl = "平涼書院歷史悠久，每年來應試的考生不計其數，但今年臨考之前，卻突然傳出今年取消考試的消息。大部分考生惋惜之余都去報考別的書院，不過此事蹊蹺，所以我決定還是來此看看。"},
	[24924] = {CommonPl = "小生雖不會武功，但也看過些武學經書。剛才那些山匪，分明只會寫粗淺功夫，嚇嚇過往商旅尚可，怕是連鏢局的人都打不過，更別說遇到武功高手了，這倒是讓我想起一些事來。"},
	[24927] = {CommonPl = "山長那樣神仙似的人，竟也被捲進這事裡。看來要早點處理了此事才好。"},
	[24930] = {CommonPl = "一會你跟天澤過去之後，我就跟陶白鈞坐著馬車沖過去！"},
	[24933] = {CommonPl = "大事不好了，我的包袱！剛剛，剛剛我去那邊山坡……有事……不料卻被山匪盯上，只好棄了包袱拼了命的跑回來。可是那包袱裡，還有蓉兒給我的香囊……#Y，你可一定得幫我這個忙啊！"},
	[24936] = {CommonPl = "看天澤擔心山長的樣子，似乎不只是與山長只有一面之緣的樣子。"},
	[24939] = {CommonPl = "客官，您要點什麼？"},
	[24942] = {CommonPl = "山長就在裡面，我們要快些救他出來。"},
	[24945] = {CommonPl = "江湖紛亂，我一介書生，又能怎麼樣呢。"},
	[25050] = {CommonPl = "給我搜！"},
	[25053] = {CommonPl = "局面混亂，\r快控制不住了！"},
	[25056] = {CommonPl = "江湖事，\r江湖了，\r別打壞我的船！！"},
	[25059] = {CommonPl = "銀票？\r大俠饒命！\r我！有！銀！票！"},
	[25062] = {CommonPl = "我乃黑蛟幫大弟子楊德，\r你們敢動手……\r就擺明瞭和我們黑蛟幫結梁子……"},
	[25065] = {CommonPl = "你們到底是何人？"},
	[25068] = {CommonPl = "……\r都是不要命的惡匪，\r找機會逃命先。"},
	[25071] = {CommonPl = "……"},
	[25074] = {CommonPl = "破地方來了這麼多江湖人，\r肯定要出大事。"},
	[25077] = {CommonPl = "家裡幾張嘴等著吃飯，\r這幾個喜餅還是帶回去給孩子們吃。"},
	[25080] = {CommonPl = "驚蟄始雷，\r難道是要下雨了？"},
	[25083] = {CommonPl = "未過驚蟄先鳴雷，\r四十九日雲不開。"},
	[25086] = {CommonPl = "（唱）\r這秋水長天來一色，\r漁舟唱晚，\r萍水相逢人，\r皆是他鄉客～～"},
	[25089] = {CommonPl = "千載風塵隨我去，\r年華踏浪何所求。\r若是不能把這一身風塵撣落，接下來的路，貧僧又該如何去何從？"},
	[25092] = {CommonPl = "外面人都說驚蟄城是無憂之城，\r但世人不懂何為憂，\r既不知憂，又何謂無憂呢？"},
	[25095] = {CommonPl = "一到驚蟄天就出事，\r不然數到梅雨季，一年都閑著，公子小姐出去找熱鬧，我們當下人卻擔心衣服曬不乾，這驚蟄城它是台戲。\r從古至今，換了多少往來人唱。"},
	[25098] = {CommonPl = "禪師與城主有恩，\r城主說話，\r就算把驚蟄城反過來抖三抖，\r也得把這包裹給抖出來。"},
	[25104] = {CommonPl = "這驚蟄天開出的火焰花香味雖清，\r但是很容易招惹毒蜂，\r你若無事，就別靠得太近。"},
	[25119] = {CommonPl = "……\r君今在羅網，何以有羽翼\r你這後輩，打何處而來？\r或是有事相求？\r還是城主叫你來的？"},
	[25122] = {CommonPl = "若是火焰花開過了驚蟄，\r花蜂就會隨它而亡，\r一季生一季死，\r你說這江湖又何嘗不是呢？"},
	[25125] = {CommonPl = "東方先生本就是明教靖龍使，\r所以這台可叫“撥亂反正”，\r我無意淌了趟渾水，\r所以現在陪著他玩命，\r你呢？"},
	[25128] = {CommonPl = "驚蟄城的莊丁被一招打倒在地。"},
	[25131] = {CommonPl = "天黑前必須要趕到，\r否則驚蟄城主一定會追上我們。"},
	[25134] = {CommonPl = "變天了？"},
	[25137] = {CommonPl = "馬嘯聲，\r人鬼都齊了！"},
	[25149] = {CommonPl = "古來征戰幾人回……\r出發。"},
	[25152] = {CommonPl = "我不殺伯仁，\r伯仁卻因我而死，\r幽冥之中，負此良友。\r少俠說我這番說話，可有不是？\r呵呵呵呵呵～"},
	[25155] = {CommonPl = "驚蟄城，\r哼～"},
	[25158] = {CommonPl = "城主不知道還會派多少人來殺我們。"},
	[25161] = {CommonPl = "這驚蟄城主真是神秘莫測的人，\r連任我行都對他頗為敬畏。"},
	[25173] = {CommonPl = "……"},
	[25176] = {CommonPl = "血腥味？"},
	[25179] = {CommonPl = "滿地的腳印，\r不過像我這種人，\r最討厭的就是熱鬧。"},
	[25182] = {CommonPl = "什麼正邪？\r關我何事？"},
	[25185] = {CommonPl = "膽敢與我兵戈相見？"},
	[25188] = {CommonPl = "起風了……"},
	[25191] = {CommonPl = "都說雲橫秦嶺家何在，\r我看這了得，\r一起雲，\r這山山寨寨的都成了神仙府邸。"},
	[25194] = {CommonPl = "先上山吧……"},
	[25197] = {CommonPl = "……"},
	[25200] = {CommonPl = "山路崎嶇霧雨滑，\r等下少俠可要走穩了，\r一失足，\r明年我還得買香燭拜祭你。"},
	[25203] = {CommonPl = "山裡是鬼天氣，\r風雨莫測，說變就變，\r你們要上山就趁早。"},
	[25230] = {CommonPl = "都說滄海桑田，\r雖然一別三年，\r這裡都一草一木都和以前一樣。"},
	[25233] = {CommonPl = "（唱）\r日落西山剛過崗，\r雲送日頭妹送郎，\r雲送日頭西山下，\r妹送情郎回家鄉～"},
	[25236] = {CommonPl = "敵人太多，速戰速決！"},
	[25239] = {CommonPl = "你快帶小姐走！！"},
	[25242] = {CommonPl = "誓死保衛淹月小舍！\r不能讓這些賊人在我們的家園裡放肆！"},
	[25245] = {CommonPl = "喪家犬－－"},
	[25248] = {CommonPl = "窮追不捨，\r任我行這個老怪物，\r想來不真瘋還是假傻！"},
	[25272] = {CommonPl = "前路未絕，誰敢阻我。"},
	[25275] = {CommonPl = "山下有水路直通黑木崖，我此時此地心生一計，呵呵～"},
	[25278] = {CommonPl = "既然無路可退，就一鼓作氣！"},
	[25293] = {CommonPl = "你們先走，\r我不喜歡別人打擾我做事。"},
	[25296] = {CommonPl = "快走！\r還在看什麼？"},
	[25299] = {CommonPl = "我的身體恐怕恐怕動了胎氣……\r得想辦法擋住追兵。"},
	[25308] = {CommonPl = "時辰剛剛好，\r跟我來…"},
	[25311] = {CommonPl = "東方……\r嵐……"},
	[25314] = {CommonPl = "好想回家……\r離開的時候……\r茶花都還沒開呢……"},
	[25317] = {CommonPl = "江湖莫測，\r人人隨波逐流，\r今日誰勝，明日誰輸，\r幾十年後終究不過一把黃土。"},
	[25320] = {CommonPl = "……\r等……\r他……\r回家……"},
	[25323] = {CommonPl = "這……\r條路……\r我……\r走不完了……"},
	[25326] = {CommonPl = "明知道這條路會有生死，\r但生死來時，\r誰又能承受？"},
	[25329] = {CommonPl = "只恐……\r雙溪舴艋舟，卻載不動……\r許多愁……"},
	[25332] = {CommonPl = "千尋－－－"},
	[25365] = {CommonPl = "千尋，挺住。\r我馬上採紫玉花來給你除掉箭毒。"},
	[25368] = {CommonPl = "大事未成，\r不可亂，\r不可違，\r亦不可退，\r不可輸……"},
	[25371] = {CommonPl = "黑木村最好吃的，\r當然是烤鷓鴣了，\r又油又香！"},
	[25383] = {CommonPl = "任我行，\r今朝只有成者為王！\r沒有敗者為寇！"},
	[25386] = {CommonPl = "壬辰年丙辰時，\r亦上樑、起宅、出行、沖虎煞南。"},
	[25389] = {CommonPl = "黑木崖高手如雲，\r生死難測。"},
	[25392] = {CommonPl = "家裡人都安頓好，\r我也安心了。"},
	[25395] = {CommonPl = "東方先生難道真的能擒下任我行老教主？"},
	[25398] = {CommonPl = "這事我該怎麼回去給家人說呢？"},
	[25419] = {CommonPl = "天剛亮的時候，\r我就看見東方先生離開了。"},
	[25422] = {CommonPl = "任我行害我家破人亡，\r今日我也要他……"},
	[25425] = {CommonPl = "東方先生行色匆匆應該是有什麼急事。"},
	[25428] = {CommonPl = "今日申時一舉攻下黑木崖！！！"},
	[25431] = {CommonPl = "任我行練那吸星大法早已走火入魔，\r還有什麼好顧忌的！！"},
	[25434] = {CommonPl = "留條命回家，\r留條命回家……"},
	[25455] = {CommonPl = "醉臥沙場君莫笑，\r古來征戰幾人回～"},
	[25458] = {CommonPl = "今日我們勢如破竹，\r有誰能阻，\r哈哈哈哈～"},
	[25461] = {CommonPl = "任我行的走狗，\r今日一個也別想逃。"},
	[25479] = {CommonPl = "東方教主神功已成，\r區區任我行，\r怎是他的敵手～"},
	[25482] = {CommonPl = "誰負我，\r我便殺誰～"},
	[25485] = {CommonPl = "東方教主神威！！！"},
	[25488] = {CommonPl = "東方教主一統千秋！！"},
	[25491] = {CommonPl = "攻入總壇，\r一個不留！！"},
	[25494] = {CommonPl = "沒有一點點手段，\r怎麼贏得了到天下？\r你說是不是？"},
	[25512] = {CommonPl = "殺入凌霄殿，\r將餘孽一舉殲滅！！"},
	[25515] = {CommonPl = "我歸順新教主，\r東方教主一統千秋！！"},
	[25518] = {CommonPl = "別殺我……\r別殺我……"},
	[25521] = {CommonPl = "我是被逼的……\r不管我事……"},
	[25524] = {CommonPl = "新教主，\r君臨天下！！"},
	[25527] = {CommonPl = "東方教主，\r一統江湖！！！"},
	[25530] = {CommonPl = "新教主人與天齊，\r功垂千秋！！"},
	[25533] = {CommonPl = "哈哈哈哈哈～\r青海長雲暗雪山，\r孤城遙望玉門關，\r黃沙百戰穿金甲，\r不破樓蘭終不還。"},
	[25536] = {CommonPl = "……"},
	[25539] = {CommonPl = "吾教神威～"},
	[25542] = {CommonPl = "日月神教，一統江湖～"},
	[25545] = {CommonPl = "新教主神威～"},
	[25548] = {CommonPl = "唉～又是一個任我行"},
	[25551] = {CommonPl = "教主神功蓋世，稱霸江湖～"},
	[25554] = {CommonPl = "別說江湖無情，\r教主不殺之恩，\r便是情。"},
	[25557] = {CommonPl = "人明白得太多，\r不見得一件好事，\r所以有些事還是忘掉的好，\r呵呵呵呵呵～"},
	[25562] = {CommonPl = "夫人的話果然都是對的，這次臨走前夫人讓我多加小心，我心想這條路我走了幾年了，這次也肯定平安無事。沒想到果然遭了土匪……"},
	[25565] = {CommonPl = "#Z，你見過魚在天上飛嗎？我就見過哦！嘻嘻，告訴你吧，那是爹爹幫我做的風箏……"},
	[25568] = {CommonPl = "但見這人倒在黃沙之上，雖氣息奄奄，難辨死活，但端的是一副清俊不凡的好相貌。\r在他身邊還有一隻滴水全無的空羊皮囊，想必又是一個將渴死之人。"},
	[25571] = {CommonPl = "但見周淮安一語不發，似在強自忍耐痛楚。\r額角都滲出細汗，黃沙之上，步履維艱。"},
	[25574] = {CommonPl = "龍門山有雨，卻緣虎下山。"},
	[25577] = {CommonPl = "八方風雨，不如我們龍門山的雨。"},
	[25580] = {CommonPl = "幸不辱命，雖死猶榮……"},
	[25583] = {CommonPl = "這個周淮安，到底是怎樣一個人物。"},
	[25586] = {CommonPl = "浮萍漂泊本無根，天涯遊子君莫問。"},
	[25589] = {CommonPl = "醉裡挑燈看劍，夢回吹角連營……\r他還在等我，我要回去，回去……"},
	[25592] = {CommonPl = "邱莫言身受重傷，魂斷戈壁。\r大漠黃沙埋豔骨，兒女英雄俱隨風。"},
	[25595] = {CommonPl = "幾日沒去龍門客棧，不知那老闆娘想我沒有。\r那小娘子真是夠味兒，不是在這大沙漠裡，還真長不出她那樣的花。"},
	[25598] = {CommonPl = "衛兵神聖，不容侵犯。"},
	[25601] = {CommonPl = "客官，您是打尖還是住店？"},
	[25604] = {CommonPl = "我在這鳥不拉屎，妞不解帶的地方一干就是十年，為了啥，為了啥啊？\r還不就是為了她！\r她卻看上那中看不中吃的小白臉！\r黃沙子迷了她的眼了，放著一身手藝的好男人不要，拿熱臉去貼那通緝犯的冷屁股！"},
	[25607] = {CommonPl = "我的故國是沙漠上最美麗的珍珠，水草豐美，喜樂多福。\r然而沙漠賜予的又由沙漠收回。\r轉眼之間，上無飛鳥，下無走獸，舉目所見，唯有枯骨。"},
	[25610] = {CommonPl = "不知為什麼，幾十匹絲綢全被搶走，焦急之外，我居然生出一點輕鬆。\r也許我在這絲綢之路上走了太久，我已經想停下來了，卻缺少一個理由。"},
	[25613] = {CommonPl = "我受夠了！\r這戈壁真是個鬼地方，馬賊完全不講規矩，劫財又劫色。\r也只有老闆娘能聊慰心腸。"},
	[25616] = {CommonPl = "我一直在這大沙漠旅行，\r直到有一個人要我為他留下來。"},
	[25619] = {CommonPl = "我一直在這裡等著那個人。\r我並不怕這無邊無際的大沙漠，\r但卻開始厭倦這風沙般鋪天蓋地的寂寞。"},
	[25622] = {CommonPl = "今天我們賭點特別的，就賭那個新來的小白臉心裡到底想著哪個女人。"},
	[25625] = {CommonPl = "來，為這沒名沒姓的年月乾一杯！"},
	[25628] = {CommonPl = "一曲琵琶數行淚，望盡黃沙君不歸。"},
	[25699] = {CommonPl = "這年輕俠士後來怎麼了，每次都有頭沒尾。"},
	[25702] = {CommonPl = "你當你自己是主角啊，那都是說書人吹的！你信！"},
	[25705] = {CommonPl = "看你這身打扮，和段子裡說的那位少俠，倒是有那麼七八分像。"},
	[25708] = {CommonPl = "這麼說來，東方不敗能當上教主也是多得這位少俠相助。"},
	[25711] = {CommonPl = "臨江鎮這地方歷來都是三教九流混雜一堂，沒事您可別瞎逛~"},
	[25714] = {CommonPl = "上一回說到啊，這“黑雲壓城城欲摧，甲光向日金鱗開”說這年輕俠士，當年離開黑木崖之後啊~就來到了一個叫……"},
	[25717] = {CommonPl = "天天都這個段子，我說說書的那個，你是不是換個段子。"},
	[25811] = {CommonPl = "#X小心一點，\r你方才受了重傷，不妨在我這兒養好病再離開。江湖險惡，以後在外面闖蕩時一定要小心自己身體哦。"},
	[25811] = {CommonPl = "是生是死一場夢，或勝或敗轉頭空！不要太介懷昨日，再戰江湖才是最緊要的！"},
	[25814] = {CommonPl = "#X小心一點，\r請再多休息一會兒，我剛為你敷上了傷藥，後面一定要更小心以免受傷。"},
	[25814] = {CommonPl = "是生是死一場夢，或勝或敗轉頭空！不要太介懷昨日，再戰江湖才是最緊要的！"},
	[25817] = {CommonPl = "#N，\r師父知道你陷入了苦戰了，特地派我前來救你，只不過晚了一點……\r師兄們都很想你，記得經常回少林寺來看看，多多修習武藝和心法才能更好的闖蕩江湖哦。"},
	[25817] = {CommonPl = "是生是死一場夢，或勝或敗轉頭空！不要太介懷昨日，再戰江湖才是最緊要的！"},
	[25820] = {CommonPl = "#N，\r師父知道你陷入了苦戰了，特地派我前來救你，只不過晚了一點……\r師兄師姐們都很想你，記得經常回少武當派來看看，多多修習武藝和心法才能更好的闖蕩江湖哦。"},
	[25820] = {CommonPl = "是生是死一場夢，或勝或敗轉頭空！不要太介懷昨日，再戰江湖才是最緊要的！"},
	[25823] = {CommonPl = "#N，\r師父知道你陷入了苦戰了，特地派我前來救你，只不過晚了一點……\r師兄師姐們都很想你，記得經常回華山派來看看，多多修習武藝和心法才能更好的闖蕩江湖哦。"},
	[25823] = {CommonPl = "是生是死一場夢，或勝或敗轉頭空！不要太介懷昨日，再戰江湖才是最緊要的！"},
	[25826] = {CommonPl = "#N，\r師父知道你陷入了苦戰了，特地派我前來救你，只不過晚了一點……\r師兄師姐們都很想你，記得經常回發恆山派來看看，多多修習武藝和心法才能更好的闖蕩江湖哦。"},
	[25826] = {CommonPl = "是生是死一場夢，或勝或敗轉頭空！不要太介懷昨日，再戰江湖才是最緊要的！"},
	[25829] = {CommonPl = "#N，\r師父知道你陷入了苦戰了，特地派我前來救你，只不過晚了一點……\r師兄師姐們都很想你，記得經常回衡山派來看看，多多修習武藝和心法才能更好的闖蕩江湖哦。"},
	[25829] = {CommonPl = "是生是死一場夢，或勝或敗轉頭空！不要太介懷昨日，再戰江湖才是最緊要的！"},
	[25832] = {CommonPl = "#N，\r師父知道你陷入了苦戰了，特地派我前來救你，只不過晚了一點……\r師兄師姐們都很想你，記得經常回日月教來看看，多多修習武藝和心法才能更好的闖蕩江湖哦。"},
	[25832] = {CommonPl = "是生是死一場夢，或勝或敗轉頭空！不要太介懷昨日，再戰江湖才是最緊要的！"},
	[25835] = {CommonPl = "#N，\r師父知道你陷入了苦戰了，特地派我前來救你，只不過晚了一點……\r師姐們都很想你，記得經常回五仙教來看看，多多修習武藝和心法才能更好的闖蕩江湖哦。"},
	[25835] = {CommonPl = "是生是死一場夢，或勝或敗轉頭空！不要太介懷昨日，再戰江湖才是最緊要的！"},
	[25838] = {CommonPl = "#N，\r師父知道你陷入了苦戰了，特地派我前來救你，只不過晚了一點……\r師兄師姐們都很想你，記得經常回逍遙派來看看，多多修習武藝和心法才能更好的闖蕩江湖哦。"},
	[25838] = {CommonPl = "是生是死一場夢，或勝或敗轉頭空！不要太介懷昨日，再戰江湖才是最緊要的！"},
	[25841] = {CommonPl = "#N，\r師父知道你陷入了苦戰了，特地派我前來救你，只不過晚了一點……\r師兄師姐們都很想你，記得經常回唐家堡來看看，多多修習武藝和心法才能更好的闖蕩江湖哦。"},
	[25841] = {CommonPl = "是生是死一場夢，或勝或敗轉頭空！不要太介懷昨日，再戰江湖才是最緊要的！"},
	[25844] = {CommonPl = "#N，\r師父知道你陷入了苦戰了，特地派我前來救你，只不過晚了一點……\r師兄師姐們都很想你，記得經常回峨峨眉派來看看，多多修習武藝和心法才能更好的闖蕩江湖哦。"},
	[25844] = {CommonPl = "是生是死一場夢，或勝或敗轉頭空！不要太介懷昨日，再戰江湖才是最緊要的！"},
	[25847] = {CommonPl = "這位#Y，\r若不是我等桃谷六仙路過救你，\r你已經不行了，\r啊，你問我是誰，\r我是二哥，叫做桃幹仙。"},
	[25847] = {CommonPl = "是生是死一場夢，或勝或敗轉頭空！不要太介懷昨日，再戰江湖才是最緊要的！"},
	[25850] = {CommonPl = "這位#Y，\r若不是我等桃谷六仙路過救你，\r你已經不行了，\r啊，你問我是誰，\r我是大哥，叫做桃根仙。"},
	[25850] = {CommonPl = "是生是死一場夢，或勝或敗轉頭空！不要太介懷昨日，再戰江湖才是最緊要的！"},
	[25853] = {CommonPl = "這位#Y，\r若不是我等桃谷六仙路過救你，\r你已經不行了，\r啊，你問我是誰，\r我是五弟，叫做桃花仙。"},
	[25853] = {CommonPl = "是生是死一場夢，或勝或敗轉頭空！不要太介懷昨日，再戰江湖才是最緊要的！"},
	[25856] = {CommonPl = "這位#Y，\r若不是我等桃谷六仙路過救你，\r你已經不行了，\r啊，你問我是誰，\r我是六弟，叫做桃實仙。"},
	[25856] = {CommonPl = "是生是死一場夢，或勝或敗轉頭空！不要太介懷昨日，再戰江湖才是最緊要的！"},
	[25859] = {CommonPl = "這位#Y，\r若不是我等桃谷六仙路過救你，\r你已經不行了，\r啊，你問我是誰，\r我才是真的三哥，叫做桃葉仙。"},
	[25859] = {CommonPl = "是生是死一場夢，或勝或敗轉頭空！不要太介懷昨日，再戰江湖才是最緊要的！"},
	[25862] = {CommonPl = "這位#Y，\r若不是我等桃谷六仙路過救你，\r你已經不行了，\r啊，你問我是誰，\r我是三哥，叫做桃枝仙，"},
	[25862] = {CommonPl = "是生是死一場夢，或勝或敗轉頭空！不要太介懷昨日，再戰江湖才是最緊要的！"},
	[25865] = {CommonPl = "三裡膝眼下，\r三寸兩筋間，\r能消心腹痛，\r善治胃中寒。\r#X可知這從中之道理？"},
	[25865] = {CommonPl = "是生是死一場夢，或勝或敗轉頭空！不要太介懷昨日，再戰江湖才是最緊要的！"},
	[25868] = {CommonPl = "世上本無醫理一說，\r他五毒教只不過仗著幾張祖傳的古怪藥方，又懂什麼狗屁醫理、藥理！\r#X在遊歷時也一定要小心，\r即使是醫者一樣可能是殺手，\r莫言吾非好意，\r世之天下庸醫殺人，\r又有哪一個不是好意！"},
	[25868] = {CommonPl = "是生是死一場夢，或勝或敗轉頭空！不要太介懷昨日，再戰江湖才是最緊要的！"},
	[25871] = {CommonPl = "毒和藥本身沒有區別，\r是藥三分毒，毒也能求命，\r人參吃死人無罪，\r大黃醫好病無功，\r凡事皆有度，醫理如此，\r做人之理亦如此。"},
	[25871] = {CommonPl = "是生是死一場夢，或勝或敗轉頭空！不要太介懷昨日，再戰江湖才是最緊要的！"},
	[25874] = {CommonPl = "人皆忘恩負義，\r故而見死不救。\r像#X少俠自然例外。\r行醫者，\r當不在於醫術之精，\r也不在號得醫仙之名，\r而是於醫學大有發明創見，\r道前賢之所未道。"},
	[25874] = {CommonPl = "是生是死一場夢，或勝或敗轉頭空！不要太介懷昨日，再戰江湖才是最緊要的！"},
	[25877] = {CommonPl = "#X，\r觀世音菩薩神通廣大，\r剛還以為你沒氣了呢，\r還好你活過來啦。"},
	[25877] = {CommonPl = "是生是死一場夢，或勝或敗轉頭空！不要太介懷昨日，再戰江湖才是最緊要的！"},
	[25880] = {CommonPl = "江湖中人，\r有人有神兵利刃，\r有人有武功絕學。\r誰卻知即使只有空拳掌，\r將武功融會貫通，應境使用，\r才是最高境界。"},
	[25880] = {CommonPl = "是生是死一場夢，或勝或敗轉頭空！不要太介懷昨日，再戰江湖才是最緊要的！"},
	[25883] = {CommonPl = "唉，\r好不容易就快集齊八種藥了，\r誰知碰上了你，得得，\r還是和先救好了你再說吧。"},
	[25883] = {CommonPl = "是生是死一場夢，或勝或敗轉頭空！不要太介懷昨日，再戰江湖才是最緊要的！"},
	[25886] = {CommonPl = "你是#N吧，\r記住老朽的話，\r酒雖是美食之一，但只要用得恰當，\r也是最好的藥物之一。\r沒有我的酒，\r這次你就怕已經不行了。"},
	[25886] = {CommonPl = "是生是死一場夢，或勝或敗轉頭空！不要太介懷昨日，再戰江湖才是最緊要的！"},
	[25889] = {CommonPl = "佛有佛法，\r武有武道，\r醫有醫理。\r不知#X認為，哪種最重要？"},
	[25889] = {CommonPl = "是生是死一場夢，或勝或敗轉頭空！不要太介懷昨日，再戰江湖才是最緊要的！"},
	[25892] = {CommonPl = "嘛，\r我只不過是順便路過時，\r看到你受傷了才救你的啦，\r才不是專門跟著你的呢。"},
	[25892] = {CommonPl = "是生是死一場夢，或勝或敗轉頭空！不要太介懷昨日，再戰江湖才是最緊要的！"},
	[25895] = {CommonPl = "呵呵呵，\r沒想到#N也會有輸的時侯啊。\r我是誰嗎，\r這個不重要，\r應該我們是第一次見到吧。"},
	[25895] = {CommonPl = "是生是死一場夢，或勝或敗轉頭空！不要太介懷昨日，再戰江湖才是最緊要的！"},
	[25898] = {CommonPl = "闖蕩江湖，\r學得一身武藝固然重要，\r而若能得一紅顏知已，\r就更是人生幸事了。"},
	[25898] = {CommonPl = "是生是死一場夢，或勝或敗轉頭空！不要太介懷昨日，再戰江湖才是最緊要的！"},
	[25901] = {CommonPl = "莫談不幸，莫談命苦，\r能讓別人快快樂樂的，\r有什麼不好嗎？"},
	[25901] = {CommonPl = "是生是死一場夢，或勝或敗轉頭空！不要太介懷昨日，再戰江湖才是最緊要的！"},
	[25904] = {CommonPl = "切不可為了一口氣，\r衝動而誤大事。\r為人一生百載，\r有氣節也好，沒氣節也好，\r百年之後，均歸黃土，\r又有甚麼分別？"},
	[25904] = {CommonPl = "是生是死一場夢，或勝或敗轉頭空！不要太介懷昨日，再戰江湖才是最緊要的！"},
	[25907] = {CommonPl = "昔日嵇康臨刑，撫琴一曲，\r歎息《廣陵散》從此絕響。\r但《廣陵散》縱情精妙，\r又怎及得上這一曲《笑傲江湖》？"},
	[25907] = {CommonPl = "是生是死一場夢，或勝或敗轉頭空！不要太介懷昨日，再戰江湖才是最緊要的！"},
	[25910] = {CommonPl = "我是生意人，\r在商言商，虧本的生意我從來不做，包括你。\r呵呵，\r你總有一天會明白我在說什麼。"},
	[25961] = {CommonPl = "一切眾生，真如法性，不生不滅，不垢不淨，不增不減，真如體、相、用的法、報、化三身本自具足，不必向外馳求。"},
	[26031] = {CommonPl = "一切眾生，真如法性，不生不滅，不垢不淨，不增不減，真如體、相、用的法、報、化三身本自具足，不必向外馳求。"},
	[26058] = {CommonPl = "身為回紇王族的後代，凡是族中的女子，生來便有一項使命，便是守護回紇王陵。"},
	[26061] = {CommonPl = "原來我以為這世上最容易的一件事，就是忘記。後來我總算明白了，原來這世上最難的事，才是忘記。"},
	[26064] = {CommonPl = "閣下是第一次來敦煌吧？\r敦者，大也；煌者，盛也。如今的敦煌是絲綢之路的必經之地，來往商旅如織。"},
	[26067] = {CommonPl = "所謂執子之手，與子偕老，卻是最悲哀不過的。因為牽手之後，便是放手。"},
	[26070] = {CommonPl = "客官裡面請，不是我吹牛，這偌大的敦煌，若是想找最最正宗的甜坯子，可就非本店莫屬了！"},
	[26144] = {CommonPl = "屍體是不會回答你的。"},
	[26147] = {CommonPl = "改天換日，在此一舉！"},
	[26150] = {CommonPl = "#N來得正是時候！快隨我一起前去攻打任我行！"},
	[26153] = {CommonPl = "屍體是不會回答你的。"},
	[26335] = {CommonPl = "哼哼，任老賊閉關中被襲擊，果然已經氣息大亂，即將走火入魔。"},
	[26338] = {CommonPl = "你們這些逆賊，老夫要先自殺，再殺你們全家！"},
	[26339] = {CommonPl = "屍體是不會回答你的。"},
	[26834] = {CommonPl = "幾度試香纖手暖，一回嘗酒絳唇光。\r古人鑿壁偷光，今日我借光誦讀，\r耳畔鶯聲燕語，美文齒頰生香。\r人生得一知己足矣，正如朝聞道夕死可也。"},
	[26837] = {CommonPl = "真是知人知面難知心！\r我們朝夕相處了幾年，生死與共情同手足的師兄弟，竟然是包藏禍心的叛徒……\r當初他要與我同往，我還喜不自禁，這世上還有人比我更傻嗎？"},
	[26840] = {CommonPl = "那些人面獸心的傢伙還口口聲聲什麼五嶽劍派同氣連枝，\r呸！\r與嵩山派同列真是我衡山的恥辱！"},
	[26843] = {CommonPl = "不好，有人來了，我們撤！給外人看出行跡就糟糕了。"},
	[26950] = {CommonPl = "倒在血泊之中的少女正是劉正風的長女。\r只見一劍自她右肩直劈至腰，慘烈至極。\r"},
	[26953] = {CommonPl = "令狐師兄，你為救我而涉險，我豈能遇難先遁？\r師父如知我如此沒同道義氣，定然將我殺了。\r師父平日時時教導，我們恆山派雖都是女流之輩，在這俠義份上可不能輸給男子漢。\r"},
	[26959] = {CommonPl = "不打不相識，咱們便交個朋友如何？\r令狐兄既看中了這個美貌的小尼姑，在下讓給你便是。\r重色輕友，豈是我輩所為？\r"},
	[27008] = {CommonPl = "千尋……"},
	[27011] = {CommonPl = "大事未成，\r不可亂，\r不可違，\r亦不可退，\r不可輸……"},
	[27014] = {CommonPl = "……"},
	[27017] = {CommonPl = "靜靜的墳墓坐落在樹旁。"},
	[27043] = {CommonPl = "這嫌犯狡猾多端，#Y千萬別被他迷惑了。"},
	[27052] = {CommonPl = "四面八方來了這許多人，看來競爭會相當激烈啊。\r我且按兵不動，觀察一下。\r知己知彼，百戰不殆。"},
	[27055] = {CommonPl = "跟人打沒意思，與自己鬥才其樂無窮呢！\r我就在這僻靜處練練功夫，免得吵吵嚷嚷亂我心神。\r老頑童當年那左右互搏的功夫可真叫人神往啊。"},
	[27058] = {CommonPl = "他們都集中在那人多處，豈不知擺在明處的都是幌子，真正的機會全是暗處功夫。\r那邊可有什麼管事的？\r就算要動真傢伙，也得先找到主場啊。"},
	[27061] = {CommonPl = "人說江湖上有三忌：老人、小孩、美女子。\r姑娘我能孤身一人闖蕩江湖，那自然身懷絕技。\r還敢動手動腳？一看你就沒長腦子！"},
	[27064] = {CommonPl = "能到得嵩山腳下，身上都是有本事的。\r敢小瞧我？叫你付出代價。\r吃我一招！"},
	[27067] = {CommonPl = "嵩山管事的叫我們在此亮亮招子，想是要擇優錄用，\r我可不能被人看扁了。\r這空手套白狼的機會決不能讓給旁人。"},
	[27089] = {CommonPl = "出家人不打誑語。\r願施主放下屠刀，立地成佛。\r善哉善哉。"},
	[27117] = {CommonPl = "出家人不打誑語。\r願施主放下屠刀，立地成佛。\r善哉善哉。"},
	[27429] = {CommonPl = "恆山派乃是武林中名門正派，從也未得罪過何人，不知是何方勢力竟要下此狠手？"},
	[27432] = {CommonPl = "老子的兵刃有些鈍了，一會兒讓鑄劍谷的朋友給我打磨打磨，哈哈！"},
	[27435] = {CommonPl = "在下點蒼派陶白白，這位#Y，點蒼派的大名，你不會不知道吧……我們點蒼派在劍術上也頗有造詣，江湖上如今都推崇五嶽劍派的劍法，要我看，哼哼，也不過如此！"},
	[27438] = {CommonPl = "與朝廷作對本不是我武林中人所為之事，不過這夥閹黨忒也欺人太甚！再說我等早年間都受過鑄劍谷的恩惠，急人所難，乃是豪傑本分，今番誓與鑄劍谷共存亡！"},
	[27441] = {CommonPl = "沒想到……五嶽劍派，同氣連枝什麼的，都是騙人的幌子！我一定要早點回去向師父報告！"},
	[27452] = {CommonPl = "你鄉下來的吧？沒見過京城的俠丐嗎？不要這樣看著我，我是不會放下身份跟你鄉下人玩的！"},
	[27455] = {CommonPl = "我家的酒樓，絕對的全京城第一！我站在這都覺得倍兒精神！倍兒有面子！"},
	[27458] = {CommonPl = "我現在雖已是家財萬貫，涵兒卻不知道身在何方。梅晨光那小子也不知道是死是活，有時間真應該回去看看他！你是幹嘛的？！沒事跑酒樓後院做什麼！"},
	[27508] = {CommonPl = "老子的兵刃有些鈍了，一會兒讓鑄劍谷的朋友給我打磨打磨，哈哈！"},
	[27511] = {CommonPl = "在下點蒼派陶白白，這位#Y，點蒼派的大名，你不會不知道吧……我們點蒼派在劍術上也頗有造詣，江湖上如今都推崇五嶽劍派的劍法，要我看，哼哼，也不過如此！"},
	[27514] = {CommonPl = "與朝廷作對本不是我武林中人所為之事，不過這夥閹黨忒也欺人太甚！再說我等早年間都受過鑄劍谷的恩惠，急人所難，乃是豪傑本分，今番誓與鑄劍谷共存亡！"},
	[27518] = {CommonPl = "泰山為五嶽之首，有天下第一山的美譽。我們泰山派也應該做五嶽劍派之首，博得天下第一劍派的美名。"},
	[27521] = {CommonPl = "泰山派居天下第一山—泰山之上，尊奉祖師東靈道人之訓，以救濟蒼生為志。"},
	[27524] = {CommonPl = "該死！我派赫赫有名，這樣的毛賊居然敢攻打山門，我立即去除掉他們。"},
	[27527] = {CommonPl = "此地山靈水秀，在此修煉劍法一定可以百尺竿頭更進一步，可以很快追上夏侯師兄。"},
	[27530] = {CommonPl = "區區山匪，我又怎麼會放在心上？但我還是很擔心，希望不要是夏侯師兄。"},
	[27533] = {CommonPl = "泰山派自東靈祖師以降，勵精圖治，苦心研究武學，而今已經在江湖上赫赫有名，為五嶽劍派之一。"},
	[27536] = {CommonPl = "泰山派在江湖上也是赫赫有名，居然有鼠輩敢來此挑事，真是該死。"},
	[27539] = {CommonPl = "為這一天，我等得太久了……"},
	[27542] = {CommonPl = "自打我離開村子加入仙霞幫，就再沒和青菱說過一句話。今天終於重回自由之身，千言萬語要從何說起呢……"},
	[27545] = {CommonPl = "他傷得太重，似乎連呼吸也沒有了……"},
	[27548] = {CommonPl = "你太傻了，竟想用蠻力綁住愛情……\r可是愛，從來都是揮著它輕盈的翅膀，不經意飛落你心田的。\r我便真的愛過你，那情愫這會兒也被嚇跑了。"},
	[27629] = {CommonPl = "青菱，我的命是你的，\r你把它拿走吧！\r你若不要，就棄在這竹林裡。"},
	[27640] = {CommonPl = "情之一字，彼之砒霜，吾之蜜糖。\r杜公子與玫兒經此考驗，相信他們以後一定會情比金堅，永不分離。"},
	[27643] = {CommonPl = "客官裡面請，不是我吹牛，這偌大的敦煌，若是想找最最正宗的甜坯子，可就非本店莫屬了！"},
	[27646] = {CommonPl = "快快帶我去找玫兒吧！"},
	[27649] = {CommonPl = "我也曾想過放棄，可我怕我放棄的不只是一段感情，而是一生。"},
	[27652] = {CommonPl = "嘿嘿，若是我考上了平涼書院，回去告訴蓉兒……嘿嘿……\r你說她會不會以身相許？"},
	[28009] = {CommonPl = "哪個少女不思春，\r花開堪折直須折。\r莫使金樽空對月，\r一枝紅杏出牆來。"},
	[28012] = {CommonPl = "我平生最不喜歡的事，便是聽到有人說令狐沖的壞話。"},
	[28015] = {CommonPl = "酒似紅顏，茶如知己。生命中，不斷有人進入或離開。於是，看見的，看不見的；記住的，遺忘了。"},
	[28018] = {CommonPl = "我幫平一指把他老婆家中一家五口盡數殺了，他才不好意思，不得不悉心替我女兒看病。如果你想讓他替你看病，已經沒有人讓你殺了。"},
	[28021] = {CommonPl = "那個矮冬瓜胖皮球的女兒肯定也是個矮冬瓜胖皮球，令狐沖居然要逼她做老婆，真是口味獨特。"},
	[28024] = {CommonPl = "令狐沖有這等的品味，我們桃谷六仙佩服不已。"},
	[28027] = {CommonPl = "黃河遠上白雲間，\r一片孤城萬仞山。\r羌笛何須怨楊柳，\r春風不度玉門關。\r初讀此詩，無甚意思，等到自己站在敦煌萬里的沙漠之中，才體會到此詩的意境。"},
	[28030] = {CommonPl = "多活幾天，少活幾天，又有什麼分別？我現在就死去，屍身趟在小師妹眼前，也不知她是否會傷心？"},
	[28035] = {CommonPl = "莊主這樣做……又是何苦呢……"},
	[28038] = {CommonPl = "經過這一次，莊主應該能夠解脫了吧……"},
	[28041] = {CommonPl = "那個矮冬瓜胖皮球的女兒肯定也是個矮冬瓜胖皮球，令狐沖居然要逼她做老婆，真是口味獨特。"},
	[28044] = {CommonPl = "令狐沖有這等的品味，我們桃谷六仙佩服不已。"},
	[28405] = {CommonPl = "我已記不得很多事了，只記得老虎的血盆大口在我背後張開……\r我拼命地跑啊，跑啊，跑丟了鞋，跑沒了腿，跑空了肚子，頭也飛起來。\r然後，我就在這了。\r你看得見我嗎？我的身子它還在嗎？"},
	[28436] = {CommonPl = "我們被一個村婦引來至此，然後一塊藍花補突然兜頭蓋上……然後……然後再醒來就在此處了……"},
	[28439] = {CommonPl = "我的頭……好暈啊……這是在哪裡……"},
	[28442] = {CommonPl = "多虧了儀琳師姐……不然真不知道會發生什麼事……"},
	[28445] = {CommonPl = "外面那些黑衣人……好恐怖哦……"},
	[28448] = {CommonPl = "阿彌陀佛，我佛保佑，總算是平安出來了。"},
	[28451] = {CommonPl = "阿彌陀佛，我佛保佑，總算是平安出來了。"},
	[28454] = {CommonPl = "這藥商處竟然沒有解迷藥的藥丸！要是下次再碰上這事，該如何是好？\r看來這趟回去，我要勤學武功防身了。"},
	[28457] = {CommonPl = "這廿八鋪的風景，也是挺美的嘛……\r好不容易出來一趟，可淨顧著趕路，都沒時間欣賞沿途的美景了。"},
	[28460] = {CommonPl = "這位施主，我看你印堂發黑，雙唇青紫，怕是不久之後有血光之災啊！\r不過若是你肯出三文錢，我就替你畫一道符，保准鬼擋殺鬼，血光變財運呐！"},
	[28463] = {CommonPl = "呸！這算命的滿嘴跑馬車，也不怕遭天譴！\r前幾天他教我種金，我就把金豆都撒在自家院子裡，沒想到那黃風寨強人說來就來，我著急挖出金豆，差點老命都沒了！"},
	[28466] = {CommonPl = "我還以為那黃風寨強人是天下最厲害的人了，沒想到吳將軍一到，把他們打的是落花流水！"},
	[28469] = {CommonPl = "天乾物燥——\r小心火燭——"},
	[28472] = {CommonPl = "待我去會會那黃風寨強人！"},
	[28475] = {CommonPl = "沒想到那些黑衣人把恆山派的小姑娘都綁在這裡了。"},
	[28478] = {CommonPl = "這一切竟然是嵩山派所為！\r沒想到啊沒想到……"},
	[28481] = {CommonPl = "還好定靜師太沒事，要不然恆山派這些小姑娘真不知如何是好。"},
	[28484] = {CommonPl = "我看見師姐被一個村婦引開了，快跟我去找她們。"},
	[28487] = {CommonPl = "快跟我去師姐他們！"},
	[28490] = {CommonPl = "多虧了你和吳將軍……\r#Y，不知是不是我多心，我總覺得……這位吳將軍，和令狐大哥有些相像……"},
	[28778] = {CommonPl = "百年修得同船渡，\r千年修得共枕眠。\r客官，我跟你很有緣呢。"},
	[28788] = {CommonPl = "剛還在想恩人在哪裡，想不到一抬頭就看到你啦！"},
	[28796] = {CommonPl = "千穿萬穿，唯馬屁不穿。\r楊總管地位極高，生性傲慢，最喜吹捧，你一定要極盡恭敬。\r最好能把他捧得飄飄欲仙，得意忘形，將你引為知己。"},
	[28802] = {CommonPl = "蓮亭兄別來無恙？小弟久未來看望，失禮失禮。今日特帶一位古玩品鑒師，並有珍惜古玩獻上，以饗楊兄。"},
	[28805] = {CommonPl = "楊兄所丟何物？\r可否說出來，令小弟幫忙尋找？"},
	[28811] = {CommonPl = "和古玩相對，我就常常忘記了自己所處的時間、空間，忘記了所背負的日月神教責任。沉浸在一種遨遊時空、任我穿梭的快感裡。"},
	[28814] = {CommonPl = "只見他臉色鐵青，緊緊咬著牙齒，一副滿腔怒火正要發洩卻被人突然堵住了嘴巴的表情。"},
	[28817] = {CommonPl = "聖教主萬歲！\r文成武德，澤被蒼生。\r千秋萬載，一統江湖。"},
	[28820] = {CommonPl = "莫愁前路無知己，\r天下誰人不識君。"},
	[29292] = {CommonPl = "咳……咳……\r即使費掉最後一點力氣，也要擊敗這個奸獰狡詐的偽君子！"},
	[29295] = {CommonPl = "聽說昨晚東方大人去後山練功了，不過再怎麼想，也應該還是打不過明教教主任我行吧"},
	[29298] = {CommonPl = "為了東方大人，這點小傷算什麼！"},
	[29301] = {CommonPl = "好－好強－\r刀砍上去完全刀槍不入的樣子。"},
	[29304] = {CommonPl = "快跟上我！"},
	[29307] = {CommonPl = "有人就有恩怨，有恩怨就有江湖，人心就是江湖，只要進來，就再也退不出了。\r成王敗寇，出來混遲早要還的……也罷……也罷……"},
	[29310] = {CommonPl = "東方大人請放心，我等一定修一坐最堅固的地牢用來囚禁任我行。"},
	[29313] = {CommonPl = "江湖本無正邪，\r人性哪來黑白？"},
	[29316] = {CommonPl = "有人愛絕世武功，\r有人愛琴棋書畫，\r有人愛傾城紅顏，\r#Y你說，人生在世，該為何往？"},
	[29319] = {CommonPl = "方才所見東方大人的功力之強，我等四人也打不過其一手。"},
	[29325] = {CommonPl = "任老賊就在前面練功，不用擔心，等下請隨我一起上去。"},
	[29328] = {CommonPl = "剷除任我行！"},
	[29509] = {CommonPl = "我投降……\r我等投降……\r誓死效忠東方嵐大人！"},
	[29978] = {CommonPl = "山寨裡很多雜事新寨主沒空理會，老寨主就把我撩這兒幫手打理。我從小被老寨主收養，他說什麼，我就一定會做。而今他雖退了位，但寨裡的大小事兒不能亂，也不能不去辦，所以你要是有空，大可來我這裡找活，總之做得好，寨主一定會記得。"},
	[29980] = {CommonPl = "我要算的不僅僅是賬，還得算算我們馬幫能維持多久，算算我們幾個的命還能有多長，你不用懷疑我有什麼本事，論資論輩，你都在我之下，所以最重要的是讓我看到你有什麼本事。"},
	[29980] = {CommonPl = "我心情好的時候姓何必，名毒，心情不好的時候姓何，名必毒。你可不要叫錯了。"},
	[29981] = {CommonPl = "我們把式人，一旦起了邪念，做出來的東西也都能沾上邪氣，雖說我們不問江湖事，但偏偏惹來了不少仇家，既然已至如此田地，有的事兒就必須要去做了。"},
	[29982] = {CommonPl = "聽說廚子今天烤了兩隻野兔，等下去偷兩條兔腿來吃，不過自從上次被抓後，我都不知道他會把烤兔擱在什麼地方。"},
	[29983] = {CommonPl = "撈魚沒撈到，撈到個破銅牌子，上面還寫著什麼字，我是看不懂，不過有人居然花了一吊銅錢來買，真是大方。"},
	[29984] = {CommonPl = "我經常來這裡打探風聲，路人都把我認熟了，說不準哪天我就被撂倒在這裡，所以趁我還活著，得多賺些銀子留給妻兒。"},
	[29985] = {CommonPl = "這幾個月連雨都不下，連河裡的鴨子都要乾死了，我打算找幾個人把山上的水給引下來。"},
	[29986] = {CommonPl = "雖然我已經不在江湖中打拼，但我千面菩薩的名號，想必你曾幾也聽過。"},
	[29987] = {CommonPl = "如果我的動作不夠快，我也不能混到今天這個名號，莫非你是覺得我徒有虛名？"},
	[29988] = {CommonPl = "什麼事我都知道，江湖人稱包打聽，不過我這價格可是不低。"},
	[29989] = {CommonPl = "東嶺的氣候是最好的，有時間去東嶺的話可以到我家坐坐。"},
	[29990] = {CommonPl = "中原的氣候多變人也多變，若不是有命在身，我也不願千里迢迢來這個無情無義之地。"},
	[29991] = {CommonPl = "南山靠海，氣候怡人，光是我們出產的水果，中原也是聞所未聞的，比如榴槤。"},
	[29991] = {CommonPl = "惡龍灘真的有一條惡龍，我爺爺曾經見過，沒事可別去那邊。"},
	[29992] = {CommonPl = "北山今冬大雪，能在天空中見到七彩華光，不過很多人不信，不怕對你說，我也親眼見過，難以言喻。"},
	[29992] = {CommonPl = "我們捕快還沒拉人，逃犯就自己要求回牢裡，此事真是天下奇談。"},
	[29993] = {CommonPl = "今年送來的茶葉全是去年的陳茶，我想走遠些總能收到些新茶，誰料人算不如天算，唉。"},
	[29993] = {CommonPl = "我一生心血，決不可讓隼幫就這樣在江湖中湮滅。"},
	[29994] = {CommonPl = "去年有人把清溪給截了，說什麼蓄水，弄得上游氣候惡劣，鳥絕魚亡，我這小檔子沒魚也沒法做生意，所以只有來城裡討些銀子周轉。"},
	[29995] = {CommonPl = "這年頭，好酒都被京城的大酒樓給定完了，柳風鎮那種小地方只能買人家賣剩的，最近我家擴建，所以我得想辦法籌銀子買些好酒回來撐門面。"},
	[29996] = {CommonPl = "沒礦這鐵怎麼打，我為了收礦，差點沒在路上被人給做了，那些女人真夠狠的，殺人還不見屍，想起來我都會起雞皮疙瘩，都不知道是人還是妖怪。"},
	[29997] = {CommonPl = "朝廷要的東西最難採購，不是你有錢就能買到的，好材料還要講究好做工，宮裡可不是收破爛的地方。"},
	[29998] = {CommonPl = "我不是什麼做大事的人，做大事太累，我只求活得舒服，左鄰右裡的那些小忙，能幫就幫了。"},
	[29999] = {CommonPl = "我這種人一輩子都是生於集市，死於集市，原來呆久了，發現這個集市裡面已經沒有不認識的人了。"},
	[30000] = {CommonPl = "此次也不過事發突然，我出手相救而已，如若無事，閣下請自便。"},
	[30001] = {CommonPl = "舉手之勞，別給我惹來什麼麻煩，早知道是江湖上的事，我絕不會插手。生意人還是應該守本份，誰想禍及全家。"},
	[30002] = {CommonPl = "還好今年收成不錯，這租子也能應付過來，如果明年也如同今年一樣，我就夠錢買了這塊田。"},
	[30003] = {CommonPl = "村裡今年鬧蝗災，莊稼全都被啃光了，我這次來找老幫主借些銀子，實是為了買些糧食回去。"},
	[30004] = {CommonPl = "最近綢緞不好賣，貨款又收不回來，真是青黃不接，也不知道有那個好心老闆肯借給些銀子給我。"},
	[30005] = {CommonPl = "這年頭不知道哪裡來的好心人，一個個爭著給姑娘們贖身，可來那些銀子都是假的，想來是被那些人給騙了，這次來貴地，就是想找老幫主借些銀子，再找大巡撫幫我徹查此事。"},
	[30006] = {CommonPl = "這生辰也算不得什麼大事，不過老來求樂，自然希望人多熱鬧，既然家裡的兒女回不來，就只有請來朋友三四喝喝酒，敘敘舊。"},
	[30007] = {CommonPl = "隨性之人做事，豈能被尋常人看透，我雖算不上是名家之後，但至少也學過文，考過科舉，今朝一舉得中，自然應該宴請諸位叔伯兄弟。"},
	[30008] = {CommonPl = "官府做事，若沒有江湖上的兄弟支持，必然困難重重，今日一宴，定當感謝各位這些年來對縣衙的幫助，今日我就代縣太爺敬大家一杯。"},
	[30009] = {CommonPl = "我皺沖向來是說一不二，今日所到之人都是自家兄弟，我今日便是要將這內鬼查出來，手刃於大家面前。"},
	[30010] = {CommonPl = "銀子多仇家就多，每次出門都要損兵折將，再這樣下去，我看不如窩在宅子裡吃老本好了，反正我家老本吃三代都吃不完。"},
	[30011] = {CommonPl = "我這人，年輕時候招惹太多江湖恩怨，現在最怕是仇家尋仇，所謂年紀越大，膽子越小，這話真是不假。"},
	[30012] = {CommonPl = "我不是買賣人，你要和我談生意，那就要看我心情如何，心情好的話，哪怕叫我送給你又何妨。"},
	[30013] = {CommonPl = "我不喜歡我那三個弟兄，他們做生意多是虧本買賣，我喜歡泡著茶慢慢聊，只要能賺，哪怕少點，我也就認了。"},
	[30014] = {CommonPl = "我歷來做的都是以物易物的生意，這要看你能拿出什麼樣的貨來，那些不入流的玩意你就自己收好了。"},
	[30015] = {CommonPl = "我家祖上就不是做買賣的，只是拿一些有價值的東西來做交換，這在江湖上算是奇事，不過比這更奇怪的事都有。"},
	[30016] = {CommonPl = "老爺子身子骨硬朗得很，聽聞還能一拳打死一頭牛，有時候我們也會懷疑，他到底是吃什麼長大的。"},
	[30017] = {CommonPl = "大哥病逝的之後，家族生意交給了我，我自然要好好打理，可惜大哥走的時候無子嗣繼後，不過有傳他在外鄉有一個私生子，將來找到這個孩子，我還是打算把這盤生意交還與他。"},
	[30018] = {CommonPl = "我的確在外面搞到些原料，不過你要和我談，就要看你夠不夠誠意了，你應該知道我說的誠意是什麼。"},
	[30019] = {CommonPl = "天工坊的人有誰不知道我。我可是老字型大小，供應的材料品質然都是最好的，所以就算貴，也是物有所值。"},
	[30020] = {CommonPl = "江湖本無正邪，\r人性哪來黑白？"},
	[30021] = {CommonPl = "江湖本無正邪，\r人性哪來黑白？"},
	[30734] = {CommonPl = "江湖本無正邪，\r人性哪來黑白？"},
	[30737] = {CommonPl = "江湖本無正邪，\r人性哪來黑白？"},
	[30740] = {CommonPl = "江湖本無正邪，\r人性哪來黑白？"},
	[30743] = {CommonPl = "江湖本無正邪，\r人性哪來黑白？"},
	[32823] = {CommonPl = "梅關古道自古便是南北交通的要道。\r自秦朝便設關卡，唐時又有張九齡主持開鑿，才有今日之古道綿長。\r奈何惡匪為患，群賊割據，以至道阻式微，民生凋敝。\r老夫雖為保長，卻無力殺賊，難以回天。\r平生所願，便是能有英雄除去梅寨惡匪，還梅關一個安寧。\r"},
	[32826] = {CommonPl = "恩公之恩，天高海深。\r妾結草銜環，不足以報。\r唯有勤學苦練，盼成一有用之才，與恩公一同仗劍江湖，扶危助困。"},
	[32829] = {CommonPl = "#N，我就知道你會來救我！\r可是，為什麼不是他，他究竟在哪裡……"},
	[32832] = {CommonPl = "娘要我嫁福州富家子，我心許過路騎馬郎。\r富家子輕薄情難久，騎馬郎仗劍天涯唱。\r便與他飄零，便隨他流浪。\r縱是冷雨淒風宿橋上，總懷著萬種柔腸。"},
	[32835] = {CommonPl = "恩公之恩，天高海深。\r妾結草銜環，不足以報。\r唯有勤學苦練，盼成一有用之才，與恩公一同仗劍江湖，扶危助困。"},
	[32838] = {CommonPl = "事不宜遲，咱們這便出發吧。"},
	[32841] = {CommonPl = "媒婆媒婆，兩頭說和。不為錢財，就為吃喝。"},
	[32844] = {CommonPl = "這阿強每日除了哼些山歌擾得我心煩，旁的全然不做。\r武藝不練，護院不勤，早晚要稟告二當家，把他撤換了才是。"},
	[32847] = {CommonPl = "遠遠的來個俏生生的妞，\r白花花的身子黑黝黝的頭。\r你是我的妹妹你就招招手，\r不是我的妹妹就朝前走。"},
	[32850] = {CommonPl = "炒菜想著採茶娘，\r燉湯遙想浪裡郎。\r自被虜到光棍寨，\r拎起鏟子就罵娘。\r只盼英雄即日至，\r打翻梅嶺山大王。"},
	[32853] = {CommonPl = "紀律嚴明，保障有力。\r殺人越貨，從我做起。\r"},
	[32856] = {CommonPl = "這侍衛正睡得香甜。\r夢裡喃喃自語，似是叫著姑奶奶、大妹子，聽不真切。"},
	[32859] = {CommonPl = "既狠心做了這行當，便早知有這麼一天。\r殺人不過頭點地，咱們多說無益。"},
	[32862] = {CommonPl = "咱們分開後，我在這寨中好一番探尋。\r多虧捉到這個俘虜，才找到監牢。"},
	[32865] = {CommonPl = "山裡人沒什麼好報答的，這些肘子、燻肉、燒酒還有筍乾，您一定要帶上。\r不是什麼值錢東西，全是咱們一片心意。"},
	[32868] = {CommonPl = "您是咱們梅關的恩公，沒什麼能報答您的。\r自此後梅關家家供著您的長生牌位，只為您福壽安康。"},
	[32888] = {CommonPl = "續命72小時黃金期，若貽誤了，便是三豐祖師也回天乏術……可憐我沖虛一身武功，謹正公允，竟換不回弟子的平安，以致重蹈當年覆轍。祖師啊，我愧對你的託付！"},
	[32891] = {CommonPl = "人皆有一死，或重於泰山，或輕於鴻毛。而獨承受飛來橫禍者，最讓我們無法接受。\r以人力行天道之事，本就困難已極，倘能有所成，餘人既得福祉，又能受感佩觸動，功德無量。而志未成竟遭變故打擊，以致身未亡而功全失，何等荒誕無理！\r憤怒，或悲痛，都不能表此情於萬一！"},
	[32894] = {CommonPl = "塵世如潮人如水，\r奔流到海不復回。\r我明明知道，生命之脆弱無常如夢幻泡影，轉瞬即逝。為何卻仍如此心痛，痛得不能思考，艱於呼吸試聽。我們修道，不就是為了臨事時能讓自己看開，我的修煉仍未到家啊！"},
	[32897] = {CommonPl = "兇手是誰！敢對三哥下手！是以為我們武當派一貫手段溫和，不懂那將人碎屍萬段的法門嗎？\r你最好已經做足了心理準備，我們一定叫你後悔來到這世界上！"},
	[32900] = {CommonPl = "別君去兮何時還？且放白鹿青崖間，須行即騎訪名山。\r三哥，你辛苦了很久，放鬆休息下，把擔子交給師傅和我們。等你休息好了，我等著你喝茶品茗，邀月賞花。"},
	[32903] = {CommonPl = "我等向來仰慕沖虛道長，居留在山下一心修道。\r小廟清修，不敢自賤。道觀清貧，故而邋遢。"},
	[32906] = {CommonPl = "別看我這會兒流落到武當山，當年也是日月神教堂堂大小姐。\r若不是任我行遭殃爹爹失事，怎可能如此這般被人呼來喝去！"},
	[32909] = {CommonPl = "這群厚顏無恥的卑鄙小人，如果不是顧及武當派威名，我早就讓他們滿地找牙了，還由得他們在這裡信口雌黃！\r虎落平陽被犬欺，落毛的鳳凰也不是雞！"},
	[32912] = {CommonPl = "見師兄面如見師傅，此時此地欣喜若狂！\r三師兄的狀況已經穩定住了？他不要緊了吧？"},
	[32915] = {CommonPl = "比起善，惡更容易蠱惑人心，尤其當它披著謀略的面具時。然而善，正因為單純，才更強大。\r可惜唯有經歷過至死困境的人，才會明白。只是，誰能換三師兄回來呢？"},
	[32918] = {CommonPl = "提劍跨騎揮鬼雨，\r白骨如山鳥驚飛。\r塵世如潮人如水，\r只歎江湖幾人回。"},
	[32921] = {CommonPl = "從衡山派和武當派的這一連串變故來看，左冷禪陰險歹毒、心狠手辣、視人命如草芥。\r此人和魔教中人還有什麼兩樣？他倒也有自知之明，直接派人假扮魔教，混淆視聽，更深諳朋友背叛之道，使天下人人自危。\r此人多留一天，世道便多一分艱險。"},
	[32936] = {CommonPl = "你這卑鄙無恥的陰險小人，鎮長家的寶鏡還在你手裡，還想抵賴！\r需要我給你搜身嗎？"},
	[32957] = {CommonPl = "長劍在手，壯志藏心。\r蒼生為上，行俠是本。"},
	[32960] = {CommonPl = "……只見他雙目緊閉，臉如金紙，只剩出氣無進氣了。"},
	[32982] = {CommonPl = "眼下三弟生死不明，還有人拿道童開玩笑。看來是存心要我武當不得安生，貽誤三弟的治療時機啊。"},
	[32988] = {CommonPl = "#N，我就知道你會來救我！\r可是，為什麼不是他，他究竟在哪裡……"},
	[32991] = {CommonPl = "俏冤家，一更裡來，二更裡耍，三更裡睡，四更裡雞叫急抓瞎。\r長恨夜短天又曉，冤家又離了懷抱！"},
	[33073] = {CommonPl = "一"},
	[33076] = {CommonPl = "一"},
	[33079] = {CommonPl = "一"},
	[33082] = {CommonPl = "一"},
	[33085] = {CommonPl = "一"},
	[34607] = {CommonPl = "一"},
	[34634] = {CommonPl = "測-世人見得村中霓虹閃耀，體味其間紛雜熙攘。\r卻不知自洪武帝以來，西北四環間多少辛酸落寞。"},
	[34851] = {CommonPl = "不見當年秦始皇"},
	[35311] = {CommonPl = "天下大事，為我所控！……這位少俠，要不要來一碗餛飩？皮薄餡多呐！"},
	[35314] = {CommonPl = "^O003老子江湖漫自誇，\r收今販古是生涯。\r年來怕作朱門客，\r閑坐街坊吃冷茶。^O000\r在下柳敬亭，自幼無藉，流落江湖，雖則為談詞之輩，卻不是飲食之人。"},
	[35317] = {CommonPl = "衡山派的兩系要開打咯，劉爺我挺你！"},
	[35320] = {CommonPl = "胡說八道！莫大先生雖然神龍見首不見尾，但這才是運籌帷幄的大人物應該有的做派！"},
	[35323] = {CommonPl = "（一套整備完畢，隨時可以使用的茶杯）"},
	[35326] = {CommonPl = "爹爹……大哥……芹兒好怕……"},
	[35329] = {CommonPl = "歡迎來到石鼓書院，你要聽我們先生講學嗎？"},
	[35332] = {CommonPl = "上次和小三子鬥蛐蛐輸了兩文錢，這次一定要贏！"},
	[35335] = {CommonPl = "好困哦……"},
	[35338] = {CommonPl = "古來聖賢皆寂寞，惟有飲者留其名……其名……名……名啊……"},
	[35341] = {CommonPl = "師兄……沒關係，你不說的，我都懂。"},
	[35344] = {CommonPl = "一花一世界，一人一江湖，一琴一天地，一劍一婆娑……"},
	[35347] = {CommonPl = "劉家今日所遭之罪，來日我定當十倍奉還！"},
	[35350] = {CommonPl = "喲這位客官，是要竹葉青還是西北望呀？本姑娘釀酒的本領可是全衡山首屈一指的！"},
	[35353] = {CommonPl = "萬花叢中過，片葉不沾身。所謂萬里獨行，除我之外，還能有誰？\r世俗禮教偏偏要教人著他人之鞋，走坎坷之路。須知人生莫放酒杯乾，怎可顧得他人眼光？哈哈哈！"},
	[35356] = {CommonPl = "格老子的……怎麼就中了那人一腳……\r哎喲……老子的屁股……"},
	[35359] = {CommonPl = "得遇盡興之時，豈有錯過之理！\r能與#N在此情此景重會，當是我令狐沖三生有幸！"},
	[35362] = {CommonPl = "這一切……都是因我而起……\r現在……現在該怎麼辦……"},
	[35365] = {CommonPl = "別人笑我太瘋癲，我笑別人看不穿"},
	[35368] = {CommonPl = "令狐大哥，你可千萬要撐住呀！"},
	[35371] = {CommonPl = "我那冤家也不知何時歸還。他這爆脾氣，但願是別遇上魚得水他們……"},
	[35374] = {CommonPl = "一具冰涼的屍體。"},
	[35377] = {CommonPl = "實在是可惡！"},
	[35380] = {CommonPl = "年年交租，伺候完了官老爺還要伺候強盜……"},
	[35383] = {CommonPl = "嗚，我從小就不是做壞人的料，可是我不做壞事就要餓死啦……"},
	[35386] = {CommonPl = "這擔驚受怕的日子，什麼時候是個頭啊？\r這小三子……這次也不提前告訴他老哥哥一聲"},
	[35389] = {CommonPl = "你莫問我，我啥子也不說！呃……\r我啥子也不曉得！"},
	[35392] = {CommonPl = "劉家今日所遭之罪，來日我定當十倍奉還！"},
	[35395] = {CommonPl = "嗚嗚……老爺，我對不住老爺……\r如果我……可惜我……實在挨不住了……"},
	[35398] = {CommonPl = "爹爹……娘……救我……為什麼丟下我……"},
	[35401] = {CommonPl = "好教你嵩山奸賊知曉！我劉家無一是貪生怕死之徒！"},
	[35404] = {CommonPl = "已經沒氣了……"},
	[35407] = {CommonPl = "兩位老前輩的深厚友情實在令人動容……"},
	[35410] = {CommonPl = "得遇一知己，此生已無憾矣。\r若有來世，願車塵馬足，笑看一世風流……"},
	[35413] = {CommonPl = "什麼是正，什麼是邪？一切，不過是人心在作祟……"},
	[35416] = {CommonPl = "已經是冰冷的小非了。再也不會說話不會笑……"},
	[35419] = {CommonPl = "嵩山派劍指江湖，所行自是不義。華山一系，無意奉陪。\r哼！巨檜喬松，生我東峰，巋然不為所動。"},
	[35422] = {CommonPl = "沒想到洗手大會會是這個結果，唉……"},
	[35425] = {CommonPl = "這猴兒，可是你帶來與大師兄的？呵呵，大師兄將其轉贈與我，想來還是托了#N的福。\r這小猴可是討喜！只是現在我可是名符其實的六猴兒了，哈哈。"},
	[35428] = {CommonPl = "曲長老的朋友就是我們的朋友，放心吧！"},
	[35431] = {CommonPl = "嚶嚶嚶嚶……"},
	[35528] = {CommonPl = "貧道是專程來調查廠衛行蹤的，掌門說他們來者不善。"},
	[35539] = {CommonPl = "這群人凶的很，也不知什麼時候能放我回家。"},
	[35542] = {CommonPl = "我素來仰慕劉正風前輩的琴技，可惜重任在身，無暇去衡山城劉府拜會。"},
	[35582] = {CommonPl = "廠衛的番子不遠千里而來，一定有詭計。"},
	[35585] = {CommonPl = "我武當創派以來，除了昔年蒙古紹敏郡主以外，未曾有人敢攜帶刀劍上山。"},
	[35588] = {CommonPl = "磨剪子嘞，鏘菜刀～"},
	[35591] = {CommonPl = "未曾想，楊某告發魏忠賢閹黨，卻連累家小被人尋仇。"},
	[35594] = {CommonPl = "唉，路漫漫其修遠兮，吾將上下而求索。"},
	[35597] = {CommonPl = "好了，此處似乎安全了許多。"},
	[35600] = {CommonPl = "呃……許顯純乃是魏忠賢得力幫兇，名列五彪之一。"},
	[35603] = {CommonPl = "（石碑上記載著明太祖朱元璋敕建大嶽太和山的124道聖旨）"},
	[35609] = {CommonPl = "無量天尊，貧道在此等你多時。"},
	[35612] = {CommonPl = "桃幹仙沒我英俊。"},
	[35615] = {CommonPl = "放屁放屁，臭不可聞。"},
	[35618] = {CommonPl = "吵吵個屁，老子告訴你們，去找令狐沖才是頭等大事。"},
	[35621] = {CommonPl = "閉嘴吧，誰知道令狐沖長什麼樣？不知道什麼樣子怎麼找？"},
	[35624] = {CommonPl = "人人都說我桃花仙美的就像桃花一樣。"},
	[35627] = {CommonPl = "那可真是污蔑了桃花。"},
	[35630] = {CommonPl = "什麼劍宗屁宗，已經被逐出華山派了，還來幹嘛！小心我大師兄把你們打得自己親娘都認不出來！"},
	[35633] = {CommonPl = "師父……師娘……弟子……弟子無礙，那群惡人可走了嗎？"},
	[35645] = {CommonPl = "沒想到幾十年過去了，仍有人再提起這些破事，還嫌華山派衰的不夠快麼！？"},
	[35648] = {CommonPl = "風太師叔讓我遠離成不憂等人，說他們行止不端。但依我看，氣宗那些人也不是什麼好人。"},
	[35651] = {CommonPl = "唔，我的腿似乎折了。"},
	[35711] = {CommonPl = "一個人玩很無聊的啊，你有空就來陪我撲蝴蝶嘛！\r……偶爾欺負一下大人也不錯，那是我最喜歡的了，嘿嘿。"},
	[35714] = {CommonPl = "一個人玩很無聊的啊，你有空就來陪我撲蝴蝶嘛！\r……偶爾欺負一下大人也不錯，那是我最喜歡的了，嘿嘿。"},
	[35717] = {CommonPl = "一個人玩很無聊的啊，你有空就來陪我撲蝴蝶嘛！\r……偶爾欺負一下大人也不錯，那是我最喜歡的了，嘿嘿。"},
	[35720] = {CommonPl = "一個人玩很無聊的啊，你有空就來陪我撲蝴蝶嘛！\r……偶爾欺負一下大人也不錯，那是我最喜歡的了，嘿嘿。"},
	[35723] = {CommonPl = "一個人玩很無聊的啊，你有空就來陪我撲蝴蝶嘛！\r……偶爾欺負一下大人也不錯，那是我最喜歡的了，嘿嘿。"},
	[35726] = {CommonPl = "君子報仇十年不晚，青城派滅我林家，害我父母，吾當隱忍蟄伏，待到他日千百倍償還之！"},
	[35729] = {CommonPl = "菩薩保佑……令狐……令狐師兄不會有事的……\r這都是那個歹人不好！不……都是因為我……"},
	[35732] = {CommonPl = "別……別擔心，我死不了，喝口酒就好……"},
	[35901] = {CommonPl = "令狐大哥……你可一定要撐住啊……"},
	[35904] = {CommonPl = "令狐大哥……你可一定要撐住啊……"},
	[35922] = {CommonPl = "幫我打跑這些欺負人的壞蛋！"},
	[35925] = {CommonPl = "哈哈哈哈，痛快痛快！！！"},
	[35928] = {CommonPl = "閑言少敘，速速前去搭救兩位前輩！"},
	[35931] = {CommonPl = "路見不平，拔刀相助，這是我等江湖人士份內之事！"},
	[35934] = {CommonPl = "好酒好酒，來來來，你我痛飲三百杯！"},
	[35937] = {CommonPl = "華山思過崖，無酒無肉，著實不是個好去處！"},
	[35940] = {CommonPl = "敵人眾多，只有殺出一條血路沖過去了！"},
	[35943] = {CommonPl = "包圍重重，敵人顯然早有準備，得另想個辦法！"},
	[35946] = {CommonPl = "爺爺怎麼還不來？他讓我在這裡等著他。"},
	[35949] = {CommonPl = "江湖門派眾多，仔細斟酌之後才好決定拜入何門何派！"},
	[35952] = {CommonPl = "……"},
	[35955] = {CommonPl = "老夫曲洋，相救來遲，切勿見怪！"},
	[35958] = {CommonPl = "天下武林，全負擔你們年輕一輩身上了！"},
	[35961] = {CommonPl = "陰險小人，能耐我何？"},
	[35964] = {CommonPl = "……"},
	[35967] = {CommonPl = "多少英雄好漢埋骨江湖，不知所求為何？唉！\r^O003不見五陵豪傑墓，無花無酒鋤做田！^O000"},
	[35970] = {CommonPl = "說不得，只好退隱江湖，遠離這無盡是非了！"},
	[35973] = {CommonPl = "天下武林正道，以我嵩山為首，哈哈哈哈哈！！！"},
	[35976] = {CommonPl = "……"},
	[35979] = {CommonPl = "^O003各有因緣莫羨人^O000，緣之一事，切莫強求！"},
	[35982] = {CommonPl = "……"},
	[35985] = {CommonPl = "……"},
	[35988] = {CommonPl = "……"},
	[35991] = {CommonPl = "……"},
	[35994] = {CommonPl = "……"},
	[35997] = {CommonPl = "……"},
	[36000] = {CommonPl = "……"},
	[36003] = {CommonPl = "……"},
	[36006] = {CommonPl = "哼，有人說本派行為不端，行事詭異？什麼人，敢不敢同我當面對質？"},
	[36009] = {CommonPl = "個人有個人的想法。把自己的想法強加於別人之上，這和殺人無異！"},
	[36012] = {CommonPl = "阿彌陀佛，若能阻止這場爭鬥，乃是我等無量功德！"},
	[36015] = {CommonPl = "阿彌陀佛，不擊敗賊人頭領，我等難以脫困！"},
	[36018] = {CommonPl = "哼，邪魔外道，人人得而誅之！"},
	[36021] = {CommonPl = "不殺賊首，誓不為人！"},
	[36039] = {CommonPl = "我保鏢四十年，護送寶物金銀往來，路上沒出一點岔子！想不到……"},
	[36042] = {CommonPl = "……（林平之冷淡地看了你一眼，一言不發。）"},
	[36117] = {CommonPl = "在下日月施令威！"},
	[36120] = {CommonPl = "在下五仙教靈兒！"},
	[36123] = {CommonPl = "在下唐門唐婉！"},
	[36126] = {CommonPl = "在下少林覺明！"},
	[36129] = {CommonPl = "在下武當玄高！"},
	[36132] = {CommonPl = "在下峨眉松紋！"},
	[36135] = {CommonPl = "在下逍遙劍璿！"},
	[36138] = {CommonPl = "在下華山英白羅！"},
	[36141] = {CommonPl = "在下衡山方千駒"},
	[36144] = {CommonPl = "在下恆山儀清！"},
	[36147] = {CommonPl = "^O003生亦何歡，死亦何苦？\r憐我世人，憂患實多！^O000\r世間善惡糾葛，著實難辨！"},
	[36150] = {CommonPl = "毒蟲是毒，卻毒不過人心。剜肉流血是痛，卻痛不過情商。\r我五仙只收女弟子，臭男人嘛？哼！想作肥料飼餵蠱兒的只管來！"},
	[36153] = {CommonPl = "我家太君什麼都好，就是心腸太軟，只怕早晚要吃大虧。"},
	[36156] = {CommonPl = "修佛為修心，習武只是強健體魄的一種途徑。\r不過，我派只收男弟子，女施主們……不妨去定逸師太那裡看看可有因緣。"},
	[36159] = {CommonPl = "哼。邪魔外道，都披著個正義的幌子。別以為天下人都如此愚蠢，連這點小把戲都看不出！"},
	[36162] = {CommonPl = "乾坤二氣生陰陽，陰陽和合化太極。這太極乃是道家的象徵，無始無終，無往不復，無窮無盡。"},
	[36165] = {CommonPl = "^O003湖上西風急暮蟬。夜來清露濕紅蓮。\r少留歸騎促歌筵。為別莫辭金盞酒，\r入朝須近玉爐煙。不知重會……是何年。^O000"},
	[36168] = {CommonPl = "華山派正氣十足，本派弟子有所為，有所不為，此乃真正習武之人所做之事。"},
	[36171] = {CommonPl = "今日衡山派在此除魔衛道，難得齊聚一堂。今晚大家把酒言歡，不歡不散！"},
	[36174] = {CommonPl = "為我門人，當心懷慈悲，性情剛烈固執，困怕難得善果，阿彌陀佛！！！"},
	[36243] = {CommonPl = "殺！"},
	[36246] = {CommonPl = "殺！"},
	[36249] = {CommonPl = "殺！"},
	[36309] = {CommonPl = "文官不愛財，武官不怕死。老夫一不愛財，二不怕死，一心只要匡扶社稷，試問天下誰敢阻我！"},
	[36481] = {CommonPl = "小心行事。"},
	[36487] = {CommonPl = "一個人玩很無聊的啊，你有空就來陪我撲蝴蝶嘛！\r……偶爾欺負一下大人也不錯，那是我最喜歡的了，嘿嘿。"},
	[36490] = {CommonPl = "怎麼了？"},
	[36701] = {CommonPl = "三豐祖師在上，弟子吳昆山誓死守衛武當山。"},
	[36704] = {CommonPl = "大膽狂徒，還不速速解除刀劍。"},
	[36707] = {CommonPl = "解劍岩前，必須除去武裝，否則就是與我武當派為敵。"},
	[36710] = {CommonPl = "這“真武七截陣”威力絕大，輕易不會動用。"},
	[36713] = {CommonPl = "我從未見吳師兄如今天這般震怒。"},
	[36716] = {CommonPl = "哼，廠衛素來欺壓良善，今日來的正好，讓他們嘗嘗我派陣法的厲害。"},
	[36830] = {CommonPl = "我老頭子活了一輩子，也沒見誰敢來武當山鬧事。這次算是開了眼。"},
	[36839] = {CommonPl = "武當晚輩不乏俊彥之流，但能演練“真武七截陣”的卻寥寥無幾。"},
	[36842] = {CommonPl = "今日一別，不知何時才能再見，唉。"},
	[36845] = {CommonPl = "天下無不散之筵席，便就在這裡和儀琳師妹道別吧。"},
	[36897] = {CommonPl = "什麼武林泰斗江湖至尊，我錦衣衛要拿人，天王老子也休想阻擋！"},
	[36900] = {CommonPl = "我等為朝廷辦事，誰敢不服？再多看我一眼，小心抓你下獄。"},
	[36909] = {CommonPl = "這幾天發生了太多的事，平靜下來，便是時候啟程了……"},
	[36912] = {CommonPl = "師兄說要帶領兄弟們幹一件大事，我也只是聽令而已……"},
	[36953] = {CommonPl = "師兄說要帶領兄弟們幹一件大事，我也只是聽令而已……"},
	[37055] = {CommonPl = "南來的北往的，\r唐時的宋代的，\r墳裡的宮中的，\r黃金的碧玉的，\r買不買瞧瞧也是好的哩。"},
	[37058] = {CommonPl = "殘雪空山冷孤城。\r落梅橫笛已三更，更無人處月朧明。\r我是人間惆悵客，知君何事淚縱橫。\r斷腸聲裡憶平生。"},
	[37061] = {CommonPl = "我黑皮老三在衡山城賣了四十年豬肉，從來是童叟無欺。\r五花肉肥瘦相間，做紅燒肉最好。\r裡脊最嫩，宜炒肉絲。\r回鍋肉必得坐臀肉，糖醋排骨則要肋排。\r肚子肉質差，卻能熬油。\r你看你來點啥？"},
	[37064] = {CommonPl = "新鮮豬肉，肉紅脂白！\r五花肉肥瘦相間，做紅燒肉最好。\r裡脊最嫩，宜炒肉絲。\r回鍋肉必得坐臀肉，糖醋排骨則要肋排。肚子肉質差，卻能熬油。\r您來點什麼肉？"},
	[37067] = {CommonPl = "落花人獨立，微雨燕雙飛。"},
	[37070] = {CommonPl = "這雨不知道什麼時候才會停，我還趕著去城外見佃農看看今年的收成呢。"},
	[37073] = {CommonPl = "獨立小橋風滿袖，平林新月人歸後。"},
	[37076] = {CommonPl = "真是可氣，分明是他濺了我一身泥水，反說是我的包袱蹭髒了他的馬車，怎能這樣仗勢欺人！"},
	[37079] = {CommonPl = "雨天正是睡覺天，可歎我這勞碌命還要出來奔口飯吃。"},
	[37082] = {CommonPl = "這雨真可恨！\r早不下晚不下，偏生人家穿了這新做的裙子出來，它下個不停。\r裙角都被沾濕了!"},
	[37085] = {CommonPl = "郎君如解意，月夕相攜歸。"},
	[37088] = {CommonPl = "萌萌最喜歡下雨了！沙沙沙的真好聽。"},
	[37091] = {CommonPl = "好端端怎麼下起雨來，唉唉唉，我早起還曬著被子呢，這可全泡湯了。"},
	[37094] = {CommonPl = "真是好酒。"},
	[37097] = {CommonPl = "你這人真有趣，大家都忙著躲雨，你卻在雨裡喝酒。"},
	[37100] = {CommonPl = "今夕何夕，見此良人……"},
	[37109] = {CommonPl = "夫君……"},
	[37112] = {CommonPl = "這幾日心裡頗不安寧，但願一切順利才好……"},
	[37115] = {CommonPl = "賢婿，我這寶貝女兒就託付給你了。"},
	[37118] = {CommonPl = "真是天作之合啊。"},
	[37121] = {CommonPl = "唉，這樣個美嬌娘，竟被不知哪裡冒出來的小子娶了去，只恨我爹娘沒給我訂下這樣的娃娃親。"},
	[37124] = {CommonPl = "梅雪這孩子是我看著長大的，最是和順乖巧，你這少年仔倒是好命，白撿個這樣好的媳婦。"},
	[37127] = {CommonPl = "小時候我們倆一起約定，一定要尋個自己真心實意喜歡的郎君，如今梅雪已經找到了，可我……"},
	[37130] = {CommonPl = "梅雪姐真是好福氣，嫁個這樣俊俏的郎君。"},
	[37133] = {CommonPl = "師叔，快回華山！"},
	[37136] = {CommonPl = "你喜歡哪個花樣，隨便看看.\r都是自家手藝，繡些看在眼裡記在心裡的舊時風光。\r不敢和那大繡坊比，只當買個野趣兒。"},
	[37139] = {CommonPl = "梅雪，我如今眼花的都拿不得針了，你這手藝倒是越來越好了。"},
	[37142] = {CommonPl = "殘雪空山冷孤城。\r落梅橫笛已三更，更無人處月朧明。\r我是人間惆悵客，知君何事淚縱橫。\r斷腸聲裡憶平生。"},
	[37449] = {CommonPl = "這群閹人，來到武當腳下也敢作威作福，若不是武當派沖虛道長閉關，豈容你們放肆。"},
	[37452] = {CommonPl = "說什麼葵花寶典都是胡扯，依我看這次是魏忠賢想借機削弱我武當實力。"},
	[37535] = {CommonPl = "先生要求背的書我還一個字都沒背，反正是要挨罵的，我不如多玩一會兒……"},
	[37541] = {CommonPl = "嗚嗚嗚嗚，我不想罰站，我以後再也不敢了。"},
	[37544] = {CommonPl = "學而時習之，不亦說乎？\r有朋自遠方來，不亦說乎？\r人不知而不慍，不亦君子乎？\r……\r白日會周公，不怕戒尺乎？\r"},
	[37556] = {CommonPl = "公子，你看你都淋濕了，快到我傘下避避雨吧。"},
	[37835] = {CommonPl = "真熱鬧。"},
	[37902] = {CommonPl = "展兒，展兒啊，你在哪裡？！"},
	[37905] = {CommonPl = "我裘展今天定要將這些壞蛋趕出武當！"},
	[37932] = {CommonPl = "（籠子裡空空如也）"},
	[37935] = {CommonPl = "壯士你要幹啥？不要打擾我發財……"},
	[37941] = {CommonPl = "一個人玩很無聊的啊，你有空就來陪我撲蝴蝶嘛！\r……偶爾欺負一下大人也不錯，那是我最喜歡的了，嘿嘿。"},
	[37947] = {CommonPl = "一個人玩很無聊的啊，你有空就來陪我撲蝴蝶嘛！\r……偶爾欺負一下大人也不錯，那是我最喜歡的了，嘿嘿。"},
	[37950] = {CommonPl = "一個人玩很無聊的啊，你有空就來陪我撲蝴蝶嘛！\r……偶爾欺負一下大人也不錯，那是我最喜歡的了，嘿嘿。"},
	[37953] = {CommonPl = "爹爹……大哥……芹兒好怕……"},
	[37956] = {CommonPl = "小心行事。"},
	[37959] = {CommonPl = "君子報仇十年不晚，青城派滅我林家，害我父母，吾當隱忍蟄伏，待到他日千百倍償還之！"},
	[37998] = {CommonPl = "君子報仇十年不晚，青城派滅我林家，害我父母，吾當隱忍蟄伏，待到他日千百倍償還之！"},
	[38001] = {CommonPl = "君子報仇十年不晚，青城派滅我林家，害我父母，吾當隱忍蟄伏，待到他日千百倍償還之！"},
	[38105] = {CommonPl = "快，快去救爺爺！！！"},
	[38108] = {CommonPl = "爺爺總是怕我說錯話闖禍，所以我什麼都不能說……"},
	[44108] = {CommonPl = "好個五嶽盟主！打著匡扶武林正氣的旗號，卻做些濫殺無辜的勾當！"},
	[44111] = {CommonPl = "劉師伯和曲先生肝膽相照卻落得如此下場，上天不公！"},
	[44117] = {CommonPl = "阿彌陀佛！請菩薩保佑逝去的靈魂安息，聞法得度，離苦得樂，往生淨土！"},
	[44130] = {CommonPl = "衡山派的地盤上，竟然會有這等無恥之徒，我，我要去師父那裡告狀，嚶嚶……"},
	[44133] = {CommonPl = "一具衣衫不整的屍體"},
	[44136] = {CommonPl = "我在衡山城倒了大半輩子的夜香，這裡的一草一木我都熟悉得很！"},
	[44139] = {CommonPl = "你再這麼無禮地接近我，我就要揍你了。"},
	[44142] = {CommonPl = "我最近是不是病了，頭昏眼花腿抽筋，砍個柴差點把自己手給剁了！"},
	[44145] = {CommonPl = "你這是自尋死路！"},
	[44148] = {CommonPl = "^O003誰道色香味，只許入皇家？\r今上毗盧洞，逍遙吃貢茶！^O000\r咱們衡山的雲霧茶味醇色秀，這位客人，要不要來一杯潤潤喉嚨？"},
	[44151] = {CommonPl = "（關押著劉府公子的囚籠）"},
	[44274] = {CommonPl = "令狐大哥說得對，一見尼姑，逢賭必輸……"},
	[44317] = {CommonPl = "哎呀，殺人啦！大白天的，好端端的姑娘，突然就暴屍街頭了，這世道還讓不讓人活啊！"},
	[44343] = {CommonPl = "這華山可真是漂亮！"},
	[44346] = {CommonPl = "令狐沖！令狐沖！令狐沖你在哪！？"},
	[44349] = {CommonPl = "吵吵個屁，老子告訴你們，去找令狐沖才是頭等大事。"},
	[44352] = {CommonPl = "閉嘴吧，誰知道令狐沖長什麼樣？不知道什麼樣子怎麼找？"},
	[44355] = {CommonPl = "人人都說我桃花仙美的就像桃花一樣。"},
	[44358] = {CommonPl = "哇！這就是傳說中天下第一險的西嶽華山啊！"},
	[44361] = {CommonPl = "多虧了這位少俠，才能將許顯純這惡賊拒於武當山門外。"},
	[44378] = {CommonPl = "福王仁政特在此招募願為國效力之能人異士，有什麼案子我可以幫你做筆錄張貼在皇榜上！\r發佈時間：10：00-19：00\r結算時間：19：00-23：59"},
	[44510] = {CommonPl = "師父平日裡最疼我了，他要金盆洗手，我得想辦法讓一切都順利才行。可是，我武功這麼差，怎樣才能幫到他呢？"},
	[44725] = {CommonPl = "哼，我最看不起這些以名門正派自居的嵩山弟子！"},
	[44737] = {CommonPl = "這些江湖仇殺，真不知何時能了啊！"},
	[44752] = {CommonPl = "正教，邪教，這些是是非非真是說不清楚！"},
	[44813] = {CommonPl = "江湖風波險惡，十大門派也免不了爭名奪利。"},
	[44816] = {CommonPl = "迢迢牽牛星，皎皎河漢女。\r纖纖擢素手，劄劄弄機杼。\r終日不成章，泣涕零如雨。\r河漢清且淺，相去複幾許？\r盈盈一水間，脈脈不得語。"},
	[45081] = {CommonPl = "綁票綁票我最愛，最愛啊！"},
	[45200] = {CommonPl = "自從老爺舉家搬往新宅，我就日日思念平之小少爺。只好收養了小靈子、小蟲子、小平子、小琳子這幾個娃娃，以慰年老寂寞之心．"},
	[55439] = {CommonPl = "福王仁政特在此招募願為國效力之能人異士，有什麼案子我可以幫你做筆錄張貼在皇榜上！\r發佈時間：10：00-19：00\r結算時間：19：00-23：59"},
	[55440] = {CommonPl = "這裡記錄著各種奇案！"},
	[55591] = {CommonPl = "唐時大詩人韓愈來登華山，被困在這天下第一險的西嶽山巔之上，嚎啕大哭驚動了華陰的縣令。哈哈，還是我祖上奉縣令之命，費了好許力氣，才將他救下山來。"},
	[55594] = {CommonPl = "誰日思夜想了？你……你們就是胡說八道"},
	[55597] = {CommonPl = "琳兒，你跟他說，爹爹的法名叫作甚麼。"},
	[55600] = {CommonPl = "來點什麼酒？"},
	[55603] = {CommonPl = "這可惡的賊禿，下手可是真重！"},
	[55606] = {CommonPl = "想不到在這窮鄉僻壤，還能遇到好酒之人，真是意外！"},
	[55609] = {CommonPl = "他日一統江湖，千秋萬代，自然有你一份功勞！"},
	[55612] = {CommonPl = "莫要驚慌，有我在此，包你有勝無敗！"},
	[55615] = {CommonPl = "吱吱吱~（猴王看著你沖你低鳴，它那眼神仿佛看穿了你的心）"},
	[55618] = {CommonPl = "想不到這小小的洞裡，今日竟然來了這麼多朋友。"},
	[55621] = {CommonPl = "往事如煙，想不到時隔數十年，竟然在此遇到獨孤前輩的隔世傳人！"},
	[55624] = {CommonPl = "無招破有招，果真是精妙無比的劍法！"},
	[55627] = {CommonPl = "哼，大師哥真是惹人生氣，我才不要去理他！"},
	[55630] = {CommonPl = "大師哥一表人才，武功又高，我得日夜勤學苦練，方不致落後！"},
	[55633] = {CommonPl = "自大小林子來了之後，小師妹的性子變得太多了！"},
	[55636] = {CommonPl = "很好，你挺有骨氣，又有眼光，看得出我們六兄弟武功高強，我兄弟們也很佩服。"},
	[55639] = {CommonPl = "少囉嗦，我們帶你去見小尼姑。"},
	[55642] = {CommonPl = "我叫小尼姑不擔心，她未必就聽我話，就算她聽了我話，假裝不擔心，其實還是在擔心。\r"},
	[55645] = {CommonPl = "小尼姑不可怕，大和尚卻有點難惹！"},
	[55648] = {CommonPl = "你為甚麼不看？瞧不起我們兄弟的功夫，我偏要你看。"},
	[55651] = {CommonPl = "我還有許多好功夫呢，這就試演幾種給你瞧瞧。"},
	[55654] = {CommonPl = "這……這……桃谷六仙真是亂七八糟，一塌糊塗……"},
	[55660] = {CommonPl = "你不敢欺騙我和你師娘？那你這些劍法，哼哼，是從哪裡學來的？難道真是夢中神人所授，突然間從天上掉下來不成？"},
	[55663] = {CommonPl = "我相信沖兒，絕不會偷什麼辟邪劍譜！"},
	[55666] = {CommonPl = "天不亮就得起身押鏢上路，前方是人是鬼都看不清，前些日子我早起裝貨，突然看見一人影在牆角鬼鬼祟祟，我沖過去就是一棍子，結果就一棍子敲昏了少鏢頭，從哪之後少鏢頭的性格就變得越發暴躁起來。"},
	[55821] = {CommonPl = "走進一間房，四面都是牆……\r都是牆，還都是石頭牆……\r我金刀王府也算得上江湖名門，在這洛陽城中也是數一數二的大戶，只是，只是這王府裡，略冷……\r還記得小時候在伊川書院，先生教我們成語，家徒四壁、形影相弔，年紀輕輕又怎能理解。\r可如今，你看看這世間，卻讓人感到一種前所未有的苦澀，人生既如此，不是嗎？"},
	[55824] = {CommonPl = "我是王家的臨時工，髒活累活是我做，有了黑鍋我來背。不過前幾日遇到一個算命瞎子，他說我這樣的臨時工還不算悲慘的，悲慘的是幾百年後的同行。"},
	[55827] = {CommonPl = "好險！好險！嵩山派的高手真厲害，多虧我拼命的護住了臉，我英俊的相貌才得以保全。"},
	[55830] = {CommonPl = "安全第一！安全第一！拿著大刀嚇唬下人就可以了，危險的地方不能去！"},
	[55833] = {CommonPl = "上次去了趟京城，那些太監總在喊：“把根留住、把根留住”。他奶奶的，老子怎麼會被一群太監奉承。"},
	[55836] = {CommonPl = "一花一世界，一葉一如來。我桃葉仙到底是仙人還是如來？"},
	[55839] = {CommonPl = "別怪我名字不乾淨，別怪我名字不乾淨！！！"},
	[55842] = {CommonPl = "和這幫不讀書的人站在一起，真丟我的臉？連“老吾老以及人之老”的意思都不明白，這還用問嗎？就是要像愛自己老婆一樣愛別人的老婆。"},
	[55845] = {CommonPl = "“桃花屋裡桃花庵，桃花屋下桃花仙……”。豈知百年之後，這桃花會不會變成菊花！"},
	[55848] = {CommonPl = "田伯光這傻小子跑哪裡去了？他上次念叨什麼：“尼姑山下尼姑庵，尼姑輕解尼姑衫，尼姑伯光倫法術，菩薩像前須盡歡”。奶奶的，說的什麼爛玩意？"},
	[55851] = {CommonPl = "別看我只是個賣茶的，可是江湖大事，我知道的可著實不少！\r“那武當太極拳名揚天下，豈料沖虛道人以此拳法與嵩山掌門左冷禪的寒冰神掌比試的時候，卻輸了半招。更讓人想不到的是，左掌門遇見魔教東方教主時，東方不敗輕抖右手食指、中指，兩道紅影掠過，左掌門就被嚇出了一身冷汗。最不解的是，東方教主對沖虛道長卻有所忌憚，她雖然兩指頻彈，卻奈何不了道長的拳頭。以此看來，天下武學相生相剋，倒也不能一概而論”\r哎，這可惜我把此事說與那口子聽的時候，她卻說：“說了這麼多，無非是石頭、剪刀、布罷了”。"},
	[55860] = {CommonPl = "裝神弄鬼，爺爺跟你們拼了。"},
	[55863] = {CommonPl = "百藥門有什麼了不起，無非就是會這幾句：“藥、藥、藥，切克鬧…”"},
	[55866] = {CommonPl = "奶奶的，弄得爺爺兩眼流淚，險些撞在樹上！"},
	[55869] = {CommonPl = "這幾個兄弟真不像話，偏偏這些跑腿的活兒讓我來幹！！"},
	[55872] = {CommonPl = "我一生的夢想，就是變成大哥，兄弟奉養、不勞而獲，哈哈哈哈！！！"},
	[55875] = {CommonPl = "年輕人，莫嫌老子走的慢，步子邁得太大，容易扯著蛋！"},
	[55878] = {CommonPl = "想當初，我給先帝煉製紅丸！哎，只可惜娘娘覺得藥效不佳，打發我回老家了！"},
	[55881] = {CommonPl = "雖不明真相，但也要文明圍觀。邊抵抗，邊圍觀。"},
	[55884] = {CommonPl = "病了不要緊，可光吃飯不幹活就不對了，現在全村的田讓我一個人來耕，這能讓我不憤怒嗎？"},
	[55887] = {CommonPl = "怎麼都病了？瘟疫尚可治，腦殘無藥醫啊！"},
	[55905] = {CommonPl = "中毒後感覺全身癢癢的，腦子也漸漸不好使了"},
	[55908] = {CommonPl = "火把？有什麼用？"},
	[55911] = {CommonPl = "有些男子會掠過心扉，有些男子會一生記掛。"},
	[55914] = {CommonPl = "小林子真討厭，呆呆傻傻的，可是他不在的時候又怪想他。"},
	[55917] = {CommonPl = "到底是何人與我華山派為敵？吃了豹子膽了嗎？"},
	[55920] = {CommonPl = "唉，大師兄會逗我開心，小林子踏實穩重，好是難選！"},
	[55923] = {CommonPl = "有些人，她明明已經走遠了，目光卻依舊逃離不了她的倩影。"},
	[55926] = {CommonPl = "每次練習孤獨心法的時候，都會感受到獨孤的心境。"},
	[55929] = {CommonPl = "有些路，走過了，就再不會回來。路是如此，人也如此。"},
	[55932] = {CommonPl = "此時有一壺好酒就好了，何以解憂，唯有杜康！"},
	[55935] = {CommonPl = "事不宜遲，速到藥王廟"},
	[55938] = {CommonPl = "你的輕功大有長進，不出時日，定會獨步天下"},
	[55941] = {CommonPl = "華山派就是我的家，可如今家人卻對我冷冷冰冰。"},
	[55944] = {CommonPl = "我本來是百藥門裡膽子最大的人，只是有次盜了女屍，又做了齷齪之事後。每天晚上身體就越來越虛了。好可怕！"},
	[55947] = {CommonPl = "屍蠱粉這東西，如若和其它幾位草藥同咀嚼的話，是越吃越上癮。糟了，我也想偷吃了，只是最近腦子越來越不好使了！"},
	[55950] = {CommonPl = "孔夫子和我有仇嗎？為何說：“君子群而不黨，小人黨而不群”。"},
	[55953] = {CommonPl = "沖兒這孩子我從小看到大，他絕不會做半點對不起師門的事！"},
	[55956] = {CommonPl = "靈珊每次叫我小林子的時候，廠衛太監看我的眼神都怪怪的。"},
	[55965] = {CommonPl = "令狐大師兄方才露的那一手功夫，好厲害！"},
	[55968] = {CommonPl = "屍蠱粉口感甜滑、微有辣味，吃一錢便腦殘，食三錢變僵屍，實在是居家旅行，殺人越貨必備之良藥！還楞著幹什麼？還不嘗嘗，你值得擁有！"},
	[55971] = {CommonPl = "“三山五嶽，唯我西岳不群；四面八方，獨他東方不敗？”，江湖人的這句話，難道是要老夫挑戰東方不敗不成？"},
	[55974] = {CommonPl = "華山派斷不能在我手中毀掉！"},
	[56122] = {CommonPl = "小林子這般焦急的追出來，怎麼也不等我一等！"},
	[56125] = {CommonPl = "小林子是不是怪我說了大師哥的好，這才賭氣獨自離開……可是大師哥的為人，爹娘最清楚不過，怎麼會做那等背信棄義私藏秘笈的事情！"},
	[56128] = {CommonPl = "小林子要是受傷了……可怎生是好。"},
	[56131] = {CommonPl = "咱們可要小心啦，千萬要小心這些巡視的嵩山高手。"},
	[56134] = {CommonPl = "既然這辟邪劍譜果真在那青城惡人手中，那可是咱們都冤枉了大師兄。"},
	[56137] = {CommonPl = "這裡的水好深，水流很急，我、我……"},
	[56140] = {CommonPl = "那少林的和尚們好生多事，為何要阻止小林子奪回自家劍譜！"},
	[56143] = {CommonPl = "嵩山的賊子們，我林平之發誓：今日所受之辱，有朝一日定要加倍奉還！"},
	[56146] = {CommonPl = "辟邪劍譜絕不能落入嵩山惡賊手裡！"},
	[56149] = {CommonPl = "我林平之有朝一日，必將用那辟邪劍法手刃仇人！"},
	[56152] = {CommonPl = "正事要緊，咱們且先留了嵩山小兒們的性命，日後總有清算的時候。"},
	[56155] = {CommonPl = "各色江湖奇藥，我信春爺！"},
	[56158] = {CommonPl = "嘿嘿，可歎那林家後人太也不濟！莫說那個僥倖逃命的嬌嫩小公子，便是林震南一身武功也只平平，倒也難怪江湖中那些野心之人覬覦。"},
	[56161] = {CommonPl = "曾哥客氣，江湖上誰不知你那”鐵獅拳“，”流星錘“的威名！"},
	[56164] = {CommonPl = "哼！那辟邪劍譜虛名在外，偏那林家後人如此不濟，不啻於三歲小兒懷揣寶藏，也難怪那許多人不要臉面來強取了。"},
	[56167] = {CommonPl = "青城派那個叫錢人仇的小子，還真是欠人抽！浪費老子這麼多時間，要是落在了咱手裡，嘿嘿嘿……"},
	[56170] = {CommonPl = "師父說了，遇到了不解的事情，就要想個明白，辯個透徹。這不僅僅是一桶水的問題，其中蘊含的禪機……待小僧仔細發掘一下！"},
	[56173] = {CommonPl = "空即是色色即是空，貧僧這具身體不過是個皮囊，有無僧衣包裹本也無甚不同。可是、但是、可但是……貧僧也不能真的就這麼出去，罪過罪過。"},
	[56176] = {CommonPl = "阿彌陀佛，世間沒有好也沒有壞，只有因果在，世間沒有對也沒有錯，只有分別在，世間沒有是也沒有非，只有執著在。還望眾位施主莫要再造殺孽，放下屠刀立地成佛。"},
	[56179] = {CommonPl = "諸位施主且聽老衲一言，冤冤相報何時了？這一生你殺了我，下一世我又殺了你，如此因果相循、恩怨難了，生生世世無窮盡也。\r願諸位施主能放下妄想分別執著，放下貪嗔癡慢，放下人我是非恩恩怨怨，純淨純善，大家一同往生西方極樂世界，豈不更好！"},
	[56182] = {CommonPl = "世界如此美好，這些人卻如此暴躁，這樣不好。師傅說了，嗔念如同烈火，將善根善業焚盡，從此墮入無邊業海、無盡地獄、無有出期……"},
	[56185] = {CommonPl = "派那嵩山賊子，竟敢殺到我少林家門口！今日就叫他們明白，咱少林弟子不只會念經，打架的本事更是不在話下！"},
	[56188] = {CommonPl = "繩命是如此的精彩，繩命是如此的美麗！"},
	[56191] = {CommonPl = "阿彌陀佛，自皈依法，當願眾生，深入經藏，智慧如海。"},
	[56194] = {CommonPl = "惡狗……不是惡狗，小僧、小僧不怕惡狗。"},
	[56197] = {CommonPl = "這天下大事沒有爺不知曉的，可是唯獨那女人的心思……唉！這聖、咳咳……那位的心思，可當真叫咱們這些大老爺們好生難解。"},
	[56215] = {CommonPl = "不過是偷了一本秘笈？！要不要這麼大陣仗萬人圍堵、千里追殺！"},
	[56224] = {CommonPl = "師父說了，山下的女人是老虎。可是、可是，我怎麼一隻老虎也沒看到。"},
	[56227] = {CommonPl = "水非水也，此處辯的亦非你我。"},
	[56242] = {CommonPl = "那個青城的小子還真是滑不留手！咱們這麼多人，找了這許久，竟然還是沒逮到他！"},
	[56245] = {CommonPl = "嘿嘿，如今這江湖上當真熱鬧，那些個自詡清高的名門正派，滅起門可真是毫不手軟！"},
	[56248] = {CommonPl = "不過是路過此地歇個腳，也要遇到那群倒胃口的嵩山崽子，當真晦氣！"},
	[56251] = {CommonPl = "若非聖姑曾再三交代，如今乃多事之秋不宜生事，咱們非要叫這些嵩山小雜碎嘗嘗厲害！"},
	[56327] = {CommonPl = "這令狐沖有如神助，半日功夫，老子便不是他的對手，古怪，古怪！！"},
	[56330] = {CommonPl = "要是大師哥在此，才不用怕這幾個臭賊！"},
	[56333] = {CommonPl = "想不到我的武功如此不濟，這樣下去，如何為父母報仇！！"},
	[56456] = {CommonPl = "你還在胡吹大氣呢，前日倘若不用我的法子，以真氣遊走他足厥陰肝經諸經脈，這小子早已死定了，哪裡還輪得你今日在他淵液之間來回？"},
	[56459] = {CommonPl = "這般以真氣在他淵液間來回，我看不大妥當，還是先治他的足少陰腎經為是。"},
	[56462] = {CommonPl = "你倒說得稀鬆平常，這一掌打在你身上，自然傷不了你，但打在這小子身上，或許便打死了他。"},
	[56465] = {CommonPl = "令狐沖當然死不了，給人輕輕的打上一掌，怎麼會死？"},
	[56468] = {CommonPl = "不錯，不過大哥的法子縱然將他內傷治好了，他雙足不能行走，總是美中不足，還是我的法子好，這小子的內傷，是屬於心包絡，須得以真氣通他腎絡三焦。"},
	[56471] = {CommonPl = "大哥，別的事情我佩服你，這以真氣療傷的本領，卻是你不及我了。這小子全身發高燒，乃是陽氣太旺的實症，須得從他手太陽經入手。\r"},
	[57279] = {CommonPl = "奇葩年年有，今年特別多。"},
	[57282] = {CommonPl = "每天都有這麼多人變著法子只為謀得福王府長工一職，這才練就了老夫這一雙火眼金睛！"},
	[57285] = {CommonPl = "我…不會罵他，罵他只會侮辱我這口每天都刷的牙。"},
	[57288] = {CommonPl = "想爺爺我縱橫江湖數十年，罵遍天下無敵手！莫非今天真要栽在這裡不成？！"},
	[57291] = {CommonPl = "家裡人都說我腦子有毛病，依我看，那是因為他們壓根就不懂啥叫生活！"},
	[57294] = {CommonPl = "等我幹完這一票，就去找姐姐雙宿雙飛！"},
	[57297] = {CommonPl = "雖然毒人都是沒有生命的死人，我們也要學會如何保養它們，讓他們變得和真人無二，永遠水當當！"},
	[57297] = {CommonPl = "自古多情空餘恨，此恨綿綿無絕期……"},
	[57300] = {CommonPl = "今天木有事兒啊！！！\r出來溜個彎啊！！"},
	[57303] = {CommonPl = "你你你…才結巴！你全家都……都都結巴！"},
	[57306] = {CommonPl = "有了這些雞，今晚的菜可不用愁了。"},
	[57309] = {CommonPl = "我的孫孫啊，很乖，很聽話。\r笑起來，眼睛彎彎的，還有兩顆小虎牙。"},
	[57312] = {CommonPl = "為什麼只有北邊才有佛呢？\r那是因為南無阿彌陀佛！"},
	[57315] = {CommonPl = "肉！！\r香噴噴的肉！！\r嫩滑滑的肉！！！"},
	[57318] = {CommonPl = "我。\r最討厭。\r說話……"},
	[57321] = {CommonPl = "我的志願……\r我的志願呢就是每天放了學，去捉魚！今天捉武昌魚，明天捉娃娃魚！\r呐，餓不餓啊？要不要我煮碗魚給你吃？"},
	[57341] = {CommonPl = "哥哥去給那些染病的病人治病了，也不知道發生了什麼事，他去了就再沒有音訊。\r為了讓娘親安心，我每天都守在橋頭等哥哥回家……\r"},
	[57344] = {CommonPl = "不想死……不想被活埋……\r孫大夫說過，只要有一絲治好的希望，就不該放棄。難道，就因為會傳染給其他人，我們就失去了求生的權利嗎？為了救其他人，我們就該死嗎？\r不，不該是這樣的……我不甘心……"},
	[57347] = {CommonPl = "凡大醫治病，必當安神定志，無欲無求，先發大慈惻隱之心，誓願普救含靈之苦。\r我給人看了一輩子的病，卻看不好自己。而今，只能找一個寂靜無人的地方靜靜地死去……"},
	[57350] = {CommonPl = "一個，兩個，三個，四個，五個……呵呵呵呵，好多個哦，大人什麼的，最容易騙了呢。"},
	[57353] = {CommonPl = "江湖百曉生……是我的哥哥！\r我們白家的人，與生俱來的八卦，有八卦的地方，就有我們白家的人！\r我們是江湖之上的八卦傳說，白洞，白色的明天再等著我們！\r我們還會再見面的——嘻！"},
	[57356] = {CommonPl = "鄙人是一塊無節操的英雄榜，身上貼滿了各路人士的懸賞任務。從你揭下英雄榜上的委託之時，你就身負著神聖的使命，所以，不要猶豫，不論雇主們的委託是多麼猥瑣多麼不可思議，都要盡心盡力地去完成，你將會獲得銀兩和大量的江湖閱歷，當你興趣缺缺想要放棄時，請記得一句話：出錢的是大爺！"},
	[57359] = {CommonPl = "對於殺手來說，風冷的時候，適合殺人。"},
	[57362] = {CommonPl = "（可憐的小松鼠啊……）"},
	[57414] = {CommonPl = "沒名沒姓的，我果然只是路過的路人……"},
	[57485] = {CommonPl = "得罪不起百藥門，我只好每天都守在這裡攔下被林忍冬欺騙的外地人。\r之所以知道那女人不是好貨色，絕對不是因為我也上過勾，你要是敢問為什麼——\r我爹是村長，不服單挑！"},
	[57520] = {CommonPl = "徇私枉法者，人人得而誅之。"},
	[58710] = {CommonPl = "這書院雖小，五經俱全。天天埋頭整理，生怕出借典籍有去無還哪。"},
	[58713] = {CommonPl = "專注掃門三十年，哼，你可知我這掃帚的厲害？"},
	[58716] = {CommonPl = "有怪蜀黍送糖吃，我自然不客氣啦！"},
	[58719] = {CommonPl = "授人玫瑰，手有餘香。我遊歷至此駐留講學，也悟出些禪理新意，才思泉湧，豈不快哉！"},
	[58723] = {CommonPl = "先生講課聽不大懂……但捉迷藏我最拿手！"},
	[58733] = {CommonPl = "做人要厚道！上次遇到一位得道高僧，對我說了三個字“無間道”，這是什麼意思？"},
	[58736] = {CommonPl = "方才在城裡見到一位長得像土地公的老頭，一直對我說“大聖，收了你的神通吧！”。"},
	[58739] = {CommonPl = "知音少，琴斷有誰知?"},
	[58742] = {CommonPl = "靈雲禪師曾說：“三十年來尋劍客，幾回落葉又抽枝，自從一見桃花後，直至如今更不疑”。以前我理解不了此詩的禪意，今天好像明白了。"},
	[58745] = {CommonPl = "那些污濁的男子，有什麼可愛慕的？我百合只喜歡如花一樣的女子。"},
	[58748] = {CommonPl = "我就是風華絕代、萬人驚豔的石榴姐！不要因為我是嬌花而憐惜我，來吧！我可是男女不拒的!"},
	[58751] = {CommonPl = "開到荼蘼花事了，芳菲落，知多少。"},
	[58754] = {CommonPl = "教中那些蘿蔔乾一樣的男子，怎懂得我梨花般的心？"},
	[58757] = {CommonPl = "當清晨的光打在臉上的時候，昨日的陰霾也就沒了。"},
	[58760] = {CommonPl = "“得意時莫看輕別人，失意時莫看輕自己”，老婆婆說的這句話未嘗沒有道理。"},
	[58789] = {CommonPl = "我被蒙了頭架到此處，可不知東南西北了……"},
	[58792] = {CommonPl = "問花花不語，為誰開，為誰落？算春色三分，半入流水，半入桃花。"},
	[58954] = {CommonPl = "看我的名字你能知道我的生日，但你不知道我的年齡。"},
	[58955] = {CommonPl = "亡命天涯是我的夢想。"},
	[58956] = {CommonPl = "我真的不在，別找了。"},
	[58957] = {CommonPl = "我爸爸希望我成為一個佈道史，那是什麼不知道，沒聽過。"},
	[58958] = {CommonPl = "他們說我出生異於常人，純黑的。"},
	[59249] = {CommonPl = "江湖兒女不拘小節，#Y叫我阿大就好。"},
	[59271] = {CommonPl = "（此人怒視著你……）"},
	[59274] = {CommonPl = "（此人怒視著你……）"},
	[59277] = {CommonPl = "（此人怒視著你……）"},
	[59280] = {CommonPl = "情為何，不過五字。\r空虛，寂寞，冷……"},
	[59283] = {CommonPl = "絕對不能讓六弟死！"},
	[59289] = {CommonPl = "六弟若死了，我就把神像打個稀巴爛！再在爛泥上撒泡尿！"},
	[59292] = {CommonPl = "倘若六弟死了呢？！"},
	[59298] = {CommonPl = "就算你這樣做，又能怎地？！六弟死都死了，總是你吃了虧。"},
	[59301] = {CommonPl = "倘若治不好，不拉尿也治不好，這尿便不用拉了。"},
	[59304] = {CommonPl = "六弟要是活不成，咱們不拉尿就不拉尿，脹死便脹死！"},
	[59307] = {CommonPl = "六弟治不好，咱們大家便不拉尿，不拉尿豈不是要脹死？！"},
	[59316] = {CommonPl = "扎扎扎扎！！\r扎得你神志不清！"},
	[59319] = {CommonPl = "你可知平一指生平最怕什麼嗎？\r不錯，就是他老婆我！"},
	[59322] = {CommonPl = "珊兒被擄走了，沖兒也不知去向。這朱仙鎮和咱們一定是八字犯沖。"},
	[59325] = {CommonPl = "……"},
	[59328] = {CommonPl = "俺爹防俺就像是防個賊，我不就是愛賭了一點麼，他竟然連這祖屋地契在哪都不願意告訴我。"},
	[59331] = {CommonPl = "好酒好酒！真是托了令狐少俠的福，我祖千秋此生才有這樣的運氣，喝到這般好酒！"},
	[59334] = {CommonPl = "春來酒味濃，\r舉杯對春從。\r一酌千憂散，\r三杯萬事空。"},
	[59337] = {CommonPl = "昔在長安醉花柳，\r五侯七貴同杯酒。\r氣岸遙凌豪上前，\r風流肯落他人後。"},
	[59340] = {CommonPl = "乾坤震巽坎離艮兌，八卦相乘，可得六十四卦。六十四卦可演變天地萬物之變化。"},
	[59343] = {CommonPl = "想當年，俺和岳飛兄弟下瀟湘擒楊么，上天庭大鬧天宮，並肩賞游水泊梁山，攜手叱吒赤壁的時候，你還穿開襠褲呢。"},
	[59346] = {CommonPl = "唉，韓相公這般瘋瘋癲癲的，妾身也著實頭疼。"},
	[59349] = {CommonPl = "最近總有人談及愛瘋，想來應是“愛他，就陪他發瘋的意思”。"},
	[59352] = {CommonPl = "同樣是掃地僧，當年少林掃地僧一人制服北喬峰和南慕容；而貧僧卻在這裡看廟，人比人氣死人啊。"},
	[59355] = {CommonPl = "人生真是惆悵啊……若不是去找祖千秋，我還不知道他就是那位公子……差點鑄成大錯。"},
	[59358] = {CommonPl = "咳咳咳……哎呀……又咳出這麼多血……咳咳……"},
	[59361] = {CommonPl = "哎呀呀，幸虧我來得及時，不然險些釀成大禍。"},
	[59364] = {CommonPl = "……這次該不會再遇到嵩山派的人了吧？我都煩死他們了。"},
	[59367] = {CommonPl = "開船咯，開船咯，各位客官快點上船吧。"},
	[59370] = {CommonPl = "走走走，游游遊，不學無術我不發愁。\r逢人不說真心話，全憑三寸爛舌頭。\r馬屁拍得他腿抽筋，老虎嘴上揩點油。\r東南西北混飯吃，坑蒙拐騙最拿手。"},
	[59373] = {CommonPl = "我就是，天上地下無所不知，無所不曉的世界第一情報販子！"},
	[59376] = {CommonPl = "若不是托了令狐公子的福，又怎請得動這許多位英雄好漢的大駕？\r眾位來到豫東魯西，都是天河幫的嘉賓，那自然是要接待的。\r待五霸崗聚會結束，若各位再經過鄙鎮，一定要來幫中吃酒！"},
	[59379] = {CommonPl = "吼——游迅竟敢用辟邪劍法“指打奸邪”對著洒家，我看他是不想活了！我便要用這九尺釘耙試試他的腦袋是否也“滑不留耙”！"},
	[59382] = {CommonPl = "我雙龍神丐的兩條青龍，那矯捷活潑勁兒可是人間少有世上無雙，游迅想借我才不會給他呢。"},
	[59385] = {CommonPl = "哼！余矮子竟在我面上劃下這十字傷，天涯海角我也不會放過他！"},
	[59388] = {CommonPl = "我們七人得到訊息，日夜不停地趕來，便是想要一識令狐大俠真容。\r果然貴人事多行路慢，我們從天擦亮就等在這裡，到現在也只見到了你這條單薄身子。"},
	[59391] = {CommonPl = "你是我的眼，帶我領略四季的變換；引我穿越擁擠的人潮；讓我感受時光的斑斕。\r因為你是我的眼，讓我看見，這世界就在我眼前。"},
	[59394] = {CommonPl = "你是我的杖，領我走過如茵的草地；帶我行過死蔭的幽谷；陪我踏過漫長的旅途。\r若某天災難來臨，我無所畏懼，因為你與我同在。"},
	[59397] = {CommonPl = "極致的寶石，是在黑暗中隱隱發光的原石。\r發現它、打磨它、培育它，讓它光彩奪目，那仿佛上帝造人的過程，是鑒寶最激動人心的極致。"},
	[59400] = {CommonPl = "一張白紙在前，心中總充滿了各種想像，仿佛有無數的可能。\r可一旦落筆，那些恣意飛翔的天馬們就消失無蹤，留下一堆言語無味的辭藻。\r只能感歎：哎，又一個充滿希望的新生兒消失了。"},
	[59403] = {CommonPl = "盜亦有道，偷也是門技術活兒，非專業的幹不了。\r你想跟著我混，有上崗證嗎？"},
	[59406] = {CommonPl = "一寫小說誤終身哪，我現在只要看到紙，不寫幾句就渾身難受，茶飯不香。\r要是身邊能有個美人，胭脂研墨、紅袖添香就完美了。"},
	[59409] = {CommonPl = "那位教書先生說我既美貌，又風騷甚麼的，真是多謝他讚美呢。\r令狐大哥是他的徒弟，嘴巴更甜如蜂蜜呢，怪不得那個不把天下男子瞧在眼裡的人，也會對他這樣好，所以啦……唉……"},
	[59439] = {CommonPl = "（此人正在聚精會神的打麻將……）"},
	[59442] = {CommonPl = "（此人正在聚精會神的打麻將……）"},
	[59445] = {CommonPl = "（此人正在聚精會神的打麻將……）"},
	[59448] = {CommonPl = "（此人正在聚精會神的打麻將……)"},
	[59451] = {CommonPl = "聽說五霸岡上有人非法集會，可能還會有懸賞一萬金的賊頭梟首出沒……若是能混上岡去殺他一個半個，那是名利雙收的好機會啊！\r只是上岡這一路上多是邪魔外道，僅靠我和我師兄……一旦暴露，怕是要搭上性命。"},
	[59454] = {CommonPl = "（眼睛死死的盯著任盈盈，生怕錯過了對方出招的時機。）"},
	[59457] = {CommonPl = "攤子不是我砸的，酒不是我喝的，人不是我殺的，出家人不打誑語。"},
	[59460] = {CommonPl = "太可怕了……鴻鵠幫七十二個分堂，一夜之間就……\r"},
	[59463] = {CommonPl = "本以為做接待後勤是又安全又有油水的活，誰知會招來滅幫之禍啊！\r我鴻鵠幫下設七十二個分堂，雖然每個分堂就一名堂主、一名副堂主，怎麼也有百來口人，居然這麼輕易就……\r唉，江湖有風險，入行須謹慎啊，年輕人。"},
	[59466] = {CommonPl = "哼，雖然岡上聚會的這幫傢伙情商低行事魯莽做事不動腦子，但想動我的人，就是不行！"},
	[59484] = {CommonPl = "一切皆有法，如夢幻泡影，如露亦如電，應作如是觀。\r想不到我令狐沖早已參透了生死，哈哈哈哈哈哈……"},
	[59487] = {CommonPl = "婆婆、婆婆地叫個不停，沒得讓人心煩！這個令狐沖除了婆婆，就不會說別的了嗎？\r難道我的聲音就那麼嘶啞難聽，真就那麼像八十歲的老婆婆？"},
	[59490] = {CommonPl = "嚶嚶嚶嚶……（大概是在抱怨你欺負了它的猴王兄弟，又來欺負它吧）"},
	[59493] = {CommonPl = "嚶嚶嚶嚶……（大概是在抱怨你欺負了它的猴王兄弟，又來欺負它吧）"},
	[59496] = {CommonPl = "反正我時日也不多了，要打要罵便隨了盈盈姑娘吧。只要能討她開心，我什麼都甘願，別說是三個願望，就算是一百個願望也無妨。"},
	[59499] = {CommonPl = "我並不想要天上的星星和月亮。\r我只是想試試他對我的真心，如果可以的話，我希望他永遠也找不到星星和月亮。一輩子都在找星星和月亮，那麼，他一輩子都欠我的，都得陪著我、哄著我、讓我開心。"},
	[59502] = {CommonPl = "反正我時日也不多了，要打要罵便隨了盈盈姑娘吧。只要能討她開心，我什麼都甘願，別說是三個願望，就算是一百個願望也無妨。"},
	[59505] = {CommonPl = "這令狐沖，又在耍什麼花樣？如果這次再欺騙我，我決不輕饒！"},
	[59508] = {CommonPl = "反正我時日也不多了，要打要罵便隨了盈盈姑娘吧。只要能討她開心，我什麼都甘願，別說是三個願望，就算是一百個願望也無妨。"},
	[59511] = {CommonPl = "若是令狐沖敢離開我，我便放出話去，要置他於死地，哼！得不到他，就毀滅他，我看他還往哪裡跑~"},
	[59514] = {CommonPl = "獨孤九劍的傳人絕不可能是奸邪之輩，可令狐沖卻與那魔教妖女交情非淺，希望他不要走上歪門邪道才好……"},
	[59517] = {CommonPl = "貧道這不是逃跑，而是戰略性撤退，及時引入外援！"},
	[59520] = {CommonPl = "咱們師兄弟不怕死，卻不能死在此時、此地！"},
	[59523] = {CommonPl = "咳咳、咳……這是、這是貧道的失誤，貧道一定要、要彌補……"},
	[59526] = {CommonPl = "內憂外患……我泰山派，危矣！"},
	[59529] = {CommonPl = "大丈夫何懼鬼怪？！"},
	[59532] = {CommonPl = "啊！別、別找我……"},
	[59535] = {CommonPl = "想我泰山派自東靈祖師建派以來，門下高手無數，劍法威震江湖，昔日盛況令人神往！\r奈何！數十年前，我派眾多高手與魔教十大長老一戰後盡數失蹤，多少絕學招式也自此失傳！"},
	[59538] = {CommonPl = "掌門師兄武功雖是不俗，奈何太過剛直，若是遇到了歹人暗中謀害，吃了暗虧，也未可知！"},
	[59541] = {CommonPl = "玉磯子師叔此番叛亂，只怕是已蓄謀多時……掌門才剛剛失去了音信兩日，他便急於趁勢奪權，哼！"},
	[59544] = {CommonPl = "如今掌門即已平安歸來，貧道倒要看看玉磯子師叔他們可敢公然叛逆犯上！"},
	[59547] = {CommonPl = "好一群卑鄙無恥的人，竟然把老夫引入了絕地，想困住我！"},
	[59550] = {CommonPl = "唉，此番禍亂雖已平定，我泰山派卻已元氣大傷！"},
	[59553] = {CommonPl = "我上次趕著驢車，拉著一車豆腐渣路過石橋，橋就塌了。工部的大人說，橋沒問題，是我超載。這不明擺著讓我背黑鍋嗎？最可氣的是，他們還要殺人滅口。"},
	[59556] = {CommonPl = "雖然有一顆禽獸的心，卻比那些飽讀詩書的人善良許多。"},
	[59559] = {CommonPl = "哼！掌門失蹤，論輩分論武功，我師兄玉磯子都是接任掌門的不二人選。區區小輩們焉敢不服？"},
	[59562] = {CommonPl = "師父定會平安歸來的！這些跟著玉磯子師叔祖反叛的弟子，盡是些平日裡品行不端、好吃懶惰之徒！如此也好，我泰山派也剛好趁此清理門戶！"},
	[59571] = {CommonPl = "掌門鐵劍，乃我派祖師留下的信物，有玉鐘子師叔和咱們師兄弟幾個在，誰也別想強奪了去！"},
	[59574] = {CommonPl = "我派先人雖也留下了一些劍譜典籍，奈何，許多絕學無師承親傳，終難領會其精髓。\r我師兄弟五個與玉鐘子師叔在此守護鐵劍多年，無日無夜不在演練切磋，試圖推演補全失傳的劍招，奈何，奈何！……"},
	[59577] = {CommonPl = "有俺天松在此，汝等邪門歪道休想踏過此地一步！"},
	[59580] = {CommonPl = "妖魔小丑，也敢在我泰山五大夫劍面前撒野！"},
	[59583] = {CommonPl = "哼！門外那些個裝神弄鬼的跳樑小丑，還無需我師兄弟幾個一齊出手應對。\r最令人痛恨的，還是那躲在幕後指使的本門叛徒！若非玉鐘子師叔要我等顧全大局、顧念先人情分，咱們早就提劍殺上玉皇觀！"},
	[59586] = {CommonPl = "他們說我愛上了一個禽獸，可是他們可否知道禽獸也有禽獸的好！不過泰山真的是一個可靠、善良、專情的禽獸男嗎？如若騙我的又該如何是好！"},
	[59589] = {CommonPl = "這男人喲！有幾個是好東西。想我家那個死鬼，在俺年方二八、貌美如花的時候，那對俺叫一個溫柔體貼，今兒送尺頭布，明兒採幾朵鮮花。\r後來，哼！大郎、二郎、三郎、四丫頭，俺給他生了一個又一個娃，那死鬼對俺卻是越來越冷淡，橫挑鼻子豎挑眼！\r俺當初就不該嫁給他喲！俺要是沒嫁給他，就不會來到這個破村子，不來到這個破村子，也就不用整天忙裡忙外又生娃，給人家做牛做馬喲！"},
	[59592] = {CommonPl = "我可有話在先！活人不救，只撈死人。五十兩銀子下水，撈到死屍再加一百兩銀子！\r什麼！嫌貴？你去黃河邊上看看，我的這個價錢可是打八八折的！絕對公道。"},
	[59595] = {CommonPl = "聽師兄們說，俺們的祖師爺東靈道長，本是江湖上有名的驅魔道人，捉鬼畫符，無所不能，後來，無意中得到了一本劍譜……咳咳，再後來嗎？\r……師兄們還沒講，就被偷聽到的師父臭罵著打了一頓，作鳥獸散了。"},
	[59598] = {CommonPl = "啥？盜墓？俺幹得才不是那缺德行當。\r俺只是在幫那些陪葬品實現廢物利用，重現價值！這叫環保節能，懂不？"},
	[59601] = {CommonPl = "……呵、呵……呵……\r（這孫老實看起來目光呆滯、似乎神志不清）"},
	[59604] = {CommonPl = "其實我有個相好名叫苦根，他是個縴夫，常常唱“縴夫的愛”逗我開懷。可是我沒過門，肚子就大起來了。\r如若再要不到工錢成親的話，一定會被爹娘打死的。"},
	[59607] = {CommonPl = "俺的相好叫鳳珍，洗衣做飯又能生。\r更有一副熱心腸，開會討薪為子孫。"},
	[59610] = {CommonPl = "為了攬下建造封禪台的活，老夫已經投了不少錢了，可是為何一點點泡泡都見不到呢！"},
	[59613] = {CommonPl = "我是封禪台的大監工，別想用小恩小惠賄賂我！一百兩以下的銀票，我可是看都不看！"},
	[59874] = {CommonPl = "師兄們，師弟能為你們做的已都做了，師弟這輩子唯獨負了她……"},
	[59875] = {CommonPl = "噢噢！看大戲咯！團子才不要回去被師父管，天天練劍好辛苦，團子也要學唱戲，今兒做皇帝，明兒是將軍！"},
	[59876] = {CommonPl = "俺聽那夏家的小姐總念叨啥“蒲草韌如絲，磐石無轉移”，俺雖不懂那些個詩文，同為女人卻明白那份相思之苦……\r他爹，你讓俺能有這麼一個可等、可想、可怨、可恨的人……俺這輩子也值了。"},
	[59877] = {CommonPl = "沒有學歷如何？！俺雖沒考上那“青花”書院建築系，卻有一雙發現美的眼睛，和一雙勤勞的手！這封禪台，將因俺的天才構想與絕世創意，而千古流芳永垂不朽！"},
	[59878] = {CommonPl = "村兒裡的姑娘們總說俺不解風情……風情是啥？難道想要抱個媳婦回家，還要看天氣風向？"},
	[59879] = {CommonPl = "奴的夢中情人，要有一頭烏黑的長髮，還有魁梧的胸肌……啊，羞死人啦！"},
	[59880] = {CommonPl = "郁姬、郁姬，奈若何！"},
	[59881] = {CommonPl = "最近俺和魚弟，都有一樣的心情，酸酸麻麻心兒揣了個兔兒般……好像、好像俺娘曾說過的愛情似的東東……不同的是，你是為她，而俺……"},
	[59882] = {CommonPl = "知人知面不知心，你看那一心護主的未必忠臣，那犯上作亂的亦未必反賊，這世上人與事，真真假假、虛虛實實，當真是想的老頭子頭疼！\r罷罷罷！咱還是自得其樂，喝點小酒，啃個桃兒吧！"},
	[59883] = {CommonPl = "Ihaveadream：Iwanttostudygoodenglish,walktotheworld!\rIhaveadream：IwanttobetheNO.1ofthestarlightbigroad！\rIhaveadream：Iwanttobethemanoftheking!\r啥？你不懂俺在說啥？這是正宗的“夕陽文”懂不?俺的志向是與國際娛樂圈（juan4)接軌，殺向“好來屋”！"},
	[59884] = {CommonPl = "Ihaveadream：Iwanttostudygoodenglish,walktotheworld!\rIhaveadream：IwanttobetheNO.1ofthestarlightbigroad！\rIhaveadream：Iwanttobethemanoftheking!\r啥？你不懂俺在說啥？這是正宗的“夕陽文”懂不?俺的志向是與國際娛樂圈（juan4)接軌，殺向“好來屋”！"},
	[59885] = {CommonPl = "愛，不是佔有，而是在他需要自由時，獨自承受著劇痛也要放手。"},
	[59886] = {CommonPl = "你問奴家為何換裝這般快？奴家這是全大明三十二場迴圈演出練就的速度！"},
	[59913] = {CommonPl = "噢噢！"},
	[59914] = {CommonPl = "嗷嗷嗷！"},
	[59915] = {CommonPl = "……"},
	[59916] = {CommonPl = "嗷嗷嗷嗷！"},
	[59917] = {CommonPl = "這、這、這大一頭野豬，泰山是咋弄回來又給掛上樹的，那劉二老爺家的三丫頭她嬸娘，總說俺不可靠，俺、俺……俺也要找泰山學學這門手藝！"},
	[59918] = {CommonPl = "噢噢！男人靠得住，母豬會上樹！俺長大了也要找個能把母豬掛到樹上的男人！"},
	[59919] = {CommonPl = "矮馬！這是哪家敗家孩子，這麼肥一隻母豬，不拿來燉了吃，掛樹上做啥！"},
	[59920] = {CommonPl = "呸，了不起麼！這能耐野豬都能給掛樹上，咋還不見那曾家丫頭給他生娃？想當年，俺趁著月黑風高摸進俺婆娘她家後院……嘿嘿嘿……"},
	[59921] = {CommonPl = "癡情啊！好漢哪！那泰山果然是咱男人中的真男人！"},
	[59929] = {CommonPl = "這難道就是泰山為了證明可靠的舉動？母豬的大師兄已經從五指山下被放出來了，他難道不怕嗎？"},
	[60202] = {CommonPl = "他，他竟然敢親我，我是要殺了他呢，還是殺了他呢？可是，為什麼我心裡會有一種甜蜜的感覺……"},
	[60306] = {CommonPl = "師父已失蹤多時，只怕，只怕是有人暗中加害！"},
	[60308] = {CommonPl = "掌門既已平安歸來，咱們這就殺回玉皇觀，看看玉磯子師叔他們還作何說法！"},
	[60309] = {CommonPl = "同門相殘……吾等愧對先師！"},
	[60313] = {CommonPl = "江湖風波不平，我泰山派不可一日無掌門。天門師侄既然已經失蹤，貧道少不得要代勞。"},
	[60314] = {CommonPl = "哼！說什麼掌門手令，當咱們是剛入觀的小道士那般好騙嗎？"},
	[60325] = {CommonPl = "不日後，就是我泰山派新掌門的繼任儀式，屆時，歡迎各路英雄前來參加。"},
	[60326] = {CommonPl = "哼！……"},
	[60327] = {CommonPl = "……"},
	[60328] = {CommonPl = "哈哈，痛快！看到那三個小老二，生生去了一個，剩下的兩個都是一副臭臉，真是痛快！"},
	[60329] = {CommonPl = "掌門師兄就是他太過念舊情，那些個犯上作亂的野心之人，哼哼……"},
	[60330] = {CommonPl = "我泰山派此番內亂，損耗不小，唉！"},
	[60331] = {CommonPl = "好在師父平安歸來，我泰山派，已是經不起更多耗損了。"},
	[60367] = {CommonPl = "那三個老匹夫！待貧道尋得掌門師兄回來，定要叫他們好看！"},
	[60434] = {CommonPl = "不過是報導了新洛陽一處豆腐渣建築，竟然把爺這個財經版首席記者發配到這窮鄉僻壤採訪什麼村姑！\r憑爺多年的從業經驗，把這位鳳姐打造成小倩那樣炙手可熱的國際巨星，也不過是小case一件！"},
	[60435] = {CommonPl = "板叔和文花阿姨都說了，咱們小報的新聞，那是全大明最屬實最有看頭滴！咱們八卦小報有加班費、有出差費，還有專款應酬交際費……常年招新，各位美女帥哥不要錯過！\r——只有您有一雙發現八卦的眼睛，生活將更加豐富多彩！"},
	[60436] = {CommonPl = "書盡天下不平事，好男人就是我，我就是好男人！"},
	[60437] = {CommonPl = "死相！那群臭男人，哪裡懂得這女兒家的心思~~~"},
	[61267] = {CommonPl = "春來江水綠如藍，能不憶江南？難怪世人都說上有天堂下有蘇杭，江南的碧水連天果然教人迷醉。若有機會，我一定要帶東方來看看這明媚的江南風光……"},
	[61270] = {CommonPl = "我為女子，薄命如斯；\r君是丈夫，負心若此！\r韶顏稚齒，飲恨而終；\r慈母在堂，不能供養；\r綺羅弦管，從此永休。\r征痛黃泉，皆郡所致。\r蘇郎蘇郎，今當永訣！\r我死之後，必為厲鬼，\r使君妻妾，終日不安！"},
	[61273] = {CommonPl = "我白弦音願等候於此，待到河海晏清，天下太平，與君共飲長生酒！"},
	[61276] = {CommonPl = "知我者謂我心憂，不知我者謂我何求。"},
	[61279] = {CommonPl = "世間安有兩全法，不負江山不負卿？就當是……我負了她吧……"},
	[61282] = {CommonPl = "一朵花兒開就有一朵花兒敗。\r滿湖的蓮花只有我最可愛。"},
	[61285] = {CommonPl = "西湖的水，我的淚……"},
	[61288] = {CommonPl = "千年等一回啊……\r啥時候才能把我的蝶妹兒救出來哩？"},
	[61291] = {CommonPl = "我不過是想氣他一下，誰知道竟落得如此境地……\r哎……孟郎，你人在何處？"},
	[61294] = {CommonPl = "嘿哎嘿！嘿哎嘿！\r西湖美景，三月天勒。\r春雨如酒，柳如煙勒……"},
	[61297] = {CommonPl = "哪裡有不平，哪有窩！"},
	[61306] = {CommonPl = "啊啊啊啊！！\r每天陪著四莊主胡鬧都快變成腦殘了！\r誰來救救我！"},
	[61309] = {CommonPl = "啊啊啊啊！！\r每天陪著四莊主胡鬧都快變成腦殘了！\r誰來救救我！"},
	[61315] = {CommonPl = "我最喜歡做的事情就是每當有外人來時，先叫丁堅給他們一個下馬威，然後我再出面解圍。這樣就可以拉他們看我的墨寶了。霍霍霍。\r哎……這裡如此荒涼，我也只有這一點樂趣了。"},
	[61318] = {CommonPl = "東方不敗是個奸詐小人，我要是能逃過此劫，定取其項上人頭！"},
	[61348] = {CommonPl = "求求你！快救我出去！！"},
	[61400] = {CommonPl = "鏢局罪案現場證物，需加入鏢局才可探查。"},
	[61401] = {CommonPl = "鏢局罪案現場證物，需加入鏢局才可探查。"},
	[61402] = {CommonPl = "鏢局罪案現場證物，需加入鏢局才可探查。"},
	[61408] = {CommonPl = "鏢局罪案現場證物，需加入鏢局才可探查。"},
	[61414] = {CommonPl = "鏢局罪案現場證物，需加入鏢局才可探查。"},
	[61416] = {CommonPl = "鏢局罪案現場證物，需加入鏢局才可探查。"},
	[61417] = {CommonPl = "鏢局罪案現場證物，需加入鏢局才可探查。"},
	[61418] = {CommonPl = "鏢局罪案現場證物，需加入鏢局才可探查。"},
	[61419] = {CommonPl = "鏢局罪案現場證物，需加入鏢局才可探查。"},
	[61420] = {CommonPl = "鏢局罪案現場證物，需加入鏢局才可探查。"},
	[61421] = {CommonPl = "鏢局罪案現場證物，需加入鏢局才可探查。"},
	[61422] = {CommonPl = "鏢局罪案現場證物，需加入鏢局才可探查。"},
	[61492] = {CommonPl = "一見尼姑，逢賭必輸！輸得我地圖都丟了！一直在南疆打轉轉，這是哪？北邙嗎？"},
	[61495] = {CommonPl = "尼姑雖然晦氣，還是蠻漂亮的嘛。尤其是旁邊那個，又清純又水靈，人間極品啊，嘖嘖。"},
	[61501] = {CommonPl = "在下久仰呂將軍大名，早想拜見一下，奈何翻山越嶺，迷霧重重，耗盡這許多歲月才到得仙霞嶺。哎哎，生不逢時啊！"},
	[61504] = {CommonPl = "這該死的鬼天氣!"},
	[61507] = {CommonPl = "這該死的鬼天氣!"},
	[61510] = {CommonPl = "這該死的鬼天氣!"},
	[61513] = {CommonPl = "廿八鋪居然如此兇險！這次帶著弟子們出遊，如果折了幾人，貧尼要如何向掌門交代……阿彌陀佛，菩薩保佑！"},
	[61516] = {CommonPl = "天殺的黃風寨強盜,你們一定八輩子不得好死!我可憐的閨女啊……"},
	[61519] = {CommonPl = "呂將軍當政時，我們的日子挺不錯，戍遠軍一直秋毫無犯。換了個金吾衛，媽媽呀，連一天安生日子也沒了！搶錢搶人搶地盤，黃風寨就差把我的腦袋提走了！"},
	[61522] = {CommonPl = "金吾衛勢大，若不用些計謀，我戍遠衛難有取勝之機啊。"},
	[61525] = {CommonPl = "遠字軍旗永不倒！"},
	[61528] = {CommonPl = "遠字軍旗永不倒！"},
	[61531] = {CommonPl = "遠字軍旗永不倒！"},
	[61534] = {CommonPl = "遠字軍旗永不倒！"},
	[61543] = {CommonPl = "去年此時，我三人賞月飲酒，其樂融融，小妹何其幸福。\r如今大哥身故，二哥背叛，小妹如何自處。"},
	[61543] = {CommonPl = "去年此時，我三人賞月飲酒，其樂融融，小妹何其幸福。\r如今大哥身故，二哥背叛，小妹如何自處。"},
	[61546] = {CommonPl = "土豆土豆我是地瓜……\r看什麼看，這是暗號你懂不！"},
	[61549] = {CommonPl = "嘿！過幾天我就退伍回鄉，取個老婆暖被窩。"},
	[61552] = {CommonPl = "此次下山遭遇諸多磨難，只願眾師姐妹都能平安回到恆山。"},
	[61555] = {CommonPl = "左冷禪竟和朝廷勾結到了一起，勢力愈發龐大，老尼回山后定要與掌門好好商議一番。"},
	[61558] = {CommonPl = "日暮鄉關何處是，煙波江上使人愁。天涯浪子，欲歸無路，說的就是我這種人吧。"},
	[61567] = {CommonPl = "老子生平有三恨，小白臉，娘娘腔，兔兒爺！那個蓮公子一看就不像是個好人。要不是還有點利用價值，早他奶奶地扭掉他的脖子！"},
	[61573] = {CommonPl = "傷敵一千自損八百，這是作參謀的恥辱啊！"},
	[61576] = {CommonPl = "忍耐已久，今日大仇得報！殺光他們，殺！殺！殺！"},
	[61579] = {CommonPl = "不顧一切，奮勇爭先，為了戍遠騎衛的榮耀！"},
	[61600] = {CommonPl = "故知般若波羅蜜多。是大神咒。是大明咒。是無上咒。是無等等咒。\r能除一切苦。真實不虛。故說般若波羅蜜多咒即說咒曰◎"},
	[61603] = {CommonPl = "很多次都想離開廿八鋪，去更自由更安全的地方。可是每每又總是回來，天地雖大，能容身的去處卻少得可憐啊。"},
	[61606] = {CommonPl = "恆山眾師太來了，快帶我走吧。寧願伴著青燈古佛，也好過在這裡終日惶惶。"},
	[61609] = {CommonPl = "上頭在下一盤很大的棋！我都這把年紀了，只能混吃等死，期盼某一天能入土為安。"},
	[61612] = {CommonPl = "真羡慕雲遊四方、化緣為生的丐幫！要不是這座房子的債款拖累，我早離開這過上幸福的小日子了！"},
	[61641] = {CommonPl = "(正愜意地梳洗著羽毛,倩影倒映在粼粼波光中)"},
	[61653] = {CommonPl = "火，到處都是火，好可怕……"},
	[61656] = {CommonPl = "蒼天啊！你為何要這樣對我孤劍村！難道只是因為懷璧有罪嗎？\r先祖啊！你睜開眼睛看看吧！願你的英靈保佑孤劍村的子孫！\r我獨孤安發下血誓，縱使孤劍村只有一條血脈，也定會報仇雪恨！"},
	[61659] = {CommonPl = "還記得大娘給你炒的雞蛋飯嗎？孩子，你以後要好好的照顧自己！"},
	[61662] = {CommonPl = "殺、殺、殺！燒、燒、燒！總有些人認為一切都毀滅了，就不會留下證據。"},
	[61665] = {CommonPl = "這個村子，據說是幾百年前一位大俠的隱居之地，可是天下哪裡有一直不為人知道的地方！"},
	[61668] = {CommonPl = "直到大火燒毀房屋的那一刻，我才明白有時候那些平時看起來普通的東西，都是那麼的珍貴。"},
	[61671] = {CommonPl = "你一定會打跑那些壞人的，對吧！"},
	[61674] = {CommonPl = "村子裡的那些惡人要幹什麼？我好怕！"},
	[61707] = {CommonPl = "皇圖霸業談笑中，不勝人生一場醉！"},
	[61710] = {CommonPl = "只記住了恨，就不會有愛。只學會拔劍，就不配聞酒香。"},
	[61713] = {CommonPl = "我學劍法，不是為了殺別人。而只想保護自己以及自己在乎的人不被受傷害。"},
	[61716] = {CommonPl = "快哉！快哉！此戰好生痛快！"},
	[61734] = {CommonPl = "哈哈，諸位真的要與我嵩山派為難嗎？"},
	[61743] = {CommonPl = "無量義者，從一法生。其一法者，即無相也。"},
	[61746] = {CommonPl = "師父在無相庵裡，我在給他放馬！黃驃馬啊，你看那些人多可笑，為爭奪兩張破圖就要打打殺殺！"},
	[61749] = {CommonPl = "世事豈是你我能揣測，施主你認為此話可有道理？"},
	[61782] = {CommonPl = "平生最愛湊熱鬧！"},
	[61785] = {CommonPl = "什麼十大門派，我看也就是如此而已！"},
	[61788] = {CommonPl = "獨來獨往不是更好！"},
	[61791] = {CommonPl = "好久沒見過塞外的風雪了！"},
	[61794] = {CommonPl = "看什麼看？再看把你一雙招子挖下來！"},
	[61797] = {CommonPl = "找老夫何事？"},
	[61800] = {CommonPl = "十大門派再厲害，厲害的過朝廷嗎？"},
	[61803] = {CommonPl = "坐山觀虎鬥！"},
	[61827] = {CommonPl = "劍魔前輩，數百年前就叱吒江湖，他隱居洞窟裡面，定然藏著讓武林人士夢寐以求的武功秘笈！"},
	[61851] = {CommonPl = "……"},
	[61854] = {CommonPl = "是是非非對對錯錯，欲與誰說。"},
	[61857] = {CommonPl = "人生得意須盡歡。"},
	[61869] = {CommonPl = "阿彌陀佛，多謝施主出手相救。"},
	[62046] = {CommonPl = "這幫人實在可惡，要不是不想多生事端，看我不打斷他們的腿！"},
	[62049] = {CommonPl = "他們在這裡吵吵鬧鬧，還妄想打聽落雪莊的事。哼，告訴他們才怪。"},
	[62052] = {CommonPl = "自從東方不敗掌權後，師父他便舉棋不定，不知是繼續協助向左使尋找任教主好，還是回黑木崖效忠。\r這次幫你和向左使之事，萬不可聲張出去，若是被楊蓮亭知道了，落雪莊定沒有好下場。"},
	[62055] = {CommonPl = "一夫當關萬夫莫開，說的就是我們門侍。"},
	[62058] = {CommonPl = "自從東方教主遇到了楊蓮亭,神教再也不是過去的神教了,黑木崖已經變成了一個傳說."},
	[62061] = {CommonPl = "這群可惡的畜生，居然堵在吊橋邊上，讓我沒法過去支援向左使。"},
	[62064] = {CommonPl = "謀事在人，成事在天，他金錢幫作惡許久，早晚要遭到報應。"},
	[62067] = {CommonPl = "別人笑我太瘋癲，我笑他人看不穿。"},
	[62070] = {CommonPl = "天大地大，竟無我容身之所……可悲，可悲啊！"},
	[62073] = {CommonPl = "我向問天心中只有一個教主，可教主……你身在何處？"},
	[62076] = {CommonPl = "這小丫頭真可憐……"},
	[62079] = {CommonPl = "殺……殺……通通殺光……"},
	[62082] = {CommonPl = "哎呦，我的背好癢啊，我快……死……了……我快死了！"},
	[62085] = {CommonPl = "向問天要去梅莊,哼哼,膽子夠大!可在這裡遇到我,那才是天意!"},
	[62088] = {CommonPl = "我就是人擋殺人，佛擋殺佛的青頭蟾。"},
	[62162] = {CommonPl = "鏢局罪案現場證物，需加入鏢局才可探查。"},
	[62189] = {CommonPl = "那老太監好大的膽子，竟敢栽贓嫁禍到老子頭上！"},
	[62192] = {CommonPl = "東方不敗！你我之間恩怨終有了時，不死不休！"},
	[62195] = {CommonPl = "囉嗦什麼？！直接殺進去便是！老子倒要看看那老太監能躲到幾時。"},
	[62198] = {CommonPl = "讓老子知道了是誰幹的，定要將其千刀萬剮！"},
	[62201] = {CommonPl = "這麼多年過去了，想不到再相見竟是此等情境！"},
	[62204] = {CommonPl = "這麼多年過去了，想不到再相見竟是此等情境！"},
	[62207] = {CommonPl = "這些法宗的傢伙，竟墮落到如斯地步！"},
	[62210] = {CommonPl = "寶劍初識血，劍氣可傷人！有朝一日，我一定也會打造出此等絕世之寶劍！"},
	[62213] = {CommonPl = "用小女娃做祭品，這些人真是喪盡天良！"},
	[62216] = {CommonPl = "這、這，唉！這些個小女娃，都是哪裡抓來的，可怎麼給送回去啊。"},
	[62222] = {CommonPl = "這習慣哪，真是可怕！俺現在一天不被眉大師罵上一頓，渾身都不舒爽！"},
	[62225] = {CommonPl = "雖複塵埋無所用，猶能夜夜氣沖天……龍泉，龍泉！這世上再無龍泉！\r老子這些年打造的兵器，比起那龍泉都不過是一堆破銅爛鐵！"},
	[62228] = {CommonPl = "相傳歐冶子鑄劍時，赤堇之山破而出錫，若耶之溪涸而出銅，雨師灑掃，雷公鼓罄，蛟龍捧爐，天帝裝碳……可歎我法宗這些年人才凋零，技藝無有增長，走入旁道……竟是自誤了！"},
	[62231] = {CommonPl = "大俠饒命！咱們不過是路過此地，想在藏劍山莊撿點便宜，便是撿不到寶劍，收集些紅線回家給婆娘織匹“煙霞羅”也是好的。"},
	[62234] = {CommonPl = "袁芳，幸得你在本官身旁，這些年，多少案子一起破解,多少風雨一起走過！"},
	[62237] = {CommonPl = "下官願誓死追隨大人！"},
	[62240] = {CommonPl = "哈哈哈，果然好狠辣的手段！當年放虎歸山，今朝滿莊滅門，當真是天意、天意！"},
	[62243] = {CommonPl = "少莊主神功大成之日，便是咱藏劍山莊名揚天下之時！"},
	[62246] = {CommonPl = "嘖嘖，想當年那藏劍山莊何等風光！最終也不過落得一朝滅門的下場，卻不曉得是得罪了什麼大人物！"},
	[62249] = {CommonPl = "救、救命！"},
	[62252] = {CommonPl = "走開走開！沒看到俺正忙著呢？"},
	[62255] = {CommonPl = "老爺子今兒心情不錯，竟然沒罵俺……"},
	[62258] = {CommonPl = "……本人已死，有事請燒紙……"},
	[62261] = {CommonPl = "誰、誰點了老子的穴道！"},
	[62264] = {CommonPl = "咳咳，這個鎮子，污染越來越嚴重了，真是沒法住人了！"},
	[62267] = {CommonPl = "咱這多年的老肺病，都是給薰出來的，可是這些個練劍的和上頭的大官關係好著哩！咱們投訴無門喲！"},
	[62270] = {CommonPl = "練武是修行，鑄劍是修行，生老病死都是修行……年輕人，我們都走在修行的路上……"},
	[62273] = {CommonPl = "……"},
	[62276] = {CommonPl = "嗤！那個眉大師整日裡呼來喝去，把咱們支使的團團轉，卻沒見到打造出什麼了不得的神兵利器！"},
	[62279] = {CommonPl = "哼！若非咱藏劍山莊為惡人所滅，老子哪裡用得著看這些朝廷鷹犬的臉色！"},
	[62282] = {CommonPl = "嗚嗚……"},
	[62285] = {CommonPl = "嗚……"},
	[62288] = {CommonPl = "娘親……我害怕……"},
	[62291] = {CommonPl = "莊主，夫人……老奴這就去下頭服侍你們了……"},
	[62294] = {CommonPl = "今兒天氣真不錯……"},
	[62297] = {CommonPl = "你這句開場白幾十年沒變過了，不累嗎？"},
	[62300] = {CommonPl = "世界上竟然有這麼多壞人嗎？我們恆山派濟世救民、與世無爭，竟然被偷襲，會是誰和我們有仇呢？"},
	[62303] = {CommonPl = "若自取，若教他取，見取隨喜。五無間罪，若自作，若教他作，見作隨喜。十不善道，若自作，若教他作，見作隨喜。所作罪障，或有覆藏，或不覆藏。"},
	[62306] = {CommonPl = "冤有頭，債有主！敢招惹佛門弟子，他們就不怕菩薩降罪，來世墮入畜生道嗎！"},
	[62309] = {CommonPl = "爾時世尊。從肉髻中。湧百寶光。光中湧出。千葉寶蓮。有化如來。坐寶花中。頂放十道。百寶光明。一一光明。皆徧示現。十恒河沙。金剛密跡。擎山持杵。徧虛空界。大眾仰觀。畏愛兼抱。求佛哀佑。一心聽佛。無見頂相。放光如來。宣說神呪。"},
	[62312] = {CommonPl = "歸依佛，歸依法，歸依僧。我今發心，不為自求人天福報，聲聞緣覺，乃至權乘諸位菩薩唯依最上乘。發菩提心，願與法界眾生，一時同得阿耨多羅三藐三菩提。"},
	[62315] = {CommonPl = "舍利弗。若有人已發願。今發願。當發願。欲生阿彌陀佛國者。是諸人等。皆得不退轉於阿耨多羅三藐三菩提。於彼國土若已生。若今生。若當生。是故舍利弗。諸善男子善女人。若有信者。應當發願生彼國土。"},
	[62318] = {CommonPl = "觀自在菩薩。行深般若波羅蜜多時。照見五蘊皆空。度一切苦厄。舍利子。色不異空。空不異色。色即是空。空即是色。受想行識。亦複如是。舍利子。是諸法空相。不生不滅。不垢不淨。不增不減。是故空中無色。"},
	[62321] = {CommonPl = "眾罪皆懺悔，諸福盡隨喜。及請佛功德，願成無上智。\r去來現在佛，於眾生最勝。無量功德海，我今皈命禮。"},
	[62324] = {CommonPl = "應墮地獄，惡鬼畜生，諸餘惡趣，邊地下賤，及蔑戾車，如是等處。所作罪障，今皆懺悔。今諸佛世尊，當證知我，當憶念我。我復於諸佛世尊前，作如是言。若我此生，若我餘生。"},
	[62327] = {CommonPl = "如是等一切世界，諸佛世尊，常住在世。是諸世尊，當慈念我。若我此生，若我前生，從無始生死以來，所做眾罪。若自作，若教他作，見作隨喜。若塔若僧，若四方僧物。"},
	[62330] = {CommonPl = "詩畫、美玉、珍玩，一切優雅之物皆我所欲也！\r恆山派冰清玉潔，至純之玄陰劍正是適合我的美器，雕琢成掛飾最能彰顯我卓越的品味！"},
	[62333] = {CommonPl = "少莊主！老奴可算等到你回來了！"},
	[62509] = {CommonPl = "天下事天下人管得！"},
	[62765] = {CommonPl = "嗚嗚……好大的火！娘為了我……嗚嗚"},
	[62916] = {CommonPl = "江湖近來風聲四起總不太平，本王正招賢納士願得良才為國效力。哎…懷念當年的孤劍村的愜意生活！"},
	[62917] = {CommonPl = "因天下第一幫主對餘杭城的恩惠使得城中百姓感激不已，特在此處建造了恩人的雕像！"},
	[63013] = {CommonPl = "江湖兒女，自當快意恩仇！"},
	[63243] = {CommonPl = "我是個石頭，你看不見我……"},
