	[63845] = {CommonPl = "鏢局罪案現場證物，需加入鏢局才可探查。"},
	[63851] = {CommonPl = "鏢局罪案現場證物，需加入鏢局才可探查。"},
	[63867] = {CommonPl = "鏢局罪案現場證物，需加入鏢局才可探查。"},
	[63868] = {CommonPl = "鏢局罪案現場證物，需加入鏢局才可探查。"},
	[63947] = {CommonPl = "他什麼時候才肯帶我離開，莫非那個仇小婉還纏著他不放。為自己贖身又怎麼樣，山雞飛上枝頭終究也是山雞，天哥根本就不會娶她過門。"},
	[64154] = {CommonPl = "鏢局罪案現場證物，需加入鏢局才可探查。"},
	[64155] = {CommonPl = "鏢局罪案現場證物，需加入鏢局才可探查。"},
	[64156] = {CommonPl = "鏢局罪案現場證物，需加入鏢局才可探查。"},
	[64157] = {CommonPl = "鏢局罪案現場證物，需加入鏢局才可探查。"},
