	[64199] = {CommonPl = "鏢局罪案現場證物，需加入鏢局才可探查。"},
	[64200] = {CommonPl = "鏢局罪案現場證物，需加入鏢局才可探查。"},
	[64201] = {CommonPl = "鏢局罪案現場證物，需加入鏢局才可探查。"},
	[64202] = {CommonPl = "鏢局罪案現場證物，需加入鏢局才可探查。"},
	[64203] = {CommonPl = "鏢局罪案現場證物，需加入鏢局才可探查。"},
	[64233] = {CommonPl = "要打架了嗎？我早就手癢了，不過此事不能讓師父知道。"},
	[64325] = {CommonPl = "只要找回琅嬛秘典，重繼失傳已久的絕學，我逍遙派恢復昔日江湖上超然地位的日子也就不遠了。"},
	[64328] = {CommonPl = "那平一指揚言“殺一人救一人”好不囂張，在下可不做這麼沒格調的事情。\r救人，那是一門藝術、一種樂趣，但凡帥哥美女前來看診，一律八折優惠。"},
	[64331] = {CommonPl = "師姐總叫我不要沉迷星相，可她又總是期盼能找一個人能夠陪她一起看星星、看月亮，從詩詞歌賦談到人生理想……真是好矛盾噢！"},
	[64334] = {CommonPl = "這世上有許多巧奪天工的精妙機關物什，並非人類自己就能打造成功的，那不過是神靈借由你的手，讓其在世間展現。"},
	[64337] = {CommonPl = "這世間，懂花、憐花有幾人，玉罌的最大心願，就是與一個同樣愛花之人攜手百年，死後同埋花下，來世做一對並蒂雙生花。"},
	[64340] = {CommonPl = "“若能了達陰陽理，天地都來一掌中。”……明宇宙長存之規律，星辰運轉之軌跡，乃在下畢生之所求也。"},
	[64343] = {CommonPl = "哈哈！人生得意須盡歡，管你輸贏多少場！最後一蹬腿一閉眼，還不是被賊老天這莊家洗牌重來！"},
	[64346] = {CommonPl = "嘖嘖，這些個殺手刺客人數雖多，奈何行進間全無章法，不過是烏合之眾，不值一提！"},
	[64349] = {CommonPl = "哼！果然是一見尼姑逢賭必輸！老子這賭聖的名頭，難不成今日真要栽倒這裡！"},
	[64352] = {CommonPl = "所謂冥冥中自有定數，想不到今日能在此處得見琅嬛秘典，孔明此生無憾矣！"},
	[64355] = {CommonPl = "哈哈哈！賽孔明，枉你自稱這天下之事盡在你推演數算之中，這次打賭卻又是我李承歡勝了！"},
	[64358] = {CommonPl = "爹爹常說“有雲的地方就有天下，有人的地方就有江湖，想要退隱江湖不啻癡人說夢……”從前雪兒不明其意，如今，卻是有些懂了。"},
	[64361] = {CommonPl = "俺姓洛，名星星，聽好……是天上的星星，不是地上的猩猩！"},
	[64364] = {CommonPl = "法宗那群混帳！盡用些不入流的手段來鑄劍，真是敗壞我鑄劍師的名頭！"},
	[64367] = {CommonPl = "老頭子年紀大了，越發膽小怕事，對上那些個朝廷鷹犬總是畏首畏尾，嘿嘿，瞧我不過是露了點小手段，那群東廠走狗還不是乖乖配合。"},
	[64370] = {CommonPl = "師父說，想要有所收穫，必先炙熱癡愛……我對那、那位姑娘一片真心，為何她卻沒有半點回應……"},
	[64373] = {CommonPl = "嘿嘿，只要打造出玄機傀儡，組成了機甲大軍，咱們東廠日後就可橫行天下無所顧忌！"},
	[64376] = {CommonPl = "老子這些年打造了多少兵器戰甲，想不到技藝竟還不如這鑄劍谷的一個小屁孩！"},
	[64379] = {CommonPl = "哼，那兩個傢伙看不慣老子又如何？老子上頭有人！就是專業不對口，照樣在這裡吃香喝辣！"},
	[64382] = {CommonPl = "走開！老子忙著呢！"},
	[64385] = {CommonPl = "嘻嘻，洛星塵這個呆子，為了討好姐姐甘願在這裡老實做花農、照料藥園，倒是癡心一片。"},
	[64388] = {CommonPl = "過去種種已如昨日死，世上已無李琅嬛。"},
	[64391] = {CommonPl = "相濡以沫，不如相忘江湖。"},
	[64394] = {CommonPl = "人生如霧亦如夢，緣生緣滅還自在。"},
	[64397] = {CommonPl = "施主好，水月庵乃避世修行之地，請勿喧嘩。"},
	[64400] = {CommonPl = "（白狐慵懶的抖了抖耳朵瞧了瞧你，並不懼怕你的靠近。）"},
	[64403] = {CommonPl = "任我行此生確是負了琅嬛，待我練成絕世武功，報了血海深仇，定當補償於她。"},
	[64406] = {CommonPl = "阿彌陀佛，多謝#Y尋回本派掌門短劍，恆山派上下感激不盡。\r本想借助寶地暫作休整，卻不想竟將那江湖風波帶至水月庵，卻是吾等之罪過。"},
	[64409] = {CommonPl = "這水月庵好生幽靜美麗，這位無相師叔也好生親切隨和。"},
	[64412] = {CommonPl = "多謝你再次出手相助。"},
	[64415] = {CommonPl = "那些東廠惡人好生難纏，咱們恆山弟子此次又是多有損傷！"},
	[64418] = {CommonPl = "有咱們再這裡，東廠惡賊休想侵擾水月庵！"},
	[64421] = {CommonPl = "喝！"},
	[64424] = {CommonPl = "落花劍陣！"},
	[64427] = {CommonPl = "嘻嘻，快快跟上。"},
	[64430] = {CommonPl = "（玄機傀儡身上燃燒著炙熱的火焰！）"},
	[64433] = {CommonPl = "這一處處山石草木，看似渾然天成，實則暗藏玄機。"},
	[64436] = {CommonPl = "哈哈，前頭聽起來熱鬧的緊，咱們快去瞧瞧。"},
	[64439] = {CommonPl = "（機關人助手正安靜的等待命令。）"},
	[64442] = {CommonPl = "（機關人助手正安靜的等待命令。）"},
	[64445] = {CommonPl = "（機關人助手正安靜的等待命令。）"},
	[64448] = {CommonPl = "這片藥園的主人，是位與世無爭的姑娘……還望諸位莫要多做打擾糾纏。"},
	[64451] = {CommonPl = "哈哈，想要來啥兵器？只要你想的出來，沒有咱們鑄劍村打不出來的！"},
	[64454] = {CommonPl = "雪兒姑娘可是咱們鑄劍谷第一美人，那個什麼小白臉書生竟然敢打她的主意！"},
	[64457] = {CommonPl = "咱們器宗，最為看重的乃是煉器所用之材料，傳說中最珍貴的礦石便是那可遇而不可求的隕鐵！"},
	[64460] = {CommonPl = "誰說女兒家就不能鑄劍？本姑娘掄得起重錘、耍得了寶劍，更能同時保有曼妙纖細的身材，可偏偏村裡的男人都更愛落雪那個嬌滴滴的小丫頭！"},
	[64574] = {CommonPl = "我叫衛雨，江南“逐鹿山莊”的管家。我想若不是這一路的風雨提醒我，恐怕我也像那些沉浮於江湖的人，是打何處來，該到何處去……都忘了。"},
	[64731] = {CommonPl = "醫者父母心艾瑪今生最大的心願就是希望能醫治所有傷患，讓他們早些擺脫病症帶來的痛苦。"},
	[64734] = {CommonPl = "嗚嗚嗚……那些猛獸好可怕，爹爹，娘，你們快帶艾瑪走吧。"},
	[64737] = {CommonPl = "想要天機譜嗎？先收下我給你們準備的這份大禮吧，哈哈哈！"},
	[64740] = {CommonPl = "爹爹，娘親，我這就為你們報仇了！"},
	[64746] = {CommonPl = "唔啊啊啊！！我的頭！！我的頭好疼！！！"},
	[64752] = {CommonPl = "……"},
	[64758] = {CommonPl = "師兄也不知熬不熬得過這關。"},
	[64761] = {CommonPl = "這種熟練的用蠱手法，果真是出自我五仙之手。看她的眉眼，真是像極了當年的她。"},
	[64764] = {CommonPl = "真是孽緣啊。"},
	[64770] = {CommonPl = "若讓我知道是誰讓我們五仙教背了這口黑鍋，我到時一定讓他十倍的吃下去！"},
	[64773] = {CommonPl = "天機譜這東西即可拆解五仙的秘術，又能破解唐門的機關術，這樣的東西，留它不得！"},
	[64776] = {CommonPl = "保護教主！！"},
	[64779] = {CommonPl = "保護教主！！"},
	[64782] = {CommonPl = "保護教主！！"},
	[64785] = {CommonPl = "保護教主！！"},
	[64788] = {CommonPl = "保護教主！！"},
	[64791] = {CommonPl = "保護教主！！"},
	[64794] = {CommonPl = "如果我拿到天機譜，卻告訴掌門，大師兄偷學天機譜的武功，已經走火入魔，筋脈爆裂而死，秘典也不知去向，這天機譜就永遠都是我的了。"},
	[64800] = {CommonPl = "我們一定要為大師兄報仇！！"},
	[64806] = {CommonPl = "……"},
	[64809] = {CommonPl = "可憐的孩子……"},
	[64812] = {CommonPl = "……"},
	[64815] = {CommonPl = "怎麼會這樣？事情怎麼會變成這樣？我的信仰，我的人生，原來到頭來不過只是個笑話。"},
	[65618] = {CommonPl = "我們四川的生活巴適呦，就是總有些不曉得哪裡來的龜兒子在村子周邊晃悠晃悠，破壞心情。"},
	[65621] = {CommonPl = "我想著等有錢了，和大志一起開一個旅館，就叫嘉州旅館，每天彈彈琵琶打打鼓，看看來來往往的形色眾生。"},
	[65624] = {CommonPl = "好久沒和虎哥一起去打漁了，這岷江中鯰魚的鮮美，真是讓人欲罷不能啊。"},
	[65627] = {CommonPl = "師父前去武當已經數月了，至今未有書信，也不知是何情況。"},
	[65630] = {CommonPl = "血菩提，哈哈哈，世人怎會如此輕信傳言，若那東西真有神效，皇帝又怎會拱手相贈。"},
	[65633] = {CommonPl = "佛珠，我的佛珠在哪……"},
	[65636] = {CommonPl = "日居月諸，東方自出。父兮畝兮，蓄我不卒。"},
	[65639] = {CommonPl = "護佛村存世千年，不曾因誰而滅，今日，貧僧當用盡生命守護此存。"},
	[65642] = {CommonPl = "君在我在，共生共滅。"},
	[65645] = {CommonPl = "師伯！師伯！師伯被抓去了，這，這可如何是好……"},
	[65648] = {CommonPl = "揚之水，不流束薪。終鮮兄弟，維予二人。無信人之言，人實不信。"},
	[65651] = {CommonPl = "江湖傳聞嘉州大彌勒佛有一不死火麒麟世代看守，今天就讓你們看看這傳聞是真是假。"},
	[65660] = {CommonPl = "若我再此掃地懺悔千年，是否能挽回逝去的那些故人？"},
	[65663] = {CommonPl = "不曾想嵩山派竟能與青城派狼狽為奸，此事一定要告知武當少林，以免武林生變。"},
	[65708] = {CommonPl = "那令狐小子當真是瞎了眼，放著我這美貌溫柔的乖女兒不愛，偏要去喜歡什麼小師妹、還有那個任大小姐，哼！"},
	[65711] = {CommonPl = "那些武林中人來來去去的那麼多，俺哪裡識得那許多個。"},
	[65714] = {CommonPl = "翠翠在夢裡聽得一段美麗的歌聲，那歌聲讓人的靈魂也要飛起來啦，一路飛到雲朵上，飛過山尖……就像蕩舟在這灕江的水面上，行在青山頂。"},
	[65717] = {CommonPl = "咱們都是五仙教中人，來此是奉藍教主之命，協助佤族開辦“笙歌會”，為雲歌公主選夫婿的。"},
	[65720] = {CommonPl = "怎麼來了這麼多倭寇，哼，方才讓他們攻了個措手不及，一會要讓他們嘗嘗姑娘的厲害！"},
	[65723] = {CommonPl = "這些日子，好些個外族人來我佤族參加“笙歌會”，想必都是為了咱們雲歌公主來的。只是，想贏得公主的芳心，可沒那麼容易。"},
	[65726] = {CommonPl = "嘿嘿，不曉得那個“笙歌會”是怎麼個比法。若是能娶得那個什麼公主，咱也做回駙馬爺！便是那公主長得醜些、性格蠻橫些，能贏得那可解百毒的“寒玉冰蠶”也夠本了！"},
	[65729] = {CommonPl = "好山好水好姑娘，嘖嘖，都說“桂林美女甲天下”當真名不虛傳!"},
	[65732] = {CommonPl = "採花採到霸王花，老子這趟桂林來的也算值了！"},
	[65735] = {CommonPl = "隻身一人趕赴情歌大會，這位阿英姑娘柔弱中帶著剛強，為求真愛勇敢率真，倒是與我那小尼姑師父有幾分相像。"},
	[65738] = {CommonPl = "這一路上所見的姑娘，都是美麗多情，有的熱情似火，有的溫柔羞澀，想必那情歌大會更是“繁花似錦”。"},
	[65741] = {CommonPl = "這阿詩瑪姑娘笑起來果真如同那三月裡的春光一般美麗，若是我那小尼姑師父肯多笑一笑，想必更是動人。"},
	[65744] = {CommonPl = "救美護花，乃我輩中人義不容辭之事。"},
	[65747] = {CommonPl = "這些倭寇好生無禮，阿英雖聽不懂他們的鬼話，卻看得明白他們輕佻的眼神！"},
	[65750] = {CommonPl = "這一路上怎麼有這麼多壞人和毒蜂。"},
	[65753] = {CommonPl = "阿英的那個“天命之人”就在這裡。"},
	[65756] = {CommonPl = "想唱就唱，要唱得響亮……歡迎來到“笙歌會”，尋找屬於你的那個“非你莫屬”！"},
	[65759] = {CommonPl = "嘻，遠方來的客人，莫要害羞，想要贏得心上人的回應，請先大膽表明你的心意——用你最真摯動情的歌聲！"},
	[65762] = {CommonPl = "我期待的那個他，要不在意我的身份、不只為我的容貌，而是用心傾聽我的歌聲、我的渴望，為我轉身、為我駐足，勇敢的對我說“我想要你”！"},
	[65765] = {CommonPl = "嘻嘻，不必擔心你這位“田兄”，若非兩情相悅，本姑娘自不會強留他。"},
	[65768] = {CommonPl = "佤族的兒女，絕不會向任何艱難險境低頭。即使在黑夜，我們也會伴著星光唱誦黎明。"},
	[65771] = {CommonPl = "佤族，是我五仙教的朋友，嵩山派的野心，休想得逞！"},
	[65774] = {CommonPl = "嘶……"},
	[65777] = {CommonPl = "蠍兒們，打起精神來，叫那些惡人嘗嘗你們的厲害！"},
	[65780] = {CommonPl = "哼，本姑娘最恨的就是左英那種花心多情的臭男人！"},
	[65783] = {CommonPl = "感謝你，佤族的勇士，雲歌的朋友。"},
	[65786] = {CommonPl = "就讓這片青山、碧水，見證我們的情誼。"},
	[65789] = {CommonPl = "感謝你，朋友。"},
	[65792] = {CommonPl = "左英為了吞併我佤族，不擇手段，只可惜他這一切打算，都是白費心機。"},
	[65795] = {CommonPl = "快快保護雲歌公主！"},
	[65798] = {CommonPl = "哼！追來的好快！"},
	[65801] = {CommonPl = "（雪背蝠已被公主的歌聲吸引，向她的身邊聚攏來。）"},
	[65804] = {CommonPl = "（花斑蛛已被公主的歌聲吸引，向她的身邊聚攏來。）"},
	[65807] = {CommonPl = "（琉璃蠍已被公主的歌聲吸引，向她的身邊聚攏來。）"},
	[65810] = {CommonPl = "問世間情為何物？直教人生死相許。"},
	[65813] = {CommonPl = "左郎雖是個多情種，對待我們姐妹幾人卻是一般的體貼溫柔。"},
	[65816] = {CommonPl = "哼！那個公主有什麼好？為了她，左郎甘願以身犯險，前來求娶！"},
	[65819] = {CommonPl = "公子、公子他不是壞人，他對雙兒很好……"},
	[65822] = {CommonPl = "牽著手兒來，牽著心兒來，丟只歌兒纏住你，等你對歌來。\r牽著手兒來，牽著心兒來，熱辣辣的眼神瞅著你，等你對歌來。"},
	[65825] = {CommonPl = "家鄉的山最美喲，青山搭歌台。"},
	[65828] = {CommonPl = "這裡的藍天高喲，星星任你摘。"},
	[65831] = {CommonPl = "對面的妹子你瞧喲，哥哥我今年二十幾，想和妹子對支歌嘞！"},
	[65834] = {CommonPl = "一路走來一路唱，春光多明媚。\r你和我來對歌，山歌好像那酒一杯。"},
	[65837] = {CommonPl = "花裙擺呀擺，辮子甩呀甩，家鄉的歌兒最多，歌兒匯成海。\r花裙擺呀擺，辮子甩呀甩，熱辣辣的酒和著歌兒，醉在你心懷。"},
	[65840] = {CommonPl = "家鄉的水最清喲，清水載歌來。"},
	[65843] = {CommonPl = "這裡的妹子俏喲，好花為你開。"},
	[65846] = {CommonPl = "對面的哥哥你聽喲，妹妹我今年才十八，要和我對歌喲，你在前來我在後喲~"},
	[65849] = {CommonPl = "一路走來一路唱，春風多嫵媚。\r你和我來對歌，山歌好比那春江水。"},
	[65852] = {CommonPl = "歡迎來到象山村，遠方的客人。"},
	[65855] = {CommonPl = "嘿嘿，瞧著這些對歌的姑娘小夥，俺也想起了年輕時候，為我家娃兒他娘唱的那曲“哎呦喂咯嘿！越唱心裡越是美唉~”……"},
	[65858] = {CommonPl = "咳咳，年輕人，真是好喲，咳咳。"},
	[65861] = {CommonPl = "你在俺心裡，永遠和當年一樣。樣子像雲朵一樣美麗，歌聲像雲鳥一樣好聽。"},
	[65983] = {CommonPl = "咱們願以性命來守護雲歌公主！"},
	[65985] = {CommonPl = "年紀不饒人，該找個徒弟，把我的醫術傳下去了。"},
	[66023] = {CommonPl = "鏢局罪案現場證物，需加入鏢局才可探查。"},
	[66024] = {CommonPl = "鏢局罪案現場證物，需加入鏢局才可探查。"},
	[66025] = {CommonPl = "鏢局罪案現場證物，需加入鏢局才可探查。"},
	[66277] = {CommonPl = "西廠的人有什麼本事，整天圍在那些個妃子旁邊，拿著雞毛當令箭，可笑。"},
	[66279] = {CommonPl = "哼，我們做的事兒，可是那些東廠人能明白的，他們不過只懂什麼叫呼之則來，揮之則去的一條狗。"},
	[66284] = {CommonPl = "冬至之前拿不到通關文牒，我們的路就算走到頭了。你還年輕，有天當你必須做出選擇的時候，你就明白我的話了，江湖路長，留心風霜。"},
	[66750] = {CommonPl = "老夫上知天文，下知地理，前算五百年，後知五十載。"},
	[66860] = {CommonPl = "不去不去，還是洗衣服比較實際。"},
	[66861] = {CommonPl = "裡面一定有許多好吃的O(∩_∩)O~要不要偷偷溜進去呢？"},
	[66862] = {CommonPl = "老夫嗅到一絲不祥的氣息……別笑，老夫的鼻子可是很靈敏的。"},
	[66863] = {CommonPl = "嘖嘖……一個老頭洗手有什麼好看的，還不如去看對面春風閣的小桃紅……"},
	[66864] = {CommonPl = "一看就知道又有麻煩事了，怎麼就沒人考慮一下咱們做捕快的難處。"},
	[66865] = {CommonPl = "聽說會有各路英雄好漢出席，真想進去瞧上一眼。"},
	[66866] = {CommonPl = "若是能在此拜師學藝，我林平之大仇可報！"},
	[66867] = {CommonPl = "真是熱鬧極了。"},
	[66868] = {CommonPl = "嘻嘻……今個兒老叫花我也成了座上嘉賓了。"},
	[66869] = {CommonPl = "那個人一直盯著我……好討厭的感覺。"},
	[66870] = {CommonPl = "哇~~~好氣派啊！"},
	[66871] = {CommonPl = "嘟嘟~~又來了一隻大烏龜！"},
	[66872] = {CommonPl = "非非姐姐……咱們一會去哪兒玩呢？"},
	[66873] = {CommonPl = "哎……小公子被這個女娃帶著瘋耍，連我也得一起跟著遭罪。"},
	[66874] = {CommonPl = "那個姐姐和哥哥剛才在幹什麼？好像很好玩的樣子。"},
	[66875] = {CommonPl = "擅闖者！殺！"},
	[66877] = {CommonPl = "這一切仿若當時的情景重現……"},
	[66878] = {CommonPl = "咳咳……非煙姐姐……非煙姐姐在哪？芹兒好難受……"},
	[66879] = {CommonPl = "劉家今日所遭之罪，來日我定當十倍奉還！"},
	[67034] = {CommonPl = "看守雕像責任重大！"},
	[67069] = {CommonPl = "江湖……"},
	[67072] = {CommonPl = "這次洗手大會，來了不少貴客，可見咱們掌門江湖名望非同一般！"},
	[67082] = {CommonPl = "調製香料時一定要心平氣和，才能製出好香。"},
	[67083] = {CommonPl = "我說小賭冶情大賭傷身這道理我也懂，但是我老婆就是不信。"},
	[67343] = {CommonPl = "今朝有酒今朝醉，莫使金樽空對月。"},
	[67344] = {CommonPl = "祈求上蒼，莫使白髮人送黑髮人。"},
	[67345] = {CommonPl = "奇遇只贈有緣人。"},
	[67346] = {CommonPl = "……"},
	[67348] = {CommonPl = "客官裡邊兒請。"},
	[67398] = {CommonPl = "肚子好疼……難道是腸胃不順？"},
	[67399] = {CommonPl = "咳咳咳……咳咳……咳咳咳咳……"},
	[67400] = {CommonPl = "哎呦，奴家每次見著那人，都會面紅氣喘，心跳加速……\r方才平大夫說了，這是心律不齊的症狀，開一帖藥來吃立馬就能好，但願如此。"},
	[67401] = {CommonPl = "我想吃藥，快給我藥吃。"},
	[67402] = {CommonPl = "嗚啊啊啊啊啊！！！我的我要爆了！！"},
	[67409] = {CommonPl = "……"},
	[67410] = {CommonPl = "剛才好多人呼的一下子躥出來，幾下就把大師哥給抬走了，不知道要抬到哪兒去。"},
	[67411] = {CommonPl = "沖兒的傷不知是否會復發。"},
	[67412] = {CommonPl = "竟然和那些邪魔外道稱兄道弟，真是師門不幸！"},
	[67413] = {CommonPl = "哎……大師兄……"},
	[67414] = {CommonPl = "剛才瞧見兩個和尚在吃人肉，可怕極了。"},
	[67415] = {CommonPl = "看什麼看！"},
	[67418] = {CommonPl = "（這隻美麗的白孔雀哀傷的看著你，婉轉低鳴）"},
	[67419] = {CommonPl = "嘿嘿，驚歎吧？趁現在好好開開眼吧。要不是聽說這傢伙是江湖上最有名的醫師，否則我怎麼可能會讓我家王爺隨意見人。"},
	[67681] = {CommonPl = "去天地者，萬物之逆途；光陰者，百代之過客，而浮生若夢，為歡幾何？"},
	[67684] = {CommonPl = "這小丫頭臉皮這麼薄，待我逗她一逗。"},
	[67687] = {CommonPl = "這次五霸崗聚會可是一件頭等大事，可惜可惜……這麼大的一件事，卻是不能讓另一個相關人物知曉的。\r哎……"},
	[67690] = {CommonPl = "今晚大家就大口喝酒，大口吃肉！咱們不醉不歸！"},
	[67696] = {CommonPl = "可憐我的沖兒……竟傷得這般重。"},
	[67699] = {CommonPl = "咳咳咳……咳咳……"},
	[67702] = {CommonPl = "我令狐沖命不久矣。但在臨死前能夠結識諸位英雄好漢，也不枉此生！哈哈哈哈！"},
	[67711] = {CommonPl = "人生真是惆悵啊……"},
	[67714] = {CommonPl = "這次若能逃過此劫，我令狐沖一定要改頭換面，和過去的自己訣別！"},
	[67723] = {CommonPl = "這位公子脈象錯亂，除非嚴格克制自己的食宿，否則就是大羅神仙來了，也無力挽回。\r什麼？我開玩笑？你看我這樣像是在開玩笑嗎？"},
	[67729] = {CommonPl = "提問！\r今天五霸崗群雄聚會是為的哪一位大人物？沒有提示，答對才可上崗！"},
	[67732] = {CommonPl = "公子真是英俊不凡，器宇軒昂，風流倜儻，那個一樹梨花壓海棠。"},
	[67738] = {CommonPl = "而我們“通犀地龍丸”呢，是用當歸，杜仲，桔梗，加上天山雪蓮配製而成，不需冷藏，也沒有防腐劑，除了副作用多一些以外，味道還很少吃。"},
	[67744] = {CommonPl = "這些人在這裡辦什麼群豪大會，哼哼，我倒要看看她們究竟是要弄些什麼名堂。"},
	[67750] = {CommonPl = "……"},
	[67756] = {CommonPl = "……"},
	[67759] = {CommonPl = "無論如何，我也要救令狐公子這條命。"},
	[67762] = {CommonPl = "沒想到，第一個看見我容貌的竟然是……"},
	[67765] = {CommonPl = "阿米豆腐……施主別看了，再看老衲的頭髮也不會長出來的。"},
	[67768] = {CommonPl = "我是桃花仙，嬌豔如花。"},
	[67771] = {CommonPl = "我是桃幹仙，最能吃的就是我！"},
	[67774] = {CommonPl = "你想看多久就看多久，若不趁現在多看上幾眼，恐怕今後再也沒有機會見到我們這般的美男子了吧。"},
	[67777] = {CommonPl = "長得帥並不是我的錯，你站在我面前嚇人就是你的不對了。哪兒來回哪兒去吧。"},
	[67780] = {CommonPl = "好餓好餓，什麼時候開飯呐？！"},
	[67783] = {CommonPl = "（此人一臉不悅的盯著你）"},
	[67810] = {CommonPl = "哎呦……我可憐的大師兄哇……嚶嚶嚶……"},
	[67816] = {CommonPl = "能夠見上公子一面，可是天大的福氣。"},
	[67819] = {CommonPl = "能夠見上公子一面，可是天大的福氣。"},
	[67822] = {CommonPl = "能夠見上公子一面，可是天大的福氣。"},
	[67825] = {CommonPl = "能夠見上公子一面，可是天大的福氣。"},
	[67828] = {CommonPl = "能夠見上公子一面，可是天大的福氣。"},
	[67831] = {CommonPl = "能夠見上公子一面，可是天大的福氣。"},
	[67834] = {CommonPl = "不錯！我就是打假鬥士，今天出現在這裡，就是特地來打假藥的！"},
	[67873] = {CommonPl = "方才我在江邊洗魚，突然竄出來四五個人，將我綁走，帶到了這裡。"},
	[67876] = {CommonPl = "真是晦氣，好不容易花了五十兩銀子見著了杜秀兒一面！半路居然被這些賊人給劫到此地！我的銀子……嗚嗚嗚嗚……"},
	[67879] = {CommonPl = "謔謔謔謔……謔謔謔……咳咳咳！！！！娘的……笑得太用力了……"},
	[67882] = {CommonPl = "我的蛋炒飯還沒吃完呢……"},
	[67885] = {CommonPl = "石打烏頭粉碎，沙飛海馬俱傷。人參官桂嶺前忙，血染朱砂地上。附子難歸故里，檳榔怎得還鄉？屍骨輕粉臥山場，紅娘子家中盼望。"},
	[67888] = {CommonPl = "我本來說什麼都不想來的，後來他們說給我一錠，我就來了……你看，我到現在，眼睛還腫著呢。"},
	[67891] = {CommonPl = "在我的從醫生涯之中，從來沒有今天如此後悔從事醫護行業。如果我當時沒有聽我娘的話上私塾，沒有聽我娘的話去杭州學醫，沒有吃那碗五個銅板的餛飩，就不會被人捉到這裡來！"},
	[67924] = {CommonPl = "正邪不兩立，廢話少說！亮劍吧！"},
	[67927] = {CommonPl = "正邪不兩立，廢話少說！亮劍吧！"},
	[67930] = {CommonPl = "正邪不兩立，廢話少說！亮劍吧！"},
	[67933] = {CommonPl = "正邪不兩立，廢話少說！亮劍吧！"},
	[67936] = {CommonPl = "正邪不兩立，廢話少說！亮劍吧！"},
	[67942] = {CommonPl = "正邪不兩立，廢話少說！亮劍吧！"},
	[67945] = {CommonPl = "正邪不兩立，廢話少說！亮劍吧！"},
	[67953] = {CommonPl = "阻我大義者，死！"},
	[67954] = {CommonPl = "酒中人飲酒中仙，殿前人承殿前歡。"},
	[67955] = {CommonPl = "吱吱……"},
	[67956] = {CommonPl = "劉府一事，自我而始，也當自我而終。"},
	[67957] = {CommonPl = "這……劉兄，我對不起你啊！！"},
	[67958] = {CommonPl = "屬下有事稟報。"},
	[67959] = {CommonPl = "屬下有事稟報。"},
	[67960] = {CommonPl = "吱吱……"},
	[67961] = {CommonPl = "吱吱……"},
	[67962] = {CommonPl = "吱吱……"},
	[67969] = {CommonPl = "劉正風與魔教中人幹出這種醜事，就想金盤洗手，掩人耳目！江湖豈是這麼好混的嗎？他以為明白人都死光了嗎，哼！"},
	[67970] = {CommonPl = "我只是來喝茶的……"},
	[67971] = {CommonPl = "這茶館裡的風言風語啊，不管你信不信，反正我是信了。"},
	[68114] = {CommonPl = "不成體統，竟然和這些邪魔壞道混雜在一起，真是氣煞我也。"},
	[68137] = {CommonPl = "我們“生生造化丸”是用十種不同的補藥，再加上川貝枇杷膏，提煉八八九十一日而成，無色無味，實在是居家旅行之必備良品！"},
	[68169] = {CommonPl = "每日放榜五次\r每人每次可從榜上領取3支木牌"},
	[68224] = {CommonPl = "伯兮朅兮，邦之桀兮。\r伯也執殳，為王前驅。\r自伯之東，首如飛蓬。\r豈無膏沐？誰適為容。\r其雨其雨，杲杲出日。\r願言思伯，其心首疾。\r焉得萱草，言樹之背。\r願言思伯，使我心痗。\r聽人說，她走的時候，嘴裡念著，這首詩。"},
	[68225] = {CommonPl = "旦兒這兔崽子又跑哪玩去了，說好今天幫為娘修補草屋頂，卻到處都找不到人。\r真是一事接一事，這桃花酒又不知被我這糟腦子忘到哪去了，明明就放在這屋簷下面的。"},
	[68226] = {CommonPl = "猴兒猴兒，莫要怕，那些張牙舞爪的不過是些紙老虎，傷不得我西嶽猴群！\r這些嵩山惡賊，不知何時才能散去，只盼岳先生能早日趕他們下山，還大夥個清淨。如此說來，老夫也是好些時日沒帶著猴兒們在山中走走了。"},
	[68227] = {CommonPl = "自從師父收了那姓林的小子，華山派中就變了味兒，那小子趁大師兄在思過崖受罰，日日和師姐眉來眼去，我們師兄弟看不過，又不好說些什麼，便來到山中練劍。\r沒想這嵩山派卻又何時佔了論劍台，真窩火……\r待我回過氣來，便上思過崖，找大師兄收拾這些傢伙。"},
	[68228] = {CommonPl = "華山號稱天下第一險，最險之處，當屬長空棧道。爺爺跟我講過，說是一位神仙在這裡修煉時架出來的，廣八寸，長十丈餘，背空虛行，世人皆知而不敢行。\r最近有好多外面的人來華山，我這日日採藥艱辛，倒不如在山腰做些油潑面，備些床褥給他們，應該能賺些銀兩去華陰縣裡給娘親買些好藥來。"},
	[68229] = {CommonPl = "一個個張牙舞爪的，以為自己是什麼東西，都是沒種的怪物。若不是他們身上披的那層皮，武當派的道長們早就把你們殺個精光，那還輪得到跟老娘作威作福。\r豬啊雞啊們，可憐了你們，死了還要進這些噁心玩意兒的腹中。"},
	[68230] = {CommonPl = "爹爹被抓走了，隔壁的展哥哥也沒回來。\r展哥哥平日裡帶小葵去陳叔叔那裡買冰糖葫蘆吃，去小溪裡抓青魚，還去山下抓草蛇，小葵想永遠都和展哥哥在一起，那樣就能永遠都有冰糖葫蘆吃，永遠都開心快樂。"},
	[68231] = {CommonPl = "臭豹子！壞豹子！\r竟敢咬傷我姐姐，我洛小丹今天讓你們拿命來償！"},
	[68232] = {CommonPl = "丹兒，丹兒！危險……危……險……快跑回村去！\r來……來人啊……救命……"},
	[68271] = {CommonPl = "不不不，我不認識什麼燕九，我也不是什麼燕九夫人。\r不，不是，你們找錯人了，我單純上來曬曬太陽，你看這谷裡太潮濕了，曬曬太陽，對皮膚好。\r我說了我不是什麼燕九夫人！你們離我遠點好嗎！"},
	[68301] = {CommonPl = "哈哈哈，一個醉鬼，兩個醉鬼……"},
	[68302] = {CommonPl = "（一尊廢棄在荒郊的石像）"},
	[68303] = {CommonPl = "……"},
	[68304] = {CommonPl = "……"},
	[68323] = {CommonPl = "青青子衿，悠悠我心。\r縱我不往，子寧不嗣音。\r青青子佩，悠悠我思。\r縱我不往，子寧不來。\r挑兮達兮，在城闕兮。\r子今不在，孤鴻斷息。\r子陵，你好傻，我本想在贈你琴之時請你與我共赴京城，誰料如此弄人。\r蒼天！你若有眼，看看這蒼生吧！"},
	[68324] = {CommonPl = "曾經有一個愛我的師弟站在我的面前，可我卻沒有珍惜，直到他離去才後悔莫及。\r人生最悲痛的事莫過於此，你年復一年的期待等待，卻忽視了身邊的那些人那些事。當有一天恍然大悟，卻發現幸福來得太快走的太急，所有傾訴都已來不及。\r師弟，等我，師兄這就來找你……"},
	[68325] = {CommonPl = "我兒時最大的夢想，就是做個劫富濟貧的自在俠盜，哈哈！可惜我武當門規嚴謹，倒是讓我好生束手束腳，今兒來偷一偷這貪官惡吏，倒也過足了癮頭。"},
	[68326] = {CommonPl = "最近華山不太平，嵩山派拉著劍宗叛徒來尋事，師父讓我來這華山山口守著，好即使通報情況。\r不能給大師兄送飯了……好難過……\r不過，可以好好和慕雲兄聊聊天下下棋了，省的我每天偷偷摸摸往這兒跑來尋他玩。"},
	[68327] = {CommonPl = "金娘！金娘你在哪裡！？\r你不是很愛看為夫的容顏嗎，為夫來了，快回來看吧！\r為夫以後讓你天天看日日看！\r金娘！金娘！\r那華山派的令狐小兒不好看，快回為夫身邊來吧！"},
	[68328] = {CommonPl = "這藥王谷啊，潮，真潮！\r陰暗潮濕，毒蟲橫行，還有些坑蒙拐騙殺人放火下毒餵藥的怪人，可謂危機四伏舉步維艱！\r不過不要緊，客官您可不要怕，我這裡有清涼油樟腦丸，還有從神秘南亞次大陸來的印度神油，專治受潮濕熱等症狀。\r這還有防身……防……\r什麼？對，對，沒錯，我是古董商販，不是賣藥的，這不是隔壁老錢拉肚子嗎，我幫他賣一會兒。\r您，有什麼寶貝想出的麼？拿出來讓咱瞧瞧~"},
	[68329] = {CommonPl = "諸位可千萬別信旁邊那騙子！\r什麼清涼油樟腦丸印度神油的，都是他自己從谷中陰溝裡灌來的髒水，可髒著呢。\r不過這谷中毒物甚多確是真的，行走一定要小心啊。\r我家奶奶說有一位姓田的青年英豪，是她的舊相識，最近要來相會，所以遣我來等候，您若是賞臉，稍會兒可以隨我回去趙府歇腳，老爺奶奶定當歡迎。"},
	[68330] = {CommonPl = "道可道，非常道，想要修成無上大道，又怎能守著陳規戒律不知變通！我，自有我的修行之道。"},
	[68331] = {CommonPl = "這藥王廟本是供奉藥王孫思邈之處，過去雖算不得上香火繁盛，但也是有些香客的。\r可自從百藥門的妖孽們來到藥王谷，谷裡的來人就越來越少，後來廟中道士也四散而去，人煙漸漸被荒草所取代……"},
	[68332] = {CommonPl = "大黃……大黃……往日這谷裡的大黃那麼多，怎麼今日都不見了。\r說來奇怪，自從百藥門進了這藥王谷，谷裡的草藥是越長越大，顏色越來越鮮豔，雖說東西大了我也開心，可……可總覺得……哪裡不對……\r呃，難道是他們給草藥澆了什麼東西？！我得趕緊查查。"},
	[68333] = {CommonPl = "晴兒他爹娘，不好好過日子，天天在家裡吵吵嚷嚷，這不，前幾天又吵了一架，他娘哭著跑回娘家，他爹也收拾東西走了，跟村裡崔老頭說，是找了幾個小夥子一起去了蘇杭。\r唉……都是老婆子上輩子造孽啊……"},
	[68334] = {CommonPl = "昨晚門縫中被人塞入一封信，說今日在村外的土地廟相見，為何等到現在還不來。\r不知那信是不是蔡兄所寫，信上那淡淡的迷人香氣倒是十分熟悉。"},
	[68335] = {CommonPl = "（安靜的望著你，眼睛清澈如潭水）"},
	[68336] = {CommonPl = "老子本來是來拜佛求財的，竟然遇到這場面，真血腥暴力，不和諧。\r這些小夥子也真不淡定，如此好的青春歲月都浪費在無意義的打鬥中，快，快到碗裡來~\r不……不對……快到叔叔這裡來~陪叔叔拜佛，佛祖賜我錢了咱們一起去城裡吃好的！"},
	[68339] = {CommonPl = "年輕時，我曾執著尋覓最好的紙、最好的墨、最好的筆，妄圖透過這些外物來幫助自己畫出最好的畫。直到……以後，我才明白，最美的畫無須刻意，是上蒼透過我心神與軀體，流瀉筆端。"},
	[68340] = {CommonPl = "金線，我的金線，怎麼就是找不到……\r年輕輕的怎麼記性就這麼差，唉，金線，我最後一次用完是放到哪裡了究竟……\r難道又是二狗子給我弄丟了？也不對啊，最近他們一直蹲守在岳王廟門口……"},
	[68341] = {CommonPl = "哇，這就是從南京來的雲錦，果真華麗。\r我若是在開封這邊開點雲錦店鋪，生意想必會非常好~"},
	[68342] = {CommonPl = "這些酒都被昆侖派的人訂了，說晌午時來取，我得趕緊給裡面投些蒙汗藥，免得令狐公子來時讓他們壞了風景。"},
	[68343] = {CommonPl = "我等聚集此處，為了一睹令狐公子俊容，一會兒定要和他乾上幾碗！\r這只有酒，沒有菜可不好，待我去打幾隻野雞兔子來，和大夥好好吃一頓！"},
	[68344] = {CommonPl = "有泰山那猴人在，想搞到虎皮估計是不可能了，只好搞些鱷魚皮，不知道賣不賣得出去。\r先跟這些泰山弟子把裝修材料的價格談好，別看一個個是修道之人，講起價來果真心狠手辣！"},
	[68587] = {CommonPl = "好酒，好酒……\r如此佳釀，豈有私藏之理？來，你我共飲一杯。"},
	[68606] = {CommonPl = "忘了帶鑰匙，進不去家門了，悲劇……\r兒子不知道幹嘛去了，門鎖的這麼緊……"},
	[68679] = {CommonPl = "哎呀這些人，總是從人家身邊走過來蹭過去的，眼珠不停地瞄著人家，也不知在打什麼壞主意。"},
	[68680] = {CommonPl = "……"},
	[68683] = {CommonPl = "大老爺對我有再造之恩，此生白相對老爺至死不渝。"},
	[68686] = {CommonPl = "謝謝關心。"},
	[70508] = {CommonPl = "江湖近來風聲四起總不太平，本王正招賢納士願得良才為國效力。哎…懷念當年的孤劍村的愜意生活！"},
	[70538] = {CommonPl = "請手下留情，不要打那些姑娘！她們都是被關中王搶來的可憐孩子，等我勸得關中王棄惡從善，就放她們返回家去。"},
	[70893] = {CommonPl = "發明了一種暗器，可以用來引燃易燃物，早前在衡山郊外的廢宅裡試過了，效果真是好。你想買幾隻玩玩嗎？"},
	[71445] = {CommonPl = "在抗擊外敵戰鬥中的英雄人物，百姓們為了感激其抗擊外敵的俠義精神，特連夜趕造“帶頭大哥”的雕像供後人瞻仰學習！"},
	[71449] = {CommonPl = "師弟你不懂愛，舒公塔會掉下來。"},
	[71452] = {CommonPl = "別唱了，難聽死了。"},
	[71455] = {CommonPl = "我就是我，是不一樣的煙火。"},
	[71458] = {CommonPl = "落大ho,落大ho，雨都下不累。\r騎著歐羅巴，唱著rainingday。"},
	[71461] = {CommonPl = "道道道，非常道。"},
	[71464] = {CommonPl = "洗刷刷~洗刷刷~\r哦洗刷刷~\r彎！圖！碎！"},
	[71467] = {CommonPl = "我左看右看上看下看，原來每個部位都不簡單！"},
	[71470] = {CommonPl = "西風將軍！快！快咬掉它的腿！"},
	[71473] = {CommonPl = "（小女孩正在聚精會神的觀看鬥蛐蛐）"},
	[71476] = {CommonPl = "上啊！暴龍獸！擰斷它的頭！！"},
	[71482] = {CommonPl = "#N,我記得你！上次你拿了我一把傘不給錢就走了！快還來！"},
	[71485] = {CommonPl = "小孩，要不要進來玩幾把？"},
	[71488] = {CommonPl = "手又癢了……可是我答應娘子不賭的，而且身上的銅板已經所剩無幾了。"},
	[71494] = {CommonPl = "嘿喲呵嘿！嘿呦呵嘿！！"},
	[71497] = {CommonPl = "都特麼別愣著！趕緊幹活！"},
	[71503] = {CommonPl = "……好累……"},
	[71506] = {CommonPl = "當歸一兩五錢，杜仲七兩三錢。"},
	[71509] = {CommonPl = "這年頭還是黑心錢好賺。"},
	[71512] = {CommonPl = "我娘叫我看鋪子，別看我人小，我可機靈了。"},
	[71515] = {CommonPl = "咕咕……咕……咕咕咕"},
	[71518] = {CommonPl = "這裡的景色真是不錯。"},
	[71521] = {CommonPl = "泥豪~~地球人~"},
	[71527] = {CommonPl = "最喜歡看別人領便當了。"},
	[71530] = {CommonPl = "關我屁事，我出來買醬油的。"},
	[71536] = {CommonPl = "這匹布可是用上等的蠶絲製作而成的，你摸摸這手感，是不是又細又滑，宛如十四歲少女的肌膚？"},
	[71539] = {CommonPl = "1＋1是等於2呢，還是等於1呢？"},
	[71542] = {CommonPl = "（這個人竟然很神奇的站著睡著了！）"},
	[71545] = {CommonPl = "笑漸不聞聲漸悄，多情總被無情惱。"},
	[71590] = {CommonPl = "老頭我活了八十年,難道今次要白髮人送黑髮人嗎?請老天爺保佑我落雪莊!"},
	[71593] = {CommonPl = "那幫帶刀的來勢洶洶,兇神惡煞的,老爺這次一定不好渡過難關啊."},
	[71596] = {CommonPl = "爸爸……爸爸……嗚嗚嗚嗚嗚"},
	[71599] = {CommonPl = "餘杭泛舟,不容錯過!不爽傾訴給我,滿意請您告訴朋友!"},
	[71602] = {CommonPl = "我們中了敵人的調虎離山之計！弟子們全都下落不明，哎，是為師考慮不周啊！"},
	[71605] = {CommonPl = "漂亮的小尼姑被抓走了，光留下這個滿臉褶子的老尼姑……抓人的你們也太不把本官放在眼裡了！"},
	[71608] = {CommonPl = "跑個啥子勁啊!沒有了馬匹我就算活下來也是個死,甭跑了."},
	[71611] = {CommonPl = "老翁我生活在廿八鋪幾十年啦，什麼大風大浪都見過。這一回孫女沒了,你們還不如把我這老骨頭抓走呢!"},
	[71614] = {CommonPl = "嘶嘶－－嘶吼吼－－"},
	[71617] = {CommonPl = "師弟,為我報……仇…………"},
	[71620] = {CommonPl = "這是一家吃人不吐骨頭的黑店！看來上下串通、裡應外合、防守嚴密。#Y你尚未進食，探聽店家的秘密就靠你了！"},
	[71623] = {CommonPl = "吃完了飯來啊唱首歌，山谷裡的妹子愛哥哥~~~我的小丫頭片子啊~~愛哥哥！\r地方是我的，貨也是我的，誰要是亂了規矩，以後就別來我這吃飯卸貨！\r小二，叫廚子，殺豬記得留個頭啊！"},
	[71626] = {CommonPl = "我們馬幫日行千里，是峽谷這條道上的貨運生命線。敢搶我們的貨物，就是與這一路上所有百姓作對！"},
	[71629] = {CommonPl = "弟兄們拼死抵抗，死傷慘重。這次的劫匪是有備而來啊！"},
	[71632] = {CommonPl = "客人，稍安勿躁，切莫喧嘩！如果影響了其它客人的飲食情緒，就不好了。"},
	[71635] = {CommonPl = "這荒郊野嶺的，能嘗到我金牌大廚的手藝，客官您就偷著樂吧，指不定就是八輩子修來的福分。"},
	[71638] = {CommonPl = "啊,終於能正常呼吸了!\r困我這麼久,麻袋裡太憋悶了!"},
	[71641] = {CommonPl = "我幫與金蟾客棧合作日久，今天居然被人撞破了……真是狗屎運當頭！"},
	[71644] = {CommonPl = "佇倚危樓風細細。望極春愁，黯黯生天際。草色煙光殘照裡。無言誰會憑闌意。"},
	[71647] = {CommonPl = "聽說柳七仙去那天,名妓們自發排隊送君千里.\r正是:郊外綠陰千里，掩映紅裙十隊。惜別語方長，車馬催人速去。偷淚，偷淚，那得分身與你！"},
	[71650] = {CommonPl = "擬把疏狂圖一醉。對酒當歌，強樂還無味。衣帶漸寬終不悔。為伊消得人憔悴。"},
	[71653] = {CommonPl = "真希望世上少幾個貪名奪利的狗官,換柳七官人再世!"},
	[71656] = {CommonPl = "幸有意中人，堪尋訪。且恁偎紅依翠，風流事、平生暢。\r青春都一餉。忍把浮名，換了淺斟低唱。\r再也沒有一個人，會像柳七那樣，真心愛我們青樓女子了。"},
	[71659] = {CommonPl = "我要是能早生幾年就好了，也能得見柳七官人仙顏。哪怕只得片刻溫存，唱得半首清詞也好。\r只可歎，千種風情同虛設，人間再無柳七君！"},
	[71662] = {CommonPl = "不願穿綾羅，願依柳七哥；不願君王召，願得柳七叫；不願千黃金，願中柳七心；不願神仙見，願識柳七面。"},
	[71665] = {CommonPl = "謝謝你救了我!這些天殺的金錢幫黑人,一定要告訴捕快,連窩端了他們!"},
	[71683] = {CommonPl = "大爺……可憐可憐我，給點錢吧……"},
	[71686] = {CommonPl = "大爺……可憐可憐我，給點錢吧……"},
	[72130] = {CommonPl = "鏢局罪案現場證物，需加入鏢局才可探查。"},
	[72131] = {CommonPl = "鏢局罪案現場證物，需加入鏢局才可探查。"},
	[72132] = {CommonPl = "鏢局罪案現場證物，需加入鏢局才可探查。"},
	[72133] = {CommonPl = "鏢局罪案現場證物，需加入鏢局才可探查。"},
	[72134] = {CommonPl = "鏢局罪案現場證物，需加入鏢局才可探查。"},
	[72135] = {CommonPl = "鏢局罪案現場證物，需加入鏢局才可探查。"},
	[72136] = {CommonPl = "鏢局罪案現場證物，需加入鏢局才可探查。"},
	[72137] = {CommonPl = "鏢局罪案現場證物，需加入鏢局才可探查。"},
	[72138] = {CommonPl = "鏢局罪案現場證物，需加入鏢局才可探查。"},
	[72139] = {CommonPl = "鏢局罪案現場證物，需加入鏢局才可探查。"},
	[72140] = {CommonPl = "鏢局罪案現場證物，需加入鏢局才可探查。"},
	[72201] = {CommonPl = "江湖本無正邪，\r人性哪來黑白？"},
	[72202] = {CommonPl = "有人愛絕世武功，\r有人愛琴棋書畫，\r有人愛傾城紅顏，\r#Y你說，人生在世，該為何往？"},
	[72227] = {CommonPl = "老夫聊發少年狂，房頂賞景自愉忙。\r什麼？你覺得我站的高嗎？我的夫人站的更高，她在落雁塔頂呢！落雁塔那麼高，一般人可上不去。"},
	[72260] = {CommonPl = "雲語朝歌,天涯水媚,白牆入畫,亦幻亦生.方才,是蝴蝶一夢看見了我,或是我夢到它們輕舞飛揚?"},
	[72283] = {CommonPl = "吾君雖已垂暮年，仍似當年少年郎。"},
	[72534] = {CommonPl = "本店名為七寶齋，自然是各種珠寶應有盡有。"},
	[72535] = {CommonPl = "初雪，你為什麼要……"},
	[72651] = {CommonPl = "我家大少爺曲危樓，生的英俊非凡，往日裡多有江南豪門遣了媒婆前來傳話，我家少爺自是孤傲，從不理會。\r仙愁峽中金錢幫開設金蟾客棧做些謀財害命的骯髒勾當，我家少爺一心想要剷除這群惡黨。老爺當然勸過不要惹是生非，可少爺他……他又如何聽得進去，便離家而去，從此再無音訊。\r老爺派莊中所有弟子各處尋找，至今未找到，只怕是已經糟了這客棧的謀害。"},
	[72652] = {CommonPl = "曲全老爺派我和宿千到這金蟾客棧尋查少爺的下落，數月過去了，卻一無所獲。少爺是生是死、現在何處竟無從所得。我倆也無面目回去稟報老爺，只能繼續杵在這黑店中，希望，能發現什麼線索。\r聽說二小姐為了少爺的事也回到谷中，但並未回到家而潛伏在客棧附近。想來從她換了名號避去山中修行到現在，也有三年了，世人多已忘記曲家二小姐曲晚晴，只知終南山中有一女俠名叫十一夜。"},
	[72653] = {CommonPl = "曲家好大的膽子，竟敢在我金錢幫的地頭撒野。曲全那老不死的東西，還真以為日月神教任我行仍在世上！\r哈哈哈，就算我們幫主不收拾他落雪莊，東方不敗也不會留他狗命太久，他們家少爺曲危樓就是活活的例子！"},
	[72654] = {CommonPl = "被擄來應已一年，可日日夜夜念著蘇州家中的父母親，不知他們身體可好，不知他們是否尋了英雄大俠前來搭救我們姐妹。呆在這山寨之中，朝不保夕，誰能料得哪日大王心情不好，便將我姐妹二人做了下酒菜，與父母陰陽相隔。"},
	[72655] = {CommonPl = "那狗賊，日日蹂躪我們，早晚有一天我要親自割開他的肚子，看看他的心是不是臭的！"},
	[72689] = {CommonPl = "我忘記許多事情了，只模模糊糊記得有些事還沒做！"},
	[72690] = {CommonPl = "就要到家裡，我不知道是開心還是惶恐！"},
	[72691] = {CommonPl = "在夢裡，我曾千百次回到這裡。然而真的回來後，看著這滿目蒼涼，我寧願從來沒回來過！"},
	[72692] = {CommonPl = "雖然到處都是發瘋的藥人，但是看著就要揭不開鍋的家，我沒有選擇，只有砍些柴然後到洛陽府換點銅錢。"},
	[72693] = {CommonPl = "親戚或余悲，他人亦已歌。這荒墳枯塚，一眨眼就會淹沒在荒草之中。"},
	[72709] = {CommonPl = "等我找到很多寶藏，發了財，就回去娶雪兒！"},
	[72780] = {CommonPl = "福王仁政特在此招募願為國效力之能人異士，有什麼案子我可以幫你做筆錄張貼在皇榜上！\r發佈時間：10：00-19：00\r結算時間：19：00-23：59"},
	[67147] = {CommonPl = "鏢局罪案現場證物，需加入鏢局才可探查。"},
	[67149] = {CommonPl = "鏢局罪案現場證物，需加入鏢局才可探查。"},
	[67146] = {CommonPl = "鏢局罪案現場證物，需加入鏢局才可探查。"},
	[67144] = {CommonPl = "鏢局罪案現場證物，需加入鏢局才可探查。"},
	[67148] = {CommonPl = "鏢局罪案現場證物，需加入鏢局才可探查。"},
	[67138] = {CommonPl = "鏢局罪案現場證物，需加入鏢局才可探查。"},
	[67139] = {CommonPl = "鏢局罪案現場證物，需加入鏢局才可探查。"},
	[67140] = {CommonPl = "鏢局罪案現場證物，需加入鏢局才可探查。"},
	[67141] = {CommonPl = "鏢局罪案現場證物，需加入鏢局才可探查。"},
	[67142] = {CommonPl = "鏢局罪案現場證物，需加入鏢局才可探查。"},
	[67145] = {CommonPl = "鏢局罪案現場證物，需加入鏢局才可探查。"},
	[72913] = {CommonPl = "恩，據我看，這菊花寶典，既然在圓王八的閨房裡找不到，他老婆的閨房裡也找不到，他小妾的閨房裡也找不到，那一定就在……為什麼他老婆和他不在一個閨房睡？這其中一定有貓膩。\r你們幾個，快去給我問問，圓王八和他老婆分房睡的原因！"},
	[72914] = {CommonPl = "哥幾個安靜！淡定！聽大哥安排！"},
	[72915] = {CommonPl = "喂！圓王八！別光顧著自己吃，也讓小姑娘送點水果點心給你桃谷六仙爺爺們！"},
	[72916] = {CommonPl = "我想想，既然藥王谷的少年說菊花寶典被圓王八偷走，那我就一定會在圓王八家找到。\r可是，可是我們哥幾個這幾天裡裡外外翻了無數遍，都沒找到，一定是圓王八偷偷給了他那個小白臉外甥。\r今天晚上趁他獨處，我要搜搜他身子，看有沒有藏著。"},
	[72917] = {CommonPl = "桃小喵！既然是我們桃谷六仙的第七個弟兄，就要按我們兄弟的方法辦事！\r第一，出門遛彎碰到要抓你吃貓肉的壞蛋，就抓他臉！\r第二，不能亂吃外面的老鼠，圓王八家的除外，他吝嗇的連老鼠藥都不買。\r第三，有好酒好肉不許自己獨吞，要是被四哥我看到，就給你做絕育！\r第四，令狐沖是你兄弟，所以你見了林平之就撓，撓死那個小三！"},
	[72918] = {CommonPl = "喂喂喂，四弟有完沒完啊，趕緊讓桃小喵去撓死圓王八，看他承認不承認偷了我們的菊花寶典！\r看來這喪幡對圓王八沒什麼作用，他該吃吃該喝喝，不搭理我們……好生鬱悶……一會兒我再多掛點，讓他滿屋都是！"},
	[72919] = {CommonPl = "我曾經愛過一個人，一心想要和他在一起。\r我陪他喝酒、陪他練劍、幫他解圍、替他報仇、幫他教訓小三、照顧他整夜不睡.\r他說他愛我，我相信了。"},
	[72920] = {CommonPl = "東方姑娘，我是我，不是別人，請你把我當做一個獨立的個體，而不是他人的影子。\r我用情專一，決不會在你給我跳舞、陪我喝酒、陪我練劍、幫我解圍、替我報仇、幫我教訓小三、照顧我整夜不睡之後，還做出要殺你，然後和別人結婚這種無恥之事！"},
	[72926] = {CommonPl = "聽福王府的人說，白馬寺就要擴建了，據說還有暹羅和日本的寺廟，我佛慈悲，那究竟是寺廟還是主題公園。"},
	[71834] = {CommonPl = "快，那幾個傢伙朝著迴雁樓的方向去了！"},
	[71837] = {CommonPl = "一個小尼姑架著個大男人，我看多半救不了他，我還是去幫幫他們算了！"},
	[72272] = {CommonPl = "這些嵩山派的壞蛋，絕對不能放過他們！"},
	[65603] = {CommonPl = "保衛王爺與王府的安全是我們的職責！"},
	[65588] = {CommonPl = "保衛王爺與王府的安全是我們的職責！"},
	[70509] = {CommonPl = "保衛王爺與王府的安全是我們的職責！"},
	[72209] = {CommonPl = "危樓，你的仇姐姐一定替你報。"},
	[74134] = {CommonPl = "小師妹心儀林師弟，師父又誤會我偷了《辟邪劍譜》……唉……何以解憂？\r猶憶那日我與東方姑娘豪飲，何其爽快！\r如今，卻只剩我一人在此喝悶酒。"},
	[74113] = {CommonPl = "瞧，那邊就是金吾衛的地盤。"},
	[74114] = {CommonPl = "專諸為報公子光知遇之恩，以魚腸劍殺吳王僚。後來專諸死後，公子光成為吳王闔閭，闔閭打敗越王勾踐後稱雄吳越，後來吳王夫差聽信讒言，派人將魚腸劍送與先祖伍子胥。最後夫差敗於越王勾踐之手。"},
	[74115] = {CommonPl = "小悠姐姐，你到底在哪裡啊？"},
	[74116] = {CommonPl = "昔年干將莫邪為鑄絕世名劍，不惜以肉身祭劍……這太血腥了。"},
	[74117] = {CommonPl = "犯我鑄劍村者，定斬不饒。"},
	[74118] = {CommonPl = "玉面醫聖莫風豐神俊秀，年少有為。相信不久，就可以取代老朽神醫的名號了。"},
	[74119] = {CommonPl = "我……好痛……五內俱……焚……"},
	[73741] = {CommonPl = "別再問我了！我急著逃命，不想多說話！"},
	[73744] = {CommonPl = "我最喜歡吃麻辣雞翅，一起吃雞，一起在歌唱。"},
	[73747] = {CommonPl = "黑心腸的人啊，你死到哪裡去了？丟下我們孤兒寡母……\r嗚嗚……嗚……"},
	[73750] = {CommonPl = "這幾天，我夜夜被惡夢纏身，總夢見他變成厲鬼來找我……\r我哭喊著求他放回我，每次都在即將被他殺掉的時候驚醒……"},
	[73753] = {CommonPl = "我打小就特別崇拜諸葛亮，他藝高人膽大，聰慧過人，以下省略一萬字……"},
	[73756] = {CommonPl = "對不起，我說了謊。\r我欺騙了國家，欺騙了人民……其實我不是人，我是蜘蛛俠。"},
	[73759] = {CommonPl = "最近無聊得緊，弄把破劍騙這些呆子玩玩。"},
	[73762] = {CommonPl = "花兒~~為甚~麼~這樣紅~~為甚麼這~樣~紅~~"},
	[73765] = {CommonPl = "那傢伙騷包一個，好好的大男人，偏要叫什麼憐花。\r我看了就來氣。"},
	[73768] = {CommonPl = "哎……這麼挑食，再餵肥一些，就把你宰了吃算了。"},
	[73847] = {CommonPl = "犧牲才能衍生。"},
	[73887] = {CommonPl = "瘋子，全都是瘋子。"},
	[73890] = {CommonPl = "我不是膽子小，我只是怕傷害到別人。"},
	[73911] = {CommonPl = "我們六人合力！天下無敵！"},
	[73914] = {CommonPl = "我們六人合力！天下無敵！"},
	[73917] = {CommonPl = "我們六人合力！天下無敵！"},
	[73920] = {CommonPl = "我們六人合力！天下無敵！"},
	[73923] = {CommonPl = "我們六人合力！天下無敵！"},
	[73926] = {CommonPl = "我們六人合力！天下無敵！"},
	[73929] = {CommonPl = "那和尚好生厲害！難道我田某人的命運就是當尼姑的徒弟嗎！"},
	[73932] = {CommonPl = "這淫賊！竟敢欺負儀琳！看我怎麼收拾他！"},
	[73935] = {CommonPl = "啊……那惡賊好像很痛苦的樣子……"},
	[73938] = {CommonPl = "我們六人合力！天下無敵！"},
	[73941] = {CommonPl = "我們六人合力！天下無敵！"},
	[73944] = {CommonPl = "我們六人合力！天下無敵！"},
	[73947] = {CommonPl = "我們六人合力！天下無敵！"},
	[73950] = {CommonPl = "我們六人合力！天下無敵！"},
	[73953] = {CommonPl = "我們六人合力！天下無敵！"},
	[73956] = {CommonPl = "哎呦……哎呦……這都是些什麼人啊……抬走我是想對我做什麼！？"},
	[74376] = {CommonPl = "好疼……好疼……"},
	[74377] = {CommonPl = "好疼……好疼……"},
	[74391] = {CommonPl = "那些東廠惡賊究竟有什麼目的？"},
	[74370] = {CommonPl = "偷他們的羊，讓他們無羊可養。\r每人每天有兩次偷羊的機會，偷到羊後會變身為抱羊狀態，變身狀態下放棄任務、死亡、下線（大退小退均算）都會浪費一次交任務的機會。"},
	[74073] = {CommonPl = "懲惡即是揚善！"},
	[74076] = {CommonPl = "菩薩亦有金剛之怒！"},
	[74209] = {CommonPl = "經書雖在，卻不見方慧禪師蹤影。"},
	[74082] = {CommonPl = "少林禪武醫不能在我手中中斷了。"},
	[74085] = {CommonPl = "阿彌陀佛，善哉！善哉！"},
	[74210] = {CommonPl = "這串佛珠，應當也是方慧禪師留下的。"},
	[74094] = {CommonPl = "村中的老老幼幼都被水潭裡這些鱷魚禍害了。"},
	[74091] = {CommonPl = "法王聽聞中原高手如雲，特命我來此地尋找高僧。"},
	[74079] = {CommonPl = "見山可是山？見水可是水？此中的禪機我還是難以領悟。"},
	[73959] = {CommonPl = "哼，跟我鬥！太嫩了！"},
	[73962] = {CommonPl = "不知道那惡賊怎麼樣了……"},
	[73965] = {CommonPl = "這種比賽真好玩！"},
	[73968] = {CommonPl = "這種比賽真好玩！"},
	[73971] = {CommonPl = "這種比賽真好玩！"},
	[73974] = {CommonPl = "這種比賽真好玩！"},
	[73977] = {CommonPl = "這種比賽真好玩！"},
	[73980] = {CommonPl = "這種比賽真好玩！"},
	[73983] = {CommonPl = "我怎麼這麼倒楣啊……"},
	[73986] = {CommonPl = "哈哈哈哈哈！今天是個好日子！"},
	[73989] = {CommonPl = "那惡賊的傷更重了……"},
	[73771] = {CommonPl = "想我堂堂黃金家族直系子孫，竟落泊至此等境地，其中淒涼有誰知。"},
	[73774] = {CommonPl = "小姐……嗚嗚嗚……可憐的小姐……"},
	[73777] = {CommonPl = "若不是為了和他雙宿雙飛，我也不會出此下策。\r我知道這樣做的後果……但我義無反顧，亦無怨無悔。"},
	[73780] = {CommonPl = "自古多情空餘恨，此恨綿綿無絕期……"},
	[73783] = {CommonPl = "來呀來喝酒啊，不醉不甘休。"},
	[73786] = {CommonPl = "客官是要來燒刀子，還是醉青花？"},
	[73795] = {CommonPl = "……"},
	[73798] = {CommonPl = "好熱，這大鍋爐日日烤夜夜烤，我滴下的汗水都快流成河了！"},
	[73717] = {CommonPl = "鋤禾日當午，汗滴禾下土。誰知盤中餐，粒粒皆辛苦。"},
	[73720] = {CommonPl = "我一個煮飯婆，黃風寨的賊囚著我也沒用。真幸運我老去得那麼早，才能和老頭子平平安安廝守一輩子。有人疼的滋味太美了。"},
	[73723] = {CommonPl = "鐵礦！鐵礦！這讓狗官瘋魔，讓我的朋友丟了性命的東西，真有那麼貴重那麼值錢嗎？"},
	[73726] = {CommonPl = "龍一，龍一你在哪？不是說好了挖礦掙夠了錢就來娶我的嗎？"},
	[73729] = {CommonPl = "小霞，我每天都在想你，想你溫暖的手，柔軟的唇。但自從來到這兒，我的命都不屬於自己了，想活，活不下去；想死，也死不了。我是不可能給你幸福了！"},
	[73732] = {CommonPl = "燕青這個苦命的妞子，傷心死了還得強撐著這支隊伍。哎，要是能撐過這一場硬仗，我要帶她去找個安靜優美的地方，倚著桃花流水，淡看雲卷雲舒。"},
	[73735] = {CommonPl = "我看著被大風卷亂的雲，胸中就生出強烈的悸動。我不要在這與世隔絕的地方平庸過一輩子，我要出去，感受世界的風暴！要讓青春在激烈地捶打中燃燒！"},
	[73738] = {CommonPl = "一周七天每天採一種不同的花，這樣只要聞到庭院的香氣就知道是星期幾了！每天都有新感覺呢！"},
	[73899] = {CommonPl = "生命在於實驗！！所有的物質基礎都來源於實驗的成功與否。"},
	[73900] = {CommonPl = "阿彌陀佛……"},
	[73901] = {CommonPl = "我得快點回去，兒子還等著我吃飯呢。"},
	[75405] = {CommonPl = "西北望長安，可憐無數山"},
	[72924] = {CommonPl = "想要知道精絕古城的秘密嗎？那得通過我的考驗才行……"},
	[72934] = {CommonPl = "想要知道精絕古城的秘密嗎？那得通過我的考驗才行……"},
	[75199] = {CommonPl = "想要知道精絕古城的秘密嗎？那得通過我的考驗才行……"},
	[75202] = {CommonPl = "想要知道精絕古城的秘密嗎？那得通過我的考驗才行……"},
	[75205] = {CommonPl = "想要知道精絕古城的秘密嗎？那得通過我的考驗才行……"},
	[61321] = {CommonPl = "口渴嗎？來碗茶？"},
	[57846] = {CommonPl = "我追隨老師出生入死的時候你都不知道在哪兒。身上帶銀子沒？拿二兩給小爺買糖葫蘆。"},
	[76068] = {CommonPl = "人老了，病痛越來越多……"},
	[76108] = {CommonPl = "前方正在施工"},
	[76050] = {CommonPl = "沒來邊境之前，我在餘杭開醫館，人稱金館長。"},
	[76122] = {CommonPl = "爺的“十三太保橫練”是硬氣功，練到絕頂，便可刀劍不入。"},
	[58979] = {CommonPl = "證書這種東西，你留著不如我收著，各得其所。"},
	[72862] = {CommonPl = "有多餘的好食材可以找我，可別糟蹋了。"},
	[76989] = {CommonPl = "\r官逼民反，民不得不反！\r我要用自己常年捕獵山裡動物練出的本事，去殺死那些不讓大家過安穩日子的狗官!"},
	[76990] = {CommonPl = "糖葫蘆，圓又紅，酸酸甜甜有生命.吃上一顆神氣清,煩惱鬱結無影蹤."},
	[76991] = {CommonPl = "佛語“當頭棒喝”教人頓悟,這些毀佛的傢伙才最需要當頭棒喝呢!\r菩薩,要是我忍不住敲上去，你一定能理解我."},
	[76992] = {CommonPl = "“菩提本非樹,明鏡亦非台”,雖然我知道佛法是無處不在的，並不受形體拘束。但看到這些無法無天的傢伙如此被佛像不敬，我就怒火中燒，難以平靜。阿彌陀佛！"},
	[76993] = {CommonPl = "身是菩提樹，心如明鏡台。\r時時常拂拭，勿使惹塵埃。"},
	[76986] = {CommonPl = "妹妹小時候最依賴我了，我不帶著她哪兒也不敢去。\r唉，現在長成大姑娘，嫁去了別的村子，一年半載的也見不到了……還好她半個月就會給我寄來一封信，念叨點家常瑣事也親切得很。"},
	[76987] = {CommonPl = "我們南疆人本來最擅長制蠱的，可自從那個雲赤來到靈蛇村，蠱蟲們突然不認識我們了！制蠱的人們紛紛重傷，要麼悲慘死去，要麼變成中毒的僵屍。"},
	[76988] = {CommonPl = "我好恨!恨死那些靈蛇打手了!"},
	[77101] = {CommonPl = "狀哉我大五仙！"},
	[77104] = {CommonPl = "那個翠翠煩死了，一天到晚沒事找事。"},
	[77107] = {CommonPl = "我的理想就是吃遍天下美食。"},
	[77112] = {CommonPl = "阿娘的病也不知道什麼時候才能治好……哎……"},
	[77115] = {CommonPl = "都別管我，讓我去死。"},
	[77118] = {CommonPl = "妹妹太淘氣了，她要一直這樣，我怎麼放得了心讓她一個人行走江湖。"},
	[77121] = {CommonPl = "我和哥哥千里迢迢從波斯趕到這裡，就是聽說這裡出現了一個新鮮玩意，嗚嗚……可是好東西沒見著，我就快要死了。"},
	[77122] = {CommonPl = "嚶嚶……房子，我娶媳婦的本兒……"},
	[77125] = {CommonPl = "越是危險的地方，我就越喜歡，風險往往和利益並存。"},
	[77142] = {CommonPl = "好餓……餓得肚子都痛了，可惡，好不想下樓……"},
	[76774] = {CommonPl = "一顆長在石頭上的奇樹。"},
	[76775] = {CommonPl = "石上有樹，葉奇，若得石樹之青葉，則為有緣人，有緣人也！"},
	[76776] = {CommonPl = "在這論劍宮之上，可觀華山全景，但此處非常人所能達，若能見到我，證明你非常人。"},
	[76777] = {CommonPl = "阿彌陀佛……這裡一點都沒變，還是我出家前的樣子……"},
	[76778] = {CommonPl = "落雪莊……落雪莊……真是好名字。"},
	[76779] = {CommonPl = "我最喜歡到處爬石頭玩了！"},
	[76780] = {CommonPl = "知道我為什麼叫張不跌嗎？因為我從來不會跌倒！\r沒事多來幫我修修木橋，說不定我哪天一高興……嘿嘿……天機不可洩露。"},
	[76781] = {CommonPl = "這次多收集一些商品拿去洛陽賣，洛陽那邊的闊少爺都是錢多的花不完呢！"},
	[76782] = {CommonPl = "好餓啊……沒力氣思考了呢！"},
	[76783] = {CommonPl = "嗚嗚嗚，都怪他，非要偷什麼秘笈！"},
	[76784] = {CommonPl = "真倒楣，偷了個假秘笈，還被追著打了一頓！"},
	[76785] = {CommonPl = "先祖為金輪法王之徒，對於這龍象般若功，我倒是有些線索，至於能否習得，就要看你的佛緣了。"},
	[76786] = {CommonPl = "老夫在這衡山城多年，只為等到有緣人。"},
	[76787] = {CommonPl = "若想從我這裡得到消息，可不是那麼容易的……"},
	[76788] = {CommonPl = "唉……孽緣……孽緣啊……"},
	[76789] = {CommonPl = "若有人能找到《龍象般若功》上中下三部，我可以教他習得此功。"},
	[76912] = {CommonPl = "……"},
	[76916] = {CommonPl = "眼光四面！耳聽八方！"},
	[76923] = {CommonPl = "我要快快長大，把欺負我娘的人通通趕跑！"},
	[76926] = {CommonPl = "小蟲兒，又出去打架了？哎……"},
	[76182] = {CommonPl = "仁者不憂、知者不惑、勇者不懼，此乃君子也！"},
	[76183] = {CommonPl = "數百年風雨飄搖，我趙氏一族早已失了皇族的風采。"},
	[76994] = {CommonPl = "哎呦！別打了，我只是聽話辦事的奴才。"},
	[76184] = {CommonPl = "寺裡好無趣，真想偷偷跑出去玩。"},
	[76185] = {CommonPl = "沖哥如果有事，我也不會獨活。"},
	[76186] = {CommonPl = "昏迷中……"},
	[76187] = {CommonPl = "南無阿彌陀佛！"},
	[76188] = {CommonPl = "若不是令狐少俠相助，不死怕是真的要死了。"},
	[76189] = {CommonPl = "老祖我拼了這條命，也要把聖姑救出去。"},
	[76190] = {CommonPl = "江湖朋友都說我詭計多端，遇到聖姑她老人家，我也是無計可施啊。"},
	[76191] = {CommonPl = "醫不好人，算什麼殺人名醫！"},
	[76205] = {CommonPl = "華山派氣宗創始人岳肅埋骨於此。"},
	[76206] = {CommonPl = "能為先知大人出一份力，就算客死異鄉我也無悔。"},
	[76207] = {CommonPl = "柳先生說書的時候講了，《如來神掌》是江湖第一絕學。"},
	[76208] = {CommonPl = "此番來到中原，希望能如願尋回聖火令。"},
	[76209] = {CommonPl = "整日打打殺殺有什麼意思，不過是粗人的勾當罷了。"},
	[76210] = {CommonPl = "江湖，在我腳下！"},
	[76274] = {CommonPl = "白髮漁樵江渚上，觀看秋月春風。一壺濁酒喜相逢：古今多少事，都付笑談中。"},
	[76275] = {CommonPl = "頃刻興亡過手，說甚龍爭虎鬥。"},
	[76276] = {CommonPl = "我最佩服前任首輔張居正，和北宋相爺王安石。唯有改革，才能強國。"},
	[76277] = {CommonPl = "遙想當年，崇聖寺又名天龍寺，乃大力皇家寺院，多少國王都曾在那裡剃度為僧。"},
	[76278] = {CommonPl = "大理段氏，上承唐末亂世，中興於兩宋風流之間，歿於蒙元韃虜鐵騎之下。哼哼，大理不滅。"},
	[76279] = {CommonPl = "段公此舉，勢必荼毒百姓。"},
	[76280] = {CommonPl = "我等不可再掀起戰亂，坑害黎民。"},
	[76281] = {CommonPl = "可惜我等為人臣子，不可忤逆君意。"},
	[76282] = {CommonPl = "李……李哥，你在哪裡？你在哪裡啊？"},
	[76283] = {CommonPl = "姐，請節哀。"},
	[76284] = {CommonPl = "此地狼煙彌漫，處處藏有殺機，施主可要小心了。"},
	[76285] = {CommonPl = "姐，你難道忘了父親生前說的話？愛恨情仇本是無聊至極的東西，我們應當清心寡欲。"},
	[76286] = {CommonPl = "問世間，情為何物？直教生死相許。天南地北雙飛客，老翅幾回寒暑。歡樂趣，離別苦，就中更有癡兒女。君應有語，渺萬里層雲，千山暮雪，只影向誰去？"},
	[76287] = {CommonPl = "眼光四面！耳聽八方！"},
	[76288] = {CommonPl = "想當年，我從大食國初來中土之際，因語言不通，鬧過許多笑話。現在我的漢語很熟練，和你們漢人溝通起來就方便多了。"},
	[76289] = {CommonPl = "當年孤劍村血案，倖存者只有寥寥數人，據說玲瓏小姑娘，也尚在人間。"},
	[76290] = {CommonPl = "#N！你還記得我嗎？我是玲瓏呀。"},
	[76291] = {CommonPl = "眼光四面！耳聽八方！"},
	[76292] = {CommonPl = "我百刃幫內，各個都是英雄好漢。你若不服，可以和我們幫的高手比劃比劃。"},
	[76293] = {CommonPl = "紫白金青，四色令旗，是號令明教法王的信物。"},
	[76294] = {CommonPl = "哼，日月神教不過如此，竟然膽敢號稱中土第一聖教。"},
	[76295] = {CommonPl = "你們倒是說說，這麼一來，能引出聖女嗎？"},
	[76296] = {CommonPl = "沒有遇到那東方不敗，真是可喜……哦不，真是可惜，漢語真麻煩，還是土耳其語簡單。"},
	[76297] = {CommonPl = "胡說九道，胡說九道，我們的目的是引出聖女，不是招惹東方不敗。"},
	[76298] = {CommonPl = "常勝王就知道打架，小心成事有餘，敗事不足……啊，敗事不足，成事有餘。好像說反了？！"},
	[76299] = {CommonPl = "你們別吵了，我們還是想想應該怎麼處理這些俘虜吧。"},
	[76300] = {CommonPl = "哼！這些俘虜引出聖女？你們哪裡來的信心。"},
	[76301] = {CommonPl = "因為聖女的情人，就是日月教的人，他們一定會來救人的。"},
	[76302] = {CommonPl = "我們原本可以光明正大的幹掉東方不敗，生擒聖女的男朋友，來引出聖女。為什麼要偷偷摸摸地上黑木崖抓住這些俘虜？"},
	[76303] = {CommonPl = "因為上天有好生之德，殺人罪孽深重，還是抓人好一些。"},
	[76304] = {CommonPl = "只是可惜俱明王，被一個中土的鼠輩給殺死了。"},
	[76305] = {CommonPl = "四色旗主在此，有如明尊摩尼光佛親臨，諸法王還不速速聽我號令？"},
	[76306] = {CommonPl = "大膽聖女，還不隨我等返回鷹巢頂繼任教主，更待何時？"},
	[76307] = {CommonPl = "聖女娘娘，既然你身為聖女，就要拋開兒女私情，用一生來侍奉明尊，不可再迷戀那個阿拔斯。"},
	[76308] = {CommonPl = "來吧，騷年，戰個痛！……戰個痛快！！"},
	[76309] = {CommonPl = "如果聖女失貞，那麼只好處以火刑。"},
	[76310] = {CommonPl = "可如果燒死聖女，那誰來繼位做教主呢？"},
	[76328] = {CommonPl = "不要想那麼多，今日一定要抓她回去，如果人手不夠，本座就向蘇丹傳書，要求增派精銳馬穆魯克騎兵來增援！"},
	[76329] = {CommonPl = "啊！聖女身邊那人，不就是殺死俱明王的鼠輩嗎？"},
	[76330] = {CommonPl = "此鼠輩身手不凡，須派我們之中最強之人來對付他。"},
	[76331] = {CommonPl = "常勝王殿下——侯賽因·默罕默德，是我們奧斯曼帝國第一高手，肯定能收拾掉那鼠輩。"},
	[76332] = {CommonPl = "如果聖女失貞，那麼只好處以火刑。"},
	[76333] = {CommonPl = "我……"},
	[77166] = {CommonPl = "我虔誠地祈禱明尊的庇佑，願您的光輝照耀常勝王，賜予他無上神通，保佑他戰無不勝！"},
	[76157] = {CommonPl = "一塊斷裂的船板,鱷魚的衝撞力和咬合力太大了……"},
	[76158] = {CommonPl = "可憐的船夫，一命嗚呼了。鮮血橫流，成為了鱷魚的美食。"},
	[76159] = {CommonPl = "嗚……嗷……吭哧……鱷魚在拼命掙扎，疼痛難忍地扭動著身體。"},
	[76160] = {CommonPl = "吭哧吭哧……哼哼……"},
	[76161] = {CommonPl = "四海遨遊隨我意，天地都來一掌中。\r徒有其表、假裝瀟灑的人太多了！像周伯通那樣真灑脫的人少啊，要是我能早生幾十年，在這莽莽紅塵裡遇到他，那該多麼有趣！"},
	[76162] = {CommonPl = "慧極必傷，情深不壽；大智若愚，大巧若拙。\r能領悟種境界的人都是天縱奇材，然而慧根深藏的人哪。"},
	[77000] = {CommonPl = "我不就是誇了一句東方姑娘美豔無雙嗎，老婆啊，你不要再生氣了啊……"},
	[77003] = {CommonPl = "不是我無情心狠，而是，是時候說結束了。唯一放不下的牽掛就是儀琳啊……"},
	[77006] = {CommonPl = "這是一扇可以藏人的屏風。"},
	[77009] = {CommonPl = "該死的田伯光，壞我名聲，我一定不會善罷甘休的555555……"},
	[77012] = {CommonPl = "春風負我，女媧垂淚。"},
	[60839] = {CommonPl = "遊街來找我哦。"},
	[77615] = {CommonPl = "又到了一年一度的光棍節，夫妻組隊找我有驚喜喲~~~喲~~~喲~~~"},
	[77616] = {CommonPl = "砍砍砍，砍光天下相思竹，讓那些狗男女無處可寄相思！"},
	[77440] = {CommonPl = "什麼曲危樓，不知不知，趕緊避開，休要我喊人來驅趕你才走！\r^4a766e一臉嫌棄的唾了口痰"},
	[77441] = {CommonPl = "看你裡裡外外轉了好幾圈，不是來吃飯的吧？\r有什麼買賣？\r只管告訴我，我可以帶你去見我們掌櫃的。"},
	[77442] = {CommonPl = "這客棧裡面是進不去了，客官您來坐這邊，我們這裡什麼好東吃的都有，天上飛的地上爬的水裡遊的，只有你想不到，沒有你吃不到！\r別說什麼龍肉，就是人肉想吃立刻就有！"},
	[77443] = {CommonPl = "客棧今日歇業，內部搞裝修，客官您坐外面吧。"},
	[77444] = {CommonPl = "我可不知道什麼風夜笛，那都是掌櫃的幹的，要問去問她，別來難為我們打下手的。"},
	[77445] = {CommonPl = "我們掌櫃的長得那可是國色天香啊呵呵，不然也不會讓那曲家小子迷得神魂顛倒。"},
	[77446] = {CommonPl = "什麼？\r不知道！不知道！\r聽清楚了！這裡只有吃飯住店，可沒什麼危樓高樓的，再多問小心你的腦袋！"},
	[77447] = {CommonPl = "這酒菜備好多時了，那位大人不知什麼時候才來。"},
	[77449] = {CommonPl = "走開走開！別擋了老子的路！"},
	[77450] = {CommonPl = "嵩山派緝拿兇手，閒人回避！"},
	[77451] = {CommonPl = "左挺這小子，自己學藝不精就跑出來招惹是非，才落得現在客死他鄉的下場，唉……左家之不幸……\r左冷禪讓我來福州追查左挺的死因，我定要查出兇手，將之碎屍萬段！\r不過先讓弟子們到處尋訪尋訪，我先好好喝幾壺酒。\r說到喝酒，我只喝福州慕溢非的私房酒，哈哈哈。"},
	[77452] = {CommonPl = "我家的酒，可不對外賣，除非你有嵩山派的字條。"},
	[77043] = {CommonPl = "咱家的菜遠近聞名，客人您裡邊請。"},
	[77046] = {CommonPl = "咱丐幫沒別的好處，就是人多，有事您說話。"},
	[77052] = {CommonPl = "自從逃離梅莊，一切都好，就是做菜要自己置辦材料，真是麻煩。"},
	[77049] = {CommonPl = "來來來，咱這兒什麼都有。"},
	[77055] = {CommonPl = "好膽色！老夫交了你這個朋友！"},
	[77058] = {CommonPl = "哈哈哈，這東方不敗上了老夫的當，練什麼葵花寶典，成為千古笑話。"},
	[77061] = {CommonPl = "^O003各有因緣莫羨人^O000，緣之一事，切莫強求！"},
	[77064] = {CommonPl = "最恨那些亂起八糟的門派了，不是因為聖姑一句話誰管他們死活。"},
	[77067] = {CommonPl = "若是大家的服食的神丹有問題，我等命不久矣！"},
	[77453] = {CommonPl = "若人心皆向善，這世間便不再需要什麼管束與法律。\r若我心為淨，又何苦去可以在乎什麼女色葷食。"},
	[77454] = {CommonPl = "虛空師父做的糯米糍，是小夏最愛吃的點心！"},
	[77930] = {CommonPl = "阿彌陀佛，《九陰真經》乃歷代掌門親傳至寶，尋不回的話，貧尼無顏面對九泉下的郭襄祖師。"},
	[77931] = {CommonPl = "那些黑衣人偷偷摸摸的，一定不是什麼好人。"},
	[77932] = {CommonPl = "不要覬覦我們的商品，否則我們和你拼刀子。"},
	[77933] = {CommonPl = "人都說我的詩吟的好吟的妙，不如你聽聽看？兩情若是久長時，一枝紅杏出牆來……"},
	[77934] = {CommonPl = "聽說有人敢冒充我聖教教徒，在此作惡。直娘賊！老子要除掉這些雜碎。"},
	[77935] = {CommonPl = "嘿嘿，你看我名字就叫做老實，那麼我一定很老實，不會騙人的。"},
	[77936] = {CommonPl = "被騙了，大家都被壞人騙了。"},
	[77937] = {CommonPl = "我是這裡的老村長，聽一位算命先生說，多年後有一種酒也會叫老村長，也不知道是真還是假。"},
	[77938] = {CommonPl = "為了取回《九陰真經》，峨嵋派出數位一流高手，只是峨嵋山防守薄弱了些，所以須儘快拿回真經，返回峨嵋。"},
	[77939] = {CommonPl = "據貧尼觀察，這劍門關乃是邪教聚眾之處，處處佈滿殺機，還請施主小心。"},
	[77940] = {CommonPl = "快放了我，不然聖火將燃盡你們罪惡的身軀和靈魂！"},
	[77941] = {CommonPl = "白蓮教與我聖教在很多年前就發生過爭執，沒想到他們居然如此下作，冒充我教汙我聖教聲譽。"},
	[77942] = {CommonPl = "對付這種邪魔，應當長驅直入，不給他們喘息的時間。"},
	[77943] = {CommonPl = "豈不聞“山中無老虎，猴子稱大王。”此間的猴子，竟然佔了山頭，當起了山大王！"},
	[77944] = {CommonPl = "逃難逃的，連祖傳的家當都丟了，你說這日子可怎麼過啊？"},
	[77945] = {CommonPl = "那些狗好凶，東東怕怕~"},
	[77946] = {CommonPl = "這些路霸，還有沒有王法了?誤了時辰，就沒辦法採到最好的藥材了。"},
	[77947] = {CommonPl = "這是無生聖母的雕像。"},
	[77948] = {CommonPl = "嗚嗚嗚，我要被殺了嗎？我沒還娶媳婦呢。"},
	[78871] = {CommonPl = "被騙了，大家都被壞人騙了。"},
	[78872] = {CommonPl = "被騙了，大家都被壞人騙了。"},
	[78643] = {CommonPl = "聖火究竟在不在西安城內？看來只有和秦靖王當面說清楚了！"},
	[78644] = {CommonPl = "怪事連連，秦兵身上怎會有白蓮教教義？難道……秦王已和白蓮教勾結？"},
	[78645] = {CommonPl = "原來這一切都是白蓮教搞的鬼！我日月神教和秦軍聯手，定能輕鬆滅掉白蓮教，取回明教聖火！"},
	[78646] = {CommonPl = "白蓮教竟然打著無生老母的旗號，蠱惑民眾。我看他們是不想活了，就這樣的貨色，也想和我日月神教爭正統，我倒要看看，他們有什麼本事能夠守住聖火，哼！"},
	[78647] = {CommonPl = "白蓮教竟然打著無生老母的旗號，蠱惑民眾。我看他們是不想活了，就這樣的貨色，也想和我日月神教爭正統，我倒要看看，他們有什麼本事能夠守住聖火，哼！"},
	[78648] = {CommonPl = "白蓮教竟然打著無生老母的旗號，蠱惑民眾。我看他們是不想活了，就這樣的貨色，也想和我日月神教爭正統，我倒要看看，他們有什麼本事能夠守住聖火，哼！"},
	[78649] = {CommonPl = "白蓮教竟然打著無生老母的旗號，蠱惑民眾。我看他們是不想活了，就這樣的貨色，也想和我日月神教爭正統，我倒要看看，他們有什麼本事能夠守住聖火，哼！"},
	[78650] = {CommonPl = "白蓮教竟然打著無生老母的旗號，蠱惑民眾。我看他們是不想活了，就這樣的貨色，也想和我日月神教爭正統，我倒要看看，他們有什麼本事能夠守住聖火，哼！"},
	[78651] = {CommonPl = "雪千尋自作自受，終有一敗，就由你去結束她的瘋狂念頭吧!"},
	[78652] = {CommonPl = "結束了，一切都結束了。每一次爭鬥，都是血流成河，踩著屍體到達江湖之巔的神教啊……我回去之後，一定要肅清這些宵小敗類，查清楚雪千尋是什麼來頭，竟能成這樣的氣候！如果是內奸作祟，呵！"},
	[78653] = {CommonPl = "聖姑親自帶隊，此行我們必能取得明教聖火！讓白蓮教一見到我日月神教，就磕頭求饒！"},
	[78654] = {CommonPl = "阿彌陀佛……"},
	[78655] = {CommonPl = "白蓮教一向囂張，這次我們日月神教出兵，誓要打的白蓮教抬不起頭來！看他們日後還敢不敢囂張！"},
	[78656] = {CommonPl = "犯我西安者，斬！"},
	[78657] = {CommonPl = "地獄的業火，終將熄滅。希望此劫一過，我的軍隊和子民都能夠振作起來。"},
	[78658] = {CommonPl = "黃天將死，蒼天將生。真空家鄉，生無父母。白蓮下凡，萬民翻身。無生老母，佛法無邊。光復明宗，一統江湖！"},
	[78659] = {CommonPl = "我一定要殺出一條血路，為家人報仇！"},
	[78660] = {CommonPl = "救……救人……"},
	[78667] = {CommonPl = "大雁塔包磚加固就快完成了，師兄們卻被這些秦王的軍隊殺害，佛祖，為什麼會這樣！？"},
	[78668] = {CommonPl = "跟何兄一同回來，就像在熟悉的地方走一走看一看，尋找兒時的回憶。卻被這些亂七八糟的事壞了心情。"},
	[78669] = {CommonPl = "保衛西安！"},
	[78670] = {CommonPl = "將軍派我來此，擾亂叛軍後方，好讓大軍抓準時機衝出城外剿殺敵匪！"},
	[78671] = {CommonPl = "秦娥夢斷秦樓月\r秦樓月\r年年柳色\r灞陵傷別\r樂遊原上清秋節\r咸陽古道音塵絕\r音塵絕\r西風殘照\r漢家陵闕"},
	[78672] = {CommonPl = "寺好因崗勢，登臨值夕陽\r青山當佛閣，紅葉滿僧廊\r竹色連平地，蟲聲在上方\r最憐東面靜，為近楚城牆"},
	[78673] = {CommonPl = "……"},
	[78674] = {CommonPl = "戰事連連，士兵傷亡慘重，我要多備些藥材，以備不時之需。"},
	[78675] = {CommonPl = "子曰，人不犯我，我不犯人；人若犯我，禮讓三分；人再犯我，我還一針；人還犯我，斬草除根。"},
	[78676] = {CommonPl = "“想要”和“得到”，中間還有2個字，是“做到”。"},
	[78677] = {CommonPl = "江湖險惡，不行就撤；若沒撤成，回來找我！"},
	[78678] = {CommonPl = "世上無數丹青手，一片傷心畫不成。"},
	[78679] = {CommonPl = "我是我們村兒跑的最快的，誰也追不到我。"},
	[78680] = {CommonPl = "每個人心中都有一個屬於自己的江湖。"},
	[78681] = {CommonPl = "琴音可入心，使人明心靜氣。"},
	[78682] = {CommonPl = "……"},
	[78683] = {CommonPl = "長相思，在長安\r絡緯秋啼金井闌，微霜淒淒簟色寒\r孤燈不明思欲絕，卷幃望月空長歎\r美人如花隔雲端\r上有青冥之長天，下有淥水之波瀾\r天長地遠魂飛苦，夢魂不到關山難\r長相思，摧心肝"},
	[78684] = {CommonPl = "淤泥源自混沌啟，白蓮一現盛世舉！"},
	[78685] = {CommonPl = "舉目見日，不見長安。"},
	[78686] = {CommonPl = "腹中甚是饑餓，待解決了這些縱火份子，再去好好喋一碗臊子面！"},
	[78687] = {CommonPl = "小哥我乃是全真派丹陽子坐下大弟子，豈容的你們這些妖魔鬼怪橫行！\r今日，我定要為死去的師兄師弟們報仇！"},
	[78688] = {CommonPl = "終南山下\r活死人墓\r神鵰俠侶\r絕跡江湖"},
	[78689] = {CommonPl = "咕咕~咕咕~"},
	[78690] = {CommonPl = "都怪我學藝不精……若不是我學藝不精，也不會被白蓮教抓到這來助紂為虐了。也不知藍教主會不會來救我……"},
	[78691] = {CommonPl = "西風多少恨，吹不散眉彎。曾經，我用一腔熱情，與之凝望繾綣，而今只剩雨雪瀟瀟，草木凋零，誓言，在世人鄙夷的目光中漸漸枯黃。"},
	[78692] = {CommonPl = "愛如風過耳，抓不住也就過去了。可我永遠都會記住朝雲公主第一次見我時，向我投來的那個眼神，那時候她笑著說：“原來你也會臉紅，我還以為你是畫中人呢。”其實，她才是那個翩翩而至的畫中人……"},
	[78693] = {CommonPl = "年輕的時候總想著要出去闖蕩一番，想著外面廣闊的天地，浩蕩的江湖，想著名利場上滾一圈，武林大會過幾招，想著名動天下，笑傲群豪……我的野心和願望都一一實現，然而，茶涼花落後，終於明白，昨日今朝，猶如舊夢，你若離去，後會無期。"},
	[78694] = {CommonPl = "我仿佛聽到了死亡的聲音……然而我不怕，我並沒有丟掉紅貨，沒有砸了長安鏢局的招牌，我……雖死猶榮……"},
	[78695] = {CommonPl = "我是繾綣天涯客，流光飛度幾回眸。欲邀秋風共一飲，明月何時照君還？"},
	[78696] = {CommonPl = "風裡來，雨裡去，踏遍萬水千山。再逢明月照九州，不知何處是心鄉……"},
	[78697] = {CommonPl = "老身閨名冷夢涵，也曾是宮中轟動一時的“四大人氣宮女”之一，而今卻人老珠黃，遠嫁他鄉，真是造化弄人喲！"},
	[78698] = {CommonPl = "大膽賤人，竟然衝撞本宮鳳駕，來人啊，拖下去，賜一丈紅！"},
	[78699] = {CommonPl = "風達殘枝夜雨涼\r天遠雲深半月藏\r掩卷尋至流香處\r倚仗笑看菊花牆\r兄弟我翻山涉水走遍半個江山，為的就是看遍這天下之古跡啊，哈哈"},
	[78700] = {CommonPl = "浮生半世，游走於這殘陽古道之上，卻從未找到個歸宿。"},
	[78701] = {CommonPl = "熱騰騰香噴噴的鍋盔牙子！\r剛出鍋的鍋盔牙子！"},
	[77651] = {CommonPl = "……"},
	[77654] = {CommonPl = "又見面了。"},
	[77657] = {CommonPl = "不用替她擔心，以她的實力足以擊退這些只會三腳功夫的傢伙。"},
	[77660] = {CommonPl = "我一定要讓他們說出余滄海這狗賊的下落！我要讓他們全都生不如死！！"},
	[77666] = {CommonPl = "呵呵呵……"},
	[77669] = {CommonPl = "這就是命運的力量嗎？果真是可怕至極。"},
	[77672] = {CommonPl = "呵呵，怎麼？不認識我了？"},
	[77675] = {CommonPl = "幹得不錯。"},
	[77678] = {CommonPl = "哎呦，看不出你也有點本事。"},
	[77681] = {CommonPl = "你跑得可真慢，我已經等了好些時候了。"},
	[77684] = {CommonPl = "終於，呵呵呵，今天既是我報仇雪恨的大好時機！"},
	[77690] = {CommonPl = "快來助我！！"},
	[77693] = {CommonPl = "這……這太可怕了！簡直是人間地獄！究竟是誰做出如此過分之事？！"},
	[77696] = {CommonPl = "……方才看到那種景象，我現在心裡還壓著一口氣，上不來下不去的。"},
	[77699] = {CommonPl = "竟然是他……不，我不接受！\r這其中定有內情，我不相信他會是做出這種殘忍之事的人！"},
	[77702] = {CommonPl = "復仇對於他來說真的就這麼重要嗎？既然如此，我便助他！"},
	[77705] = {CommonPl = "平弟這是怎麼了！莫要嚇我！"},
	[77708] = {CommonPl = "不，這不是我的錯，這不是我的錯！！"},
	[77711] = {CommonPl = "再看小心爺爺我戳瞎你的眼！"},
	[77714] = {CommonPl = "今天貧道便要帶走師兄遺物，看誰敢攔著！"},
	[78004] = {CommonPl = "可憐我那苦命的孩兒。"},
	[78016] = {CommonPl = "天下沒有不要錢的午餐，想吃是要付出代價的。"},
	[78019] = {CommonPl = "我辛辛苦苦種這些枇杷，就這樣被這群頑猴給糟蹋！我不甘心！"},
	[78022] = {CommonPl = "好可怕！太可怕了！！那個人沖進來見人就砍，到處都是血，到處都是。"},
	[78026] = {CommonPl = "哎……誰又願意做那千夫所指的罪人呢。"},
	[78029] = {CommonPl = "……"},
	[76466] = {CommonPl = "洪七公之墓"},
	[76469] = {CommonPl = "歐陽鋒之墓"},
	[76499] = {CommonPl = "當你擊敗神雕後代後，需要湊集一百枚龍幣，我才能傳授你《大海無量》神功！"},
	[77764] = {CommonPl = "墓中迷局，需調查破疑。"},
	[77765] = {CommonPl = "看上去應該和其它物品有關聯。"},
