	[77582] = {CommonPl = "以前我吃的是摸金的飯，什麼樣的怪事我沒遇到過。我三十五歲時發誓，要是讓我發一筆大的，打死我都不再進死人待的地方。人心不足蛇吞象，這幾年做什麼虧什麼，哪怕不進墓，我也得和這些死人玩意兒打交道，所以只有重抄舊業，你要找到什麼新鮮玩意，儘管帶來找我便是。"},
	[77717] = {CommonPl = "……"},
	[77720] = {CommonPl = "……"},
	[79767] = {CommonPl = "對付活著人你可以有很多辦法，對付死人唯一的辦法就是膽子夠大。尤其當對手就在你身邊。江橫舟就是我的對手，從小到大，我們兩家就愛比來比去，結果在地宮互相救過對方幾次之後，我們的關係也變得微妙起來。"},
	[79770] = {CommonPl = "沒想到慈恩寺千年古刹，竟被秦王派人圍剿，這究竟時發生了什麼事。"},
	[80182] = {CommonPl = "洛水決堤，看來是供奉不足，洛神娘娘發怒了啊。"},
	[80183] = {CommonPl = "天下河山秀麗，徐某若能在有生之年盡覽美景，那也不枉此生了。"},
	[80184] = {CommonPl = "說什麼大宗師，不過是虛名而已，哪及得養生主師叔，高我一輩卻逆增長成了孩童模樣。那才是真正的返璞歸真。"},
	[80185] = {CommonPl = "振衣千仞崗，濯足萬里流。矗立在這高峰之上，享受這山風拂面之趣，快哉快哉，這才是神仙一樣的生活。"},
	[80375] = {CommonPl = "夫君死了，剩我一人度日如年，幸好村長經常幫助我、鼓勵我，不然我真不知如何生活下去。"},
	[78667] = {CommonPl = "阿米豆腐……"},
	[78600] = {CommonPl = "……"},
	[80982] = {CommonPl = "我的母親討厭我，我的父親拋棄我，無歡啊無歡，你真是一個有意思的人。"},
	[80985] = {CommonPl = "從前的錯誤，我再不會犯了。無歡，和為父回家吧！"},
	[80925] = {CommonPl = "什麼五嶽劍派，破事真多，你們聽清楚了，我沒興趣搞清你們是劍宗還是氣宗，也沒興趣管華山派掌門是誰，更沒興趣知道五嶽盟主是不是還在尿炕。都給我離遠點，別自討苦吃!"},
	[80926] = {CommonPl = "算起來，還有十四分貨款沒有要到啊……唉……\r成兒娘，都是我沒用……"},
	[80927] = {CommonPl = "衡山城的布匹又漲價了，成兒他爹的貨款又還有那麼多沒有要到，這樣下去可如何是好……"},
	[80928] = {CommonPl = "娘說，等到杜鵑花再開，我就能上學啦~"},
	[80929] = {CommonPl = "我們這裡有好多好多漂亮的衣服~"},
	[80930] = {CommonPl = "那群龜蛋，我藏的這麼偏僻都能被他們找到！\r喂，你又是來幹嘛的！？"},
	[80931] = {CommonPl = "衡山書院，歷史悠久，師資雄厚，是遠近聞名的省級重點書院。\r歡迎各位莘莘學子前來就學，美好前程，從衡山書院開始！"},
	[80336] = {CommonPl = "寶貝，寶貝，好多寶貝！哈哈哈，這輩子不用愁了。"},
	[80337] = {CommonPl = "這麼多寶物，被人搶走怎麼辦。壓力，好大壓力。"},
	[80145] = {CommonPl = "大爺，給點錢糊口飯吃吧。"},
	[80146] = {CommonPl = "什麼心有靈犀一點通，呵呵……笑死人了。"},
	[80147] = {CommonPl = "哎……"},
	[80149] = {CommonPl = "……"},
	[78667] = {CommonPl = "師，師父不知道在哪，寺裡寺外都找不到他……"},
	[81107] = {CommonPl = "近來白蓮教反叛，秦王有令，為避免叛軍混入城中，一切閒雜人等不得入城！"},
	[81546] = {CommonPl = "以殺止殺，可殺？可殺。"},
	[81561] = {CommonPl = "犯我境者，必誅！"},
	[82861] = {CommonPl = "快來兌換銅錢吧！等我走了可就來不及了！"},
	[82837] = {CommonPl = "年貨快遞，年貨快遞。全國三日送達。"},
	[82730] = {CommonPl = "過年啦，哈哈哈。我覺得我就是中國的聖誕老人，別人過節我發獎，我是大好人。年夜飯一天一共可以開四場喲。"},
	[82731] = {CommonPl = "阿彌陀佛，新年好。"},
	[82732] = {CommonPl = "無量天尊，施主新年好。"},
	[82733] = {CommonPl = "新年好，馬年吉祥。"},
	[82734] = {CommonPl = "癸巳變甲午，整一百二十年啦。"},
	[82735] = {CommonPl = "馬到成功，新年好。"},
	[82736] = {CommonPl = "年來啦，明年一定紅紅火火。"},
	[82737] = {CommonPl = "新年好啊。"},
	[82738] = {CommonPl = "哈哈哈哈哈哈，過年好開心。"},
	[82739] = {CommonPl = "一曲胡琴繞梁，天下幸福安康。"},
	[82740] = {CommonPl = "貧尼祝施主馬年吉祥。"},
	[82741] = {CommonPl = "喜氣洋洋，喜上眉梢。"},
	[82742] = {CommonPl = "慶天慶地慶我慶你，新年好。"},
	[82743] = {CommonPl = "福壽綿長，新年吉祥。"},
	[82744] = {CommonPl = "祥瑞遍地，馬年大吉。"},
	[82833] = {CommonPl = "買年貨咯，快來買年貨咯。"},
	[82834] = {CommonPl = "買年貨咯，快來買年貨咯。"},
	[82835] = {CommonPl = "買年貨咯，快來買年貨咯。"},
	[82836] = {CommonPl = "買年貨咯，快來買年貨咯。"},
	[82837] = {CommonPl = "年迪速遞，最是貼心。"},
	[83476] = {CommonPl = "馬上要過年了，年貨還沒著落呢。好心急。"},
	[83477] = {CommonPl = "年夜飯一天一共可以開四場喲。"},
	[83478] = {CommonPl = "收集玫瑰花種，交給我，我可以幫忙培育出玫瑰花束哦！"},
	[83903] = {CommonPl = "白蓮教野心不小，看來斬草要除根，免得日後滋生事端。"},
	[83904] = {CommonPl = "白蓮教在基地培養了很多殺手，看來是想要東山再起。"},
	[83905] = {CommonPl = "白蓮教總壇甚是兇險，教眾可千萬小心。"},
	[83906] = {CommonPl = "白蓮教餘孽看趁著崆峒派的人出門辦事，躲入崆峒派，還打傷崆峒派弟子，真是用心險惡。"},
	[83910] = {CommonPl = "白蓮教，哼，我定要踏平你們的平涼總部！"},
	[83911] = {CommonPl = "白蓮教用心險惡，如若不除根，將來必有後患！"},
	[83913] = {CommonPl = "摧毀訓練基地，殺個片甲不留！"},
	[83915] = {CommonPl = "踏平白蓮教總壇，讓他們再也無法站起來！"},
	[83917] = {CommonPl = "平涼鎮雖然人丁不多，但團結友愛。吾深感欣慰。"},
	[83918] = {CommonPl = "書中自有黃金屋，書上的道理，我一生也學不完。"},
	[83919] = {CommonPl = "救我……救救我……"},
	[83920] = {CommonPl = "白蓮重生，東山再起。聖火歸兮，日月隕落！"},
	[83922] = {CommonPl = "白蓮教手段真是陰毒！"},
	[83923] = {CommonPl = "唉，松雲道人很久沒來我這做客了呢。"},
	[83924] = {CommonPl = "月娥，月娥，你像天上的月亮一樣美。"},
	[83925] = {CommonPl = "村子裡的人都好熱心呢！"},
	[83926] = {CommonPl = "手中的筆，就是我的兵器！"},
	[83927] = {CommonPl = "你還記得那年的家書嗎？"},
	[83928] = {CommonPl = "唉，陳亦然很久沒來我這做客了呢。"},
	[84383] = {CommonPl = "大軍出征，茲事體大，真是如履薄冰、步步驚心。"},
	[84386] = {CommonPl = "兄弟們平常吃好的、喝好的，關鍵時刻哪有不拼命的道理。"},
	[84389] = {CommonPl = "眾多兄弟戰死，讓我如何向他們的父母妻兒交代。"},
	[84392] = {CommonPl = "狼群來了以後，野豬、黃羊之類的動物都不見了，打不到獵物讓我如何生活。"},
	[84395] = {CommonPl = "大家都死了，留下我這條老命又有何用！"},
	[84398] = {CommonPl = "不做這守城官以後，我一定要帶著兄弟們出關去獵幾隻黃羊打牙祭。"},
	[84401] = {CommonPl = "您看我的打扮，我的長相，分明是一個大大的良民。"},
	[84404] = {CommonPl = "……"},
	[84407] = {CommonPl = "韃靼害死這麼多人，難道不怕遭報應嗎！"},
	[84410] = {CommonPl = "我算過了，這樣苟且偷生，不如殺幾個再死合算。"},
	[84413] = {CommonPl = "噓！噤聲！前往就是薩滿武士的地盤了。"},
	[84416] = {CommonPl = "這種豬狗不如的日子，我過夠了。"},
	[84419] = {CommonPl = "大仇得報，心情真是暢快。"},
	[84422] = {CommonPl = "薩滿巫師們神神叨叨，似乎精神不是很正常啊。"},
	[84425] = {CommonPl = "這窮山僻壤的鬼地方，沒的吃，沒的喝，沒的玩，悶死人了。"},
	[84428] = {CommonPl = "深入草原腹地以後才知道，蒙古人已經倡狂到這種程度了。"},
	[84431] = {CommonPl = "要是會變戲法就好了，動動手就能變出東西。"},
	[84785] = {CommonPl = "想知道去其他地方的快捷方式麼？"},
	[84674] = {CommonPl = "白蓮教真是不作就不會死啊！"},
	[84684] = {CommonPl = "我奉教主之命前來肅清假借他的名義在龍門客棧作威作福的人！"},
	[84266] = {CommonPl = "你乃大龍門客棧頭號探子，馬三才是也。"},
	[84269] = {CommonPl = "這群人以為天高皇帝遠，我日月神教就管不了了嗎？哼，教主派我和楊爺來，是對我的重視。"},
