	[84344] = {CommonPl = "出門不利，出門不利呀……"},
	[84347] = {CommonPl = "樂正七那小子離開多時了，也不知道他是不是安全地把貨物送到了。"},
	[84350] = {CommonPl = "救……救救我，嗚嗚嗚嗚嗚……"},
	[84353] = {CommonPl = "不……不要丟下我一個人……"},
	[84356] = {CommonPl = "好不容易逃了出來，再不能讓那淫僧抓住了。"},
	[84359] = {CommonPl = "我相信爹娘只是迷路了，他們總有一天會回來的……"},
	[84362] = {CommonPl = "這個秘密你要替我保守，不要告訴果果哦。"},
	[84365] = {CommonPl = "我是沙漠之王，是這片沙漠的主宰。可人總有老去的一天，我希望我的兒子能延續我的輝煌。"},
	[84368] = {CommonPl = "老子的盜賊團天下第一，不服來戰！"},
	[84371] = {CommonPl = "大家好，我是人見人愛的江湖賞金榜。是不是覺得我有點眼熟呀，是的，藥王谷有我的兄弟在。跟著我們兄弟混，有肉吃！"},
	[84374] = {CommonPl = "看來今日我要葬身於此了。"},
	[84377] = {CommonPl = "相公怎麼還不回來呀……"},
	[84380] = {CommonPl = "地獄不空，誓不成佛；度盡眾生，方證菩提。"},
	[86763] = {CommonPl = "縮骨功和芙蓉心經，是我維持童顏不老的秘笈，可它們也給我招來了禍事……"},
	[86767] = {CommonPl = "李時珍是我的偶像，他老人家出版的《本草綱目》我已經熟讀100遍啦！"},
	[86790] = {CommonPl = "情始起末，時止刹那。柳折芳宛，梅遺幽庵。生或亦死，死亦可生。四夢似醒，圓終茗堂！"},
	[86368] = {CommonPl = "天下之會，傲視群雄；盟主一出，誰與爭鋒。此乃天下會打造的“武林盟主”專屬雕像，寓意“統領天下，群雄歸心”，供江湖各路人士瞻仰叩拜！"},
	[87541] = {CommonPl = "海闊任我躍！天高任我飛！"},
	[87544] = {CommonPl = "我一定會闖出一片天地！去發現新大陸！"},
	[87545] = {CommonPl = "咦……那航海通行證究竟掉到哪裡去了？我記得……我只是去了趟衡山郊外，給三娘子送酒……\r（航海通行證或許被衡山郊外的某個怪物搶走了，去那裡找找看）"},
	[87546] = {CommonPl = "金樽清酒鬥十千，玉盤珍羞直萬錢！"},
	[87547] = {CommonPl = "大海很美，卻也很危險……"},
	[87548] = {CommonPl = "這鄭成真是古靈精怪，但是留他在身邊，又有違我當年發下的重誓……這可如何是好……"},
	[87551] = {CommonPl = "夢該醒了……"},
	[87553] = {CommonPl = "權利、金錢、美人……我得到了我想要的一切！可我卻不快樂……"},
	[87557] = {CommonPl = "嘖嘖……聽說這新郎官只是個鄉下來的窮小子，怎麼這麼好福氣，能夠迎娶郡主呢？"},
	[87558] = {CommonPl = "好看好看！婚禮現場最好看了！"},
