	[88580] = {CommonPl = "我始終覺得神器圖紙是一場陰謀，但人人趨之若鶩。這樣人云亦云的江湖也是醉了。"},
	[88581] = {CommonPl = "我始終覺得神器圖紙是一場陰謀，但人人趨之若鶩。這樣人云亦云的江湖也是醉了。"},
	[88582] = {CommonPl = "我始終覺得神器圖紙是一場陰謀，但人人趨之若鶩。這樣人云亦云的江湖也是醉了。"},
	[89226] = {CommonPl = "我和小梨本該在一個山清水秀的地方撫琴對飲，不知東方姑娘讓我們回來教一個小孩是為何故。\r^0000FF(原商店已移至獨孤門派基地相關NPC)"},
	[89227] = {CommonPl = "你知道什麼是世外高人嗎？別看白夜一臉蠢像，其實他也算是了。\r^0000FF(原商店已移至獨孤門派基地相關NPC)"},
	[89228] = {CommonPl = "我老婆的詩自然是天下第一的。"},
	[89229] = {CommonPl = "仗劍江湖行，情義腰間系。\r拂袖不平事，回眸煙波起。\r風過楊柳岸，晨露沾我衣。\r縱無青鋒劍，亦有通靈筆。\r知音一張琴，杯底風流戲。\r秉燭話西窗，悠然何所擬？\r……我學會作詩了耶！誰說我只會打打殺殺，我學會作詩了！誰敢說我的詩不好，我讓我相公殺了他！"},
	[89230] = {CommonPl = "我奉東方姑娘之命，帶你看清世間的險惡。"},
	[89262] = {CommonPl = "……唉，想這恒山十大門派之一,當年號令江湖何等輝煌令人豔羨,如今卻只剩下斷壁殘垣,可見世事變幻難以預料"},
	[89393] = {CommonPl = "這個絲帕應該是與兇手有關，但我這次真的孤陋寡聞了，不知道這東西的來歷"},
	[89394] = {CommonPl = "既然這樣，#N，我們還是接著上去看看吧"},
	[89263] = {CommonPl = "站住！恒山重地，來者止步！再不停下休怪我不客氣了！"},
	[89264] = {CommonPl = "我每每回憶起當日恒山那一幕，都感到刻骨銘心的恨意"},
	[89265] = {CommonPl = "#N，多謝你對恒山眾人的心意，相信她們在天之靈一定能得到安慰。那天山無名客一門滅門一事的確是多有蹊蹺，我這段時間多方尋訪，懷疑與恒山派藏有太昊武器圖紙的江湖傳言有關，必是有人起了貪念，從中挑撥，妄圖得到圖紙，才引得恒山遭此劫難……"},
	[89148] = {CommonPl = "樹欲靜，而風不止。"},
	[3828] = {CommonPl = "樹欲靜，而風不止。"},
	[89415] = {CommonPl = "樹欲靜，而風不止。"},
	[89848] = {CommonPl = "老夫在寨中活了大半輩子，如今都快入土了卻落得個無家可歸。\r少俠，幫我們懲治下那些強盜吧。"},
	[89854] = {CommonPl = "飲酒須得講究酒具，喝什麼酒就該用什麼酒具。這幾日釀好酒後，老夫便去尋些上好的酒杯。"},
	[90064] = {CommonPl = "一個好漢三個幫！這蒙古草原的事情嘛，你想摸得一清二楚，那可少不了我梁仁邦！"},
	[90065] = {CommonPl = "一個好漢三個幫！這蒙古草原的事情嘛，你想摸得一清二楚，那可少不了我梁仁邦！"},
	[90066] = {CommonPl = "哪裡有八卦，哪裡就有我的蹤影！"},
	[90067] = {CommonPl = "我的夢想，就是取代三思，成為老大的心腹！"},
	[90068] = {CommonPl = "心腹是那麼好當的麼！上得廳堂下得廚房只是最基本的要求！"},
	[90069] = {CommonPl = "我是一隻小小小小鳥。"},
