	[98050] = {CommonPl = "這玲瓏派冷冷清清的，什麼時候才能去外面看一看。"},
	[98051] = {CommonPl = "昆侖山那麼高，我的孔明燈不知道能不能飛過去……"},
	[98052] = {CommonPl = "山外的世界是什麼樣的啊，雪珊也想像大師姐一樣下山看看啊……"},
	[98053] = {CommonPl = "所有傷害過玲瓏派的人，都要付出代價！"},
	[98149] = {CommonPl = "你知道失去的滋味嗎？我會讓你知道的！哈哈哈"},
	[98150] = {CommonPl = "你知道失去的滋味嗎？我會讓你知道的！哈哈哈"},
	[98264] = {CommonPl = "雪竹雪竹，我為他栽得竹子，他卻看不到了……"},
	[98056] = {CommonPl = "天網恢恢，疏而不漏。"},
	[98057] = {CommonPl = "只有你付不出的代價，沒有我不知道的秘密。"},
	[98058] = {CommonPl = "收銀子我來，送死你去。"},
	[98059] = {CommonPl = "要去昆侖山，就來找我喲。"},
	[98060] = {CommonPl = "要去昆侖山，就來找我喲。"},
	[98061] = {CommonPl = "阿紫不敢回家……"},
	[98062] = {CommonPl = "這些外來的江湖人，真是太兇殘了。"},
	[98063] = {CommonPl = "醫者父母心。"},
	[98064] = {CommonPl = "老子背後有靠山，你敢惹我？"},
	[98065] = {CommonPl = "如果時間可以重來，該有多好……"},
	[98066] = {CommonPl = "少俠，你長得挺俊的嘛。"},
	[98067] = {CommonPl = "此間事了，便和沖哥另覓隱居之地。"},
	[98068] = {CommonPl = "此間事了，便和沖哥另覓隱居之地。"},
	[98069] = {CommonPl = "樹欲靜，而風不止。"},
	[98070] = {CommonPl = "請聖山的仙子，能將安寧重新賜予桃源樹。"},
	[98071] = {CommonPl = "這個世道可真奇怪，這些人都上趕著送死去了……"},
	[98072] = {CommonPl = "打打殺殺有什麼意思？嘿嘿，不如我們來過兩招吧！"},
	[98073] = {CommonPl = "打打殺殺有什麼意思？嘿嘿，不如我們來過兩招吧！"},
	[98074] = {CommonPl = "天下之大，竟無處可容身……"},
	[98075] = {CommonPl = "真相只有一個，我的藏寶圖才是真的！"},
	[98076] = {CommonPl = "這個世道可真奇怪，這些人都上趕著送死去了……"},
	[98077] = {CommonPl = "這個世道可真奇怪，這些人都上趕著送死去了……"},
	[98078] = {CommonPl = "世人笑我太瘋癲，我笑他人看不穿。"},
	[98079] = {CommonPl = "世人笑我太瘋癲，我笑他人看不穿。"},
	[98080] = {CommonPl = "只要到了昆侖泉，我就有機會拿到寶藏！"},
	[98081] = {CommonPl = "只要到了昆侖泉，我就有機會拿到寶藏！"},
	[98084] = {CommonPl = "天蒼蒼，地茫茫，水邊有個女神哎。"},
	[98085] = {CommonPl = "村裡來了好多壞人，誰能趕跑他們。"},
	[98086] = {CommonPl = "造孽哦！現在這個世道！"},
	[98087] = {CommonPl = "我只是路過而已，就被打斷一條腿。"},
	[98088] = {CommonPl = "最近生意好了很多，可是我寧願沒有這麼多生意。"},
	[98089] = {CommonPl = "長得漂亮原來也是一種錯。"},
	[98090] = {CommonPl = "總有一天，我要拜入玲瓏，習得高深武功！"},
	[98091] = {CommonPl = "這些外來的江湖人，真是太可怕了。"},
	[98092] = {CommonPl = "不知道張家大郞到了沒有，真擔心他的安危哪。"},
	[98093] = {CommonPl = "回家就成親，嘿嘿。"},
	[98094] = {CommonPl = "不講江湖道義者，就該死！"},
	[98095] = {CommonPl = "何時才能還昆侖山一片安寧。"},
	[98096] = {CommonPl = "如果時間可以重來，該有多好……"},
	[98097] = {CommonPl = "大師姐出馬，一個頂倆！"},
	[98098] = {CommonPl = "有時候當官的比江湖浪子還要兇猛。"},
	[98099] = {CommonPl = "打打殺殺有什麼意思？嘿嘿，不如我們來過兩招吧！"},
	[98100] = {CommonPl = "我不怕死，只怕死得沒有價值。"},
	[98101] = {CommonPl = "皚如山上雪，皎若雲間月。"},
	[98102] = {CommonPl = "砌下落梅如雪亂，拂了一身還滿。"},
	[98103] = {CommonPl = "五月天山雪，無花只有寒。"},
	[98104] = {CommonPl = "終南陰嶺秀，積雪浮雲端。"},
	[98105] = {CommonPl = "人生如逆旅，我亦是行人。"},
	[98106] = {CommonPl = "我是誰……我來自哪裡……"},
	[98531] = {CommonPl = "昆侖山上的雪，一百年沒有融化過。"},
	[98532] = {CommonPl = "昆侖山上的雪，一百年沒有融化過。"},
	[98533] = {CommonPl = "昆侖山上的雪，一百年沒有融化過。"},
	[98534] = {CommonPl = "敵人太強了，我們抵擋不了……"},
	[98535] = {CommonPl = "已經有那麼多姐妹受傷了！"},
	[98536] = {CommonPl = "雲不劫回來了，玲瓏派就要被他毀了……"},
	[98537] = {CommonPl = "這玲瓏派冷冷清清的，什麼時候才能去外面看一看。"},
	[98538] = {CommonPl = "昆侖山那麼高，我的孔明燈不知道能不能飛過去……"},
	[98539] = {CommonPl = "山外的世界是什麼樣的啊，雪珊也想像大師姐一樣下山看看啊……"},
	[98540] = {CommonPl = "所有傷害過玲瓏派的人，都要付出代價！"},
	[98447] = {CommonPl = "有些招式早學比晚學的好。所謂拳怕少壯。我可以幫你教教這些門徒，但是我最近手頭有點緊，要多收點銀子！"},
	[98448] = {CommonPl = "招無定式，水無常型。你若是以為招式學會後一成不變那你可就錯了。我可以幫你領悟出招式中最神妙的變數，讓你的招式威力大增。"},
	[98449] = {CommonPl = "若是想習得套路或者提升技能等級，可以來我這裡學習。"},
	[98451] = {CommonPl = "昆侖山上的雪，一百年沒有融化過。"},
	[98452] = {CommonPl = "我機緣巧合下獲得了一本手劄，據說記錄者曾是幫董公養龍的使者。手劄裡記載了門徒的馴服之道。"},
	[98455] = {CommonPl = "吹氣球，吹個大氣球，氣大了氣球玩球球~"},
	[98456] = {CommonPl = "來，給你奶一口。"},
	[98541] = {CommonPl = "若論醫術，我稱第二，無人敢稱第一！"},
	[98986] = {CommonPl = "花燼繁的妻子若薇常用的傘。"},
	[98987] = {CommonPl = "去年今日此門中，人面桃花相映紅。今年春歸尋芳蹤，桃花依然笑春風。此門此景難相忘，此恨此憂空惆悵。人面不知何處去，花開花落在夢中。"},
	[98988] = {CommonPl = "去年今日此門中，人面桃花相映紅。今年春歸尋芳蹤，桃花依然笑春風。此門此景難相忘，此恨此憂空惆悵。人面不知何處去，花開花落在夢中。"},
	[98989] = {CommonPl = "去年今日此門中，人面桃花相映紅。今年春歸尋芳蹤，桃花依然笑春風。此門此景難相忘，此恨此憂空惆悵。人面不知何處去，花開花落在夢中。"},
	[98990] = {CommonPl = "去年今日此門中，人面桃花相映紅。今年春歸尋芳蹤，桃花依然笑春風。此門此景難相忘，此恨此憂空惆悵。人面不知何處去，花開花落在夢中。"},
	[2713] = {CommonPl = "既入我武當門下，自當省得道法自然。我武當注重內功心法，秉持練精為氣、練氣化神、煉神還虛、練虛合道，是為修煉之本。"},
	[2716] = {CommonPl = "武當劍法講究的是劍隨身走、剛柔並濟、身藏八卦、步踏九宮。\r若是想習得套路或者提升技能等級，可以來我這裡學習。\r"},
	[2719] = {CommonPl = "既為武當弟子，就要記得常回來看看，為門派出力。"},
	[2722] = {CommonPl = "成天操心採買的事，武功都快荒廢了。若是師父要考量我近日進境，可就麻煩了……"},
	[2725] = {CommonPl = "門派秘境乃是本門禁地，向來只對本門弟子開放。如無特例，其他閒雜人等，一律不准進入。"},
	[2728] = {CommonPl = "天下武功，無堅不摧，唯快不破。身法若高，敵人縱有千斤之力也打你不著，豈不快哉？若是想習得修身技能，可以來我這裡學習。\r"},
	[2731] = {CommonPl = "若是想習得秘笈，可以來我這裡學習。\r\r"},
	[2734] = {CommonPl = "武當山，非真武不足以當之。我們武當上奉真武大帝威靈，下秉替天行道之心，你要謹記。"},
	[2737] = {CommonPl = "招無定式，水無常型。你若是以為招式學會後一成不變那你可就錯了。我可以幫你領悟出招式中最神妙的變數，讓你的招式威力大增。"},
	[2740] = {CommonPl = "保衛武當派安全是我的使命。"},
	[2743] = {CommonPl = "保衛武當派安全是我的使命。"},
	[2746] = {CommonPl = "俗話說大劍無鋒、大巧不工。這武當玄武重劍，須用武當嫡傳太極劍法使將出來，才能行雲流水、圓轉如意。"},
	[2800] = {CommonPl = "我這裡有武當弟子常用的劍符丹藥各種物事，需要的話隨時找我。"},
	[3105] = {CommonPl = "少林寺千年古刹，宗派武學源遠流長，只是我等出家人，四大皆空、明心見性，雖以除魔衛道為己任，更應懂得佛法無邊、悲天憫人的道理。"},
	[3108] = {CommonPl = "少林武學，集內功心法、身法、拳法、掌法、指法、腿法、劍法、刀法、棍法、杖法等萬千武功之大成，可謂包羅萬象。\r若是想習得套路或者提升技能等級，可以來我這裡學習。\r"},
	[3111] = {CommonPl = "既為少林弟子，就要記得常回來看看，為門派出力。"},
	[3114] = {CommonPl = "別小看了挑水掃地，這一樣是種修煉，百十年前我少林出了位武功出神入化的神僧，就是掃地出身的！"},
	[3117] = {CommonPl = "門派秘境乃是本門禁地，向來只對本門弟子開放。如無特例，其他閒雜人等，一律不准進入。"},
	[3120] = {CommonPl = "天下武功，無堅不摧，唯快不破。身法若高，敵人縱有千斤之力也打你不著，豈不快哉？若是想習得修身技能，可以來我這裡學習。\r"},
	[3123] = {CommonPl = "近來門派事務增多，我這實在騰不出人手了，只要請同門弟子伸出援手，幫忙做些門派中的雜事。"},
	[3126] = {CommonPl = "若是想習得秘笈，可以來我這裡學習。\r\r"},
	[3129] = {CommonPl = "少林寺乃是佛門聖地，武林泰斗。前來拜入山門者與日俱增，越發認不過來了．最近好像又多了幾張新面孔。"},
	[3132] = {CommonPl = "佛門重地，嚴禁喧嘩！"},
	[3135] = {CommonPl = "深山藏古寺，禪房花木新。"},
	[3141] = {CommonPl = "招無定式，水無常型。你若是以為招式學會後一成不變那你可就錯了。我可以幫你領悟出招式中最神妙的變數，讓你的招式威力大增。"},
	[3765] = {CommonPl = "南嶽獨秀，衡山清奇。仙樂風飄，有鳳來儀。\r我衡山弟子多通音律，琴心劍膽，行盡江湖千里；彈一曲夜雨瀟湘，便可忘三世情仇。"},
	[3768] = {CommonPl = "衡山劍法講究迅捷凌厲、以萬鈞之勢制敵先機。或許你還未看到我出手，便已死了。\r若是想習得套路或者提升技能等級，可以來我這裡學習。\r"},
	[3771] = {CommonPl = "門派秘境乃是本門禁地，向來只對本門弟子開放。如無特例，其他閒雜人等，一律不准進入。"},
	[9458] = {CommonPl = "招無定式，水無常型。你若是以為招式學會後一成不變那你可就錯了。我可以幫你領悟出招式中最神妙的變數，讓你的招式威力大增。"},
	[9461] = {CommonPl = "衡山門下弟子各個多才多藝，大多精通音律，就連後勤灑掃弟子，累了也會奏一曲漁舟唱晚，陶冶性情。"},
	[9464] = {CommonPl = "天下武功，無堅不摧，唯快不破。身法若高，敵人縱有千斤之力也打你不著，豈不快哉？若是想習得修身技能，可以來我這裡學習。\r"},
	[9467] = {CommonPl = "近來門派事務增多，我這實在騰不出人手了，只要請同門弟子伸出援手，幫忙做些門派中的雜事。"},
	[9470] = {CommonPl = "若是想習得秘笈，可以來我這裡學習。\r\r"},
