	[9476] = {CommonPl = "保衛衡山派安全是我的使命。"},
	[9479] = {CommonPl = "保衛衡山派安全是我的使命。"},
	[9482] = {CommonPl = "出門在外要處處小心，時時謹記師父教導。"},
	[3774] = {CommonPl = "君子比德於玉，仁厚端方。\r所謂天地君親師，必敬之畏之，拜之祭之。"},
	[3777] = {CommonPl = "我們華山劍法，講求以氣御劍，若要練劍，先練內功。\r若是想習得套路或者提升技能等級，可以來我這裡學習。\r"},
