	[9515] = {CommonPl = "既為華山弟子，就要記得常回來看看，為門派出力。"},
	[3783] = {CommonPl = "至人無己，神人無功，聖人無名。\r欲得大自在，享大逍遙，必絕大情愛，棄大名利。\r入逍遙派，可學之物一生難以窮盡。"},
	[3786] = {CommonPl = "逍遙神功，不重練身，更重煉心。只要領悟了自在逍遙的大境界，武功進境便可一日千里。\r若是想習得套路或者提升技能等級，可以來我這裡學習。\r"},
	[3789] = {CommonPl = "門派秘境乃是本門禁地，向來只對本門弟子開放。如無特例，其他閒雜人等，一律不准進入。"},
