	[9521] = {CommonPl = "招無定式，水無常型。你若是以為招式學會後一成不變那你可就錯了。我可以幫你領悟出招式中最神妙的變數，讓你的招式威力大增。"},
	[9524] = {CommonPl = "天下武功，無堅不摧，唯快不破。身法若高，敵人縱有千斤之力也打你不著，豈不快哉？若是想習得修身技能，可以來我這裡學習。\r"},
	[9527] = {CommonPl = "近來門派事務增多，我這實在騰不出人手了，只要請同門弟子伸出援手，幫忙做些門派中的雜事。"},
	[9530] = {CommonPl = "若是想習得秘笈，可以來我這裡學習。\r\r"},
	[9533] = {CommonPl = "這裡景色真好，怎麼看都看不厭。你也要常常回來看看風景看看我哦。"},
	[9536] = {CommonPl = "保衛逍遙派安全是我的使命。"},
	[9539] = {CommonPl = "保衛逍遙派安全是我的使命。"},
	[9542] = {CommonPl = "後勤上有什麼不懂的可以問我！"},
	[9545] = {CommonPl = "門派弟子不僅需要勤學武藝，這後勤一事，也是必修課。"},
	[3792] = {CommonPl = "袖裡乾坤旱海遊，\r暗弦斷羽何所求？\r浮雲出處原無定，\r得似浮雲也自由。"},
	[3795] = {CommonPl = "總有人覺得機關之術乃是旁門左道。哼！便是左道又如何？任你武功通天，也擋不住我唐門的火器。\r若是想習得套路或者提升技能等級，可以來我這裡學習。\r"},
	[3798] = {CommonPl = "既為唐門弟子，就要記得常回來看看，為門派出力。"},
	[9548] = {CommonPl = "你若是要出門，可要記得：在這江湖上，你相信的往往是假話。我猜，也許是真話比假話難聽之故。"},
	[9551] = {CommonPl = "門派弟子不僅需要勤學武藝，這後勤一事，也是新入門弟子的必修課。"},
	[9554] = {CommonPl = "天下武功，無堅不摧，唯快不破。身法若高，敵人縱有千斤之力也打你不著，豈不快哉？若是想習得修身技能，可以來我這裡學習。\r"},
	[9557] = {CommonPl = "近來門派事務增多，我這實在騰不出人手了，只要請同門弟子伸出援手，幫忙做些門派中的雜事。"},
	[9560] = {CommonPl = "若是想習得秘笈，可以來我這裡學習。\r\r"},
	[9563] = {CommonPl = "門派秘境乃是本門禁地，向來只對本門弟子開放。如無特例，其他閒雜人等，一律不准進入。"},
	[9566] = {CommonPl = "保衛唐門安全是我的使命。"},
	[9569] = {CommonPl = "保衛唐門安全是我的使命。"},
	[9572] = {CommonPl = "後勤上有什麼不懂的可以問我！"},
	[9575] = {CommonPl = "招無定式，水無常型。你若是以為招式學會後一成不變那你可就錯了。我可以幫你領悟出招式中最神妙的變數，讓你的招式威力大增。"},
	[3801] = {CommonPl = "天下風雲出我輩，\r一入江湖歲月催。\r皇圖霸業談笑中，\r不勝人生一場醉。"},
	[3804] = {CommonPl = "我神教弟子有教主恩澤，只要對教主忠心，必定可以練到身隨意轉、刀槍不入的境界。\r若是想習得套路或者提升技能等級，可以來我這裡學習。\r"},
	[3807] = {CommonPl = "既為神教弟子，就要記得常回來看看，為門派出力。"},
