	[3810] = {CommonPl = "一樹開五花，五花八葉扶。\r皎皎娥眉月，光輝滿江湖。"},
	[3813] = {CommonPl = "與少林武當不同，峨嵋武功融匯佛道兩家之長，更具千般神奇變化。\r若是想習得套路或者提升技能等級，可以來我這裡學習。\r"},
