	[3819] = {CommonPl = "別以為我們五仙教都是絕情的女子，只是……江湖險惡，不能不防。\r只有最多情的女子，才能養出最無情的蠱毒。"},
	[3822] = {CommonPl = "五仙教以青蛇、蜘蛛、蜈蚣、蠍子、蟾蜍為五寶，本教諸多武功和奇毒，都是從這五寶身上幻化而來。\r若是想習得套路或者提升技能等級，可以來我這裡學習。\r"},
	[3825] = {CommonPl = "既為五仙弟子，就要記得常回來看看，為門派出力。"},
	[9638] = {CommonPl = "中原男人一向油滑的緊，出門在外可要留個心眼，別叫人騙去了你的心。"},
	[9641] = {CommonPl = "招無定式，水無常型。你若是以為招式學會後一成不變那你可就錯了。我可以幫你領悟出招式中最神妙的變數，讓你的招式威力大增。"},
