	[9665] = {CommonPl = "門派弟子不僅需要勤學武藝，這後勤一事，也是新入門弟子的必修課。"},
	[3828] = {CommonPl = "什麼是江湖？一個門派興起，一個門派滅亡，英雄的血，情人的淚。\r而今獨孤興起，恒山滅門，我受摯友所托，在此暫代掌門之職，只希望有一天恒山派能再度復興，重現昔日風采……"},
	[3831] = {CommonPl = "招無定式，水無常形。你若是以為招式學會後一成不變那你可就錯了。我可以幫你領悟出招式中最神妙的變數，讓你的招式威力大增。\r"},
