	[9680] = {CommonPl = "若是想習得秘笈，可以來我這裡學習。\r\r"},
	[9683] = {CommonPl = "身為恆山弟子，在江湖上行走要以本門清譽為重，不可與人妄動干戈。"},
	[9686] = {CommonPl = "保衛恆山派安全是我的使命。"},
	[9692] = {CommonPl = "哎呀哎呀……\r最近只顧練功，荒於功課，萬一師父責罰，可如何是好？"},
	[9695] = {CommonPl = "恆山劍法綿密嚴謹，長於守禦，而往往在最令人出其不意之處突出殺著，正是適於女子所使的武功。\r若是想習得套路或者提升技能等級，可以來我這裡學習。"},
	[4819] = {CommonPl = "有人求功名，有人求利祿，有人求家宅安康，有人求終成眷屬。\r你求的是什麼，你可想過？\r有人的地方，就有江湖。入得此間，老夫唯盼你能一生無悔，恣情笑傲。"},
	[11075] = {CommonPl = "師門貢獻度可以用來換取很多東西，你想換什麼？\r自己看看吧，總有你想要的。"},
	[11078] = {CommonPl = "師門貢獻度可以用來換取很多東西，你想換什麼？\r自己看看吧，總有你想要的。"},
	[11081] = {CommonPl = "師門貢獻度可以用來換取很多東西，你想換什麼？\r自己看看吧，總有你想要的。"},
