	[11099] = {CommonPl = "師門貢獻度可以用來換取很多東西，你想換什麼？\r自己看看吧，總有你想要的。"},
	[22228] = {CommonPl = "師姐，這水為什麼是倒著流的？\r"},
	[22231] = {CommonPl = "我知道！師父好像說過，什麼依天干地支，造了什麼機關，水就會逆流而上啦！"},
	[23119] = {CommonPl = "武當弟子遍佈天下，行俠仗義、鋤強扶弱乃是我輩本分。"},
	[35916] = {CommonPl = "是非憎愛世偏多，仔細思量奈我何。\r寬卻肚皮常忍辱，放開泱日暗消磨。\r若逢知己須依分，縱遇冤家也共和。\r要使此心無掛礙，自然證得六波羅。\r"},
	[35919] = {CommonPl = "師傅總說我年紀小，不准我下山，我也好想去大千世界開開眼界啊！\r#N#Y，你要去哪？回來一定記得給我講講!"},
	[61752] = {CommonPl = "日月賈布！鄙夷天下者，可入日月！"},
	[61755] = {CommonPl = "在下五仙護法，我教只收女子，負心、污濁的臭男人，是絕對不收的！"},
	[61758] = {CommonPl = "唐門暗器，天下無雙！"},
	[61761] = {CommonPl = "少林方生，菩薩亦有金剛之怒，見到江湖敗類的話，老衲也會忍不住出手！"},
	[61764] = {CommonPl = "貧道武當玄高！"},
	[61767] = {CommonPl = "峨眉長鴻，金頂佛光！"},
	[61770] = {CommonPl = "逍遙自在李玉衡！"},
	[61773] = {CommonPl = "華山勞德諾！"},
	[61776] = {CommonPl = "衡山魯連榮！"},
	[61779] = {CommonPl = "貧尼恆山定逸！"},
	[75532] = {CommonPl = "我祖上曾是幫董公養龍的使者，不過此技早於春秋時失傳。好在老祖宗還留了另一本手札，記載門徒的馴服之道，雖比不上馭龍威風，但此技不招人奪搶，方可留傳給後輩糊口。"},
