	[75650] = {CommonPl = "師父什麼時候才會准許我去外面闖蕩呀？"},
	[75651] = {CommonPl = "師父什麼時候才會准許我去外面闖蕩呀？"},
	[75652] = {CommonPl = "師父什麼時候才會准許我去外面闖蕩呀？"},
	[75653] = {CommonPl = "師父什麼時候才會准許我去外面闖蕩呀？"},
	[92835] = {CommonPl = "我獨孤一脈弟子往日裡孑然一身行走江湖，行俠仗義。雖不曾開宗立派，卻也俠名遠播！我輩之人雖無意權勢爭奪，但終感獨木難支，沒有歸宿！\r今日，我獨孤一脈依託獨孤前輩劍塚開宗立派！代掌門獨孤鳴在此廣邀江湖各處的獨孤子弟回家。從此，你們不再漂泊，我們共同懲惡揚善！"},
	[92724] = {CommonPl = "師父什麼時候才會准許我去外面闖蕩呀？"},
	[92725] = {CommonPl = "天下武功，唯獨孤自成一派。一人一鷹，融會貫通。招式剛猛，出手果決——取鷹之淩厲，藏刃之精准。這些，可絕非一日之功啊！\r若是想習得套路或者提升技能等級，可以來我這裡學習。"},
	[92726] = {CommonPl = "招無定式，水無常型。你若是以為招式學會後一成不變那你可就錯了。我可以幫你領悟出招式中最神妙的變數，讓你的招式威力大增。"},
	[92727] = {CommonPl = "天下武功，無堅不摧，唯快不破。身法若高，敵人縱有千斤之力也打你不著，豈不快哉？若是想習得修身技能，可以來我這裡學習。"},
	[92728] = {CommonPl = "我祖上曾是幫董公養龍的使者，不過此技早于春秋時失傳。好在老祖宗還留了另一本手劄，記載門徒的馴服之道，雖比不上馭龍威風，但此技不招人奪搶，方可留傳給後輩糊口。"},
	[92729] = {CommonPl = "有些招式早學比晚學的好。所謂拳怕少壯。我可以幫你教教這些門徒，不過最近我手頭緊，所以多少要收點銀子，所謂你來我往，承蒙大俠包涵~"},
	[92730] = {CommonPl = "門派秘境乃是本門禁地，向來只對本門弟子開放。如無特例，其他閒雜人等，一律不准進入。"},
	[92731] = {CommonPl = "獨孤派弟子遍佈大江南北，彙聚天下英豪。俠之大者，為國為民，雖獨孤，卻仁義！"},
	[92732] = {CommonPl = "師父什麼時候才會准許我去外面闖蕩呀？"},
	[92926] = {CommonPl = "與仁義為友，與邪惡為敵。我獨孤派歡迎各位朋友的到訪~\r哈哈，裡面請！"},
	[93028] = {CommonPl = "我可以送你進入一個秘境，開啟門派試練。秘境內有無盡的敵人，殺敵越多，獲得的積分就越高。\r如若本周內你的試練積分高居榜首，那麼下周你就是本門的首席弟子！\r開啟門派試練,^FF0000需要100門派貢獻！\r"},
	[93029] = {CommonPl = "我可以送你進入一個秘境，開啟門派試練。秘境內有無盡的敵人，殺敵越多，獲得的積分就越高。\r如若本周內你的試練積分高居榜首，那麼下周你就是本門的首席弟子！\r開啟門派試練,^FF0000需要100門派貢獻！\r"},
