	[93038] = {CommonPl = "我可以送你進入一個秘境，開啟門派試練。秘境內有無盡的敵人，殺敵越多，獲得的積分就越高。\r如若本周內你的試練積分高居榜首，那麼下周你就是本門的首席弟子！\r開啟門派試練,^FF0000需要100門派貢獻！\r"},
	[99357] = {CommonPl = "煉心之旅，你準備好了嗎？"},
	[99356] = {CommonPl = "玲瓏心典，講究一力破萬法。\r只有心志堅定，日夜勤學苦練，才能打出令人側目的高輸出，高爆發。"},
	[99363] = {CommonPl = "想要習得高深的玲瓏武學嗎？\r很簡單哦，只需要付出一點點的代價。"},
	[99360] = {CommonPl = "如今的裝備更新換代的速度是越來越快了，但是前期升級打怪，少不得還是要找我換些實用的裝備，這樣會讓你事半功倍。"},
	[99358] = {CommonPl = "闖蕩江湖，怎能缺少一個隨叫隨到的如意門徒呢？"},
	[99354] = {CommonPl = "天地萬法，一力以破之。"},
	[2668] = {CommonPl = "走南闖北，身上的帶的東西多了都是累贅，大俠出手，那都得飄逸，飄逸你懂嗎？\r所以多餘的東西就放我這裡吧，放心吧，保證不會丟！"},
	[2671] = {CommonPl = "闖蕩江湖，沒有一把好武器可不行。\r我這裡貨品齊全，童叟無欺，雙刀，單劍，軟鞭一應俱全。\r這位#Y,你想要點什麼？\r"},
	[2674] = {CommonPl = "佛要金裝嘛。每年佛誕，我家都會捐三百兩香油給“到佛寺”的“笑彌勒”貼金箔。說是“衣紫腰金”為大官，若是穿得體面，自然也就有了官氣，我看你亦非下三流，如果是，這裝扮上就更省不得，你是明白人，明白人知道自己要選啥～"},
	[2677] = {CommonPl = "街坊說我是生意人，其實我自己知道，這點皮毛醫術，就只能混個飽，當不了大夫，我還可以治點小病，這些方子都是我這幾年闖南走北收集來的，要說送，我還真有點捨不得，所以拿出來和你換一壺酒錢，你可願意？"},
	[2680] = {CommonPl = "一副擔子走千里，針頭線腦全包羅。\r紅頭繩——狗娃哨——要啥有啥喲——\r客官，有什麼需要的嗎？"},
	[2686] = {CommonPl = "幫會的建立，升級，以及其他有關幫會的事情，都可以從我這裡得到你想知道的。\r只有你想不到的，沒有我不知道的。\r"},
	[2689] = {CommonPl = "一個籬笆三個樁，一個好漢三個幫。\r行走江湖，多個幫手總是好事。\r你要結義嗎？"},
	[2692] = {CommonPl = "前路風雨飄搖，#Y多加保重，出門謹記：\r舉步常看蟲蟻，禁火莫燒山林。\r點夜燈以照人行，勿宰耕牛，勿棄字紙。"},
	[2695] = {CommonPl = "要想馬兒跑的快，又想馬兒不吃草，哪有這麼好的事！要把養馬當做養孩子，馬兒才能跑得快。"},
	[2698] = {CommonPl = "你知道酒與水的區別嗎？酒越喝越熱，水卻越喝越寒。\r古人說：“綠蟻新醅酒，紅泥小火爐”。\r約三兩知己，品十八女兒紅，豈不妙哉？"},
	[2704] = {CommonPl = "千里有緣一線牽,攜手同心共百年。"},
	[2707] = {CommonPl = "行走江湖,義字為先!"},
	[2710] = {CommonPl = "我祖上曾是幫董公養龍的使者，不過此技早於春秋時失傳。好在老祖宗還留了另一本手札，記載門徒的馴服之道，雖比不上馭龍威風，但此技不招人奪搶，方可留傳給後輩糊口。"},
