	[4632] = {CommonPl = "南來的，北往的；拿刀的，帶劍的。\r正宗金創藥，西域大還丹。\r走過路過不要錯過。"},
	[4635] = {CommonPl = "一副擔子走千里，針頭線腦全包羅。\r紅頭繩——狗娃哨——要啥有啥喲——\r客官，有什麼需要的嗎？"},
	[4875] = {CommonPl = "是藥三分毒，所以才會有“良醫救人，庸醫殺人”這種說法。\r不過我這裡的藥，保管你藥到病除不留根，強身健體不上火！"},
	[4878] = {CommonPl = "一副擔子走千里，針頭線腦全包羅。\r紅頭繩——狗娃哨——要啥有啥喲——\r客官，有什麼需要的嗎？"},
	[5239] = {CommonPl = "一副擔子走千里，針頭線腦全包羅。\r紅頭繩——狗娃哨——要啥有啥喲——\r客官，有什麼需要的嗎？"},
	[5242] = {CommonPl = "是藥三分毒，所以才會有“良醫救人，庸醫殺人”這種說法。\r不過我這裡的藥，保管你藥到病除不留根，強身健體不上火！"},
	[5250] = {CommonPl = "一副擔子走千里，針頭線腦全包羅。\r紅頭繩——狗娃哨——要啥有啥喲——\r客官，有什麼需要的嗎？"},
	[5253] = {CommonPl = "南來的，北往的；拿刀的，帶劍的。\r正宗金創藥，西域大還丹。\r走過路過不要錯過。"},
	[5256] = {CommonPl = "一副擔子走千里，針頭線腦全包羅。\r紅頭繩——狗娃哨——要啥有啥喲——\r客官，有什麼需要的嗎？"},
	[5259] = {CommonPl = "南來的，北往的；拿刀的，帶劍的。\r正宗金創藥，西域大還丹。\r走過路過不要錯過。"},
	[5468] = {CommonPl = "人靠衣裝，馬靠鞍。\r出門在外，難免碰到颳風下雨濕了衣服，還是多備兩件妥當。"},
	[5471] = {CommonPl = "走南闖北，身上的帶的東西多了都是累贅，大俠出手，那都得飄逸，飄逸你懂嗎？\r所以多餘的東西就放我這裡吧，放心吧，保證不會丟！"},
	[5474] = {CommonPl = "闖蕩江湖，沒有一把好武器可不行。\r我這裡貨品齊全，童叟無欺，雙刀，單劍，軟鞭一應俱全。\r這位#Y,你想要點什麼？\r"},
	[6105] = {CommonPl = "千金買骨，紅綾換笑，不過平常遊戲。\r肝膽忠僕，一生之伴，卻還待我尋尋覓覓。"},
	[6192] = {CommonPl = "有些人沒病就喜歡吃藥，說是補身，其實那就是矯情，就像林家幾個姨奶奶，那個不是吃藥吃死的。病人藥吃多了，方子就不好開了，病人就病死，醫師就等著餓死。所以在我餓死之前，先賣了這些藥方子。換點錢嘛～以後兒子娶媳婦也好，老婆子守寡立牌坊也好，總得花。"},
	[6225] = {CommonPl = "嗷……嗷……"},
	[9698] = {CommonPl = "一副擔子走千里，針頭線腦全包羅。\r紅頭繩——狗娃哨——要啥有啥喲——\r客官，有什麼需要的嗎？"},
