	[12511] = {CommonPl = "此地就是五霸崗"},
	[12514] = {CommonPl = "此地就是桂林"},
	[14178] = {CommonPl = "此地就是泰山"},
	[14181] = {CommonPl = "此地就是日月神教"},
	[12543] = {CommonPl = "#N俠士，吾乃福州人士“馮夢龍”字“猶龍”，聽聞少俠已初入門徒之道，而今時機已經成熟，你若想增強門徒的實力，讓它助你笑傲江湖，請務必找我。"},
	[12546] = {CommonPl = "要是你早些年來，我一定會殺了你，我最不喜歡別人打擾我品茶。不過對一個風燭殘年的人而言，還有多少火爆脾氣。要說我和馮夢龍曾經也是水火不容之人，還鬧得天翻地覆，現在反而成了朋友。"},
	[13057] = {CommonPl = "這鍋裡打滾兒的東西，無非酸甜苦辣，你想做啥，完全在於你的心情，你要高興做出來的菜都能笑。不信？你看“居月樓”吃我菜的人個個都在笑。這鍋子能煮熟很多東西，除了人，不然該成熟人了，哈哈！"},
	[13060] = {CommonPl = "“鄉村四月閒人少，才了蠶桑又插田”江湖往來如此多人，哪值我們農人這份閒情，只寄喜樂於耕作。你寫意了恩怨情仇又如何，你放下了恩怨情仇又如何，到頭自己還不是套在一個局裡，走得出來能笑著，走不出來就藏著，不知我這說話可對。"},
	[13070] = {CommonPl = "挖礦就是賭命，你有幾條命？有九條那是貓，貓不挖礦，牠不混江湖，你一條命，你還混江湖，江湖講什麼？“兵戈”，掂掂你手上這把，幾斤？幾兩幾？夠不上斤兩，不夠就跟我學學怎麼弄到好石頭。算命的騙你十年八年，我算哄你不騙你，怎麼樣？學不學？"},
	[13076] = {CommonPl = "人既然吃五穀雜糧，就免不了被病疾纏身，得病的人，有得醫的是命，沒得醫的是命，命中註定，你就算捧個百寶箱都得死。凡世間的草藥不是天上神仙種來，吃下去百病全消，所以才有擇藥醫人的學問。"},
	[13306] = {CommonPl = "走南闖北，身上的帶的東西多了都是累贅，大俠出手，那都得飄逸，飄逸你懂嗎？\r所以多餘的東西就放我這裡吧，放心吧，保證不會丟！"},
	[13309] = {CommonPl = "闖蕩江湖，沒有一把好武器可不行。\r我這裡貨品齊全，童叟無欺，雙刀，單劍，軟鞭一應俱全。\r這位#Y,你想要點什麼？\r"},
	[13312] = {CommonPl = "人靠衣裝，馬靠鞍。\r出門在外，難免碰到颳風下雨濕了衣服，還是多備兩件妥當。"},
	[13330] = {CommonPl = "要想馬兒跑的快，又想馬兒不吃草，哪有這麼好的事！要把養馬當做養孩子，馬兒才能跑得快。"},
	[13333] = {CommonPl = "天下人言“四大金族”。從黃帝時期傳襲到現在，經百朝變故，很多人根本聞所未聞。他們的存在只因為他們背負超乎常人責任。我打理的這些事，真正的背後操手人就是他們，沒人知道為什麼，也沒有人可以找到他們。"},
	[13939] = {CommonPl = "走南闖北，身上的帶的東西多了都是累贅，大俠出手，那都得飄逸，飄逸你懂嗎？\r所以多餘的東西就放我這裡吧，放心吧，保證不會丟！"},
	[13942] = {CommonPl = "闖蕩江湖，沒有一把好武器可不行。\r我這裡貨品齊全，童叟無欺，雙刀，單劍，軟鞭一應俱全。\r這位#Y,你想要點什麼？\r"},
	[13945] = {CommonPl = "人靠衣裝，馬靠鞍。\r出門在外，難免碰到颳風下雨濕了衣服，還是多備兩件妥當。"},
	[13966] = {CommonPl = "“凡胎那識真明月，白鶴東來惹青霜”師尊說能說的，我說。師尊說不能說的，我不說。要不是我放走了九華鯉，師尊也不會罰我呆在這兒，小仙人索性就開檔賺錢游這方。"},
	[10186] = {CommonPl = "假如有朝你在江湖中遇到一個叫司馬牧雨的姑娘，幫我帶句話，就說阿力曲比會一直等她。說來不知道有什麼能幫少俠的？"},
	[10189] = {CommonPl = "這場江湖能走下去的人太多，沒人在意誰消失了，誰還活著，人心叵測，倒不如這些門生想得簡單。這番話，你總有一天會明白。想我幫你什麼？"},
	[11169] = {CommonPl = "南來的，北往的；拿刀的，帶劍的。\r正宗金創藥，西域大還丹。\r走過路過不要錯過。"},
	[3546] = {CommonPl = "本以為只是路經此地，沒想到跟山賊拼鬥起來，我這藥材沒帶多少，這可真是巧婦難為無米之炊啊……"},
	[13984] = {CommonPl = "你知道酒與水的區別嗎？酒越喝越熱，水卻越喝越寒。\r古人說：“綠蟻新醅酒，紅泥小火爐”。\r約三兩知己，品十八女兒紅，豈不妙哉？"},
	[17171] = {CommonPl = "江湖人士，不看年紀，不問身份，只要你有足夠的銀兩，我就能給你搞到一間屋子，別怪我貪財，我們都是從錢眼裡鑽出來的，心照不宣。"},
	[13987] = {CommonPl = "一副擔子走千里，針頭線腦全包羅。\r紅頭繩——狗娃哨——要啥有啥喲——\r客官，有什麼需要的嗎？"},
	[13990] = {CommonPl = "南來的，北往的；拿刀的，帶劍的。\r正宗金創藥，西域大還丹。\r走過路過不要錯過。"},
	[13993] = {CommonPl = "看看有什麼需要的首飾吧。"},
	[13996] = {CommonPl = "闖蕩江湖，沒有一把好武器可不行。\r我這裡貨品齊全，童叟無欺，雙刀，單劍，軟鞭一應俱全。\r這位#Y,你想要點什麼？\r"},
	[13999] = {CommonPl = "人靠衣裝，馬靠鞍。\r出門在外，難免碰到颳風下雨濕了衣服，還是多備兩件妥當。"},
