	[14020] = {CommonPl = "人靠衣裝，馬靠鞍。\r出門在外，難免碰到颳風下雨濕了衣服，還是多備兩件妥當。"},
	[14023] = {CommonPl = "走南闖北，身上的帶的東西多了都是累贅，大俠出手，那都得飄逸，飄逸你懂嗎？\r所以多餘的東西就放我這裡吧，放心吧，保證不會丟！"},
	[14026] = {CommonPl = "你知道酒與水的區別嗎？酒越喝越熱，水卻越喝越寒。\r古人說：“綠蟻新醅酒，紅泥小火爐”。\r約三兩知己，品十八女兒紅，豈不妙哉？"},
	[14029] = {CommonPl = "一副擔子走千里，針頭線腦全包羅。\r紅頭繩——狗娃哨——要啥有啥喲——\r客官，有什麼需要的嗎？"},
	[14032] = {CommonPl = "南來的，北往的；拿刀的，帶劍的。\r正宗金創藥，西域大還丹。\r走過路過不要錯過。"},
	[14035] = {CommonPl = "看看有什麼需要的首飾吧。"},
	[14038] = {CommonPl = "闖蕩江湖，沒有一把好武器可不行，這位#Y,到我這來看看吧。"},
	[14041] = {CommonPl = "人靠衣裝，馬靠鞍。\r出門在外，難免碰到颳風下雨濕了衣服，還是多備兩件妥當。"},
	[14044] = {CommonPl = "走南闖北，身上的帶的東西多了都是累贅，大俠出手，那都得飄逸，飄逸你懂嗎？\r所以多餘的東西就放我這裡吧，放心吧，保證不會丟！"},
	[14047] = {CommonPl = "你知道酒與水的區別嗎？酒越喝越熱，水卻越喝越寒。\r古人說：“綠蟻新醅酒，紅泥小火爐”。\r約三兩知己，品十八女兒紅，豈不妙哉？"},
	[14557] = {CommonPl = "金蘭之玉，珠光寶氣，誰不喜歡？你可以說我俗，不過世間多幾個人不是俗？即然到我這兒來，我一定給你最好的推薦，你看這點翠、鑲嵌、雕刻工藝，哪家師父及得上？"},
	[14560] = {CommonPl = "家園裡有很多事，雖然不及江湖轟轟烈烈，但自有一番閑趣，若你有意，可以找周圍的朋友多打聽打聽。"},
	[14566] = {CommonPl = "金石木竹，本就為天生天養之物，若要提煉出它們與生的靈氣，豈是朝夕可成，想學頂尖的金石之技，那得看你的資質，不過有句話我要提醒你“金石無心人有心。”如果有天你忘了這句話，你就變得和你手中的金石一樣冰冷。"},
	[14569] = {CommonPl = "靠山吃山，靠水吃水，我們靠的是林場，做的是手工活，做手工活的人不會說太多，所以只能靠自己多看多學，你如果能做到，就拿工具跟我學。"},
	[14575] = {CommonPl = "這幾年棉花收成不好，家裡那死小子又不長進，說什麼也不願繼承我這手藝，要去華山學武，學武有什麼好，整天喊打喊殺，所以我決定趁現在還能動彈給他留點錢，至於這門手藝就只有留給有緣人了。"},
	[14581] = {CommonPl = "金玉滿堂是好兆頭，不過要好兆頭就要有條好命，好命人的生意我真沒做過，可能因為我的命不好，這些首飾，雖沒有堆金砌銀，但這紋路可是南海師父親手刻出來的，就算有一條好命，你也未必遇得到。"},
	[14584] = {CommonPl = "酒質優與劣，真不是人人都喝得出來的，很多人喝酒只是種情緒，喜怒哀樂，終究只得一場醉而已。"},
	[14587] = {CommonPl = "要找個地方安居，還真不是件容易事，我這裡還有些空屋子，不過能不能住得進去，就要看你有沒有這個本事了。"},
	[14614] = {CommonPl = "翡翠瑪瑙都可以做成很獨特的飾品，但關鍵在於配搭的人，如果少了那氣質，就算佩戴再名貴的飾品都毫無意義，雖說生意人都只會說個好字，但是不是真好，其實大家都心知肚明。"},
	[14617] = {CommonPl = "酒質優與劣，真不是人人都喝得出來的，很多人喝酒只是種情緒，喜怒哀樂，終究只得一場醉而已。"},
	[14620] = {CommonPl = "江湖風雨無常，有個家，遮風避雨也好，累了發發呆也好，浪跡天涯總要給自己找一個落葉歸根地方。"},
	[14623] = {CommonPl = "一顆樹風風雨雨長幾十年，砍斷它就只用一炷香的時間，雖說我們靠伐木為生，但是也得講這行的規矩，不夠年頭或年頭久遠的樹木我們一律不能砍，人雖然要吃飯，但也得有點良知，給子子孫孫留點東西。"},
	[14626] = {CommonPl = "放長線掉大魚，你真以為是這樣？在我們這種小河裡，誰敢放長線，那早就給河底的石頭給勾斷了，所以釣魚也得講個因地制宜，看你聽得這麼認真，加上老夫今日心情又不錯，就教你兩手絕活。"},
	[14629] = {CommonPl = "學養牲口，我沒聽錯？你們這些年輕人不是都養什麼貓狗兔子，誰有興趣來學養牲口。我不會？哈哈！可惡，激將法，正中我的死穴，我就非給你看看我的本事！"},
	[9823] = {CommonPl = "別人的貨是死的，我的貨的活的，活的東西就得吃喝拉撒，會幫你打架，也也會幫你使錢，這長腦袋的和不長腦袋的差別就在這兒，你想要好的門徒，就得有駕馭他的本事，沒本事，你就成了他的門徒，怎麼樣？談談價錢？"},
	[17809] = {CommonPl = "翡翠瑪瑙都可以做成很獨特的飾品，但關鍵在於配搭的人，如果少了那氣質，就算佩戴再名貴的飾品都毫無意義，雖說生意人都只會說個好字，但是不是真好，其實大家都心知肚明。"},
	[13723] = {CommonPl = "這集市多複雜，三教九流什麼人都有，看好你的錢包。另外，離手買賣，眼神准點，要是看偏了，哭天哭地都哭不回來。"},
	[13726] = {CommonPl = "擂臺上拳腳說話，輸贏得失別看得太重。\r切磋怡情，動氣傷身。\r少俠可要試試？"},
	[19323] = {CommonPl = "我負責劍塚殺怪活動。"},
	[22073] = {CommonPl = "聲望可以透過完成聲望相關任務來增加聲望點數。\r當聲望足夠高時可以在聲望負責人處換取裝備，食譜，家園用品等不同的獎勵。"},
	[22076] = {CommonPl = "聲望可以透過完成聲望相關任務來增加聲望點數。\r當聲望足夠高時可以在聲望負責人處換取裝備，食譜，家園用品等不同的獎勵。"},
	[22079] = {CommonPl = "聲望可以透過完成聲望相關任務來增加聲望點數。\r當聲望足夠高時可以在聲望負責人處換取裝備，食譜，家園用品等不同的獎勵。"},
	[22082] = {CommonPl = "聲望可以透過完成聲望相關任務來增加聲望點數。\r當聲望足夠高時可以在聲望負責人處換取裝備，食譜，家園用品等不同的獎勵。"},
	[22085] = {CommonPl = "聲望可以透過完成聲望相關任務來增加聲望點數。\r當聲望足夠高時可以在聲望負責人處換取裝備，食譜，家園用品等不同的獎勵。"},
	[22088] = {CommonPl = "聲望可以透過完成聲望相關任務來增加聲望點數。\r當聲望足夠高時可以在聲望負責人處換取裝備，食譜，家園用品等不同的獎勵。"},
	[22091] = {CommonPl = "聲望可以透過完成聲望相關任務來增加聲望點數。\r當聲望足夠高時可以在聲望負責人處換取裝備，食譜，家園用品等不同的獎勵。"},
	[22992] = {CommonPl = "在我這裡，你可以換到闖蕩江湖，傲游武林的必備之物。"},
	[22178] = {CommonPl = "#N，很高興看到你。\r一旦重傷昏迷，復生後會很虛弱，氣血和內力都非常低。\r這種情況下，不要忘了來福州、衡山、洛陽等地找我或我的同伴，我們可以為你提供治療。\r在安全復生後會有重傷標記，上次重傷的地點和敵人會有提示，可以透過系統提示或傳送旗返回。"},
	[22181] = {CommonPl = "#N，很高興看到你。\r一旦重傷昏迷，復生後會很虛弱，氣血和內力都非常低。\r這種情況下，不要忘了來福州、衡山、洛陽等地找我或我的同伴，我們可以為你提供治療。\r在安全復生後會有重傷標記，上次重傷的地點和敵人會有提示，可以透過系統提示或傳送旗返回。"},
	[22184] = {CommonPl = "#N，很高興看到你。\r一旦重傷昏迷，復生後會很虛弱，氣血和內力都非常低。\r這種情況下，不要忘了來福州、衡山、洛陽等地找我或我的同伴，我們可以為你提供治療。\r在安全復生後會有重傷標記，上次重傷的地點和敵人會有提示，可以透過系統提示或傳送旗返回。"},
	[22465] = {CommonPl = "有些招式早學比晚學的好。所謂拳怕少壯。我可以幫你教教這些門徒，不過最近我手頭緊，所以多少要收點銀子，所謂你來我往，承蒙大俠包涵~"},
	[22468] = {CommonPl = "有些招式早學比晚學的好。所謂拳怕少壯。我可以幫你教教這些門徒，不過最近我手頭緊，所以多少要收點銀子，所謂你來我往，承蒙大俠包涵~"},
