	[22242] = {CommonPl = "天上的事我知道一半，地上的事我知道八成。"},
	[10192] = {CommonPl = "前路風雨飄搖，#Y多加保重，出門謹記：\r舉步常看蟲蟻，禁火莫燒山林。\r點夜燈以照人行，勿宰耕牛，勿棄字紙。"},
	[10195] = {CommonPl = "前路風雨飄搖，#Y多加保重，出門謹記：\r舉步常看蟲蟻，禁火莫燒山林。\r點夜燈以照人行，勿宰耕牛，勿棄字紙。"},
	[23456] = {CommonPl = "#X，\r如果你想一展身手，\r歡迎來參加競技戰。"},
	[23459] = {CommonPl = "#X，\r如果你想名揚江湖，\r歡迎來參加組隊戰。"},
	[24599] = {CommonPl = "人是一種很奇怪的動物，不管這種東西你再怎麼愛，如果讓你每天面對他，久了你一定會煩，會膩，對他的喜歡和愛的熱度一定會退，會淡。"},
	[24602] = {CommonPl = "仗劍紅塵已是癲,\r有酒平步上青天。\r遊星戲鬥弄日月,\r醉臥雲端笑人間。"},
