	[26329] = {CommonPl = "走南闖北，身上的帶的東西多了都是累贅，大俠出手，那都得飄逸，飄逸你懂嗎？\r所以多餘的東西就放我這裡吧，放心吧，保證不會丟！"},
	[26332] = {CommonPl = "別人的貨是死的，我的貨的活的，活的東西就得吃喝拉撒，會幫你打架，也也會幫你使錢，這長腦袋的和不長腦袋的差別就在這兒，你想要好的門徒，就得有駕馭他的本事，沒本事，你就成了他的門徒，怎麼樣？談談價錢？"},
	[26824] = {CommonPl = "人是一種很奇怪的動物，不管這種東西你再怎麼愛，如果讓你每天面對他，久了你一定會煩，會膩，對他的喜歡和愛的熱度一定會退，會淡。"},
