	[29142] = {CommonPl = "三百六十行，行行出狀元。對手工製造有興趣，就來我這兒看看吧。"},
	[29145] = {CommonPl = "三百六十行，行行出狀元。對治療養生有興趣，就來我這兒看看吧。"},
	[29148] = {CommonPl = "三百六十行，行行出狀元。對禮儀交際有興趣，就來我這兒看看吧。"},
	[29151] = {CommonPl = "三百六十行，行行出狀元。對門徒有興趣，就來我這兒看看吧。"},
	[29139] = {CommonPl = "一招先，吃遍天，有門壓箱底的絕活是必須的。"},
	[29952] = {CommonPl = "每週一到週五，想要參加武林盟主戰的結義成員，可以帶著武林盟主英雄帖找我報名。"},
	[29955] = {CommonPl = "要去嵩山的話儘管找我，盟主的客人不收路費！"},
	[29958] = {CommonPl = "要去洛陽的話儘管找我，盟主的客人不收路費！"},
	[30092] = {CommonPl = "只要是江湖上的必需品，我這裡應有盡有！"},
	[31037] = {CommonPl = "如果要回洛陽，找我說一聲。"},
	[31040] = {CommonPl = "如果要回洛陽，找我說一聲。"},
	[31043] = {CommonPl = "如果要回洛陽，找我說一聲。"},
	[31046] = {CommonPl = "如果要回洛陽，找我說一聲。"},
	[32876] = {CommonPl = "（唱）落盤菜～搖壺酒～天南地北任我走～盤龍大棍挽在手～小俠能否施我口……"},
	[32879] = {CommonPl = "（唱）落盤菜～搖壺酒～天南地北任我走～盤龍大棍挽在手～小俠能否施我口……"},
	[32882] = {CommonPl = "（唱）落盤菜～搖壺酒～天南地北任我走～盤龍大棍挽在手～小俠能否施我口……"},
	[32885] = {CommonPl = "（唱）落盤菜～搖壺酒～天南地北任我走～盤龍大棍挽在手～小俠能否施我口……"},
	[13948] = {CommonPl = "情不知所起，一往而深。生者可以死，死可以生。生而不能死，死而不可復生者，皆非情之至也。\r你問我還相信愛情嗎？那還用說，我可是專業吃這碗飯的，雙魚座哦！"},
	[13957] = {CommonPl = "五嶽劍派，同氣連枝！聽過吧？別看現在人家勢大，當年他們也是從小幫會發展起來的。\r你不想在江湖上闖出一番名頭？先建個幫吧。"},
	[13960] = {CommonPl = "雙拳難敵四手，麻雀自己不成。行走江湖，誰沒幾個好兄弟呢？\r加入結義，那些年你們一起獲得的財物、打退的強敵、追過的妹子，可就都能記錄在案啦。"},
	[13951] = {CommonPl = "師徒之情能有多深？看看李杜。子美視太白為精神導師，連名句的調調都深入骨髓啊。\r山隨平野盡，江入大荒流。——李白\r星垂平野闊，月湧大江流。——杜甫"},
	[36030] = {CommonPl = "生來三十餘載，鍛劍無數，卻無一把不義之刃！！鑄劍如此，為人更要如此！！！"},
	[36033] = {CommonPl = "偽君子往往比真小人更難對付！行走江湖，可千萬要擦亮眼啊！\r"},
	[36036] = {CommonPl = "客人是來買藥的吧，不妨在咱們鋪子裡看看，各種內用外敷、疑難雜症所需之藥，本店應有盡有，保管藥到病除！"},
	[4289] = {CommonPl = "一入江湖塵世遠，高堂雙鬢盡染霜。有多久沒回過老家了？給親人寫封信吧。"},
	[4313] = {CommonPl = "一入江湖塵世遠，高堂雙鬢盡染霜。有多久沒回過老家了？給親人寫封信吧。"},
	[13963] = {CommonPl = "是騾子是馬，拉出來遛遛！我敢開這店，就有底氣說這話。怎麼樣，選一匹試騎下？沒入眼的？哎，千里馬常有，而伯樂不常有啊！"},
	[44823] = {CommonPl = "前路風雨飄搖，#Y多加保重，出門謹記：\r舉步常看蟲蟻，禁火莫燒山林。\r點夜燈以照人行，勿宰耕牛，勿棄字紙。"},
