	[44688] = {CommonPl = "南來北往，咱們鏢局中人靠的是信用和腳力，最近人手不夠，壓下了不少生意。\r少俠可否順道幫押趟鏢？報酬嘛自然少不了。"},
	[44386] = {CommonPl = "鄙人喜歡收集各地的奇珍異寶，其中西域異寶為最，這次來到洛陽進行文化交流特意帶來了大量珍寶，想舉辦一場拍賣盛會，就等親王大人首肯了。"},
	[44387] = {CommonPl = "親王大人日理萬機，日夜操勞為的就是天下太平。我的工作就是按照大人命令發放獎勵。"},
	[13324] = {CommonPl = "五嶽劍派，同氣連枝！聽過吧？別看現在人家勢大，當年他們也是從小幫會發展起來的。\r你不想在江湖上闖出一番名頭？先建個幫吧。"},
	[55441] = {CommonPl = "親王大人日理萬機，日夜操勞為的就是天下太平。我的工作就是按照大人命令發放獎勵。"},
	[55442] = {CommonPl = "南洋的奇珍異寶甲天下，這次來到洛陽進行文化交流特意帶來了大量珍寶，想舉辦一場拍賣盛會，就等親王大人首肯了。"},
	[31022] = {CommonPl = "大江南北的奇事、前朝歷代的寶藏，我這裡都有消息，要不要瞧瞧？"},
	[31025] = {CommonPl = "江湖上的英雄好漢看著光鮮，實則大多是錢堆的，沒錢誰識得你是何許人也。"},
	[30971] = {CommonPl = "幫派行不行先看設施齊不齊，營建的事找我准沒錯。"},
	[38475] = {CommonPl = "再硬的嘴巴我也能撬開，在這兒玩寧死不屈的戲碼可就找錯地方了。"},
	[30970] = {CommonPl = "開心了要喝，寂寞了要喝，成功了要喝，落難了要喝，不喝哪算江湖中人？"},
	[31028] = {CommonPl = "有好東西記得來找我，有多少收多少，價格包你滿意。"},
	[31031] = {CommonPl = "聰明人要學會借力，瑣碎之事有人代勞豈不快哉？"},
	[44375] = {CommonPl = "世人常說寶物鎮有氣運，幫派會因為得到一個寶物而興，自然也會因為失去一個寶物而衰。"},
	[34666] = {CommonPl = "大江南北的奇事、前朝歷代的寶藏，我這裡都有消息，要不要瞧瞧？"},
	[34667] = {CommonPl = "江湖上的英雄好漢看著光鮮，實則大多是錢堆的，沒錢誰識得你是何許人也。"},
	[34668] = {CommonPl = "幫派行不行先看設施齊不齊，營建的事找我准沒錯。"},
	[30411] = {CommonPl = "與犯案者鬥智鬥勇固然有趣，但我更希望天下無賊世間太平。"},
	[34669] = {CommonPl = "開心了要喝，寂寞了要喝，成功了要喝，落難了要喝，不喝哪算江湖中人？"},
	[31034] = {CommonPl = "江湖惡人在我這裡個個都有標價，想賺花紅就提他們的首級來。"},
	[34670] = {CommonPl = "聰明人要學會借力，瑣碎之事有人代勞豈不快哉？"},
	[34671] = {CommonPl = "世人常說寶物鎮有氣運，幫派會因為得到一個寶物而興盛，自然也會因為失去一個寶物而衰亡。"},
	[58705] = {CommonPl = "福州、衡山還有洛陽都是當世有名的大城，前去路上自然一片坦途。"},
	[58706] = {CommonPl = "福州、衡山還有洛陽都是當世有名的大城，前去路上自然一片坦途。"},
	[58707] = {CommonPl = "福州、衡山還有洛陽都是當世有名的大城，前去路上自然一片坦途。"},
	[58708] = {CommonPl = "福州、衡山還有洛陽都是當世有名的大城，前去路上自然一片坦途。"},
	[57469] = {CommonPl = "做生意，講究的是公平交易。\r我這兒的裝備可都是百裡挑一的良品，想要？且拿出同等價值的物什來兌換。"},
	[58679] = {CommonPl = "做生意，講究的是公平交易。\r我這兒的裝備可都是百裡挑一的良品，想要？且拿出同等價值的物什來兌換。"},
	[58917] = {CommonPl = "這鍋裡打滾兒的東西，無非酸甜苦辣，你想做啥，完全在於你的心情，你要高興做出來的菜都能笑。不信？你看“居月樓”吃我菜的人個個都在笑。這鍋子能煮熟很多東西，除了人，不然該成熟人了，哈哈！"},
	[58918] = {CommonPl = "靠山吃山，靠水吃水，我們靠的是林場，做的是手工活，做手工活的人不會說太多，所以只能靠自己多看多學，你如果能做到，就拿工具跟我學。"},
	[58919] = {CommonPl = "人既然吃五穀雜糧，就免不了被病疾纏身，得病的人，有得醫的是命，沒得醫的是命，命中註定，你就算捧個百寶箱都得死。凡世間的草藥不是天上神仙種來，吃下去百病全消，所以才有擇藥醫人的學問。"},
	[58920] = {CommonPl = "這幾年棉花收成不好，家裡那死小子又不長進，說什麼也不願繼承我這手藝，要去華山學武，學武有什麼好，整天喊打喊殺，所以我決定趁現在還能動彈給他留點錢，至於這門手藝就只有留給有緣人了。"},
	[58921] = {CommonPl = "金石木竹，本就為天生天養之物，若要提煉出它們與生的靈氣，豈是朝夕可成，想學頂尖的金石之技，那得看你的資質，不過有句話我要提醒你“金石無心人有心。”如果有天你忘了這句話，你就變得和你手中的金石一樣冰冷。"},
	[58922] = {CommonPl = "“鄉村四月閒人少，才了蠶桑又插田”江湖往來如此多人，哪值我們農人這份閒情，只寄喜樂於耕作。你寫意了恩怨情仇又如何，你放下了恩怨情仇又如何，到頭自己還不是套在一個局裡，走得出來能笑著，走不出來就藏著，不知我這說話可對。"},
	[58923] = {CommonPl = "一顆樹風風雨雨長幾十年，砍斷它就只用一炷香的時間，雖說我們靠伐木為生，但是也得講這行的規矩，不夠年頭或年頭久遠的樹木我們一律不能砍，人雖然要吃飯，但也得有點良知，給子子孫孫留點東西。"},
	[58924] = {CommonPl = "放長線掉大魚，你真以為是這樣？在我們這種小河裡，誰敢放長線，那早就給河底的石頭給勾斷了，所以釣魚也得講個因地制宜，看你聽得這麼認真，加上老夫今日心情又不錯，就教你兩手絕活。"},
	[58925] = {CommonPl = "挖礦就是賭命，你有幾條命？有九條那是貓，貓不挖礦，牠不混江湖，你一條命，你還混江湖，江湖講什麼？“兵戈”，掂掂你手上這把，幾斤？幾兩幾？夠不上斤兩，不夠就跟我學學怎麼弄到好石頭。算命的騙你十年八年，我算哄你不騙你，怎麼樣？學不學？"},
	[58926] = {CommonPl = "學養牲口，我沒聽錯？你們這些年輕人不是都養什麼貓狗兔子，誰有興趣來學養牲口。我不會？哈哈！可惡，激將法，正中我的死穴，我就非給你看看我的本事！"},
	[58895] = {CommonPl = "做生意，講究的是公平交易。\r我這兒的裝備可都是百裡挑一的良品，想要？且拿出同等價值的物什來兌換。"},
	[58896] = {CommonPl = "做生意，講究的是公平交易。\r我這兒的裝備可都是百裡挑一的良品，想要？且拿出同等價值的物什來兌換。"},
	[58907] = {CommonPl = "這鍋裡打滾兒的東西，無非酸甜苦辣，你想做啥，完全在於你的心情，你要高興做出來的菜都能笑。不信？你看“居月樓”吃我菜的人個個都在笑。這鍋子能煮熟很多東西，除了人，不然該成熟人了，哈哈！"},
	[58908] = {CommonPl = "靠山吃山，靠水吃水，我們靠的是林場，做的是手工活，做手工活的人不會說太多，所以只能靠自己多看多學，你如果能做到，就拿工具跟我學。"},
	[58909] = {CommonPl = "人既然吃五穀雜糧，就免不了被病疾纏身，得病的人，有得醫的是命，沒得醫的是命，命中註定，你就算捧個百寶箱都得死。凡世間的草藥不是天上神仙種來，吃下去百病全消，所以才有擇藥醫人的學問。"},
	[58910] = {CommonPl = "這幾年棉花收成不好，家裡那死小子又不長進，說什麼也不願繼承我這手藝，要去華山學武，學武有什麼好，整天喊打喊殺，所以我決定趁現在還能動彈給他留點錢，至於這門手藝就只有留給有緣人了。"},
	[58911] = {CommonPl = "金石木竹，本就為天生天養之物，若要提煉出它們與生的靈氣，豈是朝夕可成，想學頂尖的金石之技，那得看你的資質，不過有句話我要提醒你“金石無心人有心。”如果有天你忘了這句話，你就變得和你手中的金石一樣冰冷。"},
