	[58943] = {CommonPl = "人既然吃五穀雜糧，就免不了被病疾纏身，得病的人，有得醫的是命，沒得醫的是命，命中註定，你就算捧個百寶箱都得死。凡世間的草藥不是天上神仙種來，吃下去百病全消，所以才有擇藥醫人的學問。"},
	[58944] = {CommonPl = "這幾年棉花收成不好，家裡那死小子又不長進，說什麼也不願繼承我這手藝，要去華山學武，學武有什麼好，整天喊打喊殺，所以我決定趁現在還能動彈給他留點錢，至於這門手藝就只有留給有緣人了。"},
	[58945] = {CommonPl = "金石木竹，本就為天生天養之物，若要提煉出它們與生的靈氣，豈是朝夕可成，想學頂尖的金石之技，那得看你的資質，不過有句話我要提醒你“金石無心人有心。”如果有天你忘了這句話，你就變得和你手中的金石一樣冰冷。"},
	[59936] = {CommonPl = "在下負責把守各個挑戰副本的入口。"},
