	[62899] = {CommonPl = "江湖上從來都是拳頭大的有道理，不服氣就來踢館試試。不過本使對外不對內，想踢哪個幫就去找他們幫的招討使才行。"},
	[62897] = {CommonPl = "江湖上從來都是拳頭大的有道理，不服氣就來踢館試試。不過本使對外不對內，想踢哪個幫就去找他們幫的招討使才行。"},
	[64714] = {CommonPl = "因為在踢館戰鬥中受了傷，半個時辰之內無力召開宴會，請見諒。"},
	[64715] = {CommonPl = "因為在踢館戰鬥中受了傷，半個時辰之內無力召開宴會，請見諒。"},
	[64716] = {CommonPl = "因為在踢館戰鬥中受了傷，半個時辰之內無力召開宴會，請見諒。"},
	[64717] = {CommonPl = "因為在踢館戰鬥中受了傷，半個時辰之內無力召開宴會，請見諒。"},
	[66320] = {CommonPl = "為天地立心\r為生民立命\r為往聖繼絕學\r為萬世開太平"},
	[64535] = {CommonPl = "砍倒了對方的幫派大旗就可以來塗鴉，不過只有踢館發起者和幫主才有這個權力。我很忙所以停留的時間有限，抓緊呦！"},
	[64536] = {CommonPl = "砍倒了對方的幫派大旗就可以來塗鴉，不過只有踢館發起者和幫主才有這個權力。我很忙所以停留的時間有限，抓緊呦！"},
	[64537] = {CommonPl = "砍倒了對方的幫派大旗就可以來塗鴉，不過只有踢館發起者和幫主才有這個權力。我很忙所以停留的時間有限，抓緊呦！"},
	[64538] = {CommonPl = "砍倒了對方的幫派大旗就可以來塗鴉，不過只有踢館發起者和幫主才有這個權力。我很忙所以停留的時間有限，抓緊呦！"},
	[29979] = {CommonPl = "以前鏢局門簷有窩燕子，每到春天燕子就會飛回來，就像進進出出的鏢師們。早六年大旱，鏢局押著糧草南下賑災，半路遭難民搶糧，原來賑災糧都被那些狗官給私吞了。我們是人，不能無情，我們也是鏢師，不能失鏢。所以我自殘雙腿，讓百姓分了糧草，也犯下大錯。人就像燕子，沒了翅膀就飛不回來了，隔年老鏢頭找來福州背著我回到這個窩。故事說完，說正事。"},
	[68282] = {CommonPl = "誰上山狠狠揍那群混蛋，我就送他點好貨。總之誰欺負我家弟兄，我就鼓搗鼓搗他個心肝脾肺腎！"},
	[68283] = {CommonPl = "我家可是暴發戶，別看兄弟我這身打扮，這叫扮豬兒吃老虎。"},
	[68284] = {CommonPl = "這周圍的野味都被我吃完了，你看能不能讓他給我換個地方，我自己走不了……你知道他是誰，你懂的。"},
	[68285] = {CommonPl = "東方教主千秋萬載一統江湖。這黑木崖的口號，我選擇用陝北民歌的方式表達出來……看你的樣子不是太想聽啊?"},
	[70658] = {CommonPl = "老夫愛武成狂，雖然不知此間是何時何世，但只要遇到天下高手總忍不住想痛快一戰！"},
	[70659] = {CommonPl = "我縱橫天下多年，經歷過無數激烈壯絕的情景歷歷在目。你若想成為江湖中的新一代傳奇，不妨聽我說一說當代的英雄事蹟。"},
	[71956] = {CommonPl = "哈哈哈，你最近可是名聲鵲起了。你若想成為江湖中的新一代傳奇，何不聽我說一說當代的英雄事蹟。"},
	[71725] = {CommonPl = "#N，很高興看到你。\r一旦重傷昏迷，復生後會很虛弱，氣血和內力都非常低。\r這種情況下，不要忘了來福州、衡山、洛陽等地找我或我的同伴，我們可以為你提供治療。\r在安全復生後會有重傷標記，上次重傷的地點和敵人會有提示，可以透過系統提示或傳送旗返回。"},
