	[72712] = {CommonPl = "走南闖北，身上的帶的東西多了都是累贅，大俠出手，那都得飄逸，飄逸你懂嗎？\r所以多餘的東西就放我這裡吧，放心吧，保證不會丟！"},
	[72713] = {CommonPl = "走南闖北，身上的帶的東西多了都是累贅，大俠出手，那都得飄逸，飄逸你懂嗎？\r所以多餘的東西就放我這裡吧，放心吧，保證不會丟！"},
	[72714] = {CommonPl = "本店經過新的整修，現正式開業，想要淘寶或是出貨，都來我這裡！"},
	[72749] = {CommonPl = "客官好，請問您要去哪裡？"},
	[72750] = {CommonPl = "客官好，請問您要去哪裡？"},
