	[44625] = {CommonPl = "南來北往，咱們鏢局中人靠的是信用和腳力，最近人手不夠，壓下了不少生意。\r少俠可否順道幫押趟鏢？報酬嘛自然少不了。"},
	[44634] = {CommonPl = "南來北往，咱們鏢局中人靠的是信用和腳力，最近人手不夠，壓下了不少生意。\r少俠可否順道幫押趟鏢？報酬嘛自然少不了。"},
