	[63991] = {CommonPl = "闖蕩江湖，沒有一把好武器可不行。\r我這裡貨品齊全，童叟無欺，雙刀，單劍，軟鞭一應俱全。\r這位#Y,你想要點什麼？"},
	[63992] = {CommonPl = "人靠衣裝，馬靠鞍。\r出門在外，難免碰到颳風下雨濕了衣服，還是多備兩件妥當。"},
	[63993] = {CommonPl = "是藥三分毒，所以才會有“良醫救人，庸醫殺人”這種說法。\r不過我這裡的藥，保管你藥到病除不留根，強身健體不上火！"},
