	[78906] = {CommonPl = "這位#Y，我看你筋骨奇異，脈象特殊，一股紫光從天靈蓋直竄到腳底心。如何，要不要老衲幫你蔔上一卦？"},
	[70724] = {CommonPl = "呵呵，我美嗎？"},
	[79731] = {CommonPl = "傳說有一個神秘的島，有些人去過之後就發了財，有些人去了之後再也沒回來。你敢去看看嗎？"},
	[79915] = {CommonPl = "#N，很高興看到你。\r一旦重傷昏迷，復生後會很虛弱，氣血和內力都非常低。\r這種情況下，不要忘了來福州、衡山、洛陽等地找我或我的同伴，我們可以為你提供治療。\r在安全復生後會有重傷標記，上次重傷的地點和敵人會有提示，可以透過系統提示或傳送旗返回。"},
