	[81361] = {CommonPl = "在天下第一武道會中力挫群雄，贏得比賽者可重鑄此像，供世人敬仰。"},
	[81557] = {CommonPl = "你好，我是寶石商人！把你用不上的寶石出售後，商人們會退給你一些寶石碎片。我可以回收這些碎片助你變廢為寶。你能得到有用的寶石，這些碎片我也自有妙用，你我皆大歡喜，可好？"},
	[81558] = {CommonPl = "你好，我是寶石商人！把你用不上的寶石出售後，商人們會退給你一些寶石碎片。我可以回收這些碎片助你變廢為寶。你能得到有用的寶石，這些碎片我也自有妙用，你我皆大歡喜，可好？"},
	[81559] = {CommonPl = "你好，我是寶石商人！把你用不上的寶石出售後，商人們會退給你一些寶石碎片。我可以回收這些碎片助你變廢為寶。你能得到有用的寶石，這些碎片我也自有妙用，你我皆大歡喜，可好？"},
	[82051] = {CommonPl = "傳說在一年之初，放煙花許願，神明便會聽到你的心願！大家快來買煙花吧！"},
	[83041] = {CommonPl = "曾經不代表現在，現在決定未來！我是導師詩蔓，歡迎更多的學員加入哦！"},
	[83047] = {CommonPl = "曾經不代表現在，現在決定未來！我是導師詩蔓，歡迎更多的學員加入哦！"},
	[83048] = {CommonPl = "曾經不代表現在，現在決定未來！我是導師詩蔓，歡迎更多的學員加入哦！"},
	[83367] = {CommonPl = "我準備了一些獎勵供您用寶銀兌換，並且將來還會有新的貨物不定期更新，敬請期待！\r感謝您對『笑傲江湖OL』的支持和厚愛！\r您當前的寶銀：∧寶銀數∨。"},
	[84731] = {CommonPl = "你好，我是神器兌換使者，願意為你效勞。"},
	[84967] = {CommonPl = "#N，很高興看到你。\r一旦重傷昏迷，複生後會很虛弱，氣血和內力都非常低。\r這種情況下，不要忘了來福州、衡山、洛陽等地找我或我的同伴，我們可以為你提供治療。\r在安全複生後會有重傷標記，上次重傷的地點和敵人會有提示，可以通過系統提示或傳送旗返回。"},
	[84968] = {CommonPl = "#N，很高興看到你。\r一旦重傷昏迷，複生後會很虛弱，氣血和內力都非常低。\r這種情況下，不要忘了來福州、衡山、洛陽等地找我或我的同伴，我們可以為你提供治療。\r在安全複生後會有重傷標記，上次重傷的地點和敵人會有提示，可以通過系統提示或傳送旗返回。"},
	[84969] = {CommonPl = "#N，很高興看到你。\r一旦重傷昏迷，複生後會很虛弱，氣血和內力都非常低。\r這種情況下，不要忘了來福州、衡山、洛陽等地找我或我的同伴，我們可以為你提供治療。\r在安全複生後會有重傷標記，上次重傷的地點和敵人會有提示，可以通過系統提示或傳送旗返回。"},
	[24864] = {CommonPl = "一副擔子走千里，針頭線腦全包羅。\r紅頭繩——狗娃哨——要啥有啥喲——\r客官，有什麼需要的嗎？"},
	[83387] = {CommonPl = "安全交易，買賣無憂，尋寶天行專員給您最優質的服務！\r<溫馨提示>\r1、選擇尋寶交易服務可進行物品和金錢的寄售（交易成功需要收取手續費，具體說明見尋寶天行-幫助中心-手續費）；也可即時查看到與自己相關的寄售資訊（安全鎖狀態下除外）。\r2、選擇尋寶天行服務可快捷流覽和打開尋寶天行網頁。\r3、商品的購買和下架等操作需要登陸尋寶天行-笑傲頁面，有問題請及時與客服聯繫。\r4、交易玩家角色時，角色擁有的寵物等級將重置為1級。"},
	[85562] = {CommonPl = "請到問天處領取“冰糖雪梨大禮包”。"},
	[86282] = {CommonPl = "幻一個裝束，換一份心情。\r歡迎客官體驗這來自西域的變化玄奇之術。"},
	[86283] = {CommonPl = "幻一個裝束，換一份心情。\r歡迎客官體驗這來自西域的變化玄奇之術。"},
	[86284] = {CommonPl = "幻一個裝束，換一份心情。\r歡迎客官體驗這來自西域的變化玄奇之術。"},
	[86704] = {CommonPl = "這位英雄您要駕著運送物資的鏢車到邊疆支援？？恕在下直言，路途艱辛危險重重，不過閣下就可以在我這裡消費1錠銀子進行投保，我們鏢師們會保護您，避免鏢車受損的情況，還可以獲得額外的好處，如果您遭遇不測也沒關係，我們鏢行會加倍賠償您！！"},
	[86285] = {CommonPl = "哎。。。最近忙死我了，邊疆戰火頻頻，物資奇缺，什麼時候能夠恢復和平啊！！！眼下在下正在發愁運送物資到邊疆的軍事，誰願意幫幫我啊，我絕對不會讓他吃虧的！！！！！"},
	[86706] = {CommonPl = "如果你是盟主所在幫派的成員，那麼每天你支援邊疆的時候可以直接來找我，我會幫你托運，這樣你就不必再拉著物資東奔西跑了，這可是盟主大人下發的特權哦！！！！"},
	[86766] = {CommonPl = "親，你想由禦姐變蘿莉嗎？想由蘿莉變禦姐嗎？我可以讓你即刻擁有自己想要的體型哦！\r^4a766e轉換體型後現有形象將被更換，如果喜歡現有形象，請到詩音處先保存形象再來轉換體型^000000"},
	[86723] = {CommonPl = "感謝各位官員對天下會嘔心瀝血的付出與縝密細緻的管理，你們是最棒的！\r每週日13:00-23:00為軍餉發放時間，在下特意為十大高級官員與10名飛龍軍準備了專屬禮包！\r請恕在下多囉嗦一句，十大官員的紫裝現已用禮盒包裝,與軍餉一起發放.最終產出的部件位置和屬性未知,但裝備等級與自身等級掛鉤！"},
	[86791] = {CommonPl = "盟主大人和蒼穹賢士，身為天下會的軍師我有必要告訴二位，你們一定要合理安排開啟活動的時間，讓所有英雄能夠積極回應您的號召，讓盟主大人能夠坐穩稱霸武林的寶座！！"},
	[86810] = {CommonPl = "戰場開啟後,我送攻方進入戰場。\r開啟時間：週三、週日19：00。\r雪鎮之爭須知：\r戰場結束後，雙方最終獲得的雪戰積分高的一方獲勝。\r如果雙方獲得的雪戰積分相同，守方獲勝！\r^FF0000雪戰兇險，僅限60級以上大俠參與！\r^7093DB戰場內玩家之間等級差大於15級，將不能獲得戰績！^000000"},
	[86935] = {CommonPl = "戰場開啟後,我送守方進入戰場。\r開啟時間：週三、週日19：00。\r雪鎮之爭須知：\r戰場結束後，雙方最終獲得的雪戰積分高的一方獲勝。\r如果雙方獲得的雪戰積分相同，守方獲勝！\r^FF0000雪戰兇險，僅限60級以上大俠參與！\r^7093DB戰場內玩家之間等級差大於15級，將不能獲得戰績！^000000"},
	[86949] = {CommonPl = "雪鎮之爭結束後，根據當場獲得的雪戰積分，可找我兌換武勳。\r傳奇獎勵：積分4000以上\r輝煌獎勵：積分2500-3999\r榮耀獎勵：積分1200-2499\r英雄獎勵：積分600-1199\r勇者獎勵：積分300-599\r戰士獎勵：積分100-299\r消極怠戰：積分低於100不與兌換。\r當前擁有雪戰積分：^7093DB∧雪戰積分∨\r^FF0000戰場內獲得的雪戰積分，必須當天兌換完畢，否則過期作廢！^000000"},
	[86690] = {CommonPl = "閣下首次進入天下會之後就可以通過各個地區的驛站老闆那裡傳送到天下會，參加每天的活動了！"},
	[86286] = {CommonPl = "邊疆戰火紛紛，支援邊疆義不容辭，能者多勞，我不會虧待你們的，想支援邊疆，去天下會找孫將軍吧！"},
	[86779] = {CommonPl = "邊疆戰火紛紛，支援邊疆義不容辭，能者多勞，我不會虧待你們的，想支援邊疆，去天下會找孫將軍吧！"},
	[87013] = {CommonPl = "我不光能醫人，還能醫裝備。"},
	[87014] = {CommonPl = "我不光能醫人，還能醫裝備。"},
	[86953] = {CommonPl = "戰場結束後，我負責送守方回城。"},
