	[86983] = {CommonPl = "天下之會，傲視群雄；一統江湖，誰與爭鋒。"},
	[87077] = {CommonPl = "天上飛的地上跑的，三條眼睛四條腿的，只要是活的沒有我這找不到的！"},
	[87078] = {CommonPl = "什麼？您要千年靈芝？不是我唬您，我這小攤上一顆看似普通的藥草都比那千年靈芝值錢！"},
	[87371] = {CommonPl = "想要獲得獨一無二的時裝嗎？不如來我這裡看看。"},
	[87030] = {CommonPl = "闖蕩江湖，沒有一把好武器可不行。\r我這裡貨品齊全，童叟無欺，雙刀，單劍，軟鞭一應俱全。\r這位#Y,你想要點什麼？"},
	[87031] = {CommonPl = "人靠衣裝，馬靠鞍。\r出門在外，難免碰到颳風下雨濕了衣服，還是多備兩件妥當。"},
	[87028] = {CommonPl = "是藥三分毒，所以才會有“良醫救人，庸醫殺人”這種說法。\r不過我這裡的藥，保管你藥到病除不留根，強身健體不上火！"},
	[87029] = {CommonPl = "走南闖北，身上的帶的東西多了都是累贅，大俠出手，那都得飄逸，飄逸你懂嗎？\r所以多餘的東西就放我這裡吧，放心吧，保證不會丟！"},
	[87045] = {CommonPl = "#N，很高興看到你。\r一旦重傷昏迷，複生後會很虛弱，氣血和內力都非常低。\r這種情況下，不要忘了來找我或我的同伴，我們可以為你提供治療。"},
	[87025] = {CommonPl = "福州、衡山還有洛陽都是當世有名的大城，前去路上自然一片坦途。"},
	[87026] = {CommonPl = "福州、衡山還有洛陽都是當世有名的大城，前去路上自然一片坦途。"},
	[58708] = {CommonPl = "福州、衡山還有洛陽都是當世有名的大城，前去路上自然一片坦途。"},
	[62898] = {CommonPl = "江湖上從來都是拳頭大的有道理，不服氣就來踢館試試。不過本使對外不對內，想踢哪個幫就去找他們幫的招討使才行。"},
	[87044] = {CommonPl = "幫派行不行先看設施齊不齊，營建的事找我准沒錯。"},
	[87043] = {CommonPl = "江湖上的英雄好漢看著光鮮，實則大多是錢堆的，沒錢誰識得你是何許人也。"},
	[60101] = {CommonPl = "聰明人要學會借力，瑣碎之事有人代勞豈不快哉？"},
	[87035] = {CommonPl = "大江南北的奇事、前朝歷代的寶藏，我這裡都有消息，要不要瞧瞧？"},
	[87040] = {CommonPl = "開心了要喝，寂寞了要喝，成功了要喝，落難了要喝，不喝哪算江湖中人？"},
	[87032] = {CommonPl = "世人常說寶物鎮有氣運，幫派會因為得到一個寶物而興，自然也會因為失去一個寶物而衰。"},
	[87038] = {CommonPl = "再希奇古怪的東西，往細了分析都不過是若干種常見元素的雜糅，只看你夠不夠眼力罷了。"},
	[87037] = {CommonPl = "工具、人力都是資材，別以為我們這兒又是另一個倉庫。"},
	[87039] = {CommonPl = "幫派建築“奇物居”需要幫派建設度達到5000才能開啟，不過奇物異制的活兒還是由我兼著，等奇物居開放後活動的獎勵就更高了。"},
	[87042] = {CommonPl = "幫派建築“後勤處”需要幫派建設度達到15000才能開啟。"},
	[87034] = {CommonPl = "幫派建築“藏寶閣”需要幫派建設度達到33500才能開啟。"},
	[87041] = {CommonPl = "幫派建築“廣場”需要幫派建設度達到5000才能開啟。"},
	[87074] = {CommonPl = "走過路過不要錯過，我這賣的可都是稀有寶貝，一般人我不告訴他！"},
	[87075] = {CommonPl = "客官您仔細瞧瞧，這可都是我從各地搜來的特產，錯過了您可再也找不著！"},
	[87993] = {CommonPl = "江山如此多嬌，快來收集風物志吧！這是個坑我才不會告訴你們呢……"},
	[87985] = {CommonPl = "跨地圖做任務是不是萌萌的？交不了任務是不是萌萌的？若不是有我在你們就跪了~"},
	[88325] = {CommonPl = "什麼是浪漫？什麼是孤獨？你永遠不會懂我！因為你體會不到這種境界。"},
	[89843] = {CommonPl = "我是2014笑傲江湖“蓋世杯”世界聯賽冠軍得主---打工皇帝唐駿!\r^4a766e“與其瞻仰他人，不如自己便成為那個人”！"},
	[92426] = {CommonPl = "世間萬物，輪回往生"},
	[93229] = {CommonPl = "神兵出鞘，誰與爭峰。"},
	[93598] = {CommonPl = "權杖可兌換的獎勵物品已更新，歡迎各位俠士前來利用七星權杖和玉珊瑚進行兌換！\r"},
	[94666] = {CommonPl = "古墓成蒼嶺，幽宮象紫台。\r星晨七曜隔，河漢九泉開。\r有海人寧渡，無春雁不回。\r更聞松韻切，疑是大夫哀。\r秦皇陵地宮充滿了機遇挑戰,也充滿了危險與血腥!我奉命鎮守此處,就是為了告誡闖入者,若沒有足夠的實力,一定要慎入!"},
	[96146] = {CommonPl = "俗話說得好，人靠衣裳，馬靠鞍。我看少俠風度翩翩器宇不凡，可這寵物就有點……趕巧我這兒有祖上留下來的寵物裝備，不僅樣式好看，還能提升寵物的作戰能力。少俠，您得我眼緣，看上哪套裝備只管拿，這價格嘛，好說好說！"},
	[98821] = {CommonPl = "·活動期間，君臨天下伺服器中原隸屬於三生三世伺服器，並且滿足活動條件的玩家可領取如下補償：\r1.專屬大聖靈丹。使用後可享受30倍升級速度，最高可升至115級。\r2.靈草禮包（總共含1000顆靈草，每日使用一次靈草禮包可獲得100棵靈草，10天可全部開啟完畢）\r3.武尊令*2（打開禮包後獲得隨機屬性）\r4.風物石禮包（共含700個風物石，每日可打開禮包獲得100個風物石，7天可全部開啟完畢）\r·活動期間，君臨天下伺服器中原隸屬於浪蕩乾坤伺服器，並且滿足活動條件的玩家可領取如下補償：\r1.武尊令*1（打開禮包後獲得隨機屬性）\r2.靈草禮包（總共包含500棵靈草，每日使用一次禮包可獲得50棵靈草，10天可全部開啟完畢）\r3.專屬大聖靈丹。使用後可享受30倍升級速度，最高可升至115級。\r4.風物石禮包（共含350個風物石，每日可打開禮包獲得50個風物石，7天可全部開啟完畢）\rPS:每個角色活動期間只可領取一次補償\r"},
	[100319] = {CommonPl = ""},
	[100402] = {CommonPl = "乾三連，坤六斷，震仰盂……八卦五行，玄之又玄！"},
	[100330] = {CommonPl = "最近官道上山賊猖獗，可苦了我們這些做生意的人。\r貴幫幫主跟我推薦你，說你武藝高強運鏢自然不在話下。你替我跑這一趟，報酬自然少不了你的！"},
	[100350] = {CommonPl = "嘿嘿，只要你的東西有價值，我給你東西也會有價值，大家都是自己人，你還怕我坑你。"},
	[100331] = {CommonPl = "哎呦，你可來了！我就等著這批緊俏貨出手，這些銀兩你收著，替我請兄弟們吃酒！"},
	[3334] = {CommonPl = "這兒便是傳說中的@T@少林木人巷@S@。\r自古以來，挑戰木人巷的少林弟子和江湖俠客極多，但其中能夠完全通過的屈指可數。闖關成功的高手對其中奧秘三緘其口，而更多的失敗者更是聞@E@“木人”@S@色變，絕口不提闖關慘敗的經歷。\r因此千百年，少林木人巷一直神秘莫測，民間傳說頗多。顧名思義，木人巷內有很多木人，但事實上，此處種種木制人偶，均為我等@I@魯家後人@S@所創，各種機關之精妙，舉世罕有。因此，木人巷充滿玄機與挑戰，不愧為少林寺最高武功的衡量。"},
	[3337] = {CommonPl = "前面就是是淨觸之間。\r此處是專是供少林弟子修練的。"},
	[3340] = {CommonPl = "這個大廳裡四處都是巡邏的守衛，如果你能找到香爐並點燃它，\r這些守衛就會誤以為是開關的信號，從而退散。"},
	[3343] = {CommonPl = "西面方間是了塵之間。\r此處是專是供少林弟子修練的。"},
	[3346] = {CommonPl = "師傅一再強調要同時拆掉這兩隻銅人，可殺了一隻後另一隻很快就消失了。\r難道是我的修為還不夠迅速拆掉這兩隻銅人？"},
	[3349] = {CommonPl = "這個房間的頭目正隱藏在某地，也許需要你多拆幾個銅人來激怒他？\r"},
	[3352] = {CommonPl = "我不喜歡說話，將來只賣雜貨。"},
	[3355] = {CommonPl = "#N，久違了。\r木人巷雖為練功之地，但如果沒有熱身就直接前往必定難免碰到麻煩，因此，還請務必在準備完美後再前往挑戰。\r當然，挑戰成功的話，得到的修練也自然不小。總之，若想練成一身真本事，多想、多看與多練，都是必不可少的。"},
	[3358] = {CommonPl = "正如你所見，我是負責掃地的……\r木人巷中的人偶均為鐵木製成，難免受傷，如果遇到麻煩老朽自會為助你一臂之力，請放心前往修練。"},
	[3361] = {CommonPl = "@F@（木人巷闖關內容寫在上面）"},
	[3364] = {CommonPl = "@F@（木人巷闖關內容寫在上面）"},
	[3367] = {CommonPl = "@F@（告示牌上寫著木人巷的注意事項）"},
	[3370] = {CommonPl = "@F@（告示牌上寫著木人巷的注意事項）"},
	[3373] = {CommonPl = "@F@（告示牌上寫著木人巷的注意事項）"},
	[3376] = {CommonPl = "@F@（銅人身上清晰的寫著：[開心銅人]）"},
	[3379] = {CommonPl = "@F@（銅人身上清晰的寫著：[歡喜銅人]）"},
