	[3394] = {CommonPl = "@F@（銅人身上清晰的寫著：[探手銅人]）"},
	[3397] = {CommonPl = "@F@（銅人身上清晰的寫著：[挖耳銅人]）"},
	[3400] = {CommonPl = "@F@（銅人身上清晰的寫著：[布袋銅人]）"},
	[3403] = {CommonPl = "@F@（銅人身上清晰的寫著：[芭蕉銅人]）"},
	[3406] = {CommonPl = "@F@（銅人身上清晰的寫著：[舉缽銅人]）"},
	[3409] = {CommonPl = "@F@（銅人身上清晰的寫著：[托塔銅人]）"},
	[3412] = {CommonPl = "@F@（銅人身上清晰的寫著：[長眉銅人]）"},
	[3415] = {CommonPl = "@F@（銅人身上清晰的寫著：[笑獅銅人]）"},
	[3418] = {CommonPl = "@F@（銅人身上清晰的寫著：[過江銅人]）"},
	[3421] = {CommonPl = "@F@（銅人身上清晰的寫著：[看門銅人]）"},
	[3424] = {CommonPl = "@F@（銅人身上清晰的寫著：[降龍銅人]）"},
	[3427] = {CommonPl = "@F@（銅人身上清晰的寫著：[伏虎銅人]）"},
	[3430] = {CommonPl = "聽說現有人在@T@淨觸之間@S@闖關，\r如果是師兄的話就快去吧。"},
	[3433] = {CommonPl = "聽說現有人在@T@脫俗之間@S@闖關，\r如果是師兄的話就快去吧。"},
	[3436] = {CommonPl = "聽說現有人在@T@了塵之間@S@闖關，\r如果是師兄的話就快去吧。"},
	[3439] = {CommonPl = "聽說現有人在@T@戒世之間@S@闖關，\r如果是師兄的話就快去吧。"},
	[3454] = {CommonPl = "聽說現有人在@T@歸業之間@S@闖關，\r如果是師兄的話就快去吧。"},
	[3442] = {CommonPl = "這個房間的高級木樁，必須得開啟隱藏機關方會出現。\r"},
	[3445] = {CommonPl = "真不愧是木人巷，\r比打蹈草人雖難，但也有趣多了。"},
	[3448] = {CommonPl = "#N也來啊，\r今天一定要出一身汗，好好練練。"},
	[3451] = {CommonPl = "吃得苦中苦，方為人上人！\r如果沒師父的教誨，估計我早就放棄了，天下武功出少林果然不簡單。"},
	[3457] = {CommonPl = "來這練了不到一月，\r身子果然結實多了……"},
	[6040] = {CommonPl = "世上本無事，庸人偏自擾。這世上癡人甚多，不要擾了姑姑的清淨才好。"},
	[6041] = {CommonPl = "長空凝翠，水光相親。清涼境裡醉花陰。\r樽前琴上江湖老，肯寄逍遙在竹林。"},
	[6042] = {CommonPl = "原來是令狐公子托閣下來修琴。\r只是……今日綠竹巷裡臥虎藏龍，實在不是拜訪的良時。\r在下不才，願斗膽一試，把這琴弦為令狐公子接上。"},
	[10407] = {CommonPl = "竟然有人敢來我福威鏢局挑釁，我倒要會會這是個什麼人！"},
	[10409] = {CommonPl = "這夥賊人太過囂張，福威鏢局的鏢師可不是他能殺的！"},
	[10445] = {CommonPl = "我早料今日有此一劫，勸你也是無用。\r“情”之一字，我尚不能勘破，又如何勸得了你。\r我所能為，全盡於此。\r師弟，你二人生能再合奏一曲，死能死在一處，卻是比我幸運得多。\r"},
	[10446] = {CommonPl = "咱們自居俠義道，與邪魔外道勢不兩立，這“俠義”二字，是什麼意思？\r欺辱身負重傷之人，算不算俠義？\r殘殺無辜幼女，算不算俠義？\r要是這種事情都幹得出，跟邪魔外道又有什麼分別？\r"},
	[10447] = {CommonPl = "昔日嵇康臨刑，撫琴一曲，歎息《廣陵散》從此絕響。\r《廣陵散》縱然精妙，又怎及得上咱們這一曲《笑傲江湖》？\r只是當年嵇康的心情，卻也和你我一般。\r"},
	[10448] = {CommonPl = "曲大哥剛才還甚達觀，卻又如何執著起來？\r你我今晚合奏，將這一曲《笑傲江湖》發揮得淋漓盡致。\r世上已有過了這一曲，你我已奏過了這一曲。\r人生於世，夫複何恨？\r"},
	[10449] = {CommonPl = "爺爺和劉叔叔有什麼錯？難道這偌大江湖，竟沒有一個地方能讓他們恣意合奏嗎？"},
	[10867] = {CommonPl = "我來助你一臂之力！"},
	[10868] = {CommonPl = "我來助你一臂之力！"},
	[10869] = {CommonPl = "我來助你一臂之力！"},
	[10875] = {CommonPl = "令狐沖之死輕於鴻毛，各位朋友不要再為我枉費力氣了。"},
	[10877] = {CommonPl = "令狐公子的傷，看來只能用我們苗人的法子來醫治了。"},
	[10938] = {CommonPl = "我在為令狐公子輸血，不敢有絲毫分心。"},
	[10892] = {CommonPl = "別管我，我只是被這些歹人點住了穴道，快去救小林子！\r他受了傷，怕是撐不住了！"},
	[10895] = {CommonPl = "我還扛得住，快去幫師姐。"},
	[10898] = {CommonPl = "劍宗為奪掌門之位，竟設下如此毒計。待我傷癒，定要清理門戶！"},
	[10901] = {CommonPl = "不要管我，快快去助師兄一臂之力！"},
	[10904] = {CommonPl = "我內力全失，眼見師門有難，卻使不出半點力氣，當真是枉自為人！還望閣下出手相助，一解華山危難。"},
	[11072] = {CommonPl = "在下被那蒙面老者點中穴道，動彈不得。我華山派上下，唯有仰仗英雄了。"},
	[23082] = {CommonPl = "原來我今日才知，這正教弟子，竟比魔教長老還殘忍十倍！"},
	[23083] = {CommonPl = "爺爺和劉叔叔有什麼錯？難道這偌大江湖，竟沒有一個地方能讓他們恣意合奏嗎？"},
	[23084] = {CommonPl = "我死在這裡不打緊，可是竟連累了劉賢弟！"},
	[23085] = {CommonPl = "我劉正風逃避了一世，今日能和曲大哥合奏一曲再死，劉某此生無憾！"},
	[23086] = {CommonPl = "今日之事，只有索性將這些妖人一併殺了。"},
	[23299] = {CommonPl = "竟然有人敢來我福威鏢局挑釁，我倒要會會這是個什麼人！"},
	[23300] = {CommonPl = "這夥賊人太過囂張，福威鏢局的鏢師可不是他能殺的！"},
	[23301] = {CommonPl = "這些青衣人武功這麼高！"},
	[23302] = {CommonPl = "聽這些人的口音像是川人。"},
	[23303] = {CommonPl = "啊，我負傷了。"},
	[23304] = {CommonPl = "拼了命也要保住鏢局！"},
	[23305] = {CommonPl = "這群該死的青衣人，到底從什麼鬼地方來的！"},
	[23306] = {CommonPl = "沒力氣了……官府也不管管嗎？"},
	[23307] = {CommonPl = "一定要頂住啊！"},
	[23308] = {CommonPl = "難道是我們鏢局的仇家？"},
