	[29160] = {CommonPl = "1級雜貨鋪，可以升級為2級雜貨鋪。1把摺扇50銅錢，1個馬鞍80銅錢。"},
	[29163] = {CommonPl = "2級雜貨鋪，可以升級為3級雜貨鋪。2把摺扇100銅錢，2個馬鞍160銅錢。"},
	[29166] = {CommonPl = "3級雜貨鋪，已達最高等級。3把摺扇150銅錢，3個馬鞍240銅錢，1個百寶箱150銅錢。"},
