	[29187] = {CommonPl = "2級涼茶攤，可以升級為3級涼茶攤。2杯茶水100銅錢，3塊糕點160銅錢。"},
	[29190] = {CommonPl = "3級涼茶攤，已達最高等級。3杯茶水150銅錢，3塊糕點240銅錢，1個歸去來250銅錢。"},
	[29193] = {CommonPl = "逛窯子，就該有把漂亮的摺扇。"},
	[29196] = {CommonPl = "老闆，快給俺拿個既結實又牢固的馬鞍！"},
	[29199] = {CommonPl = "大隱隱於市，像葵花寶典一樣強大的武林秘笈也許就藏在這兒呢。"},
	[29202] = {CommonPl = "聽說最近流行一種秘藥，吃了之後能夠返老還童。"},
	[29205] = {CommonPl = "店家，來杯茶水，天氣燥熱，我這把老骨頭可受不了。"},
	[29208] = {CommonPl = "娘，給我買快糕點來吃吧。"},
	[29211] = {CommonPl = "打劫！要想老子放你一條生路，快把銅錢交出來！"},
	[29217] = {CommonPl = "想買好東西的快來看看喲，我這裡無奇不有。"},
	[29214] = {CommonPl = "咱就是銅錢多，商品要買就買最高級的。"},
