	[36783] = {CommonPl = "在下不過只是個無名的說書人而已。"},
	[36786] = {CommonPl = "各式各樣稀奇的罐子，我這裡都有！"},
	[36789] = {CommonPl = "藥沒那麼貴，我也沒那麼黑。"},
	[37358] = {CommonPl = "歡迎來到神秘黑店，今天客人可以體驗到【青城突破】和【聯手】兩出精心準備的評書，請多提意見！"},
	[36861] = {CommonPl = "師叔不顧咱們，獨自下山探親，這一路上好吃的好玩的不知要見識多少。"},
	[36864] = {CommonPl = "風師叔身系劍宗前途，一定要照顧好自己的身體。"},
	[36867] = {CommonPl = "如今劍氣兩宗之爭愈演愈烈，風師叔卻能置身事外，不偏不倚，果然是一代宗師風範。"},
	[36870] = {CommonPl = "我沒種哦！"},
	[36873] = {CommonPl = "其他劍宗師叔都凶的要吃人，還是風師叔和藹。"},
	[36876] = {CommonPl = "我沒種哦！"},
	[37292] = {CommonPl = "今日華山劍宗一敗塗地，不知何時才能東山再起。"},
	[37295] = {CommonPl = "卑鄙！無恥！氣宗各個都是陰險小人。"},
	[37298] = {CommonPl = "我是怪哦！"},
	[37301] = {CommonPl = "劍氣大戰慘烈至此，我真的不希望再死人了！"},
	[37304] = {CommonPl = "我死了哦！"},
	[37307] = {CommonPl = "我死了哦！"},
	[37310] = {CommonPl = "我死了哦！"},
	[37313] = {CommonPl = "我死了哦！"},
	[37316] = {CommonPl = "我死了哦！"},
	[37319] = {CommonPl = "我死了哦！"},
	[37322] = {CommonPl = "我死了哦！"},
	[37421] = {CommonPl = "劍宗之人平日裡耀武揚威，卻有勇無謀，師叔們略施小計便將他們一網打盡。"},
	[55974] = {CommonPl = "情勢不妙，難道華山派多年基業，真要垮在我岳不群手裡？"},
	[55977] = {CommonPl = "就算是死，也要保證孩子們的安全……"},
	[55980] = {CommonPl = "只要還有一口氣，就要保護好師父師娘和眾師兄妹的安全！"},
	[55983] = {CommonPl = "我……我還不想死……"},
	[55986] = {CommonPl = "（冷冷看著眼前眾人，面無表情。）"},
	[55989] = {CommonPl = "大師兄！師父要被壞人抓走啦！"},
	[55992] = {CommonPl = "保護師父！"},
	[55995] = {CommonPl = "看劍！"},
	[55998] = {CommonPl = "左掌門胸中的乾坤，豈是這些凡夫俗子能知曉！"},
	[56001] = {CommonPl = "左掌門胸中的乾坤，豈是這些凡夫俗子能知曉！"},
	[56004] = {CommonPl = "我深山隱居十五年，練成這一百零八式狂風快劍，定要將岳不群這氣宗偽君子推下掌門之位！"},
	[56007] = {CommonPl = "華山派劍、氣兩宗的爭鬥，由我來將它終結，就在今天！"},
	[56010] = {CommonPl = "五嶽劍盟，嵩山為尊！"},
	[56013] = {CommonPl = "殺！"},
	[60718] = {CommonPl = "前方就是百毒禁地的第一隻守護獸，如果有膽量的話，就跳下去吧。\r要記住，前面迎接你的是百蟲陣的挑戰，在進入大廳後，只有先毀掉十五個蟲卵，守護獸才會現身。"},
	[60719] = {CommonPl = "競然闖過了第一關，你的實力還真不可小視，不過下面就沒這麼簡單了。\r經過數種蜘蛛的考驗後，你就可以見到第二隻守護獸。"},
	[60720] = {CommonPl = "之前還從來沒有見過有人到這，剩下的即將是最強的挑戰。\r沿著萬毒道一路下去，即可見到最終守護獸，看看你的實力吧。"},
	[60721] = {CommonPl = "#N，我見到了你們的實力。\r按先前所說，如有需要老朽一定助爾等一臂之力。"},
	[60722] = {CommonPl = "@F@(巨大的蛾卵立於大廳正中)"},
	[66826] = {CommonPl = "#N，謝謝你的幫忙。\r據我的親信調查到到的消息，任教主就備困在梅莊裡，沒想到的是水下還有這樣大一座地牢，我在這兒守住追兵，你們前去前方探一探。\r各位俠士請先行一步，我們牢底會合！"},
	[66827] = {CommonPl = "竟然這事要我來出手，看來他們還是火侯不夠，這事是東方大人親屬的，讓你們過去了我們可擔待不起。\r看你們也不像是來砸場子的人，我就用我的琴來和你們鬥鬥吧，不過，如果身法不足，要在我的琴聲下存活下來可也是一件難事呢。\r準備好了就開始吧！"},
	[66828] = {CommonPl = "梅莊四莊主的迷陣，你們已通過了一半，真想不你們有這樣的實力。\r如果想繼續前進，就得通過我的黑白迷蹤陣了，如果你能在規定時間內贏得比我更多的棋子，就可通過考驗，不過，這只是這個迷陣的第一步哦，至於後面還有什麼，等你先通過了第一步再說吧。\r讓我見識一下你們的實力吧。"},
	[66829] = {CommonPl = "能闖到這兒，說明你們還是有兩把刷子，怎麼樣，敢來挑戰下我的乾坤書魂陣嗎。\r記住，前面這方硯臺中有大量壯志未籌的書法家的魂魄，你需要用濃墨和清水調配出調配出恰當濃度的墨汁，才能讓這書魂聽從你的號令。關鍵就在打開開關的時機和時長了。\r如果準備好了，請隨時告訴我！"},
	[66830] = {CommonPl = "想通過畫房可沒那麼容易，需要先通過我的百獸圖陣考驗才行。\r怎麼？怕了？現在點右上角的退出副本還來得及，勉強挑戰只怕你的小命都會留在此處。\r如果想拿雞蛋碰石頭，就來試試吧！"},
	[66831] = {CommonPl = "#N，原來任我行大人被困在此處。\r以前就聽說梅莊水下來有一座地牢，原來通過了水下梅莊四房後，還有這樣一座洞天，任教主被關了很久了，我馬上去為他解開腳蹽。\r我有種不好的感覺，各位小心一點！"},
	[66832] = {CommonPl = "（任我行被困在冷冰冰的鐵床上）"},
	[66833] = {CommonPl = "我們終於把任教主救出來了。\r大家儘快從這兒逃出，與令狐沖會合後，我們儘快作一個萬全之計，一定要奪回日月教，讓東方不敗嘗嘗種下的苦果。\r#N，為了感謝你的幫忙，這點小禮物請收下吧，這是你應得的！"},
	[72247] = {CommonPl = "一個黑漆漆的火藥桶，旁邊有根引導線，點燃似乎可以將火藥桶引爆。"},
	[73644] = {CommonPl = "連雲堡大門堅固，且有弓箭手把守，不易攻破。穿過瀑布可抵達堡壘側門，此路雖險，但能節約不少時間。"},
	[73645] = {CommonPl = "少俠若對自己的腳下功夫頗有信心，不妨跳上老夫身後的石柱，這連串的石柱直通第二堡的側門。\r若不慎墜落，可順著鐵鍊重新爬回柱頂。第二、三條鐵鍊在擊碎柱頂石燈後才可使用。"},
	[73646] = {CommonPl = "從此處下坡後前行有一處山崖，身手矯健者可借助古樹、岩石直達崖頂的堡壘側門。"},
	[72514] = {CommonPl = "幸會幸會，你可以叫我風流倜儻玉樹臨風小田田。"},
	[72515] = {CommonPl = "幸會幸會，你可以叫我風流倜儻玉樹臨風小田田。"},
