	[72523] = {CommonPl = "幸會幸會，你可以叫我風流倜儻玉樹臨風小田田。"},
	[72524] = {CommonPl = "幸會幸會，你可以叫我風流倜儻玉樹臨風小田田。"},
	[74477] = {CommonPl = "多謝各位相助，教主脫困指日可待。"},
	[79776] = {CommonPl = "此處危機四伏，各位多加小心！"},
	[79709] = {CommonPl = "擊敗所有敵人，便可開啟出口大門"},
	[79710] = {CommonPl = "余神教長老周燕鴻，知東方賊子犯上作亂，任教主不知去向，結義兄弟向問天自甘墮落，為東方賊子趨勢，恨不能生食其肉。幸而聽聞，東方賊子所練葵花神功傳自皇陵之中，乃前往長陵盜寶，尋求克制葵花寶典之發。只求他日盡誅賊子，迎奉任教主歸還黑木崖。"},
	[79711] = {CommonPl = "同心同德\r點化三客"},
	[79712] = {CommonPl = "這裡邊佈滿各種零碎的東西，但已無機關存在，顯然已經被前人探索完了。"},
	[79713] = {CommonPl = "這裡邊佈滿各種零碎的東西，但已無機關存在，顯然已經被摸金校尉探索完了。"},
	[79714] = {CommonPl = "欲練神功，引刀自宮，孰知不必自宮，亦可成功。葵花寶典，三寶太監，害人不淺！余日月神教左使楊信陵，早年不幸，誤得神功，以致抱撼終生。一人孤寂，縱然天下無敵又有何用。乃索天下有情女子百人魂魄，拘於此地，看有情人生死相離，足慰平生！紅娘月老，天公地道，能耐我何！"},
	[79715] = {CommonPl = "這裡的佈局有些古怪，隱藏著機關。有些物件散落四處，莫非是前人前來探墓留下的關鍵用品。"},
	[79716] = {CommonPl = "日月初升陰霾既去"},
	[79717] = {CommonPl = "這裡的佈局有些古怪，隱藏著機關。有些物件散落四處，莫非是前人前來探墓留下的關鍵用品。"},
	[79718] = {CommonPl = "據說段譽在神仙姐姐的雕像前磕了好些頭，把蒲團磕破了，然後收穫了一本淩波微步。"},
	[79719] = {CommonPl = "吾等四人，乃聖上御前陣殿將軍，隨李景隆平燕王之亂。豈料景隆臨陣無謀，不如三歲孩童，致使我軍，屢戰屢敗，數十萬將士，埋骨沙場。賊子景隆，賣主求榮，獻關投敵，致聖上兵敗身上。吾等不甘，投身燕王枯塚，縱死也要燕王魂魄不寧。"},
	[79720] = {CommonPl = "天可度，地可量，惟有人心不可防！余南宮信，為故友張陵所害，妻離子散，家破人亡，身陷囹圄。幸得苗人相助，習得禦蠱之術，委身大內十年，乃得報大仇。後人有緣致此，當知寧與蛇蠍為友，莫可輕信他人！"},
	[79721] = {CommonPl = "這裡邊佈滿各種零碎的東西，但已無機關存在，顯然已經被前人探索完了。"},
	[79722] = {CommonPl = "天馬當空否極見泰"},
	[79723] = {CommonPl = "這裡邊佈滿各種零碎的東西，但已無機關存在，顯然已經被摸金校尉探索完了。"},
	[79724] = {CommonPl = "茫茫天地\r不知所終\r四龍耀空\r照臨八方"},
	[79725] = {CommonPl = "這裡邊佈滿各種零碎的東西，但已無機關存在，顯然已經被前人探索完了。"},
	[79726] = {CommonPl = "余李惟忠，司設監六品掌案太監。幸得內管監鄭公公賞識，隨同五下西洋，遊歷百國，實不枉此生。在下魯鈍，無以為報，惟將百國所見機關奇物，建於陵中，只求保得長陵百年平安！"},
	[79727] = {CommonPl = "小尼儀琳被困於天鉞府中，還望大俠捨身相救！近來看那鎮墓蛤蟆有鬼，千萬別碰……別……！只怪小尼嘴拙，未能阻止大俠。害了自己不要緊，還連累的大俠，實在罪過。唯今之法只望大俠能速速將之修好，否則等此陰水漫頂，恐怕回天無術了！"},
	[79728] = {CommonPl = "這裡邊佈滿各種零碎的東西，但已無機關存在，顯然已經被摸金校尉探索完了。"},
	[79729] = {CommonPl = "余河東趙鴻，自幼同周興，梁宏、孫羽三位元兄弟結義，相約共闖江湖。不求同生，但求同死，休戚相關，福禍同當。宣德九年，為獲葵花寶典，兄弟四人夜盜長陵，不想遇強敵所阻，吾兄弟四人以同歸劍陣迎敵，終殲賊首。奈何三位兄弟傷終不治，嗚呼哀哉，恨不能與兄弟同死，此生所恨。但求埋骨於此，以慰兄弟在天之靈！"},
	[79730] = {CommonPl = "這裡邊佈滿各種零碎的東西，但已無機關存在，顯然已經被摸金校尉探索完了。"},
	[79742] = {CommonPl = "我怎麼到這裡了？神奇！也罷，隨遇而安，只是若有壺好酒就再好不過了。"},
	[79743] = {CommonPl = "沖哥你在哪兒？我好怕"},
	[79744] = {CommonPl = "令狐兄弟你是逃不出我的手掌心的"},
	[79745] = {CommonPl = "不知道她是不是還纏著我的沖"},
	[79746] = {CommonPl = "我愛他，他愛她，唉……"},
	[79747] = {CommonPl = "身為左使我定要忠肝瀝膽，死而後已"},
	[79767] = {CommonPl = "世間事，真真假假，難解難分。難！唉，難！"},
	[77582] = {CommonPl = "世間事，真真假假，難解難分。難！唉，難！"},
	[79792] = {CommonPl = "我是誰？我好像從來就沒離開過這裡。好混亂。混亂。"},
	[79955] = {CommonPl = "我是誰？我好像從來就沒離開過這裡。好混亂。混亂。"},
	[79956] = {CommonPl = "我是誰？我好像從來就沒離開過這裡。好混亂。混亂。"},
	[80128] = {CommonPl = "嶺南春光遍山腳，伊人風雨任飄搖。"},
	[80129] = {CommonPl = "你見過我家寶劍了麼？它在哪兒？"},
	[80130] = {CommonPl = "一縷香魂無斷絕，是耶非耶，化為蝴蝶。"},
	[80131] = {CommonPl = "我為什麼要這麼做？為什麼要流落在此？"},
	[87857] = {CommonPl = "你們也是為了東廠密文而來？勸你們還是想清楚…我桃谷迷陣鮮少開放，“需三人組隊，必默契配合”否則唯恐有去無回！鑒於你們勇氣可嘉，老夫就讓你們長長見識！"},
	[87480] = {CommonPl = "從桃谷迷陣形成至今，鮮有人破，究其原因，歸功於這是我桃谷六仙悉心研究的陣法需要全隊人員的默契配合！\r溫馨提示如下\r1、組隊跟隨在桃谷迷陣可是不被允許的！\r2、破陣過程中，隊長可任意踢除隊員，翻牌超時三次系統會踢除隊員，可一旦隊伍人數只剩一人，陣法會即刻關閉…"},
	[95037] = {CommonPl = "我的力量正在流失……救我……"},
	[96297] = {CommonPl = "少俠非我峨眉弟子，我這裡沒有什麼可以幫到你的，只希望此行你們一切順利。"},
	[96534] = {CommonPl = "初歲元祚，吉日維良。歡笑盡娛，樂哉未央。"},
	[96536] = {CommonPl = "我平生只怕兩件事，一是窮，二是鬼。唉喲，那黑漆漆的是什麼，俠士助我！"},
	[96815] = {CommonPl = "請少俠放入已有神石嘗試啟動石台"},
	[96816] = {CommonPl = "歡迎少俠來到本關卡，請仔細閱讀規則後完成關卡。"},
	[96692] = {CommonPl = "哎呦喂少俠快請進，聽個小曲兒鬆快鬆快，幾位姑娘可是等您好久了~不過聽完曲子若想出去，少俠還得過我這一關。\r規則簡述：\r1、少俠進入本關卡後，需要前往四位元琴女處傾聽她們彈奏的小曲兒，並瞭解所奏曲目的名稱及簡要描述，再與[老鴇]對話進行答題，[老鴇]會演奏少俠聽到的四首曲子之一，只有答出這首曲子的彈奏者、名字以及簡要描述才算過關。\r2、少俠在與[老鴇]對話開始答題前，可以在時限內重複傾聽琴女彈奏，一旦在[老鴇]處選擇了[開始答題]，將無法再重新聽曲兒！"},
	[96693] = {CommonPl = "少俠遠道而來，且聽司琴一曲，聊表心意。"},
	[96694] = {CommonPl = "少俠遠道而來，且聽司箏一曲，聊表心意。"},
	[96695] = {CommonPl = "少俠遠道而來，且聽司音一曲，聊表心意。"},
	[96696] = {CommonPl = "少俠遠道而來，且聽司樂一曲，聊表心意。"},
	[96868] = {CommonPl = "沙灘上的逃犯共有四種，每次會在其中隨機刷新出一種，若一時找不到可以看看小地圖上的紅點來尋找。\r找到後可以對他們使用驅趕技能來鞭策他們移動，但不同的逃犯移動方式迥異。任我強是個倔脾氣，移動方向和你使用技能時面朝的方向相反，任我橫只會橫著走，所以會和你釋放技能時的面朝方向成九十度，任我蹦和任我踱倒是會直線向前，不過一個是用跳的，一個則會慢慢走。\r如果逃犯卡住或者走到了地圖邊緣，可以用重來一次技能讓他們重新回到沙灘上。\r最終，把逃犯都驅趕到我面前的閃光處就算完成任務。"},
	[96297] = {CommonPl = "本關卡中，少俠需要儘快達到200點積分即可通關，積分通過擊殺小精靈獲得，小精靈被擊殺的位置越靠近箭靶，則積分越高。準備好告訴我就可以開始啦！"},
	[97196] = {CommonPl = "世上最痛苦的事，莫過於寶箱就在你眼前，你卻開不了。"},
	[97383] = {CommonPl = "我法名不戒，自然是怎麼快活怎麼來。"},
	[97428] = {CommonPl = "天下武功唯快不破！！！"},
	[97214] = {CommonPl = "將小師妹送到終點，就算你贏。"},
	[97343] = {CommonPl = "邪神教主異常強大，少俠你要多加小心！"},
	[99393] = {CommonPl = "大逃殺的勝者法則：低調，隱忍，殺戮。"},
	[100446] = {CommonPl = "軍團信息問我就沒錯了"},
	[100448] = {CommonPl = "知己知彼，百戰不殆"},
