	[19189] = {CommonPl = "最近每天夜間，綠竹林都會不斷被動物啃咬破壞。這樣下去綠竹巷的清淨可就全都被毀了。"},
	[19331] = {CommonPl = "最近每天綠竹林都會不斷被動物啃咬破壞。這樣下去綠竹巷的清淨可就全都被毀了。每天凌晨0點至2點、中午12點到14點，晚上20點到22點，希望你能和2位以上志同道合的30級以上同伴一起來幫助我趕走這些動物。"},
	[19375] = {CommonPl = "想要和我鬥喵，先打敗我的兒孫們再說喵。"},
	[19376] = {CommonPl = "想要和我鬥喵，先打敗我的兒孫們再說喵。"},
	[19377] = {CommonPl = "想要和我美猴王打，先去和猴孫們過招吧。"},
	[24781] = {CommonPl = "谷主連日來身體欠佳，谷中雜務不能躬親，看這位少俠身形健碩，想必也是習武、熱腸之人。\r可願相助處理谷中雜務？事成自當有好禮相謝。\r（提示：每日最多可完成兩次，當日未完成會累加到次日，每週最多10次，每週一早上6點重置次數）"},
	[24784] = {CommonPl = "近來莊上出現大批烏合之眾，小女子受少莊主委託，誠招各路豪傑掃清流寇。\r這位少俠可願拔刀相助？\r（提示：每日最多可完成兩次，當日未完成會累加到次日，每週最多10次，每週一早上6點重置次數）"},
	[28427] = {CommonPl = "行至此處，腹中饑餓。\r是殺幾隻鳥烤來吃，還是掏一窩鳥蛋，亦或速速回門派吃頓精緻飯菜？\r真叫人好生糾結！"},
	[28430] = {CommonPl = "半日沒吃人肉，嘴裡都要淡出鳥來了。\r這小和尚看來倒是細嫩，但他居然在我們漠北雙熊面前還如此淡定，必是有驚人藝業，還是小心為上。"},
	[28433] = {CommonPl = "小朋友，看你似乎很驚訝。\r衡山派的劉正風已經死了，這裡只有一個嗜好吹簫聽琴的江湖野老。\r吃碗安樂茶飯，聽書湊個熱鬧。"},
	[28737] = {CommonPl = "聽說群雄在此圍攻向問天，駝子也來湊個熱鬧。\r這位小哥，遇龍崖怎麼走？"},
	[29236] = {CommonPl = "人皆苦炎熱，我愛夏日長。\r田間一壺酒，心中好時光。\r瓜地在城南的農場，你帶好澆灌和施肥的用具直接去那裡就好了。"},
	[29352] = {CommonPl = "一劍橫空星斗寒，\r甫隨平北複征蠻。\r他年覓得徵候印，\r願學幽人住此山。"},
	[29891] = {CommonPl = "每年的七月十五乃是道家的中元節，也稱鬼節。坊間相傳，閻王每年七月初一打開鬼門關，放出無人祭祀的孤魂野鬼來到陽間享受人們的供奉，到七月最後一天時再讓鬼們都回到陰間。"},
	[30139] = {CommonPl = "不入虎穴，焉得虎子？跟緊！跟緊！"},
	[30371] = {CommonPl = "不入虎穴，焉得虎子？跟緊！跟緊！"},
	[30374] = {CommonPl = "不入虎穴，焉得虎子？跟緊！跟緊！"},
	[30377] = {CommonPl = "夕陽無限好，只是近黃昏。回家！回家！"},
	[30380] = {CommonPl = "採集資源，賞罰分明。論功行賞，童叟無欺！"},
	[30396] = {CommonPl = "瞧你這表現，真替你汗顏！還不快走！"},
	[30403] = {CommonPl = "人非聖賢，孰能無過？再接再厲吧。"},
	[30406] = {CommonPl = "你的表現有我當年的風采。後生可畏呐！"},
	[30334] = {CommonPl = "我在把風，行動要快！"},
	[30337] = {CommonPl = "我在把風，行動要快！"},
	[30340] = {CommonPl = "我在把風，行動要快！"},
	[30319] = {CommonPl = "今年各地大熟，倉稟皆實。惟願天佑我朝，國祚永昌。\r天子命本官在洛陽城九龍台架起一堆篝火，犒賞剿賊護糧有功的諸位英傑。你可把狩獵野豬所獲的野豬肉拿來炙烤，本官自有你的好處。"},
	[30727] = {CommonPl = "在下我熟知天下美酒釀造之法，又精通品酒賞酒之道。只是要把這酒造出來，可就不是那麼容易。非得有許多人一起幫忙才行。"},
	[31049] = {CommonPl = "青青子衿，悠悠我心。\r何以解憂？唯有杜康。\r恰逢美酒節，小老兒也來湊個熱鬧，與各位共度佳節。若是單喝酒，酒入愁腸，不免平添許多憂思；若是邀三五好友，品酒之餘射覆助興，豈不妙哉！"},
	[31052] = {CommonPl = "喝汾酒當用玉杯，玉碗玉杯，能增酒色。"},
	[31055] = {CommonPl = "“紅袖織綾誇柿葉，青旗沽酒趁梨花”\r飲梨花酒該當用翡翠杯。"},
	[31058] = {CommonPl = "關外白酒，酒味是極好的，只可惜少了一股芳冽之氣，最好是用犀角杯盛之而飲，那就醇美無比，須知玉杯增酒之色，犀角杯增酒之香。"},
	[31061] = {CommonPl = "百草美酒，乃採集百草，浸入美酒，故酒氣清香，如行春郊，令人未飲先醉。飲這百草酒須用古藤杯。百年古藤雕而成杯，以飲百草酒則大增芳香之氣。"},
	[31064] = {CommonPl = "高粱美酒，乃是最古之酒。夏禹時儀狄作酒，禹飲而甘之，那便是高粱酒了。飲這高粱酒，須用青銅酒爵，始有古意。"},
	[31067] = {CommonPl = "上佳米酒，其味雖美，失之於甘，略稍淡薄，當用大鬥飲之，方顯氣概。"},
	[31070] = {CommonPl = "葡萄美酒作豔紅之色，我輩鬚眉男兒飲之，未免豪氣不足。葡萄美酒盛入夜光杯之後，酒色便與鮮血一般無異，飲酒有如飲血。岳武穆詞雲：‘壯志饑餐胡虜肉，笑談渴飲匈奴血’，豈不壯哉！"},
	[31073] = {CommonPl = "飲玉露酒，當用琉璃杯。玉露酒中有如珠細泡，盛在透明的琉璃杯中而飲，方可見其佳處。"},
	[31076] = {CommonPl = "飲紹興狀元紅須用古瓷杯，最好是北宋瓷杯，南宋瓷杯勉強可用，但已有衰敗氣象，至於元瓷，則不免粗俗了。"},
	[31241] = {CommonPl = "這是一面大鼓"},
	[31244] = {CommonPl = "這是一面大鼓"},
	[31247] = {CommonPl = "這是一面大鼓"},
