	[31265] = {CommonPl = "這是一面大鼓"},
	[29897] = {CommonPl = "我好餓……給我點吃的好嗎？"},
	[29900] = {CommonPl = "……"},
	[35509] = {CommonPl = "我的兄弟願意慷慨赴死，但我不忍讓他孤獨而死，成與不成，至少我陪著他……"},
	[36309] = {CommonPl = "文官不愛財，武官不怕死。老夫一不愛財，二不怕死，一心只要匡扶社稷，試問天下誰敢阻我！"},
	[58892] = {CommonPl = "俺村的那幫娃子無意中發現的這個破洞，有人猜說裡面有寶貝，結果下去尋寶的幾個後生都受了重傷，聽他們說是裡面全是火，全是妖怪！嚴重的那幾個到現在還沒治好呢！\r村裡的人都知道這洞下不得，怕外地人不小心闖了進去，白白丟了性命，大夥就推舉俺在這盯著，給你們提個醒。\r你硬要進去俺也不攔著，但你得給俺一文錢，俺們好湊錢找醫生給那些後生治病去，要不俺不會告訴你洞口在哪的。\r"},
	[59652] = {CommonPl = "天下第一大幫，心系百姓疾苦。你……幸福嗎？"},
	[59653] = {CommonPl = "剛來這兒時聽說竹葉青多，我還道是好酒……哪知是這毒煞人的畜生！"},
	[63020] = {CommonPl = "你瞧見沒?旁邊那個日本小人就是專門負責監視和敲詐我的！\r咱們私下交易，大聲的不要！\r你也不想你的錢最後落到日本小人口袋裡去，對不對？\r"},
	[65599] = {CommonPl = "在下負責接待前來參加【決戰武尊堂】的各路英雄。\r入場時間：每週六\r【20：00-20：10】\r【21：00-21：10】\r入場要求：同等級段六人組隊\r入場分組：\r【玄武組】20-39級\r【白虎組】40-59級\r【青龍組】60-79級\r【朱雀組】80-99級\r揚名立萬，在此一舉!"},
	[62775] = {CommonPl = "有人前來踢館，我輩怎可袖手旁觀。贏了這一戰咱們再擺宴痛飲！"},
	[62776] = {CommonPl = "有人前來踢館，定要與之死戰。想搶我帳房裡的財物那是一文錢都欠奉！"},
