	[79642] = {CommonPl = "透過界碑，可以回到洛陽城。"},
	[79624] = {CommonPl = "珍獸谷裡傳說中隱藏有有大量神秘的財寶，但只有有能力挑戰神獸的人才能獲得財寶。\r每當神獸出現前江湖上會流出大量傳言，請關注。"},
	[79627] = {CommonPl = "北方平原有可能出現神獸『北冥玄狼』，只有擊敗它，才能繼承北冥一派的財寶！\r前進吧，騷年！"},
	[79630] = {CommonPl = "聽說有一名大俠帶領江湖友人前來挑戰琅寰神獸的真身，真是後生可畏啊。\r不過只要挑戰成功，傳說中的江湖絕學即將現世。"},
	[79633] = {CommonPl = "活死人墓裡的鎮墓之寶，不是說來試試就能試試的！\r當然，挑戰險和機遇是並存的，危險的戰鬥後面就是無與倫比的財寶，"},
	[79636] = {CommonPl = "天下有能力擊敗劍塚護靈的俠士，希望我有生之年還可以看到。\r之後，老夫是不介意傳授給你一些招式的……就看有沒有緣份了"},
	[79639] = {CommonPl = "聖火令一出，\r四方來朝，天下歸宗！\r只要能夠挑戰珍獸谷中最強的聖獸，就可以成為聖火教的傳人！"},
	[79707] = {CommonPl = "最靈通的消息，最賺錢的途徑，找我遊迅打聽就絕對沒錯啦！最近襄陽一帶有人發現了傳說中的絕情谷的入口。聽說谷中三百年來積累了各種暗器秘寶，去尋寶的江湖豪客絡繹不絕。還沒有心動嗎？快從我這裡拿一張絕情谷入口地圖，組隊三人去絕情谷拼出個富貴吧！"},
	[79846] = {CommonPl = "你要問什麼地方最有可能埋藏著無盡的寶藏？當然是皇陵！"},
	[80905] = {CommonPl = "你要問什麼地方最有可能埋藏著無盡的寶藏？當然是皇陵！"},
	[82649] = {CommonPl = "生（聖）蛋（誕）快樂！"},
	[83079] = {CommonPl = "#Y今天穿得真漂亮，福海在這裡給你拜個年！嘶嘶嘶，好冷啊，春寒料峭的生意不好做哇！"},
	[83080] = {CommonPl = "福州魚丸，筋道好吃，你要來一碗嗎？"},
	[83081] = {CommonPl = "大家都太客氣了，如果你不嫌棄的話，就來我家嘗嘗我媽親手做的花生糕吧，香甜可口，別家買不到的呢。"},
	[83082] = {CommonPl = "我這米粉是獨家配方，煮出來鮮香爽滑，吃了還想吃，你在路上可不要偷吃啊……"},
	[83083] = {CommonPl = "明窗延靜書，默坐消塵緣。\r即將無限意，寓此一柱煙。\r當時戒定慧，妙供均人天。\r我豈不清友，於今心醒然。\r爐香嫋孤獸，雲縷霏數千。\r悠然淩空去，飄渺隨風還。\r世事有過現，熏性無變遷。\r應是水中月，波定還自圓。"},
	[83084] = {CommonPl = "明窗延靜書，默坐消塵緣。\r即將無限意，寓此一柱煙。\r當時戒定慧，妙供均人天。\r我豈不清友，於今心醒然。\r爐香嫋孤獸，雲縷霏數千。\r悠然淩空去，飄渺隨風還。\r世事有過現，熏性無變遷。\r應是水中月，波定還自圓。"},
