	[83088] = {CommonPl = "明窗延靜書，默坐消塵緣。\r即將無限意，寓此一柱煙。\r當時戒定慧，妙供均人天。\r我豈不清友，於今心醒然。\r爐香嫋孤獸，雲縷霏數千。\r悠然淩空去，飄渺隨風還。\r世事有過現，熏性無變遷。\r應是水中月，波定還自圓。"},
	[83089] = {CommonPl = "獨孤村承載了我兒時所有的美好回憶，即使它已經化作廢墟，我依舊會守著它度過餘生……"},
	[59400] = {CommonPl = "都說最好的宣紙是徽宣，我陳氏宣紙於烘焙方面，卻有著更獨到的心得，宋朝時也一度是貢品，只可惜這項技術後來沒落了。"},
	[83091] = {CommonPl = "一年一度的元宵節又來啦！受禮部之托，我來給大家發放燈謎，猜對有獎哦，不要大意地戳我戳我再戳我吧！"},
