	[84982] = {CommonPl = "西邊白蓮教蠢蠢欲動，北疆蒙古鐵騎屢屢進犯。大明此刻最需要上下一心，眾志成城，共同抵禦外敵。"},
	[84974] = {CommonPl = "快快快！敵人已經逼近我方據點了，快去給我守住。"},
	[84975] = {CommonPl = "快快快！敵人已經逼近我方據點了，快去給我守住。"},
	[85766] = {CommonPl = "小師妹啊小師妹，你會不會喜歡菊花呢？"},
	[85767] = {CommonPl = "大師兄死哪兒去了，也不來陪我放風箏！"},
	[85768] = {CommonPl = "紅塵客棧裡那位賭酒娘真是風騷，趕明兒我去調戲一番！"},
	[85789] = {CommonPl = "世界盃開戰，我江湖兒女怎能不關注！還找不到地方看球賽？就來找我吧！"},
	[85994] = {CommonPl = "自從聽說令狐大俠來過這個酒館，我就天天來著喝酒！"},
	[85995] = {CommonPl = "總有一天我要換上儀琳那身衣服，真是太好看了！"},
	[85996] = {CommonPl = "曾經我也是五仙教的教眾，後因一些私事離開，很想念教主藍鳳凰，不知何時能再見她一面。"},
	[85997] = {CommonPl = "美女們！快到碗裡來！唉，我要是能像田伯光大俠那樣風流瀟灑就好了！"},
	[86021] = {CommonPl = "熱烈慶祝《笑傲江湖》人氣爆滿！快來參加笑傲江湖歡慶活動吧！"},
	[85976] = {CommonPl = "北方戰事在即，國家興亡匹夫有責，七尺男兒當圖強報國，前往大漠大展身手！"},
	[85969] = {CommonPl = "死去的馬賊身上掉落了一個破布包裹。\r提示：查看包裹為日常任務，若今天已經調查過，則不能再次完成。"},
	[85970] = {CommonPl = "不知道是誰留下了這個箱子，裡面也沒什麼值錢的東西。\r提示：查看箱子為日常任務，若今天已經完成過，則不能再次完成。另外，箱子不會每次都出現在同一個地方哦。"},
	[85971] = {CommonPl = "謝謝你，好心人！草原是我們美麗的家園，這裡的小動物都是我們可愛的家人。"},
	[85974] = {CommonPl = "這只小兔子驚慌失措，它非常需要大家的説明。\r提示：救助野兔為日常任務，若今天已經完成過，則不能再次完成。"},
	[87007] = {CommonPl = "月宮賜桂子，獎賞善人家。福高桂樹碧，壽高樹滿花。採花釀桂酒，酒香滿天涯。"},
	[87681] = {CommonPl = "只有“參賽幫會”的“四階”及以上成員，在背包中裝有“精英比武令”的情況下，才能在比賽開始後進入戰場。\r請諸位大俠認准比賽時間和比賽場地，不要錯過比賽哦！"},
	[62479] = {CommonPl = "逃跑的罪犯，必須緝拿歸案！"},
	[87048] = {CommonPl = "你要問什麼地方最有可能埋藏著無盡的寶藏？當然是皇陵！"},
	[87047] = {CommonPl = "小小毛賊就想來動我們工坊的倉庫，這次要讓他們有來無回！"},
	[87633] = {CommonPl = "箭塔的射速很快，3捆箭矢可以使用1分鐘，如果你想讓它運行個5分鐘那麼最好一次性交15捆。"},
