	[89224] = {CommonPl = "貨殖八方活動中獲得的特產實在沒辦法出手可以賣給我，不過在我這裡就別指望有太好的回報啦，保個本罷了。"},
	[89840] = {CommonPl = "貨殖八方活動中獲得的特產實在沒辦法出手可以賣給我，不過在我這裡就別指望有太好的回報啦，保個本罷了。"},
	[89841] = {CommonPl = "貨殖八方活動中獲得的特產實在沒辦法出手可以賣給我，不過在我這裡就別指望有太好的回報啦，保個本罷了。"},
	[90565] = {CommonPl = "我是牛郎，出來放牛時遇到一位仙女。一見鍾情後，我知道我不再是個快樂的單身漢了。"},
	[90566] = {CommonPl = "我叫織女，是天上的仙女，但是對凡間的牛郎起了情愫，我覺得我有大麻煩了。"},
	[90567] = {CommonPl = "我可不是一般的牛，我是神牛！！為了報恩留在牛郎身邊，默默的在保護他。但是，這次的事兒玩兒大了！仙凡之戀可不是那麼好玩兒的！"},
	[90546] = {CommonPl = "牽牛出河西，織女處其東。\r萬古永相望，七夕誰見同。\r一聲歎息，是年七夕，君又與誰同？\r今紅娘有姻緣樹種一枚，欲贈於你。\r若想求緣，便與你知己一起前往，說不定會有意外的收穫呢！"},
	[90614] = {CommonPl = "明天的保證再真誠，也比不上今天的實際行動！\r每天將活躍度刷到70，可以獲得一枚青龍令，拿到青龍令之後就可以來找我兌換獎勵！兌換商店中的寶貝會不定時更新，只要你付出了努力，我就不會讓你們失望。"},
	[90609] = {CommonPl = "呵呵噠，你好啊，小兄弟~"},
	[90717] = {CommonPl = "中秋佳節到來，還請各位英雄按時來小月月這參加好玩的中秋活動哦~"},
	[91031] = {CommonPl = "所謂活動，先有活，才有動。"},
	[91044] = {CommonPl = "嵩山派隱秘鑄劍師歐煉子，人人得而誅之！"},
	[91100] = {CommonPl = "過去之事已經過去，我已不願再提……如今恒山重建，正是百廢待興之際，恒山派上下衷心感謝所有前來相幫的武林同道。"},
	[91032] = {CommonPl = "所謂活動，先有活，才有動。"},
	[91033] = {CommonPl = "所謂活動，先有活，才有動。"},
	[91189] = {CommonPl = "退隱江湖多年，一朝回歸，還有幾人記得你曾經的風采？\r沒關係，是時候用拳頭讓他們記起你了！"},
	[91191] = {CommonPl = "誰說兔子最喜歡的食物是蘿蔔？人家明明最愛吃月餅的說~"},
	[91707] = {CommonPl = "……"},
	[91708] = {CommonPl = "滅門之仇，莫不敢忘！只要能夠報仇，我付出什麼都是值得的！"},
	[91709] = {CommonPl = "滅門之仇，莫不敢忘！只要能夠報仇，我付出什麼都是值得的！"},
	[91710] = {CommonPl = "我不管別人怎麼想他，我總是要跟著他的……如果連我都離開了，還有誰能幫著他呢？"},
	[91319] = {CommonPl = "春城三月，洛陽飛花"},
	[91320] = {CommonPl = "春城三月，洛陽飛花"},
	[91321] = {CommonPl = "春城三月，洛陽飛花"},
	[91413] = {CommonPl = "趁白蓮教還沒進村，讓大家趕緊跑啊！"},
	[91433] = {CommonPl = "恒山已經開始慢慢恢復昔年的樣子，過去的事情，我已不願再提起……"},
	[91571] = {CommonPl = "吾心所願，唯君平安"},
	[91574] = {CommonPl = "吾心所願，唯君平安"},
	[91575] = {CommonPl = "聖姑高瞻遠矚，果然英明！"},
	[91577] = {CommonPl = "昨日種種如昨日死，今日事事是今日生"},
	[91578] = {CommonPl = "努力支撐起恒山派，儀琳師姐其實很辛苦……"},
	[91579] = {CommonPl = "我佛慈悲，阿彌陀佛"},
	[91580] = {CommonPl = "佛曰七苦：生、老、病、死、怨憎會、愛別離、求不得"},
	[91581] = {CommonPl = "我佛慈悲，阿彌陀佛"},
	[91805] = {CommonPl = "山河千里國，城闕九重門。\r不睹皇居壯，安知天子尊。\r皇居帝裡崤函穀，鶉野龍山侯甸服。\r五緯連影集星躔，八水分流橫地軸。\r秦塞重關一百二，漢家離宮三十六。\r桂殿嶔岑對玉樓，椒房窈窕連金屋。\r三條九陌麗城隈，萬戶千門平旦開。\r複道斜通鳷鵲觀，交衢直指鳳凰台。"},
	[91440] = {CommonPl = "……"},
	[91843] = {CommonPl = "願以我之性命，護衛河山!"},
	[91844] = {CommonPl = "這個部落有個小哥兒不錯哩！"},
	[91845] = {CommonPl = "我跟隨相公來這遺跡尋寶，不過，最近他變得有點怪怪的……"},
	[91846] = {CommonPl = "我的偶像，是關雲飛大人！"},
	[91847] = {CommonPl = "愛得越深，制出的情人蠱才越毒！"},
	[91848] = {CommonPl = "斷情穀的花燈美不勝收，誰願為我采一朵？"},
	[91849] = {CommonPl = "人生四大喜事：每天三菜一湯，過年一件新衣裳，隔壁阿花愛上我，三十歲來兒孫滿堂！"},
	[91850] = {CommonPl = "這裡充滿危險，卻也美麗無比。"},
	[91896] = {CommonPl = "……你說，這天有多大？"},
	[92351] = {CommonPl = "當初吾等奉師命外出雲遊，沒想到一夜生變，師門竟再也無法回去……我們已經在外遊蕩了太久太久，連歸家的路途似乎都已模糊在記憶裡了……"},
	[92438] = {CommonPl = "完成福州郊外、衡山郊外、夜嵐谷、武當山腳以及華山的聲望任務可獲得白色聲望果。\r累積到一定數量後，可我兌換各種獎勵哦。"},
	[92439] = {CommonPl = "完成泰山、仙愁峽、少室山、朱仙鎮、五霸崗以及藥王穀的聲望任務可獲得綠色聲望果。\r累積到一定數量後，可我兌換各種獎勵哦。"},
	[92440] = {CommonPl = "完成福州城、衡山城、洛陽城、天下會以及門派聲望任務可獲得藍色聲望果。\r累積到一定數量後，可我兌換各種獎勵哦。"},
	[92441] = {CommonPl = "完成桂林、嘉州、鑄劍谷、龍泉以及仙霞嶺的聲望任務可獲得紅色聲望果。\r累積到一定數量後，可我兌換各種獎勵哦。"},
	[92442] = {CommonPl = "完成青城山、劍閣、西安以及南疆的聲望任務可獲得紫色聲望果。\r累積到一定數量後，可我兌換各種獎勵哦。"},
	[92458] = {CommonPl = "完成平涼、敦煌、陰山草原以及蒙古草原的聲望任務可獲得金色聲望果。\r累積到一定數量後，可我兌換各種獎勵哦。"},
	[92536] = {CommonPl = "江湖盛傳，老夫當年闖蕩靠的是一本《辟邪劍譜》。殊不知，老夫這身功夫全憑一顆無敵于世的武魂！"},
	[92825] = {CommonPl = "餃子餡都要搶，這群青城派的人真是喪心病狂！"},
	[92881] = {CommonPl = "誰能來買我的火柴……誰能來帶我回家……"},
	[92948] = {CommonPl = "東方……姑娘……唉，這個苦差事為什麼要我來啊……"},
	[92966] = {CommonPl = "遠點遠點！別打擾我做生意！"},
	[92656] = {CommonPl = "謔謔~小夥子們，來拿聖誕禮物吧！"},
	[96408] = {CommonPl = "謔謔~小夥子們，來拿聖誕禮物吧！"},
	[92986] = {CommonPl = "好冷的天啊，只有用禮物埋住我才能感到暖和一些。"},
	[97680] = {CommonPl = "感謝您一直以來對笑傲江湖的支持，值此盛大的周年慶之際，武林盟為您準備了諸多福利活動，請多多關注哦。"},
	[97679] = {CommonPl = "相逢即是有緣！有點小禮物還請大俠收下哦！"},
	[98788] = {CommonPl = "纖雲弄巧，飛星傳恨，銀漢迢迢暗度。金風玉露一相處，便勝卻人間無數。\r柔情似水，佳期如夢，忍顧鵲橋歸路。兩情或是久長時，又豈在朝朝暮暮。"},
	[99768] = {CommonPl = "東方姑娘是我，東方教主亦是我，歲月流轉，你可還記得自己最初的樣子？"},
	[99777] = {CommonPl = "東方姑娘是我，東方教主亦是我，歲月流轉，你可還記得自己最初的樣子？"},
	[99778] = {CommonPl = "東方姑娘是我，東方教主亦是我，歲月流轉，你可還記得自己最初的樣子？"},
	[10198] = {CommonPl = "往東五里乃蜘蛛泉\r推薦等級：20-35"},
	[10201] = {CommonPl = "往西十里乃野豬嶺\r推薦等級：35-45"},
	[10204] = {CommonPl = "往東六里乃燕子塢\r推薦等級：？？"},
	[10207] = {CommonPl = "往南九里乃虎跳峽\r推薦等級：55-65"},
	[10214] = {CommonPl = "閣下既能來到此處，想必也是有緣之人，哈哈哈哈……"},
	[10217] = {CommonPl = "我已厭倦江湖紛爭，在此隱居多年。"},
	[10220] = {CommonPl = "這裡氣候舒爽，生長有許多上好的藥材。"},
	[13234] = {CommonPl = "福州碼頭近年來越來越繁忙了。你瞧瞧這貨物，都堆的像小山似的了。"},
	[13237] = {CommonPl = "保衛福州人民的安全是我的職責！"},
	[13240] = {CommonPl = "威——武——\r衙門重地，閒雜人等不得亂闖。"},
	[13243] = {CommonPl = "那大盜田伯光，人稱“快刀一枝花”，一把快刀使的是虎虎生威，我可是他的粉絲！！"},
	[13246] = {CommonPl = "威——武——\r衙門重地，閒雜人等不得亂闖。"},
	[13249] = {CommonPl = "保衛衡山城人民的安全是我的職責！"},
	[13252] = {CommonPl = "嘿！我和荷包呐？難道剛剛過去的那位女俠……\r抓小偷啊！大家快來抓小偷啊！"},
	[13255] = {CommonPl = "保衛洛陽人民的安全是我的職責！"},
	[13258] = {CommonPl = "哎呦喂！這大街上怎麼這麼多人？哪又打架鬥毆，賭錢賠命啦？"},
	[13261] = {CommonPl = "杭州碼頭近年來越來越繁忙了。你瞧瞧這貨物，都堆的像小山似的了。"},
	[13264] = {CommonPl = "聽說醉仙樓新開封了上好的陳年女兒紅，喝上一口，回味三年！無論如何都得去嘗嘗！"},
	[13267] = {CommonPl = "阿彌陀佛，善哉善哉。"},
	[13270] = {CommonPl = "少林七十二絕技博大精深，從今天開始我每天練八個時辰的話……"},
	[13273] = {CommonPl = "“一生二，二生三，三生萬物”\r我的好好鑽研一下這句話的意思。"},
	[13276] = {CommonPl = "白雲出岫！看招！喝！"},
	[13279] = {CommonPl = "雖然我們恆山派武功威力不強，但是也往往很難被抓住破綻。"},
	[13282] = {CommonPl = "百變千幻，虛虛實實。\r瞧我的！"},
	[13285] = {CommonPl = "聖教主文成武德，澤被蒼生，千秋萬載，一統江湖。\r每次練武前總得先練練喊口號。"},
	[13288] = {CommonPl = "蠍子？我的蠍子呢？蜈蚣？蜈蚣又跑哪去了？"},
	[13291] = {CommonPl = "加油練功，一會還要去跟師父學琴棋書畫呢。"},
	[13294] = {CommonPl = "師傅說，如果不能做到在對手看清楚自己之前擊敗對方，這仗基本就輸定了。"},
	[13297] = {CommonPl = "“化萬法為一法，以一法破萬法。”\r口訣聽起來簡單，練起來才知道有多難。"},
	[7004] = {CommonPl = "師弟，別擔心，咱們道家真法天下第一，魔教那些妖賊算的了什麼，哼！"},
	[7007] = {CommonPl = "師兄，你說萬一有人來救他怎麼辦……"},
	[7010] = {CommonPl = "我在此等你多時，聽說你挺厲害的，真想和你比試比試！"},
	[7013] = {CommonPl = "加緊幹活，呼呼……"},
	[7016] = {CommonPl = "１：\r姐，我休息一會兒接著乾。"},
	[7019] = {CommonPl = "２：\r才這一會兒就要休息啊，真受不你了。"},
	[7022] = {CommonPl = "還沒下葬，屍體就被陽光照射的青煙四起，怕的是晚上會不會屍變呀。"},
	[7025] = {CommonPl = "１：\r娘，我要吃冰糖葫蘆！\r２：\r你這個孩子，甜的吃多了要牙疼哦！"},
	[7028] = {CommonPl = "不缺斤，不少兩，不差錢！"},
	[7031] = {CommonPl = "１：\r強盜再來啊，我們一定抓你！\r４：\r小鎮的安全，就由我們三人來守護了。"},
	[7034] = {CommonPl = "２：\r小虎哥挺住，我保護你。"},
	[7037] = {CommonPl = "３：\r報告，暫時沒發現敵情！"},
	[7040] = {CommonPl = "該死！一路跟著那淫賊，本想在他犯案時一舉抓獲，沒想到竟然跟丟了！"},
	[7043] = {CommonPl = "什麼？難道那個死淫賊又染指了哪家的黃花大閨女嗎？！真是可恨！"},
	[7046] = {CommonPl = "終於送到了……"},
	[7049] = {CommonPl = "快要變天了，我得趕緊把貨物送過去。"},
	[7052] = {CommonPl = "造孽啊，造孽啊，收成一年比一年差，這日子可怎麼活。"},
	[7055] = {CommonPl = "哎喲喲！這可怎生是好？那玉簪明明是在這裡丟的，怎麼到處都找不到呢！"},
	[7058] = {CommonPl = "好漂亮的蝴蝶，我要逮住它送給二妞！"},
	[7061] = {CommonPl = "終於把雜草除完了，那臭小子整天就知道跟表妹玩，也不幫忙做農活！"},
	[7064] = {CommonPl = "Zz……"},
	[7067] = {CommonPl = "１：\r表妹！快到湖裡來泡泡吧！好涼快！"},
	[7070] = {CommonPl = "２：\r呸！我一個女孩子，光天化日之下，被人看到了可沒法活啦。"},
	[7073] = {CommonPl = "嘿咻嘿咻，好好把網給洗乾淨，明天多打兩斤魚，給老婆熬魚湯喝咯！"},
	[7076] = {CommonPl = "這收成是一年不如一年啦！"},
	[7079] = {CommonPl = "我剛剛明明釣到五條魚，為什麼去了趟茅廁就沒有了。"},
	[7082] = {CommonPl = "趕了一天的路了，不知這附近可有店家投宿。"},
	[7085] = {CommonPl = "１：\r啊！嚇死我了，差點打破罐子！"},
	[7088] = {CommonPl = "２：\r小心點，摔壞了你可賠不起！"},
	[7091] = {CommonPl = "１：\r好東西啊，沒想到品質如此之好。\r２：\r應該多運些給公公！！他老人家一定會好好提拔我的。"},
	[7094] = {CommonPl = "真累啊。等我攢夠錢，就回老家結婚去！"},
	[8635] = {CommonPl = "這位#Y，近來梅關山賊倡狂，您可得小心點。"},
	[8638] = {CommonPl = "他奶奶的熊！就為了這趟鏢，小命都差點沒了！老子還沒討媳婦呢！"},
	[8641] = {CommonPl = "嘶……好痛，我的手呢？手呢？"},
	[8644] = {CommonPl = "不知鏢車被劫一事總鏢頭可否知曉……算時辰也該來救我們了……"},
	[8647] = {CommonPl = "哎呀呀，上年紀了走點路都喘。咦？那個年輕人該不會是要跳下去吧？"},
	[8650] = {CommonPl = "嗚嗚……我不活啦！我有什麼不好，你偏偏不喜歡我……看什麼看！沒見過失戀啊！"},
	[8653] = {CommonPl = "１：\r三進三出四合院，重簷滴水八抬轎。薇薇，只要你跟了我，包你一輩子過的舒舒坦坦！"},
	[8656] = {CommonPl = "２：\r哥哥，婚姻大事，父母之命媒妁之言，豈能如此兒戲？"},
	[8659] = {CommonPl = "還好我起的早，集市還有新鮮的蔬菜賣，不然又要被婆婆嘮叨了！"},
	[8662] = {CommonPl = "早就聽說梅嶺風雪甲天下，待我歇歇腳，定要一口氣走到山上好好欣賞一番！"},
	[8665] = {CommonPl = "小二小二！快點上菜啊！耽誤了老爺我的正經事，讓你吃不了兜著走！"},
	[8668] = {CommonPl = "１：\r哎？為啥咱家的雞越來越少了？\r２：\r媳婦哪去了？快來數數！"},
	[8673] = {CommonPl = "小女如花，今年十八，求菩薩保佑，賜一位貌如潘安的才子……"},
	[8676] = {CommonPl = "武當真乃道家福地，嘖嘖，這空氣中都有一股神仙的味道。"},
	[8679] = {CommonPl = "聽說這山頂有棵千年靈芝，我爬，我爬，我爬爬爬！"},
	[8682] = {CommonPl = "吱吱！吱——"},
	[8685] = {CommonPl = "佛祖在上，請保佑我爹爹上山採藥，一路平安，早日採到靈芝，替我娘治病。"},
	[8696] = {CommonPl = "１：\r娘子，你看這嵩山的景色美不美？這幾天連著趕路，辛苦你了。"},
	[8699] = {CommonPl = "２：\r與君為伴，縱情山水，我願永遠與夫君在一起！"},
	[8702] = {CommonPl = "１：\r師兄練功我送飯，師妹念經師兄伴。師兄師妹心不變，只羨鴛鴦不羨仙。"},
	[8705] = {CommonPl = "２：\r看破紅塵入少林，怎料姻緣應聲到。只要我倆一條心，不畏世俗見真情！"},
	[8708] = {CommonPl = "別人笑我太瘋癲，我笑他人看不穿。老婆孩子熱炕頭，生活樂無邊。"},
	[8711] = {CommonPl = "少俠此次入谷可千萬當心啊，這裡可是處處危機，時時命懸啊，找些江湖朋友結伴同行吧！"},
	[8714] = {CommonPl = "上天梯子未做起，閻王發牌鬼來催——小命難保啊！"},
	[8717] = {CommonPl = "好酒！來陪兄弟我喝兩杯，嘗嘗這仙愁峽的佳釀！"},
	[8720] = {CommonPl = "這一路太可怕了，處處是陷阱，差點丟了小命……"},
	[8723] = {CommonPl = "１：\r我這把寶劍如何？不如兄台與我切磋切磋？"},
	[8726] = {CommonPl = "２：\r且慢，待我運功片刻，活動活動筋骨。"},
	[8729] = {CommonPl = "你也是來仙愁峽尋寶的？不如先來店裡喝幾杯，壯壯膽吧。"},
	[8732] = {CommonPl = "少俠請，好酒好菜好景色！"},
	[8738] = {CommonPl = "１：\r重陽節後天如錦，天狼射盡。\r２：\r行歡須盡千杯酒，笙歌伴飲。"},
	[8741] = {CommonPl = "３：\r這小妮子，唱的真是……嗝……真是……嗝……好啊……"},
	[8744] = {CommonPl = "親娘咧！那幫小兔崽子在那飲酒作樂，竟讓老子替他們殺敵！啐！"},
	[8747] = {CommonPl = "呼兒嘿！大王派我來砍樹嘞……"},
	[8753] = {CommonPl = "哎喲我的親娘四舅奶奶，巨蠍橫行，叫我如何出門呐！"},
	[8756] = {CommonPl = "世人皆道龍泉寶劍乃不詳之物，殊不知罪在持劍之人，與劍無關。"},
	[8759] = {CommonPl = "１：\r夫君，你不管我可以，但不能不管咱們的孩子啊，跟我回家好好過日子吧。"},
	[8762] = {CommonPl = "２：\r我畢生為劍而活，為了它，我可以捨棄一切，你帶著孩子走吧！"},
	[8765] = {CommonPl = "１：\r可憐我兒，從小沒了娘，還要跟著我在這深山裡採藥……"},
	[8768] = {CommonPl = "２：\r爹……"},
	[8771] = {CommonPl = "江湖恩怨，與我無關，我只是這江湖中的一個看客！"},
	[8774] = {CommonPl = "龍泉的青瓷，青如玉，明如鏡，聲如磬，據說皇后娘娘都是用咱的瓷盆洗腳呢。"},
	[8777] = {CommonPl = "燒瓷除了要祭拜祖師爺，更有山神，土地，運水郎君同祀，規矩可是大得很。"},
	[8780] = {CommonPl = "外人只道龍泉寶劍與青瓷，卻不知此處香菇更是人間至味。不信便來嘗嘗我相公做的香菇燉雞。"},
	[8783] = {CommonPl = "素胚青花濃轉淡，釉色渲染餘香散。天青等煙雨，此情誰念？隔江千萬裡，當年龍泉。"},
	[8786] = {CommonPl = "好端端趕著的屍體，一到這裡竟然消失了，這讓我如何去與主顧交代。"},
	[8789] = {CommonPl = "最近的客人見少啊是啊，生意是越來越差嘍！唉……我還是改行抓魚算了。"},
	[8792] = {CommonPl = "１：\r我家那臭老頭子不知道又到哪拈花惹草去了！\r２：\r今晚不跪著搓板給我洗腳就別想進門！"},
	[8795] = {CommonPl = "２：\r娘子，再美的花也沒有我的娘子美啊！"},
	[8798] = {CommonPl = "１：\r官人，你看這橋下的野花好美啊"},
	[8801] = {CommonPl = "哈哈，有酒相伴，今生無憾啦！"},
	[8804] = {CommonPl = "哼，聽說最近來了一個武林高手，我倒要看看他有幾斤幾兩！"},
	[8807] = {CommonPl = "哈哈，今天收穫不錯，趕緊交給大哥領賞去！"},
	[8810] = {CommonPl = "１：\r我的聘禮啊！那幫天殺的強盜，叫我還怎麼娶老婆啊！"},
	[8813] = {CommonPl = "２：\r少爺……少爺！您沒傷到吧，聘禮被劫事小，傷到您可不得了啦！"},
	[8816] = {CommonPl = "１：\r這幾天真不太平，都不敢出門了，攢了這麼多衣服沒洗！"},
	[8819] = {CommonPl = "２：\r就是就是，千萬別碰見前幾天在這兒聚會的那群怪人，趕緊洗完回家。"},
	[8822] = {CommonPl = "請老天保佑我的家鄉，讓那些強盜再也不要來了……"},
	[8825] = {CommonPl = "殺戮太多，回頭是岸，請施主好自為之，阿彌陀佛……"},
	[8828] = {CommonPl = "１：\r師兄，這盤棋你我二人下了整整十年了，卻始終未能分出勝負啊！"},
	[8831] = {CommonPl = "２：\r何謂勝？何謂負？阿彌陀佛，一切皆是過眼雲煙……"},
	[8834] = {CommonPl = "１：\r聖姑讓咱兄弟倆在此守了快一個月了，沒酒沒女人的，悶死了！"},
	[8837] = {CommonPl = "２：\r噓，小聲點，小心聖姑突然出現把你發配去鳥不拉屎的無人島！"},
	[8840] = {CommonPl = "習武之道，貴在一個勤字，勤學苦練，才能有所成！"},
	[8843] = {CommonPl = "嗨！哈！"},
	[8846] = {CommonPl = "太極奧義，在於清修……"},
	[8849] = {CommonPl = "師父不收我為徒，我就在這跪一輩子。"},
	[8852] = {CommonPl = "記不清第幾百次失戀了，今天我要喝個痛快，然後就在這泰山出家，永不還俗！"},
	[8855] = {CommonPl = "吱——"},
	[8858] = {CommonPl = "１：\r走過路過不要錯過！上好的香啊，拜神求仙良伴，送子得財必備咯！"},
	[8861] = {CommonPl = "２：\r去去去！道觀乃清淨之地，怎能容得爾等喧嘩！"},
	[8864] = {CommonPl = "３：\r這位道長，生活不易，還望您能大人大量，給我們一條活路啊！"},
	[8867] = {CommonPl = "４：\r沖虛道長每次都在我這買糖葫蘆送給山下的孩子們吃，他都沒說什麼，你憑什麼趕我走？"},
	[8870] = {CommonPl = "賣酒了啊！杏花村的好酒喲——"},
	[8873] = {CommonPl = "２：\r我下棋的那年，你還吃糖葫蘆呢！"},
	[8876] = {CommonPl = "１：\r你到底會不會下棋？不會就別耽誤我的時間。"},
	[8879] = {CommonPl = "１：\r老伯，我們主僕二人各來一乘轎子！"},
	[8882] = {CommonPl = "２：\r小姐，十兩銀子一位，要不您先給錢吧？"},
	[8885] = {CommonPl = "得嘞，您稍等，馬上就來！"},
	[8888] = {CommonPl = "２：\r小二，來兩斤醬牛肉，三兩燒白乾，再來幾個小菜！"},
	[8891] = {CommonPl = "１：\r大哥，聽說這家店的醬牛肉很是不錯呢！"},
	[8897] = {CommonPl = "Zzzzzzzz——"},
	[8900] = {CommonPl = "上有天堂下有蘇杭，打著蘇杭的傘，大嬸變西施喲！"},
	[8903] = {CommonPl = "１：\r好酒量，來，乾了這杯！"},
	[8906] = {CommonPl = "２：\r乾！"},
	[8909] = {CommonPl = "１：\r小萌，一會給你燉雞湯好不好？"},
	[8912] = {CommonPl = "２：\r不要不要！這些小雞好可愛，我要看著他們長大！"},
	[8915] = {CommonPl = "聽說東邊羅凝家的媳婦生了個大胖小子！一會得去問問她拜了哪座廟的送子觀音！"},
	[8918] = {CommonPl = "哈哈哈！我當爹啦！趕緊砍點柴回家，給娘子燉魚湯去！"},
	[19083] = {CommonPl = "少莊主整天愁眉苦臉，真讓人揪心啊。"},
	[19084] = {CommonPl = "少莊主整天愁眉苦臉，真讓人揪心啊。"},
	[23404] = {CommonPl = "瓦剌部族向來野心勃勃，這次活佛坐化，不知道又要鬧出什麼風波。"},
	[23407] = {CommonPl = "活佛坐化於此，我們很悲傷。但是活佛會再一次降臨，我們在等待。"},
	[23410] = {CommonPl = "金剛怒目，護佑我佛！"},
	[24677] = {CommonPl = "草原上不僅有迅猛的鷹，兇殘的狼，還有殺人越貨的響馬和一直在追殺我們的瓦剌人。但草原依然是我們最美麗的家園。"},
	[24680] = {CommonPl = "擠牛奶，打馬草，剪羊毛，天天干這些事情，真是沒意思……"},
	[24683] = {CommonPl = "我們是黃金家族，草原上最偉大的族群，守護大汗陵是無上榮光的使命。"},
	[24948] = {CommonPl = "……"},
	[24951] = {CommonPl = "如今這日子，可是越來越難過啦。"},
	[24954] = {CommonPl = "我只是一個小老百姓，我什麼都不知道。"},
	[24957] = {CommonPl = "那黃陵派不過是峨嵋派的走狗罷了，囂張什麼！"},
	[36024] = {CommonPl = "這江湖，怕是風雨欲來啊！"},
	[36027] = {CommonPl = "客官，您裡邊請！"},
	[36045] = {CommonPl = "鐵廉，你想多了……"},
	[36048] = {CommonPl = "說好的天高皇帝遠呢？！我只不過偷了幾塊豬肉，就整天被人追得東躲西藏，到了這福州還能被仇人發現？上帝啊！我信你了，快來拯救我吧！"},
	[36051] = {CommonPl = "賭酒娘老在我面前俯首弄姿，是不是對我有什麼企圖？"},
	[36054] = {CommonPl = "江湖險惡，你要保重。"},
	[36057] = {CommonPl = "這中原劍法同我們西域劍法的差別在什麼地方，弄不明白，我就不離開這裡！！"},
	[36060] = {CommonPl = "有話要你們管事的來說，這裡有你們插嘴的地方嗎？你哪個門派的？"},
	[36063] = {CommonPl = "王月生姑娘，又白、又富、又美，我一個老頭子，她能忠心於我嗎？"},
	[36066] = {CommonPl = "仗劍行千里，微軀敢一言。曾為大樑客，不負信陵恩。"},
	[36069] = {CommonPl = "段大俠，你欠我的三枚銅錢該還了，若不然，你即使是天王老子，在下也會捅你三刀。"},
	[36072] = {CommonPl = "古來聖賢皆寂寞，惟有淫……飲者留其名。這句話真奇怪，為何越下作的人越有名呢？"},
	[36075] = {CommonPl = "風姑娘，這天下的事兒啊，沒什麼我不懂的，你有什麼疑問，儘管問便是。"},
	[36078] = {CommonPl = "生也是苦，死也是苦，恩恩怨怨，貧僧早已看破。何必諸多囉唆，擾我清修？"},
	[36081] = {CommonPl = "修道的境界，你們這些只知每日專營蠅營狗苟的人，永運也不會懂。"},
	[36084] = {CommonPl = "《詩經》有言：兄弟鬩於牆，外禦其侮。本派之內雖有意見不合，但不可忘記大家共同的目標。"},
	[36087] = {CommonPl = "鐵打的福州，流水的過客。一個沒有記憶的城市，一個只有背叛和遺忘的江湖。"},
	[36090] = {CommonPl = "好好好，全依你，全依你。"},
	[37884] = {CommonPl = "我這次一定要考取功名，回來娶蘇姑娘……"},
	[37887] = {CommonPl = "唉，我爹爹真是太勢力了，他竟然逼我嫁給王員外做小妾！"},
	[37890] = {CommonPl = "王員外實在欺人太甚，不但侵佔了我的田地，還搶走了我小兒子，強逼我兒子做那兔兒爺！\r我，我便是拼了老命去，也要告官！\r"},
	[36093] = {CommonPl = "難道我威名四方的福威鏢局，今天竟要折在家門口了嗎？讓我老鄭的臉往哪擱啊！"},
	[43740] = {CommonPl = "見到我男人鐵廉了嗎？這個沒良心的，迷上了一個狐狸精，天天來這裡喝酒，若是被我找到了他，定要把他閹了"},
	[43734] = {CommonPl = "關大夫是我的大恩人啊，上次吃了他開的藥，我就有了俏丫頭。這次再找他開藥，希望日後會有個胖小子。"},
	[43776] = {CommonPl = "聲聲蘇州謠，侉侉江南調。\r清音說故國，揚子風韻嬌。\r一曲談幽情，再彈濃春宵。\r溫婉牽憂腸，悠柔惹紅消。\r細細呀，道來吆，絲絲呀，黛黛吆。\r吳地美人吟，秦淮葉落了。"},
	[43767] = {CommonPl = "以前常聽別人說“寂寞”總覺得不屑，今天我也明白那種滋味了。這麼孤苦而絕望，無人訴說，無法可救。\r偌大的世界，洶湧的人潮，而想找個說話的人卻都沒有。"},
	[43716] = {CommonPl = "有些事，知道了，要比不知道，痛苦萬倍。即使這樣，也要去探尋，也要去瞭解真相。興許，這便是人生。"},
	[45118] = {CommonPl = "十年一覺江湖夢，贏得花酒薄幸名。\r我本將心向明月，奈何明月照溝渠。\r流水光陰彈指過，抱柱尾生已死絕。\r文藝落伍基友笑，醉生夢死樂逍遙。"},
	[45139] = {CommonPl = "沒有人生來浪蕩。\r我只是用風流不羈的外表來掩飾內心的滿目瘡痍。\r可曾記得，那些年，我們一起追過的那個花魁……"},
	[45142] = {CommonPl = "近日在家中發現一本好書。\r文采飛揚、情節跌宕起伏，字裡行間又蘊含了若干為人處事的哲理，讀來讓人神清氣爽、獲益良多，當真是愛不釋手。\r只是不知這作者蘭陵笑笑生是何許人也。"},
	[45136] = {CommonPl = "喜歡哪一個？\r這種浪蕩公子哥兒有哪一點值得我花飛雪多看一眼？\r只不過……屬於她洛小仙的東西，我都會一件一件搶過來！"},
	[43746] = {CommonPl = "年輕人，我看你骨骼驚奇、天賦異稟，當真是練武的好材料！\r我這有一套合訂版的秘笈，包含《菊花寶典》《獨孤十劍》《吸月大法》等數十種絕學，現在只賣你998錢。\r998，絕世秘笈帶回家！你還在猶豫什麼？拯救武林的重任就交給你了！"},
	[45209] = {CommonPl = "當初是你要分開，分開就分開，現在又想用真愛，把我哄回來~"},
	[45097] = {CommonPl = "貧道修陰陽調和、天人合一之術，早已看破世俗紅塵，至於那些任盈盈、岳靈珊、儀琳、藍鳳凰之流的美女，更是一個也不知曉！"},
	[45124] = {CommonPl = "你可聽過我福建民間的山歌？家家的人都會唱幾句哩！\r^O003藥，藥，切棵鬧！\r小弟我出生在衡山碼頭邊，\r家中沒屋也沒田……^O000\r"},
	[43755] = {CommonPl = "人生最悲慘的莫過於：辛辛苦苦做了一晚上內容香豔的美夢，第二天早上醒來居然全都記不起來了！"},
	[43758] = {CommonPl = "聽這一曲《天上人間》，竟花了我十個銅板！\r你們有句古訓說得很對——女為悅己者容，男為己悅者窮。"},
	[43761] = {CommonPl = "以前太年輕，總夢想自己能夠成為一名劍客四處行俠仗義。\r現在成熟了，便幻想自己是地主家的少爺，家有良田千頃，終日不學無術，沒事領著一群漂亮妹紙上街去調戲良家少年……\r"},
	[56200] = {CommonPl = "咱爺們雖然是個和尚，但從來不守清規戒律。想喝就喝，要喝的痛快；想唱就唱，要唱的響亮！"},
	[56203] = {CommonPl = "哼，傳說聖姑對一個毛頭小子有意思，也不知是真是假。"},
	[56206] = {CommonPl = "（用力啐了李嘯任一口）你嚎叫個屁！還是讓本小姐唱一曲吧“蒼茫的天涯是我的愛……”"},
	[56209] = {CommonPl = "相比任大小姐，其實我更想見見昔年的魔教教主——任我行。"},
	[56239] = {CommonPl = "一定要追到錢人仇，一定要拿回我家的辟邪劍譜。"},
	[56233] = {CommonPl = "（深情款款）小林子，放心吧，我會一路陪著你。"},
	[63989] = {CommonPl = "俗話說寧拆十座廟不毀一樁婚，沒見這兒正談情說愛？速速拆廟去吧，休要囉嗦。"},
	[63990] = {CommonPl = "俗話說寧拆十座廟不毀一樁婚，沒見這兒正談情說愛？速速拆廟去吧，休要囉嗦。"},
	[63995] = {CommonPl = "竊賊的信物--賞銀10兩,\r山匪的信物--賞銀20兩,\r慣盜的信物--賞銀50兩,\r……\r"},
	[63996] = {CommonPl = "近來手頭緊得很,不知可有門路搞些銀錢花銷花銷。"},
	[63997] = {CommonPl = "重賞之下必有勇夫，相信對那些妨礙鏢局運鏢的賊人會是一記重擊。"},
	[64088] = {CommonPl = "小聲點，別驚了我的魚。"},
	[64089] = {CommonPl = "厭倦了江湖的腥風血雨以後回到這小漁村隱居實在是再合適不過。\r這位大俠行行好，施捨點吧。"},
	[64090] = {CommonPl = "如今雖然世道不好但鏢行反倒頗為興旺，我們這些給碼頭賣苦力的也能多賺不少。"},
	[64091] = {CommonPl = "快走開快走開，老子行事向來低調，別給我惹麻煩(又往陰暗處縮了縮)。"},
	[64092] = {CommonPl = "奇怪，我家的小貓跑哪去了，難道是要和我玩捉迷藏？"},
	[64093] = {CommonPl = "喵~(瞪著水裡的魚)"},
	[64111] = {CommonPl = "鏢局的安全自有我們來守衛。"},
	[64112] = {CommonPl = "馬幫屯有諸多財物，輕慢不得。"},
	[64113] = {CommonPl = "山寨由我們護衛，固若金湯。"},
	[64114] = {CommonPl = "工坊進出人等須仔細盤查。"},
	[64478] = {CommonPl = "鏢局重地，請勿喧嘩。"},
	[64479] = {CommonPl = "咱是鏢師又不是士卒何苦每日操練，再這裡偷個懶逍遙逍遙再說。"},
	[64480] = {CommonPl = "什麼時候才有機會跟隊去押鏢呢？"},
	[64481] = {CommonPl = "嘿嘿，有什麼不懂的問我這種老江湖就對了。"},
	[64482] = {CommonPl = "一喝酒，啥煩心的事都沒了。"},
	[64483] = {CommonPl = "要不要出個千呢？"},
	[64484] = {CommonPl = "別慌，下一把我就能翻盤。"},
	[64485] = {CommonPl = "財運來了真是檔也檔不住。"},
	[70874] = {CommonPl = "一念花開，一念花落。相思難舍，不如不見。"},
	[70875] = {CommonPl = "世間無數丹青手，一片傷心畫不成。"},
	[36619] = {CommonPl = "當官好！當官妙！當官的好處都知道。"},
--[[#tag pop]]
--导出开场白结束
}

--按条件返回当前数据
function NpcPrologue:GetContionNow(strCond)
	if strCond == --[[!AUTO_1]]"gametime" then
		return GameApi.GetGameTime ()
	elseif strCond == --[[!AUTO_2]]"hour" then
		return GameApi.GetServerTime ()["hour"]
	elseif strCond == --[[!AUTO_3]]"weekday" then
		return GameApi.GetServerTime ()["weekday"]
	end
	return
end

--获取特殊开场白
function NpcPrologue:SpecialPrologue(npcID)
    local condnow
    for k , v in pairs(NpcPrologue.Desinged_Prologue[npcID].SpecialPl) do
		condnow = NpcPrologue:GetContionNow(v.Condition)
    	for s , t in pairs(v.Variable) do
    		if t == condnow then
    			return v.String
    		end
    	end
    end
    return
end

--获得NPC开场白字符串
function NpcPrologue:GetNpcPrologue(npcID, IsOutServer, isCanService)
	local condprol = nil
	if IsOutServer then
		if isCanService then
			if NpcPrologue.Desinged_Prologue[npcID].NPCType == 1 then
				condprol = NpcPrologue:SpecialPrologue(npcID)
				elseif NpcPrologue.Desinged_Prologue[npcID].NPCType == 2 then
				--将来添加其它分类时使用
			end
			return string.format(--[[!AUTO_4]]"@S@\r%s%s", TaskHelp.Color["@黑色@"][2], condprol or NpcPrologue.Desinged_Prologue[npcID].CommonPl)
		else
			return string.format(--[[!AUTO_5]]"@S@\r%s%s", TaskHelp.Color["@黑色@"][2], --[[!AUTO_6]]"我不為其他伺服器玩家提供服務。")
		end
	else
		if NpcPrologue.Desinged_Prologue[npcID] then
			if isCanService then
				if NpcPrologue.Desinged_Prologue[npcID].NPCType == 1 then
					condprol = NpcPrologue:SpecialPrologue(npcID)
				elseif NpcPrologue.Desinged_Prologue[npcID].NPCType == 2 then
				--将来添加其它分类时使用
				end
				if string.find(condprol or NpcPrologue.Desinged_Prologue[npcID].CommonPl, --[[!AUTO_7]]"∧綁定元寶數∨") then
					return string.gsub(string.format(--[[!AUTO_9]]"@S@\r%s%s", TaskHelp.Color["@黑色@"][2], condprol or NpcPrologue.Desinged_Prologue[npcID].CommonPl), --[[!AUTO_10]]"∧綁定元寶數∨", GameApi.GetReputation (196))
				elseif string.find(condprol or NpcPrologue.Desinged_Prologue[npcID].CommonPl, "∧寶銀數∨") then
					return string.gsub(string.format("@S@\r%s%s", TaskHelp.Color["@黑色@"][2], condprol or NpcPrologue.Desinged_Prologue[npcID].CommonPl), "∧寶銀數∨", GameApi.GetReputation (209))
				elseif string.find(condprol or NpcPrologue.Desinged_Prologue[npcID].CommonPl, "∧雪戰積分∨") then
					return string.gsub(string.format("@S@\r%s%s", TaskHelp.Color["@黑色@"][2], condprol or NpcPrologue.Desinged_Prologue[npcID].CommonPl), "∧雪戰積分∨", GameApi.GetReputation (218))
				else
					return string.format(--[[!AUTO_8]]"@S@\r%s%s", TaskHelp.Color["@黑色@"][2], condprol or NpcPrologue.Desinged_Prologue[npcID].CommonPl)
				end
				--return string.format("@S@\r%s%s", TaskHelp.Color["@黑色@"][2], condprol or NpcPrologue.Desinged_Prologue[npcID].CommonPl)
				--return string.format("%s%s%s", "@S@\r", condprol or NpcPrologue.Desinged_Prologue[npcID].CommonPl, "\r\r")
			else
				return string.format(--[[!AUTO_11]]"@S@\r%s%s", TaskHelp.Color["@黑色@"][2], --[[!AUTO_12]]"我只為其他伺服器玩家提供服務。")
			end
		end
		return string.gsub(--[[NpcPrologue:SpecialPrologue(622) or ]]NpcPrologue.Desinged_Prologue[622].CommonPl,--[[!AUTO_13]]"ffffff",TaskHelp.Color["@黑色@"][1])
	--return condprol or NpcPrologue.Error_Prologue
	end
end

